--
-- Name: backflush_materials(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.backflush_materials(p_work_order_id uuid, p_quantity_produced numeric) RETURNS SETOF public.material_consumption
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_work_order RECORD;
    v_mo RECORD;
    v_bom_line RECORD;
BEGIN
    -- الحصول على أمر العمل وأمر التصنيع
    SELECT wo.*, mo.bom_id, mo.org_id as mo_org_id
    INTO v_work_order
    FROM work_orders wo
    JOIN manufacturing_orders mo ON wo.mo_id = mo.id
    WHERE wo.id = p_work_order_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Work order not found: %', p_work_order_id;
    END IF;

    -- [120] حارس عضوية على مؤسسة أمر التصنيع
    PERFORM public.wardah_assert_org_member(v_work_order.mo_org_id);

    -- استهلاك المواد بناءً على BOM
    FOR v_bom_line IN
        SELECT bl.*, i.name as item_name
        FROM bom_lines bl
        JOIN items i ON bl.item_id = i.id
        WHERE bl.bom_id = v_work_order.bom_id
        AND bl.item_type IN ('RAW_MATERIAL', 'COMPONENT')
    LOOP
        RETURN QUERY
        INSERT INTO material_consumption (
            org_id, work_order_id, mo_id, item_id,
            planned_quantity, consumed_quantity, consumption_type,
            unit_cost, total_cost, status, consumption_date, created_by
        ) VALUES (
            v_work_order.mo_org_id, p_work_order_id, v_work_order.mo_id, v_bom_line.item_id,
            v_bom_line.quantity * (v_work_order.planned_quantity),
            v_bom_line.quantity * p_quantity_produced,
            'BACKFLUSH',
            v_bom_line.unit_cost,
            v_bom_line.unit_cost * v_bom_line.quantity * p_quantity_produced,
            'PENDING', NOW(), auth.uid()
        )
        RETURNING *;
    END LOOP;
END;
$$;


--
-- Name: batch_post_journal_entries(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.batch_post_journal_entries(p_entry_ids uuid[]) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_entry_id UUID;
    v_result JSON;
    v_success_count INTEGER := 0;
    v_fail_count INTEGER := 0;
    v_results JSONB := '[]'::JSONB;
    v_entry_result JSON;
    v_tenant_id UUID;
    v_org UUID;
BEGIN
    IF p_entry_ids IS NULL OR array_length(p_entry_ids, 1) IS NULL THEN
        RETURN json_build_object(
            'success', false,
            'error', 'No entries provided'
        );
    END IF;

    -- [120] حارس: كل قيد في الدفعة يجب أن ينتمي لمؤسسة المستدعي (admin)
    IF NOT EXISTS (SELECT 1 FROM journal_entries WHERE id = ANY(p_entry_ids)) THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Entries not found'
        );
    END IF;
    FOR v_org IN SELECT DISTINCT tenant_id FROM journal_entries WHERE id = ANY(p_entry_ids)
    LOOP
        IF v_org IS NULL THEN
            RAISE EXCEPTION 'ORG_UNRESOLVED';
        END IF;
        PERFORM public.wardah_assert_org_admin(v_org);
    END LOOP;
    SELECT tenant_id INTO v_tenant_id FROM journal_entries WHERE id = ANY(p_entry_ids) LIMIT 1;

    -- Process each entry
    FOREACH v_entry_id IN ARRAY p_entry_ids
    LOOP
        BEGIN
            -- Try to post the entry
            SELECT post_journal_entry(v_entry_id) INTO v_entry_result;

            IF (v_entry_result->>'success')::BOOLEAN THEN
                v_success_count := v_success_count + 1;
                v_results := v_results || jsonb_build_object(
                    'entry_id', v_entry_id,
                    'success', true,
                    'message', v_entry_result->>'message'
                );
            ELSE
                v_fail_count := v_fail_count + 1;
                v_results := v_results || jsonb_build_object(
                    'entry_id', v_entry_id,
                    'success', false,
                    'error', v_entry_result->>'error'
                );
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_fail_count := v_fail_count + 1;
            v_results := v_results || jsonb_build_object(
                'entry_id', v_entry_id,
                'success', false,
                'error', SQLERRM
            );
        END;
    END LOOP;

    -- Return summary
    RETURN json_build_object(
        'success', v_fail_count = 0,
        'total', array_length(p_entry_ids, 1),
        'success_count', v_success_count,
        'fail_count', v_fail_count,
        'results', v_results
    );
END;
$$;


--
-- Name: build_bom_tree(uuid, numeric, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.build_bom_tree(p_bom_id uuid, p_quantity numeric DEFAULT 1, p_org_id uuid DEFAULT NULL::uuid, p_force_rebuild boolean DEFAULT false) RETURNS TABLE(id uuid, parent_id uuid, item_id uuid, item_code character varying, item_name character varying, level_number integer, quantity_required numeric, cumulative_quantity numeric, unit_cost numeric, total_cost numeric, is_critical boolean, scrap_factor numeric, line_type character varying, path text, has_children boolean)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_cache_expiry INTERVAL := INTERVAL '1 hour';
    v_cached_count INTEGER;
    items_table_exists BOOLEAN;
    products_table_exists BOOLEAN;
BEGIN
    -- التحقق من وجود الجداول
    SELECT EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_schema = 'public' AND table_name = 'items'
    ) INTO items_table_exists;
    
    SELECT EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_schema = 'public' AND table_name = 'products'
    ) INTO products_table_exists;

    -- التحقق من وجود cache صالح
    IF NOT p_force_rebuild THEN
        SELECT COUNT(*) INTO v_cached_count
        FROM bom_tree_cache
        WHERE bom_id = p_bom_id
        AND (p_org_id IS NULL OR org_id = p_org_id)
        AND (expires_at IS NULL OR expires_at > NOW());
        
        IF v_cached_count > 0 THEN
            -- إرجاع البيانات من cache
            IF items_table_exists THEN
                RETURN QUERY
                SELECT 
                    c.id,
                    c.parent_id,
                    c.item_id,
                    COALESCE(i.code, i.item_code)::VARCHAR AS item_code,
                    COALESCE(i.name, i.item_name)::VARCHAR AS item_name,
                    c.level_number,
                    c.quantity_required,
                    c.cumulative_quantity,
                    c.unit_cost,
                    c.total_cost,
                    c.is_critical,
                    c.scrap_factor,
                    c.line_type,
                    c.path,
                    EXISTS(
                        SELECT 1 FROM bom_tree_cache child 
                        WHERE child.parent_id = c.id
                    ) AS has_children
                FROM bom_tree_cache c
                LEFT JOIN items i ON i.id = c.item_id
                WHERE c.bom_id = p_bom_id
                AND (p_org_id IS NULL OR c.org_id = p_org_id)
                AND (c.expires_at IS NULL OR c.expires_at > NOW())
                ORDER BY c.level_number, c.path;
            ELSIF products_table_exists THEN
                RETURN QUERY
                SELECT 
                    c.id,
                    c.parent_id,
                    c.item_id,
                    COALESCE(p.code, p.product_code)::VARCHAR AS item_code,
                    COALESCE(p.name, p.product_name)::VARCHAR AS item_name,
                    c.level_number,
                    c.quantity_required,
                    c.cumulative_quantity,
                    c.unit_cost,
                    c.total_cost,
                    c.is_critical,
                    c.scrap_factor,
                    c.line_type,
                    c.path,
                    EXISTS(
                        SELECT 1 FROM bom_tree_cache child 
                        WHERE child.parent_id = c.id
                    ) AS has_children
                FROM bom_tree_cache c
                LEFT JOIN products p ON p.id = c.item_id
                WHERE c.bom_id = p_bom_id
                AND (p_org_id IS NULL OR c.org_id = p_org_id)
                AND (c.expires_at IS NULL OR c.expires_at > NOW())
                ORDER BY c.level_number, c.path;
            END IF;
            
            RETURN;
        END IF;
    END IF;

    -- بناء شجرة جديدة
    IF items_table_exists THEN
        WITH RECURSIVE bom_tree AS (
            -- الجذر (المنتج النهائي)
            SELECT 
                0 AS level,
                bh.item_id,
                NULL::UUID AS parent_item_id,
                p_quantity AS qty_required,
                p_quantity AS cumulative_qty,
                false AS is_critical,
                0 AS scrap_factor,
                'COMPONENT'::VARCHAR AS line_type,
                bh.id AS bom_id,
                '/' || bh.item_id::TEXT AS path
            FROM bom_headers bh
            WHERE bh.id = p_bom_id
            AND (p_org_id IS NULL OR bh.org_id = p_org_id)
            
            UNION ALL
            
            -- المستويات الفرعية
            SELECT 
                bt.level + 1,
                bl.item_id,
                bt.item_id AS parent_item_id,
                bt.qty_required * bl.quantity * (1 + COALESCE(bl.scrap_factor, 0)/100) AS qty_required,
                bt.cumulative_qty * bl.quantity * (1 + COALESCE(bl.scrap_factor, 0)/100) AS cumulative_qty,
                COALESCE(bl.is_critical, false) AS is_critical,
                COALESCE(bl.scrap_factor, 0) AS scrap_factor,
                COALESCE(bl.line_type, 'COMPONENT')::VARCHAR AS line_type,
                COALESCE(sub_bh.id, bt.bom_id) AS bom_id,
                bt.path || '/' || bl.item_id::TEXT AS path
            FROM bom_tree bt
            JOIN bom_lines bl ON bl.bom_id = bt.bom_id
            LEFT JOIN bom_headers sub_bh ON sub_bh.item_id = bl.item_id 
                AND sub_bh.is_active = true
                AND (p_org_id IS NULL OR sub_bh.org_id = p_org_id)
            WHERE bt.level < 20
            AND bl.line_type != 'REFERENCE'
        )
        INSERT INTO bom_tree_cache (
            bom_id, parent_id, item_id, level_number, 
            quantity_required, cumulative_quantity, 
            unit_cost, total_cost, is_critical, scrap_factor, 
            line_type, path, org_id, expires_at
        )
        SELECT DISTINCT ON (bt.item_id, bt.path)
            p_bom_id,
            NULL, -- سيتم تحديثه لاحقاً
            bt.item_id,
            bt.level,
            bt.qty_required,
            bt.cumulative_qty,
            COALESCE(i.unit_cost, i.standard_cost, 0) AS unit_cost,
            bt.cumulative_qty * COALESCE(i.unit_cost, i.standard_cost, 0) AS total_cost,
            bt.is_critical,
            bt.scrap_factor,
            bt.line_type,
            bt.path,
            COALESCE(p_org_id, (SELECT org_id FROM bom_headers WHERE id = p_bom_id)),
            NOW() + v_cache_expiry
        FROM bom_tree bt
        LEFT JOIN items i ON i.id = bt.item_id
        ORDER BY bt.item_id, bt.path, bt.level;
    END IF;

    -- تحديث parent_id
    UPDATE bom_tree_cache c1
    SET parent_id = c2.id
    FROM bom_tree_cache c2
    WHERE c1.bom_id = p_bom_id
    AND c1.path LIKE c2.path || '/%'
    AND c1.level_number = c2.level_number + 1
    AND (p_org_id IS NULL OR c1.org_id = p_org_id);

    -- إرجاع النتيجة
    IF items_table_exists THEN
        RETURN QUERY
        SELECT 
            c.id,
            c.parent_id,
            c.item_id,
            COALESCE(i.code, i.item_code)::VARCHAR AS item_code,
            COALESCE(i.name, i.item_name)::VARCHAR AS item_name,
            c.level_number,
            c.quantity_required,
            c.cumulative_quantity,
            c.unit_cost,
            c.total_cost,
            c.is_critical,
            c.scrap_factor,
            c.line_type,
            c.path,
            EXISTS(
                SELECT 1 FROM bom_tree_cache child 
                WHERE child.parent_id = c.id
            ) AS has_children
        FROM bom_tree_cache c
        LEFT JOIN items i ON i.id = c.item_id
        WHERE c.bom_id = p_bom_id
        AND (p_org_id IS NULL OR c.org_id = p_org_id)
        ORDER BY c.level_number, c.path;
    END IF;
END;
$$;


--
-- Name: calculate_available_capacity(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_available_capacity(p_work_center_id uuid, p_start_date date, p_end_date date) RETURNS TABLE(total_available_hours numeric, working_days integer, avg_daily_hours numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    WITH calendar_data AS (
        SELECT 
            COALESCE(wcc.available_hours, wc.capacity_hours_per_day) - 
            COALESCE(wcc.planned_maintenance_hours, 0) as daily_hours,
            COALESCE(wcc.is_working_day, true) as is_working
        FROM generate_series(p_start_date, p_end_date, '1 day'::interval) d(date)
        CROSS JOIN work_centers wc
        LEFT JOIN work_center_calendars wcc 
            ON wcc.work_center_id = wc.id 
            AND wcc.calendar_date = d.date::DATE
        WHERE wc.id = p_work_center_id
    )
    SELECT 
        COALESCE(SUM(CASE WHEN is_working THEN daily_hours ELSE 0 END), 0)::DECIMAL as total_available_hours,
        COUNT(*) FILTER (WHERE is_working)::INTEGER as working_days,
        COALESCE(AVG(CASE WHEN is_working THEN daily_hours ELSE NULL END), 0)::DECIMAL as avg_daily_hours
    FROM calendar_data;
END;
$$;


--
-- Name: calculate_bom_cost(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_bom_cost(p_bom_id uuid, p_quantity numeric DEFAULT 1) RETURNS numeric
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_total_cost NUMERIC := 0;
    items_table_exists BOOLEAN;
BEGIN
    -- تحديد الجدول المستخدم
    SELECT EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_name = 'items'
    ) INTO items_table_exists;

    IF items_table_exists THEN
        -- استخدام items
        SELECT COALESCE(SUM(
            eb.quantity_required * 
            COALESCE(i.unit_cost, i.standard_cost, i.cost_price, 0)
        ), 0)
        INTO v_total_cost
        FROM explode_bom(p_bom_id, p_quantity) eb
        LEFT JOIN items i ON i.id = eb.item_id;
    ELSE
        -- استخدام products
        SELECT COALESCE(SUM(
            eb.quantity_required * 
            COALESCE(p.unit_cost, p.standard_cost, p.cost_price, 0)
        ), 0)
        INTO v_total_cost
        FROM explode_bom(p_bom_id, p_quantity) eb
        LEFT JOIN products p ON p.id = eb.item_id;
    END IF;
    
    RETURN v_total_cost;
END;
$$;


--
-- Name: calculate_bom_standard_cost(uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_bom_standard_cost(p_bom_id uuid, p_quantity numeric DEFAULT 1, p_org_id uuid DEFAULT NULL::uuid) RETURNS TABLE(material_cost numeric, labor_cost numeric, overhead_cost numeric, total_cost numeric, unit_cost numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_material_cost NUMERIC := 0;
    v_labor_cost NUMERIC := 0;
    v_overhead_cost NUMERIC := 0;
    v_total_cost NUMERIC := 0;
    items_table_exists BOOLEAN;
    products_table_exists BOOLEAN;
BEGIN
    -- تحديد الجدول المستخدم
    SELECT EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_schema = 'public' AND table_name = 'items'
    ) INTO items_table_exists;
    
    SELECT EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_schema = 'public' AND table_name = 'products'
    ) INTO products_table_exists;

    -- حساب تكلفة المواد
    IF items_table_exists THEN
        SELECT COALESCE(SUM(
            eb.quantity_required * 
            COALESCE(i.standard_cost, i.unit_cost, 0)
        ), 0)
        INTO v_material_cost
        FROM explode_bom(p_bom_id, p_quantity, p_org_id) eb
        LEFT JOIN items i ON i.id = eb.item_id
        WHERE eb.line_type = 'COMPONENT';
    ELSIF products_table_exists THEN
        SELECT COALESCE(SUM(
            eb.quantity_required * 
            COALESCE(p.standard_cost, p.unit_cost, 0)
        ), 0)
        INTO v_material_cost
        FROM explode_bom(p_bom_id, p_quantity, p_org_id) eb
        LEFT JOIN products p ON p.id = eb.item_id
        WHERE eb.line_type = 'COMPONENT';
    END IF;

    -- حساب تكلفة العمالة (من routing إذا كان موجوداً)
    SELECT COALESCE(SUM(
        bo.setup_time_minutes / 60.0 * COALESCE(bo.labor_rate, 0) +
        bo.run_time_minutes / 60.0 * COALESCE(bo.labor_rate, 0) * p_quantity
    ), 0)
    INTO v_labor_cost
    FROM bom_operations bo
    WHERE bo.bom_id = p_bom_id
    AND bo.is_active = true
    AND (p_org_id IS NULL OR bo.org_id = p_org_id);

    -- حساب التكاليف غير المباشرة (نسبة من العمالة)
    SELECT COALESCE(v_labor_cost * 0.15, 0) INTO v_overhead_cost; -- 15% افتراضي

    -- التكلفة الإجمالية
    v_total_cost := v_material_cost + v_labor_cost + v_overhead_cost;

    RETURN QUERY SELECT 
        v_material_cost,
        v_labor_cost,
        v_overhead_cost,
        v_total_cost,
        CASE WHEN p_quantity > 0 THEN v_total_cost / p_quantity ELSE 0 END;
END;
$$;


--
-- Name: calculate_bom_total_cost(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_bom_total_cost() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.total_cost = NEW.quantity * NEW.unit_cost;
  RETURN NEW;
END;
$$;


--
-- Name: calculate_labor_variances(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_labor_variances(p_mo_id uuid, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date) RETURNS TABLE(work_center_code character varying, work_center_name character varying, standard_hours numeric, actual_hours numeric, standard_rate numeric, actual_rate numeric, rate_variance numeric, efficiency_variance numeric, total_variance numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
BEGIN
    IF to_regclass('public.labor_entries') IS NULL THEN
        RETURN; -- جداول التتبع غير مفعَّلة — فارغ بدل 42P01
    END IF;
    RETURN QUERY EXECUTE format($q$
        SELECT wc.code::varchar, wc.name::varchar,
               SUM(le.standard_hours), SUM(le.actual_hours),
               AVG(le.standard_rate), AVG(le.actual_rate),
               SUM((le.actual_rate - le.standard_rate) * le.actual_hours),
               SUM((le.actual_hours - le.standard_hours) * le.standard_rate),
               SUM((le.actual_rate - le.standard_rate) * le.actual_hours) +
               SUM((le.actual_hours - le.standard_hours) * le.standard_rate)
        FROM labor_entries le
        JOIN work_centers wc ON wc.id = le.work_center_id
        WHERE le.mo_id = %L
          AND (%L::date IS NULL OR le.entry_date >= %L::date)
          AND (%L::date IS NULL OR le.entry_date <= %L::date)
        GROUP BY wc.code, wc.name ORDER BY wc.code
    $q$, p_mo_id, p_start_date, p_start_date, p_end_date, p_end_date);
END;
$_$;


--
-- Name: calculate_material_variances(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_material_variances(p_mo_id uuid, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date) RETURNS TABLE(product_code character varying, product_name character varying, standard_qty numeric, actual_qty numeric, standard_cost numeric, actual_cost numeric, qty_variance numeric, price_variance numeric, efficiency_variance numeric, total_variance numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RAISE EXCEPTION 'MATERIAL_VARIANCE_SOURCE_RETIRED: canonical standard-cost snapshot is not implemented'
    USING ERRCODE = '0A000',
          HINT = 'Use material_consumption for actual quantities/costs; add a separately reviewed standard-cost snapshot before computing variances.';
END;
$$;


--
-- Name: calculate_planned_load(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_planned_load(p_work_center_id uuid, p_start_date date, p_end_date date) RETURNS TABLE(total_planned_hours numeric, total_work_orders integer, pending_work_orders integer, in_progress_work_orders integer)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COALESCE(SUM((wo.planned_setup_time + wo.planned_run_time) / 60), 0)::DECIMAL as total_planned_hours,
        COUNT(*)::INTEGER as total_work_orders,
        COUNT(*) FILTER (WHERE wo.status IN ('PENDING', 'READY'))::INTEGER as pending_work_orders,
        COUNT(*) FILTER (WHERE wo.status = 'IN_PROGRESS')::INTEGER as in_progress_work_orders
    FROM work_orders wo
    WHERE wo.work_center_id = p_work_center_id
    AND wo.status NOT IN ('COMPLETED', 'CANCELLED')
    AND (
        (wo.planned_start_date::DATE BETWEEN p_start_date AND p_end_date)
        OR (wo.planned_end_date::DATE BETWEEN p_start_date AND p_end_date)
        OR (wo.planned_start_date IS NULL AND wo.created_at::DATE BETWEEN p_start_date AND p_end_date)
    );
END;
$$;


--
-- Name: calculate_risk_score(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_risk_score() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.risk_score = (NEW.probability * NEW.impact) / 100;
  RETURN NEW;
END;
$$;


--
-- Name: calculate_routing_cost(uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_routing_cost(p_bom_id uuid, p_quantity numeric DEFAULT 1, p_org_id uuid DEFAULT NULL::uuid) RETURNS TABLE(operation_sequence integer, operation_code character varying, operation_name character varying, setup_cost numeric, run_cost numeric, total_cost numeric, total_time_minutes numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        bo.operation_sequence,
        bo.operation_code,
        bo.operation_name,
        bo.setup_cost,
        bo.run_cost_per_unit * p_quantity AS run_cost,
        bo.setup_cost + (bo.run_cost_per_unit * p_quantity) AS total_cost,
        bo.setup_time_minutes + (bo.run_time_minutes * p_quantity) AS total_time_minutes
    FROM bom_operations bo
    WHERE bo.bom_id = p_bom_id
    AND bo.is_active = true
    AND (p_org_id IS NULL OR bo.org_id = p_org_id)
    ORDER BY bo.operation_sequence;
END;
$$;


--
-- Name: calculate_routing_standard_cost(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_routing_standard_cost(p_routing_id uuid, p_quantity numeric DEFAULT 1) RETURNS TABLE(total_labor_cost numeric, total_overhead_cost numeric, total_routing_cost numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COALESCE(SUM(
            ((ro.standard_setup_time + (ro.standard_run_time_per_unit * p_quantity)) / 60) * 
            COALESCE(ro.labor_rate_per_hour, wc.default_labor_rate, 0)
        ), 0) as total_labor_cost,
        COALESCE(SUM(
            ((ro.standard_setup_time + (ro.standard_run_time_per_unit * p_quantity)) / 60) * 
            COALESCE(ro.overhead_rate_per_hour, wc.default_overhead_rate, 0)
        ), 0) as total_overhead_cost,
        COALESCE(SUM(
            ((ro.standard_setup_time + (ro.standard_run_time_per_unit * p_quantity)) / 60) * 
            (COALESCE(ro.labor_rate_per_hour, wc.default_labor_rate, 0) + 
             COALESCE(ro.overhead_rate_per_hour, wc.default_overhead_rate, 0))
        ), 0) as total_routing_cost
    FROM routing_operations ro
    LEFT JOIN work_centers wc ON ro.work_center_id = wc.id
    WHERE ro.routing_id = p_routing_id
    AND ro.is_active = true;
END;
$$;


--
-- Name: calculate_routing_total_time(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_routing_total_time(p_routing_id uuid, p_quantity numeric DEFAULT 1) RETURNS TABLE(total_setup_time numeric, total_run_time numeric, total_queue_time numeric, total_move_time numeric, total_lead_time numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COALESCE(SUM(ro.standard_setup_time), 0) as total_setup_time,
        COALESCE(SUM(ro.standard_run_time_per_unit * p_quantity), 0) as total_run_time,
        COALESCE(SUM(ro.standard_queue_time), 0) as total_queue_time,
        COALESCE(SUM(ro.standard_move_time), 0) as total_move_time,
        COALESCE(SUM(
            ro.standard_setup_time + 
            (ro.standard_run_time_per_unit * p_quantity) + 
            ro.standard_queue_time + 
            ro.standard_move_time
        ), 0) as total_lead_time
    FROM routing_operations ro
    WHERE ro.routing_id = p_routing_id
    AND ro.is_active = true;
END;
$$;


--
-- Name: calculate_total_routing_cost(uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_total_routing_cost(p_bom_id uuid, p_quantity numeric DEFAULT 1, p_org_id uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_total_cost NUMERIC := 0;
BEGIN
    SELECT COALESCE(SUM(total_cost), 0)
    INTO v_total_cost
    FROM calculate_routing_cost(p_bom_id, p_quantity, p_org_id);
    
    RETURN v_total_cost;
END;
$$;


--
-- Name: calculate_wip_equivalent_units(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_wip_equivalent_units() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_completed numeric := COALESCE(NEW.units_completed, 0);
  v_ending numeric := COALESCE(NEW.units_ending_wip, 0);
  v_material_pct numeric := COALESCE(NEW.material_completion_pct, 0) / 100.0;
  v_conversion_pct numeric := COALESCE(NEW.conversion_completion_pct, 0) / 100.0;
  v_begin_total numeric := COALESCE(NEW.cost_beginning_wip, 0);
  v_begin_material numeric;
  v_begin_conversion numeric;
  v_begin_transferred numeric;
  v_split_total numeric;
BEGIN
  IF v_completed < 0 OR v_ending < 0 THEN
    RAISE EXCEPTION 'WIP_UNITS_MUST_BE_NONNEGATIVE';
  END IF;

  IF v_material_pct < 0 OR v_material_pct > 1
     OR v_conversion_pct < 0 OR v_conversion_pct > 1 THEN
    RAISE EXCEPTION 'WIP_COMPLETION_PERCENT_OUT_OF_RANGE';
  END IF;

  v_begin_material := NEW.cost_beginning_wip_material;
  v_begin_conversion := NEW.cost_beginning_wip_conversion;
  v_begin_transferred := NEW.cost_beginning_wip_transferred_in;

  IF v_begin_total > 0
     AND v_begin_material IS NULL
     AND v_begin_conversion IS NULL
     AND v_begin_transferred IS NULL THEN
    v_begin_material := v_begin_total;
    v_begin_conversion := 0;
    v_begin_transferred := 0;
    NEW.eu_calculation_note := 'legacy_unsplit_beginning_wip_assigned_to_material';
  ELSE
    v_begin_material := COALESCE(v_begin_material, 0);
    v_begin_conversion := COALESCE(v_begin_conversion, 0);
    v_begin_transferred := COALESCE(v_begin_transferred, 0);
    v_split_total := v_begin_material + v_begin_conversion + v_begin_transferred;

    IF abs(v_split_total - v_begin_total) > 0.000001 THEN
      RAISE EXCEPTION
        'BEGINNING_WIP_COST_SPLIT_MISMATCH: total=%, split=%',
        v_begin_total, v_split_total;
    END IF;
    NEW.eu_calculation_note := NULL;
  END IF;

  NEW.equivalent_units_material :=
    v_completed + (v_ending * v_material_pct);
  NEW.equivalent_units_conversion :=
    v_completed + (v_ending * v_conversion_pct);
  NEW.equivalent_units_transferred_in :=
    v_completed + v_ending;

  NEW.cost_per_eu_material :=
    CASE WHEN NEW.equivalent_units_material > 0
      THEN (v_begin_material + COALESCE(NEW.cost_material, 0))
           / NEW.equivalent_units_material
      ELSE 0
    END;

  NEW.cost_per_eu_conversion :=
    CASE WHEN NEW.equivalent_units_conversion > 0
      THEN (v_begin_conversion + COALESCE(NEW.cost_labor, 0)
            + COALESCE(NEW.cost_overhead, 0))
           / NEW.equivalent_units_conversion
      ELSE 0
    END;

  NEW.cost_per_eu_transferred_in :=
    CASE WHEN NEW.equivalent_units_transferred_in > 0
      THEN (v_begin_transferred + COALESCE(NEW.cost_transferred_in, 0))
           / NEW.equivalent_units_transferred_in
      ELSE 0
    END;

  NEW.cost_completed_transferred :=
    v_completed * (
      COALESCE(NEW.cost_per_eu_material, 0)
      + COALESCE(NEW.cost_per_eu_conversion, 0)
      + COALESCE(NEW.cost_per_eu_transferred_in, 0)
    );

  NEW.cost_ending_wip :=
    (v_ending * v_material_pct * COALESCE(NEW.cost_per_eu_material, 0))
    + (v_ending * v_conversion_pct * COALESCE(NEW.cost_per_eu_conversion, 0))
    + (v_ending * COALESCE(NEW.cost_per_eu_transferred_in, 0));

  NEW.eu_calculation_version := 2;
  RETURN NEW;
END;
$$;


