--
-- Name: create_mo_with_reservation(uuid, jsonb, jsonb[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_mo_with_reservation(p_org_id uuid, p_mo_data jsonb, p_materials jsonb[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_mo_id UUID;
    v_material JSONB;
    v_reservation_id UUID;
    v_result JSONB;
    v_errors TEXT[] := ARRAY[]::TEXT[];
BEGIN
    -- Start transaction (implicit in function)
    
    -- 1. Create manufacturing order
    INSERT INTO manufacturing_orders (
        org_id,
        mo_number,
        product_id,
        qty_planned,
        status
        -- ... other fields from p_mo_data can be added here
    )
    SELECT
        p_org_id,
        p_mo_data->>'mo_number',
        (p_mo_data->>'product_id')::UUID,
        (p_mo_data->>'qty_planned')::DECIMAL,
        'draft'
    RETURNING id INTO v_mo_id;
    
    -- 2. Reserve materials
    FOREACH v_material IN ARRAY p_materials
    LOOP
        -- Check availability
        IF NOT EXISTS (
            SELECT 1 FROM stock_quants
            WHERE item_id = (v_material->>'item_id')::UUID
            AND org_id = p_org_id
            AND quantity >= (v_material->>'quantity')::DECIMAL
        ) THEN
            v_errors := array_append(
                v_errors,
                format('Insufficient stock for item %s', v_material->>'item_id')
            );
            RAISE EXCEPTION 'Insufficient inventory';
        END IF;
        
        -- Create reservation
        INSERT INTO material_reservations (
            org_id,
            mo_id,
            item_id,
            quantity_reserved,
            status,
            reserved_at
        ) VALUES (
            p_org_id,
            v_mo_id,
            (v_material->>'item_id')::UUID,
            (v_material->>'quantity')::DECIMAL,
            'reserved',
            NOW()
        ) RETURNING id INTO v_reservation_id;
    END LOOP;
    
    -- 3. Return success result
    v_result := jsonb_build_object(
        'success', true,
        'mo_id', v_mo_id,
        'reservations', array_length(p_materials, 1)
    );
    
    RETURN v_result;
    
EXCEPTION
    WHEN OTHERS THEN
        -- Transaction will automatically rollback
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM,
            'mo_id', v_mo_id
        );
END;
$$;


--
-- Name: create_role_from_template(uuid, uuid, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_role_from_template(p_org_id uuid, p_template_id uuid, p_custom_name character varying DEFAULT NULL::character varying, p_created_by uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_template role_templates%ROWTYPE;
    v_new_role_id UUID;
    v_perm_key TEXT;
    v_granted_keys jsonb;
BEGIN
    -- [120] admin gate on the target org; p_created_by is ignored (would
    -- otherwise allow impersonating a different creator).
    PERFORM public.wardah_assert_org_admin(p_org_id);

    SELECT * INTO v_template FROM role_templates WHERE id = p_template_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Template not found';
    END IF;

    INSERT INTO roles (org_id, name, name_ar, description_ar, created_by)
    VALUES (
        p_org_id,
        COALESCE(p_custom_name, v_template.name),
        v_template.name_ar,
        v_template.description_ar,
        auth.uid()
    )
    RETURNING id INTO v_new_role_id;

    FOREACH v_perm_key IN ARRAY v_template.permission_keys
    LOOP
        INSERT INTO role_permissions (role_id, permission_id, created_by)
        SELECT v_new_role_id, p.id, auth.uid()
        FROM permissions p
        WHERE p.permission_key LIKE REPLACE(v_perm_key, '%', '%%')
           OR p.permission_key LIKE v_perm_key
        ON CONFLICT DO NOTHING;
    END LOOP;

    SELECT COALESCE(jsonb_agg(p.permission_key ORDER BY p.permission_key), '[]'::jsonb)
      INTO v_granted_keys
    FROM role_permissions rp
    JOIN permissions p ON p.id = rp.permission_id
    WHERE rp.role_id = v_new_role_id;

    -- 175: the only change to this function. Every other write above is
    -- byte-for-byte the body that shipped in migration ~120.
    INSERT INTO audit_logs (org_id, user_id, action, entity_type, entity_id, old_data, new_data, metadata)
    VALUES (
      p_org_id, auth.uid(), 'rbac.role.create', 'role', v_new_role_id::text,
      NULL,
      jsonb_build_object('role_id', v_new_role_id,
                         'name', COALESCE(p_custom_name, v_template.name),
                         'permission_keys', v_granted_keys),
      jsonb_build_object(
        'migration', 175,
        'source', 'template',
        'template_id', p_template_id,
        'permission_count', jsonb_array_length(v_granted_keys),
        'sensitive_keys', (
          SELECT COALESCE(jsonb_agg(k ORDER BY k), '[]'::jsonb)
          FROM jsonb_array_elements_text(v_granted_keys) AS t(k)
          WHERE wardah_is_sensitive_permission(k)
        ))
    );

    RETURN v_new_role_id;
END;
$$;


--
-- Name: create_simple_org_rls(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_simple_org_rls(table_name text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    -- Enable RLS
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', table_name);
    
    -- Drop existing policies
    EXECUTE format('DROP POLICY IF EXISTS %I_org_isolation ON %I', table_name, table_name);
    EXECUTE format('DROP POLICY IF EXISTS %I_select_policy ON %I', table_name, table_name);
    EXECUTE format('DROP POLICY IF EXISTS %I_insert_policy ON %I', table_name, table_name);
    EXECUTE format('DROP POLICY IF EXISTS %I_update_policy ON %I', table_name, table_name);
    EXECUTE format('DROP POLICY IF EXISTS %I_delete_policy ON %I', table_name, table_name);
    
    -- Create simple org-based policy (allow all operations for same org)
    EXECUTE format('
        CREATE POLICY %I_org_isolation ON %I
        FOR ALL
        USING (org_id = current_setting(''app.current_org_id'', true)::uuid)
        WITH CHECK (org_id = current_setting(''app.current_org_id'', true)::uuid)
    ', table_name, table_name);
    
    RAISE NOTICE 'Created simple RLS for table: %', table_name;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Could not create RLS for %: %', table_name, SQLERRM;
END;
$$;


--
-- Name: ensure_column(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_column(p_table text, p_column text, p_type text, p_default text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_exists BOOLEAN;
    v_sql TEXT;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = 'public'
          AND table_name = p_table
          AND column_name = p_column
    ) INTO v_exists;

    IF NOT v_exists THEN
        v_sql := format(
            'ALTER TABLE %I ADD COLUMN %I %s',
            p_table, p_column, p_type
        );

    IF p_default IS NOT NULL THEN
        v_sql := v_sql || format(' DEFAULT %s', p_default);
        END IF;

        EXECUTE v_sql;
        RAISE NOTICE '✓ Added column % to %', p_column, p_table;
    END IF;
END;
$$;


--
-- Name: explode_bom(uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.explode_bom(p_bom_id uuid, p_quantity numeric DEFAULT 1, p_org_id uuid DEFAULT NULL::uuid) RETURNS TABLE(level_number integer, item_id uuid, item_code character varying, item_name character varying, quantity_required numeric, unit_of_measure character varying, is_critical boolean, scrap_factor numeric, line_type character varying)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_org uuid; v_header_qty numeric;
BEGIN
  SELECT org_id,quantity INTO v_org,v_header_qty
  FROM public.bom_headers WHERE id=p_bom_id AND (p_org_id IS NULL OR org_id=p_org_id);
  IF NOT FOUND THEN RAISE EXCEPTION 'BOM_NOT_FOUND_OR_WRONG_ORG'; END IF;
  IF p_quantity IS NULL OR p_quantity<=0 OR COALESCE(v_header_qty,0)<=0 THEN
    RAISE EXCEPTION 'BOM_EXPLOSION_QUANTITY_INVALID';
  END IF;
  IF EXISTS (SELECT 1 FROM public.bom_lines WHERE bom_id=p_bom_id AND quantity_base IS NULL AND line_type<>'REFERENCE') THEN
    RAISE EXCEPTION 'BOM_HAS_UNRESOLVED_UOM_LINES';
  END IF;

  RETURN QUERY
  WITH RECURSIVE bom_tree AS (
    SELECT 1 AS level,
           bl.item_id,bl.product_id,
           round((p_quantity/v_header_qty)*bl.quantity_base*(1+COALESCE(bl.scrap_factor,0)/100),6) AS qty_required,
           COALESCE(bl.is_critical,false) AS critical,
           COALESCE(bl.scrap_factor,0) AS scrap,
           COALESCE(bl.line_type,'COMPONENT')::text AS kind,
           ARRAY[bl.item_id]::uuid[] AS path
    FROM public.bom_lines bl
    WHERE bl.bom_id=p_bom_id AND bl.line_type<>'REFERENCE'

    UNION ALL

    SELECT bt.level+1,
           child.item_id,child.product_id,
           round((bt.qty_required/public.wardah_require_positive_bom_quantity(
                    child_header.id,child_header.quantity
                  ))*child.quantity_base*
                 (1+COALESCE(child.scrap_factor,0)/100),6),
           COALESCE(child.is_critical,false),COALESCE(child.scrap_factor,0),
           COALESCE(child.line_type,'COMPONENT')::text,
           bt.path||child.item_id
    FROM bom_tree bt
    JOIN LATERAL (
      SELECT bh.id,bh.quantity
      FROM public.bom_headers bh
      WHERE bh.org_id=v_org AND bh.item_id=bt.item_id AND COALESCE(bh.is_active,true)
        AND COALESCE(bh.effective_date,CURRENT_DATE)<=CURRENT_DATE
      ORDER BY COALESCE(bh.bom_version,1) DESC,bh.effective_date DESC NULLS LAST,bh.created_at DESC
      LIMIT 1
    ) child_header ON true
    JOIN public.bom_lines child ON child.bom_id=child_header.id AND child.line_type<>'REFERENCE'
    WHERE bt.level<20
      AND child.quantity_base IS NOT NULL
      AND NOT child.item_id=ANY(bt.path)
  )
  SELECT min(bt.level)::integer,
         bt.item_id,
         COALESCE(i.code,i.item_code)::varchar,
         COALESCE(i.name,i.item_name)::varchar,
         round(sum(bt.qty_required),6),
         u.symbol::varchar,
         bool_or(bt.critical),
         max(bt.scrap),
         min(bt.kind)::varchar
  FROM bom_tree bt
  LEFT JOIN public.items i ON i.id=bt.item_id
  LEFT JOIN public.products p ON p.id=bt.product_id
  LEFT JOIN public.uoms u ON u.id=p.base_uom_id
  GROUP BY bt.item_id,i.code,i.item_code,i.name,i.item_name,u.symbol
  ORDER BY min(bt.level),COALESCE(i.code,i.item_code);
END;
$$;


--
-- Name: fn_invitations_set_token_hash(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_invitations_set_token_hash() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NEW.token IS NOT NULL THEN
        NEW.token_hash := encode(sha256(NEW.token::bytea), 'hex');
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: generate_adjustment_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_adjustment_number() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  next_num INTEGER;
BEGIN
  -- Get next number for this organization
  SELECT COALESCE(MAX(
    CAST(SUBSTRING(adjustment_number FROM 'ADJ-(\d+)') AS INTEGER)
  ), 0) + 1 
  INTO next_num
  FROM stock_adjustments
  WHERE organization_id = NEW.organization_id;
  
  -- Generate formatted number
  NEW.adjustment_number := 'ADJ-' || LPAD(next_num::TEXT, 6, '0');
  
  RETURN NEW;
END;
$$;


