  -- Check if user is org admin for this specific org
  RETURN EXISTS (
    SELECT 1 FROM user_organizations
    WHERE user_id = auth.uid()
    AND org_id = check_org_id
    AND is_org_admin = true
    AND is_active = true
  );
END;
$$;


