--
-- Name: log_activity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_org_id UUID;
    v_action VARCHAR(50);
    v_old_data JSONB;
    v_new_data JSONB;
    v_changes JSONB;
    v_entity_id TEXT;
BEGIN
    -- الحصول على معرف المستخدم الحالي
    v_user_id := auth.uid();
    
    -- تحديد نوع العملية والبيانات
    IF TG_OP = 'INSERT' THEN
        v_action := 'create';
        v_new_data := to_jsonb(NEW);
        v_old_data := NULL;
        v_changes := v_new_data;
        v_entity_id := NEW.id::TEXT;
        -- محاولة الحصول على org_id
        BEGIN
            v_org_id := NEW.org_id;
        EXCEPTION WHEN OTHERS THEN
            v_org_id := NULL;
        END;
    ELSIF TG_OP = 'UPDATE' THEN
        v_action := 'update';
        v_old_data := to_jsonb(OLD);
        v_new_data := to_jsonb(NEW);
        v_changes := jsonb_build_object('before', v_old_data, 'after', v_new_data);
        v_entity_id := NEW.id::TEXT;
        BEGIN
            v_org_id := NEW.org_id;
        EXCEPTION WHEN OTHERS THEN
            v_org_id := NULL;
        END;
    ELSIF TG_OP = 'DELETE' THEN
        v_action := 'delete';
        v_old_data := to_jsonb(OLD);
        v_new_data := NULL;
        v_changes := v_old_data;
        v_entity_id := OLD.id::TEXT;
        BEGIN
            v_org_id := OLD.org_id;
        EXCEPTION WHEN OTHERS THEN
            v_org_id := NULL;
        END;
    END IF;

    -- تسجيل النشاط
    BEGIN
        INSERT INTO audit_logs (
            org_id,
            user_id,
            action,
            entity_type,
            entity_id,
            old_data,
            new_data,
            changes,
            metadata,
            created_at
        ) VALUES (
            v_org_id,
            v_user_id,
            v_action,
            TG_TABLE_NAME,
            v_entity_id,
            v_old_data,
            v_new_data,
            v_changes,
            jsonb_build_object(
                'table_schema', TG_TABLE_SCHEMA,
                'trigger_name', TG_NAME,
                'triggered_at', NOW()
            ),
            NOW()
        );
    EXCEPTION WHEN OTHERS THEN
        -- تسجيل الخطأ دون إيقاف العملية
        RAISE WARNING 'Audit log failed: % - %', SQLSTATE, SQLERRM;
    END;

    -- إرجاع السجل المناسب
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
END;
$$;


--
-- Name: log_custom_activity(uuid, character varying, character varying, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_custom_activity(p_org_id uuid, p_action character varying, p_entity_type character varying, p_entity_id text DEFAULT NULL::text, p_details jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_log_id UUID;
BEGIN
    INSERT INTO audit_logs (
        org_id,
        user_id,
        action,
        entity_type,
        entity_id,
        changes,
        metadata
    ) VALUES (
        p_org_id,
        auth.uid(),
        p_action,
        p_entity_type,
        p_entity_id,
        p_details,
        jsonb_build_object('timestamp', NOW(), 'source', 'manual')
    )
    RETURNING id INTO v_log_id;

    RETURN v_log_id;
END;
$$;


--
-- Name: normalize_mo_status(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_mo_status(p_status text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
    SELECT CASE lower(trim(p_status))
        WHEN 'in-progress'     THEN 'in_progress'
        WHEN 'in_progress'     THEN 'in_progress'
        WHEN 'completed'       THEN 'done'
        WHEN 'done'            THEN 'done'
        WHEN 'on-hold'         THEN 'on_hold'
        WHEN 'on_hold'         THEN 'on_hold'
        WHEN 'quality-check'   THEN 'quality_check'
        WHEN 'quality_check'   THEN 'quality_check'
        WHEN 'draft'           THEN 'draft'
        WHEN 'confirmed'       THEN 'confirmed'
        WHEN 'pending'         THEN 'pending'
        WHEN 'cancelled'       THEN 'cancelled'
        ELSE lower(trim(p_status))
    END;
$$;


--
-- Name: post_journal_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_journal_entry(p_entry_id uuid) RETURNS json
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_entry RECORD;
    v_total_debit NUMERIC(18,4);
    v_total_credit NUMERIC(18,4);
    v_line_count INTEGER;
    v_result JSON;
BEGIN
    -- الحصول على تفاصيل القيد
    SELECT * INTO v_entry
    FROM journal_entries 
    WHERE id = p_entry_id;
    
    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Journal entry not found'
        );
    END IF;
    
    -- التحقق من الحالة
    IF v_entry.status = 'posted' THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Journal entry is already posted'
        );
    END IF;
    
    IF v_entry.status = 'reversed' THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Cannot post a reversed entry'
        );
    END IF;
    
    -- التحقق من وجود بنود
    SELECT 
        COUNT(*),
        COALESCE(SUM(debit), 0),
        COALESCE(SUM(credit), 0)
    INTO v_line_count, v_total_debit, v_total_credit
    FROM journal_lines 
    WHERE entry_id = p_entry_id;
    
    IF v_line_count = 0 THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Journal entry has no lines'
        );
    END IF;
    
    -- التحقق من أن كل بند له مدين أو دائن فقط (وليس الاثنين)
    IF EXISTS (
        SELECT 1 FROM journal_lines
        WHERE entry_id = p_entry_id 
        AND (debit > 0 AND credit > 0)
    ) THEN
        RETURN json_build_object(
            'success', false,
            'error', 'كل بند يجب أن يحتوي على مدين أو دائن فقط، وليس الاثنين معاً / Each line must have either debit or credit, not both'
        );
    END IF;
    
    -- التحقق من عدم وجود بنود بدون مدين ولا دائن
    IF EXISTS (
        SELECT 1 FROM journal_lines
        WHERE entry_id = p_entry_id 
        AND debit = 0 AND credit = 0
    ) THEN
        RETURN json_build_object(
            'success', false,
            'error', 'كل بند يجب أن يحتوي على مبلغ في المدين أو الدائن / Each line must have either debit or credit amount'
        );
    END IF;
    
    -- التحقق من التوازن
    IF v_total_debit != v_total_credit OR v_total_debit = 0 THEN
        RETURN json_build_object(
            'success', false,
            'error', 'القيد غير متوازن. المدين: ' || v_total_debit || '، الدائن: ' || v_total_credit || ' / Journal entry is not balanced. Debit: ' || v_total_debit || ', Credit: ' || v_total_credit
        );
    END IF;
    
    -- التحقق من أن جميع الحسابات تقبل الترحيل
    IF EXISTS (
        SELECT 1 FROM journal_lines jl
        LEFT JOIN gl_accounts a ON jl.account_id = a.id
        WHERE jl.entry_id = p_entry_id 
        AND (a.allow_posting = false OR a.id IS NULL)
    ) THEN
        RETURN json_build_object(
            'success', false,
            'error', 'لا يمكن الترحيل على حسابات رئيسية أو حسابات غير صالحة / Cannot post to non-posting accounts or invalid accounts'
        );
    END IF;
    
    -- تحديث حالة القيد
    UPDATE journal_entries
    SET 
        status = 'posted',
        posting_date = CURRENT_DATE,
        posted_at = NOW(),
        total_debit = v_total_debit,
        total_credit = v_total_credit
    WHERE id = p_entry_id;
    
    RETURN json_build_object(
        'success', true,
        'message', 'تم ترحيل القيد بنجاح / Journal entry posted successfully',
        'entry_id', p_entry_id,
        'total_debit', v_total_debit,
        'total_credit', v_total_credit
    );
END;
$$;


--
-- Name: protect_posted_gl_entries(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_posted_gl_entries() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_controlled_unpost boolean :=
    coalesce(current_setting('wardah.voucher_unpost', true), '') = 'on';
  v_controlled_cancel boolean :=
    coalesce(current_setting('wardah.voucher_gl_cancel', true), '') = 'on';
  v_voucher_eligible boolean := false;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status IN ('posted', 'reversed') THEN
      RAISE EXCEPTION 'POSTED_ENTRY_IMMUTABLE: لا يمكن حذف قيد مرحّل (%) — استخدم العكس', OLD.entry_number;
    END IF;
    RETURN OLD;
  END IF;

  IF NEW.status = 'cancelled' AND OLD.status IS DISTINCT FROM 'cancelled' THEN
    IF OLD.reference_type IN ('CUSTOMER_RECEIPT', 'SUPPLIER_PAYMENT')
       AND OLD.reference_id IS NOT NULL THEN
      IF NOT v_controlled_cancel THEN
        RAISE EXCEPTION
          'VOUCHER_GL_CANCEL_FORBIDDEN: لا يمكن إلغاء قيد سند (%) خارج RPC الإلغاء المعتمد',
          OLD.entry_number;
      END IF;

      IF OLD.reference_type = 'CUSTOMER_RECEIPT' THEN
        SELECT EXISTS (
          SELECT 1
          FROM public.customer_collections c
          WHERE c.id = OLD.reference_id
            AND c.org_id = OLD.org_id
            AND c.gl_entry_id = OLD.id
            AND c.status = 'draft'
            AND EXISTS (
              SELECT 1
              FROM public.audit_logs a
              WHERE a.org_id = OLD.org_id
                AND a.action = 'voucher_reset_to_draft'
                AND a.entity_type = 'customer_receipt'
                AND a.entity_id = c.id::text
            )
        ) INTO v_voucher_eligible;
      ELSE
        SELECT EXISTS (
          SELECT 1
          FROM public.supplier_payments p
          WHERE p.id = OLD.reference_id
            AND p.org_id = OLD.org_id
            AND p.gl_entry_id = OLD.id
            AND p.status = 'draft'
            AND EXISTS (
              SELECT 1
              FROM public.audit_logs a
              WHERE a.org_id = OLD.org_id
                AND a.action = 'voucher_reset_to_draft'
                AND a.entity_type = 'supplier_payment'
                AND a.entity_id = p.id::text
            )
        ) INTO v_voucher_eligible;
      END IF;

      IF NOT v_voucher_eligible THEN
        RAISE EXCEPTION
          'VOUCHER_GL_CANCEL_SCOPE_INVALID: القيد (%) لا يطابق سندًا مؤهلًا لمسار الإلغاء',
          OLD.entry_number;
      END IF;
    ELSIF OLD.status = 'posted' THEN
      RAISE EXCEPTION
        'POSTED_ENTRY_IMMUTABLE: لا يمكن إلغاء قيد مرحّل (%) — استخدم العكس', OLD.entry_number;
    END IF;
  END IF;

  IF OLD.status IN ('posted', 'reversed') THEN
    IF NEW.entry_date IS DISTINCT FROM OLD.entry_date
       OR NEW.total_debit IS DISTINCT FROM OLD.total_debit
       OR NEW.total_credit IS DISTINCT FROM OLD.total_credit
       OR NEW.journal_id IS DISTINCT FROM OLD.journal_id THEN
      RAISE EXCEPTION 'POSTED_ENTRY_IMMUTABLE: لا يمكن تعديل الحقول المالية لقيد مرحّل (%) — استخدم العكس', OLD.entry_number;
    END IF;

    IF OLD.status = 'posted' AND NEW.status = 'draft' THEN
      IF NOT v_controlled_unpost
         OR OLD.reference_type NOT IN ('CUSTOMER_RECEIPT', 'SUPPLIER_PAYMENT')
         OR OLD.reference_id IS NULL THEN
        RAISE EXCEPTION 'POSTED_ENTRY_IMMUTABLE: لا يمكن إرجاع قيد مرحّل إلى مسودة (%)', OLD.entry_number;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END
$$;


--
-- Name: protect_posted_gl_entry_lines(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_posted_gl_entry_lines() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    v_status TEXT;
    v_entry UUID := COALESCE(NEW.entry_id, OLD.entry_id);
BEGIN
    SELECT status INTO v_status FROM gl_entries WHERE id = v_entry;
    IF v_status IN ('posted', 'reversed') THEN
        RAISE EXCEPTION 'POSTED_ENTRY_IMMUTABLE: لا يمكن تعديل/حذف سطور قيد مرحّل — استخدم العكس';
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: reconcile_account(uuid, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_account(p_account_id uuid, p_reconciliation_date date, p_statement_items jsonb DEFAULT NULL::jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_tenant_id UUID;
    v_reconciliation_id UUID;
    v_opening_balance NUMERIC(18,4);
    v_closing_balance NUMERIC(18,4);
    v_unreconciled_amount NUMERIC(18,4);
    v_item JSONB;
    v_result JSON;
BEGIN
    -- Get tenant context
    v_tenant_id := current_setting('app.current_tenant_id', true)::UUID;
    
    -- Get account balance
    SELECT get_account_balance(p_account_id, p_reconciliation_date, false)
    INTO v_closing_balance;
    
    -- Calculate opening balance
    SELECT get_account_balance(p_account_id, p_reconciliation_date - INTERVAL '1 day', false)
    INTO v_opening_balance;
    
    -- Create reconciliation record
    v_reconciliation_id := gen_random_uuid();
    
    INSERT INTO account_reconciliations (
        id, account_id, reconciliation_date,
        opening_balance, closing_balance,
        reconciled_amount, unreconciled_amount,
        status, tenant_id
    ) VALUES (
        v_reconciliation_id,
        p_account_id,
        p_reconciliation_date,
        v_opening_balance,
        v_closing_balance,
        v_closing_balance - v_opening_balance,
        0,
        'open',
        v_tenant_id
    );
    
    -- Add statement items if provided
    IF p_statement_items IS NOT NULL THEN
        FOR v_item IN SELECT * FROM jsonb_array_elements(p_statement_items)
        LOOP
            INSERT INTO reconciliation_items (
                reconciliation_id,
                statement_date,
                statement_amount,
                statement_reference,
                tenant_id
            ) VALUES (
                v_reconciliation_id,
                (v_item->>'date')::DATE,
                (v_item->>'amount')::NUMERIC(18,4),
                v_item->>'reference',
                v_tenant_id
            );
        END LOOP;
    END IF;
    
    RETURN json_build_object(
        'success', true,
        'reconciliation_id', v_reconciliation_id,
        'opening_balance', v_opening_balance,
        'closing_balance', v_closing_balance,
        'movement', v_closing_balance - v_opening_balance
    );
END;
$$;


--
-- Name: release_expired_reservations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_expired_reservations(p_org_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    UPDATE material_reservations
    SET status = 'expired',
        released_at = NOW(),
        quantity_released = quantity_reserved - quantity_consumed,
        updated_at = NOW()
    WHERE status = 'reserved'
    AND expires_at IS NOT NULL
    AND expires_at < NOW()
    AND (p_org_id IS NULL OR org_id = p_org_id);
    
    GET DIAGNOSTICS v_count = ROW_COUNT;
    
    RETURN v_count;
END;
$$;


--
-- Name: release_manufacturing_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_manufacturing_order(p_mo_id uuid) RETURNS public.manufacturing_orders
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_mo manufacturing_orders;
    v_org UUID;
BEGIN
    -- [120] حارس عضوية على مؤسسة أمر التصنيع
    SELECT org_id INTO v_org FROM manufacturing_orders WHERE id = p_mo_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Manufacturing order not found or invalid status';
    END IF;
    PERFORM public.wardah_assert_org_member(v_org);

    -- تحديث حالة أمر التصنيع لـ RELEASED
    UPDATE manufacturing_orders SET
        status = 'RELEASED',
        start_date = COALESCE(start_date, CURRENT_DATE),
        updated_at = NOW()
    WHERE id = p_mo_id
    AND status IN ('PENDING', 'PLANNED')
    RETURNING * INTO v_mo;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Manufacturing order not found or invalid status';
    END IF;

    RETURN v_mo;
END;
$$;


--
-- Name: reverse_journal_entry_enhanced(uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_journal_entry_enhanced(p_entry_id uuid, p_reversal_reason text DEFAULT NULL::text, p_reversal_date date DEFAULT CURRENT_DATE) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_original_entry RECORD;
    v_reversal_entry_id UUID;
    v_reversal_number TEXT;
    v_line RECORD;
    v_tenant_id UUID;
    v_result JSON;
BEGIN
    -- Get original entry
    SELECT * INTO v_original_entry
    FROM journal_entries
    WHERE id = p_entry_id;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Original entry not found'
        );
    END IF;

    -- [120] tenant من صف القيد + بوابة admin (بدل app.current_tenant_id الميت)
    v_tenant_id := v_original_entry.tenant_id;
    IF v_tenant_id IS NULL THEN
        RAISE EXCEPTION 'ORG_UNRESOLVED';
    END IF;
    PERFORM public.wardah_assert_org_admin(v_tenant_id);

    IF v_original_entry.status != 'posted' THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Can only reverse posted entries'
        );
    END IF;

    IF v_original_entry.reversed_by_entry_id IS NOT NULL THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Entry already reversed'
        );
    END IF;

    -- Generate reversal entry
    v_reversal_entry_id := gen_random_uuid();
    v_reversal_number := generate_entry_number_enhanced(v_original_entry.journal_id, p_reversal_date);

    -- Create reversal entry ([120] المستخدم من auth.uid() بدل app.current_user_id الميت)
    INSERT INTO journal_entries (
        id, journal_id, entry_number, entry_date, posting_date,
        reference_type, reference_id, reference_number,
        description, description_ar,
        status, posted_at, posted_by,
        total_debit, total_credit,
        reversed_by_entry_id, reversal_reason,
        tenant_id, created_by, updated_by
    ) VALUES (
        v_reversal_entry_id,
        v_original_entry.journal_id,
        v_reversal_number,
        p_reversal_date,
        p_reversal_date,
        'reversal',
        p_entry_id,
        'REV-' || v_original_entry.entry_number,
        COALESCE('Reversal: ' || v_original_entry.description, 'Reversal Entry'),
        COALESCE('عكس: ' || v_original_entry.description_ar, 'عكس قيد'),
        'posted',
        CURRENT_TIMESTAMP,
        auth.uid(),
        v_original_entry.total_credit, -- Swap totals
        v_original_entry.total_debit,  -- Swap totals
        NULL,
        p_reversal_reason,
        v_tenant_id,
        auth.uid(),
        auth.uid()
    );

    -- Create reversal lines (swap debit/credit)
    FOR v_line IN
        SELECT * FROM journal_lines
        WHERE entry_id = p_entry_id
        ORDER BY line_number
    LOOP
        INSERT INTO journal_lines (
            entry_id, line_number, account_id,
            cost_center_id, partner_id, product_id, project_id,
            debit, credit, currency_code,
            description, description_ar,
            tenant_id
        ) VALUES (
            v_reversal_entry_id,
            v_line.line_number,
            v_line.account_id,
            v_line.cost_center_id,
            v_line.partner_id,
            v_line.product_id,
            v_line.project_id,
            v_line.credit, -- Swap
            v_line.debit,  -- Swap
            v_line.currency_code,
            'REV: ' || COALESCE(v_line.description, ''),
            'عكس: ' || COALESCE(v_line.description_ar, ''),
            v_tenant_id
        );
    END LOOP;

    -- Update original entry
    UPDATE journal_entries SET
        status = 'reversed',
        reversed_by_entry_id = v_reversal_entry_id,
        reversal_reason = p_reversal_reason,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_entry_id;

    RETURN json_build_object(
        'success', true,
        'message', 'Entry reversed successfully',
        'original_entry_id', p_entry_id,
        'reversal_entry_id', v_reversal_entry_id,
        'reversal_number', v_reversal_number
    );
END;
$$;


--
-- Name: rpc_accept_invitation(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_accept_invitation(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_caller_id    UUID := auth.uid();
    v_caller_email TEXT;
    v_inv          invitations%ROWTYPE;
    v_hash         TEXT;
BEGIN
    IF v_caller_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_AUTHENTICATED'); END IF;
    SELECT email INTO v_caller_email FROM auth.users WHERE id = v_caller_id;
    v_hash := encode(sha256(p_token::bytea), 'hex');
    SELECT * INTO v_inv FROM invitations WHERE token_hash = v_hash FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'INVITATION_NOT_FOUND'); END IF;
    IF v_inv.status != 'pending' THEN RETURN jsonb_build_object('ok', false, 'error', 'INVITATION_ALREADY_USED'); END IF;
    IF v_inv.expires_at < NOW() THEN
        UPDATE invitations SET status = 'expired' WHERE id = v_inv.id;
        RETURN jsonb_build_object('ok', false, 'error', 'INVITATION_EXPIRED');
    END IF;
    IF lower(v_caller_email) != lower(v_inv.email) THEN RETURN jsonb_build_object('ok', false, 'error', 'EMAIL_MISMATCH'); END IF;
    INSERT INTO user_organizations (user_id, org_id, is_active, is_org_admin, joined_at, invited_by)
    VALUES (v_caller_id, v_inv.org_id, true, false, NOW(), v_inv.invited_by)
    ON CONFLICT (user_id, org_id) DO NOTHING;
    IF v_inv.role_ids IS NOT NULL AND array_length(v_inv.role_ids, 1) > 0 THEN
        INSERT INTO user_roles (user_id, role_id, org_id)
        SELECT v_caller_id, role_id, v_inv.org_id FROM unnest(v_inv.role_ids) AS role_id
        ON CONFLICT DO NOTHING;
    END IF;
    UPDATE invitations SET status = 'accepted', accepted_at = NOW() WHERE id = v_inv.id;
    RETURN jsonb_build_object('ok', true, 'org_id', v_inv.org_id);
END;
$$;


--
-- Name: rpc_approve_purchase_order(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_approve_purchase_order(p_org_id uuid, p_purchase_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org uuid;
  v_status text;
  v_lines integer;
BEGIN
  v_org := public.wardah_org_id(p_org_id);
  IF v_org IS NULL THEN RAISE EXCEPTION 'ORG_NOT_RESOLVED'; END IF;
  PERFORM public.wardah_assert_org_admin(v_org);

  IF p_purchase_order_id IS NULL THEN
    RAISE EXCEPTION 'PO_ID_REQUIRED';
  END IF;

  SELECT status INTO v_status
  FROM public.purchase_orders
  WHERE id = p_purchase_order_id AND org_id = v_org
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'PO_NOT_FOUND'; END IF;
  IF v_status NOT IN ('draft', 'submitted') THEN
    RAISE EXCEPTION 'PO_NOT_APPROVABLE: %', v_status;
  END IF;

  SELECT count(*) INTO v_lines
  FROM public.purchase_order_lines
  WHERE purchase_order_id = p_purchase_order_id AND org_id = v_org;

  IF v_lines = 0 THEN RAISE EXCEPTION 'PO_HAS_NO_LINES'; END IF;

  UPDATE public.purchase_orders
  SET status = 'approved'
  WHERE id = p_purchase_order_id;

  RETURN jsonb_build_object(
    'success', true,
    'purchase_order_id', p_purchase_order_id,
    'status', 'approved'
  );
END;
$$;


--
-- Name: rpc_assign_product_base_uom(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_assign_product_base_uom(p_org_id uuid, p_product_id uuid, p_uom_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_current_base uuid;
  v_current_status text;
  v_is_product_specific boolean;
  v_has_movements boolean;
  v_resolved_issues int := 0;
  v_reconciled boolean := false;
BEGIN
  PERFORM public.wardah_assert_org_admin(p_org_id);

  IF p_product_id IS NULL OR p_uom_id IS NULL THEN
    RAISE EXCEPTION 'PRODUCT_AND_UOM_REQUIRED';
  END IF;

  SELECT base_uom_id, uom_migration_status
  INTO v_current_base, v_current_status
  FROM public.products
  WHERE id = p_product_id
    AND org_id = p_org_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PRODUCT_NOT_FOUND_OR_WRONG_ORG';
  END IF;

  SELECT u.is_product_specific
  INTO v_is_product_specific
  FROM public.uoms u
  WHERE u.id = p_uom_id
    AND u.is_active
    AND (u.org_id IS NULL OR u.org_id = p_org_id);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'UOM_NOT_FOUND_OR_INACTIVE: uom=%', p_uom_id;
  END IF;
  IF v_is_product_specific THEN
    RAISE EXCEPTION 'PRODUCT_BASE_UOM_CANNOT_BE_PRODUCT_SPECIFIC: product=%', p_product_id;
  END IF;

  IF v_current_base IS NOT NULL AND v_current_base IS DISTINCT FROM p_uom_id THEN
    RAISE EXCEPTION
      'PRODUCT_BASE_UOM_CHANGE_REQUIRES_ATOMIC_REMAP: product=%, current=%, requested=%',
      p_product_id, v_current_base, p_uom_id;
  END IF;

  IF v_current_base IS NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.stock_ledger_entries sle
      WHERE sle.product_id = p_product_id
        AND sle.org_id = p_org_id
    )
    INTO v_has_movements;

    IF v_has_movements THEN
      RAISE EXCEPTION 'PRODUCT_BASE_UOM_LOCKED_HAS_MOVEMENTS: product=%', p_product_id;
    END IF;
  ELSE
    v_reconciled := true;
  END IF;

  SELECT count(*)
  INTO v_resolved_issues
  FROM public.uom_backfill_issues
  WHERE org_id = p_org_id
    AND source_table = 'products'
    AND source_id = p_product_id
    AND status = 'OPEN';

  UPDATE public.products
  SET base_uom_id = p_uom_id,
      uom_migration_status = 'MAPPED',
      updated_at = v_now
  WHERE id = p_product_id
    AND org_id = p_org_id;

  UPDATE public.uom_backfill_issues
  SET status = 'RESOLVED',
      resolved_uom_id = p_uom_id,
      resolved_by = auth.uid(),
      resolved_at = v_now,
      details = COALESCE(details, '{}'::jsonb)
        || jsonb_build_object(
          'resolution',
          CASE WHEN v_reconciled
            THEN 'reconciled_existing_base_uom'
            ELSE 'auto_on_base_uom_assign'
          END
        )
  WHERE org_id = p_org_id
    AND source_table = 'products'
    AND source_id = p_product_id
    AND status = 'OPEN';

  RETURN jsonb_build_object(
    'success', true,
    'product_id', p_product_id,
    'org_id', p_org_id,
    'base_uom_id', p_uom_id,
    'previous_base_uom_id', v_current_base,
    'previous_uom_migration_status', v_current_status,
    'uom_migration_status', 'MAPPED',
    'reconciled_existing_base_uom', v_reconciled,
    'resolved_issue_count', v_resolved_issues
  );
END;
$$;


--
-- Name: rpc_batch_post_manual_journal_entries(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_batch_post_manual_journal_entries(p_entry_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id uuid;
  v_result jsonb;
  v_results jsonb := '[]'::jsonb;
  v_success integer := 0;
  v_failed integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED'; END IF;
  FOREACH v_id IN ARRAY COALESCE(p_entry_ids,ARRAY[]::uuid[]) LOOP
    BEGIN
      v_result := public.rpc_post_manual_journal_entry(v_id);
      v_success := v_success + 1;
      v_results := v_results || jsonb_build_array(v_result);
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'entry_id',v_id,'success',false,'error',SQLERRM));
    END;
  END LOOP;
  RETURN jsonb_build_object(
    'success',v_failed=0,'total',COALESCE(array_length(p_entry_ids,1),0),
    'success_count',v_success,'fail_count',v_failed,'results',v_results);
END;
$$;


--
-- Name: rpc_cancel_customer_receipt(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_cancel_customer_receipt(p_receipt_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF public.get_current_tenant_id() IS NULL
     OR NOT public.wardah_is_org_member(public.get_current_tenant_id()) THEN
    RAISE EXCEPTION 'TENANT_MEMBERSHIP_REQUIRED';
  END IF;
  PERFORM public.wardah_169_enter_write_context();
  BEGIN
    v_result := public.wardah_169_internal_cancel_customer_receipt(p_receipt_id, p_reason);
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.wardah_169_leave_write_context();
    RAISE;
  END;
  PERFORM public.wardah_169_leave_write_context();
  RETURN v_result;
END $$;


--
-- Name: rpc_cancel_stock_adjustment(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_cancel_stock_adjustment(p_adjustment_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_adj public.stock_adjustments%rowtype;
  v_sle record;
  v_prev record;
  v_prod_qty numeric;
  v_prod_value numeric;
  v_gl jsonb;
  v_lines jsonb;
BEGIN
  SELECT * INTO v_adj
  FROM public.stock_adjustments
  WHERE id = p_adjustment_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ADJUSTMENT_NOT_FOUND'; END IF;

  v_adj.org_id := COALESCE(v_adj.org_id, v_adj.organization_id);
  PERFORM public.wardah_assert_org_admin(v_adj.org_id);

  IF v_adj.status = 'CANCELLED' THEN
    RETURN jsonb_build_object('success', true, 'duplicate', true, 'adjustment_id', v_adj.id);
  END IF;
  IF v_adj.status <> 'SUBMITTED' THEN RAISE EXCEPTION 'ADJUSTMENT_NOT_SUBMITTED'; END IF;
  IF NULLIF(trim(p_reason), '') IS NULL THEN RAISE EXCEPTION 'CANCELLATION_REASON_REQUIRED'; END IF;

  -- Fail closed if a later active movement exists; exact restoration is then unsafe.
  FOR v_sle IN
    SELECT * FROM public.stock_ledger_entries
    WHERE voucher_type = 'Stock Adjustment'
      AND voucher_id = v_adj.id
      AND COALESCE(is_cancelled, false) = false
    ORDER BY posting_datetime DESC, id DESC
  LOOP
    IF EXISTS (
      SELECT 1 FROM public.stock_ledger_entries later
      WHERE later.org_id = v_adj.org_id
        AND later.product_id = v_sle.product_id
        AND later.warehouse_id = v_sle.warehouse_id
        AND COALESCE(later.is_cancelled, false) = false
        AND later.voucher_id <> v_adj.id
        AND (later.posting_datetime, later.id) > (v_sle.posting_datetime, v_sle.id)
    ) THEN
      RAISE EXCEPTION 'LATER_STOCK_MOVEMENT_EXISTS: product=% warehouse=%',
        v_sle.product_id, v_sle.warehouse_id;
    END IF;

    SELECT qty_after_transaction, valuation_rate, stock_value, stock_queue
    INTO v_prev
    FROM public.stock_ledger_entries prev
    WHERE prev.org_id = v_adj.org_id
      AND prev.product_id = v_sle.product_id
      AND prev.warehouse_id = v_sle.warehouse_id
      AND COALESCE(prev.is_cancelled, false) = false
      AND prev.voucher_id <> v_adj.id
      AND (prev.posting_datetime, prev.id) < (v_sle.posting_datetime, v_sle.id)
    ORDER BY prev.posting_datetime DESC, prev.id DESC
    LIMIT 1;

    UPDATE public.stock_ledger_entries
    SET is_cancelled = true, modified_at = now(), modified_by = auth.uid()
    WHERE id = v_sle.id;

    UPDATE public.bins
    SET actual_qty = COALESCE(v_prev.qty_after_transaction, 0),
        valuation_rate = COALESCE(v_prev.valuation_rate, 0),
        stock_value = COALESCE(v_prev.stock_value, 0),
        stock_queue = COALESCE(v_prev.stock_queue, '[]'::jsonb),
        updated_at = now()
    WHERE org_id = v_adj.org_id
      AND product_id = v_sle.product_id
      AND warehouse_id = v_sle.warehouse_id;

    INSERT INTO public.stock_ledger_entries (
      voucher_type, voucher_id, voucher_number, product_id, warehouse_id,
      posting_date, actual_qty, qty_after_transaction, incoming_rate, outgoing_rate,
      valuation_rate, stock_value, stock_value_difference, stock_queue,
      batch_no, serial_nos, is_cancelled, docstatus, org_id, created_by
    ) VALUES (
      'Stock Adjustment Reversal', v_adj.id, 'CANCEL-' || v_adj.adjustment_number,
      v_sle.product_id, v_sle.warehouse_id, CURRENT_DATE,
      -v_sle.actual_qty, COALESCE(v_prev.qty_after_transaction, 0),
      v_sle.outgoing_rate, v_sle.incoming_rate,
      COALESCE(v_prev.valuation_rate, 0), COALESCE(v_prev.stock_value, 0),
      -v_sle.stock_value_difference, COALESCE(v_prev.stock_queue, '[]'::jsonb),
      v_sle.batch_no, v_sle.serial_nos, false, 1, v_adj.org_id, auth.uid()
    );

    SELECT COALESCE(SUM(actual_qty), 0), COALESCE(SUM(stock_value), 0)
    INTO v_prod_qty, v_prod_value
    FROM public.bins
    WHERE org_id = v_adj.org_id AND product_id = v_sle.product_id;

    UPDATE public.products
    SET stock_quantity = v_prod_qty,
        stock_value = v_prod_value,
        cost_price = CASE WHEN v_prod_qty > 0 THEN v_prod_value / v_prod_qty ELSE cost_price END,
        updated_at = now()
    WHERE id = v_sle.product_id AND org_id = v_adj.org_id;
  END LOOP;

  IF v_adj.canonical_gl_entry_id IS NOT NULL THEN
    SELECT jsonb_agg(jsonb_build_object(
      'line_number', line_number,
      'account_id', account_id,
      'debit', credit,
      'credit', debit,
      'currency_code', COALESCE(currency_code, 'SAR'),
      'description', 'Reversal: ' || COALESCE(description, '')
    ) ORDER BY line_number)
    INTO v_lines
    FROM public.gl_entry_lines
    WHERE entry_id = v_adj.canonical_gl_entry_id;

    IF jsonb_array_length(COALESCE(v_lines, '[]'::jsonb)) >= 2 THEN
      v_gl := public.rpc_create_journal_entry(jsonb_build_object(
        'org_id', v_adj.org_id,
        'entry_date', CURRENT_DATE,
        'reference_type', 'Stock Adjustment Reversal',
        'reference_number', 'CANCEL-' || v_adj.adjustment_number,
        'description', 'Reversal: ' || p_reason,
        'idempotency_key', 'stock-adjustment-reversal:' || v_adj.id::text,
        'auto_post', true,
        'lines', v_lines
      ));
    END IF;
  END IF;

  UPDATE public.stock_adjustments
  SET status = 'CANCELLED',
      cancelled_by = auth.uid(),
      cancelled_at = now(),
      cancellation_reason = p_reason,
      canonical_reversal_gl_entry_id = NULLIF(v_gl ->> 'entry_id', '')::uuid,
      updated_by = auth.uid(),
      updated_at = now()
  WHERE id = v_adj.id;

  RETURN jsonb_build_object(
    'success', true,
    'adjustment_id', v_adj.id,
    'reversal_gl_entry_id', NULLIF(v_gl ->> 'entry_id', '')::uuid
  );
END;
$$;


