--
-- Name: rpc_check_and_record_ai_usage(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_check_and_record_ai_usage(p_org_id uuid, p_user_id uuid) RETURNS TABLE(allowed boolean, user_accepted_count integer, org_accepted_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  c_user_daily_limit CONSTANT integer := 20;
  c_org_daily_limit CONSTANT integer := 100;
  v_today date := (now() AT TIME ZONE 'utc')::date;
  v_user_accepted integer;
  v_org_accepted integer;
BEGIN
  IF p_org_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'AI_USAGE_171_NULL_ARGUMENT'
      USING ERRCODE = '22004';
  END IF;

  -- The Edge Function checks membership with the request-bound client, but
  -- this privileged RPC independently validates the supplied pair. A stale,
  -- disabled, or fabricated membership therefore fails closed before the
  -- quota lock or any counter write.
  PERFORM 1
  FROM public.user_organizations AS uo
  WHERE uo.org_id = p_org_id
    AND uo.user_id = p_user_id
    AND uo.is_active IS TRUE
  FOR SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'AI_USAGE_171_ACTIVE_MEMBERSHIP_REQUIRED'
      USING ERRCODE = '42501';
  END IF;

  -- Serialize all requests for one organization and UTC day. Rejections
  -- increment only rejected_count and never consume the shared accepted
  -- quota.
  PERFORM pg_advisory_xact_lock(
    hashtext(p_org_id::text),
    hashtext(v_today::text)
  );

  INSERT INTO public.ai_usage_daily (org_id, user_id, usage_date)
  VALUES (p_org_id, p_user_id, v_today)
  ON CONFLICT ON CONSTRAINT ai_usage_daily_org_user_date_key DO NOTHING;

  SELECT accepted_count
  INTO v_user_accepted
  FROM public.ai_usage_daily
  WHERE org_id = p_org_id
    AND user_id = p_user_id
    AND usage_date = v_today;

  SELECT COALESCE(SUM(accepted_count), 0)::integer
  INTO v_org_accepted
  FROM public.ai_usage_daily
  WHERE org_id = p_org_id
    AND usage_date = v_today;

  IF v_user_accepted >= c_user_daily_limit
     OR v_org_accepted >= c_org_daily_limit THEN
    UPDATE public.ai_usage_daily
    SET rejected_count = rejected_count + 1,
        updated_at = now()
    WHERE org_id = p_org_id
      AND user_id = p_user_id
      AND usage_date = v_today;

    RETURN QUERY SELECT false, v_user_accepted, v_org_accepted;
    RETURN;
  END IF;

  UPDATE public.ai_usage_daily
  SET accepted_count = accepted_count + 1,
      updated_at = now()
  WHERE org_id = p_org_id
    AND user_id = p_user_id
    AND usage_date = v_today
  RETURNING accepted_count INTO v_user_accepted;

  RETURN QUERY SELECT true, v_user_accepted, v_org_accepted + 1;
END;
$$;


--
-- Name: rpc_complete_manufacturing_order(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_complete_manufacturing_order(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_uid uuid;
  v_mo_id uuid;
  v_mo record;
  v_prod record;
  v_done_qty numeric;
  v_wip_cost numeric;
  v_unit_cost numeric;
  v_new_qty numeric;
  v_new_rate numeric;
  v_allow_zero boolean;
  v_warnings jsonb := '[]'::jsonb;
BEGIN
  v_org := public.wardah_org_id(NULLIF(p_payload ->> 'tenant_id', '')::uuid);
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'ORG_NOT_RESOLVED: تعذر تحديد هوية المؤسسة';
  END IF;
  v_uid := auth.uid();
  IF v_uid IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.user_organizations
    WHERE user_id = v_uid AND org_id = v_org
  ) THEN
    RAISE EXCEPTION 'FORBIDDEN_ORG: المستخدم ليس عضواً في المؤسسة المطلوبة';
  END IF;

  v_mo_id := (p_payload ->> 'mo_id')::uuid;
  IF v_mo_id IS NULL THEN
    RAISE EXCEPTION 'INVALID_PAYLOAD: mo_id مطلوب';
  END IF;

  SELECT id, status, quantity, completed_quantity, product_id, total_cost
  INTO v_mo
  FROM public.manufacturing_orders
  WHERE id = v_mo_id AND org_id = v_org
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'MO_NOT_FOUND: أمر التصنيع غير موجود ضمن مؤسستك';
  END IF;

  IF public.normalize_mo_status(v_mo.status) = 'done' THEN
    RETURN jsonb_build_object(
      'success', true,
      'mo_id', v_mo_id,
      'already_done', true,
      'completed_quantity', v_mo.completed_quantity,
      'total_cost', round(COALESCE(v_mo.total_cost, 0), 6)
    );
  END IF;

  IF v_mo.product_id IS NULL THEN
    RAISE EXCEPTION 'MO_NO_PRODUCT: أمر التصنيع بلا منتج تام محدَّد';
  END IF;

  v_done_qty := COALESCE((p_payload ->> 'completed_quantity')::numeric, v_mo.quantity);
  IF v_done_qty IS NULL OR v_done_qty <= 0 THEN
    RAISE EXCEPTION 'INVALID_QUANTITY: الكمية المنجزة يجب أن تكون موجبة';
  END IF;

  SELECT COALESCE(SUM(COALESCE(total_cost, consumed_quantity * COALESCE(unit_cost, 0))), 0)
  INTO v_wip_cost
  FROM public.material_consumption
  WHERE mo_id = v_mo_id AND org_id = v_org;

  v_allow_zero := COALESCE(p_payload ->> 'allow_zero_cost', 'false') = 'true';
  IF v_allow_zero AND NOT EXISTS (
    SELECT 1 FROM public.user_organizations
    WHERE user_id = v_uid AND org_id = v_org
      AND (COALESCE(is_org_admin, false) OR role IN ('admin', 'owner'))
  ) THEN
    v_allow_zero := false;
  END IF;

  IF v_wip_cost <= 0 AND NOT v_allow_zero THEN
    RAISE EXCEPTION 'ZERO_COST_COMPLETION: لا تكلفة مواد مسجَّلة لأمر التصنيع — '
      'الإتمام بتكلفة صفرية مرفوض (يلوّث متوسط تكلفة المنتج). سجّل استهلاك المواد '
      'أولاً، أو مرّر allow_zero_cost=true بصلاحية مدير للإتمام المصرَّح.';
  END IF;

  v_unit_cost := CASE WHEN v_done_qty > 0 THEN v_wip_cost / v_done_qty ELSE 0 END;

  SELECT id, COALESCE(stock_quantity, 0) AS qty, COALESCE(cost_price, 0) AS cost
  INTO v_prod
  FROM public.products
  WHERE id = v_mo.product_id AND org_id = v_org
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ITEM_NOT_FOUND: منتج أمر التصنيع غير موجود ضمن مؤسستك';
  END IF;

  v_new_qty := v_prod.qty + v_done_qty;
  v_new_rate := CASE
    WHEN v_new_qty > 0 THEN (v_prod.qty * v_prod.cost + v_wip_cost) / v_new_qty
    ELSE v_unit_cost
  END;

  UPDATE public.products
  SET stock_quantity = v_new_qty,
      cost_price = v_new_rate,
      updated_at = now()
  WHERE id = v_mo.product_id;

  UPDATE public.manufacturing_orders
  SET status = 'done',
      completed_quantity = v_done_qty,
      total_cost = v_wip_cost,
      unit_cost = v_unit_cost
  WHERE id = v_mo_id;

  IF v_wip_cost > 0 THEN
    PERFORM public.rpc_post_event_journal(
      'MATERIAL_ISSUE', v_wip_cost, 'صرف مواد لأمر تصنيع - ' || v_mo_id::text,
      'MANUFACTURING_ORDER', v_mo_id, v_org, 'MATERIAL_ISSUE:' || v_mo_id::text, NULL
    );
    PERFORM public.rpc_post_event_journal(
      'FG_RECEIPT', v_wip_cost, 'إنتاج تام لأمر تصنيع - ' || v_mo_id::text,
      'MANUFACTURING_ORDER', v_mo_id, v_org, 'FG_RECEIPT:' || v_mo_id::text, NULL
    );
  ELSE
    v_warnings := v_warnings || to_jsonb(
      'إتمام بتكلفة صفرية (مصرَّح allow_zero_cost بصلاحية مدير): لا استهلاك مواد، لا قيد.'::text
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'mo_id', v_mo_id,
    'completed_quantity', v_done_qty,
    'total_cost', round(v_wip_cost, 6),
    'unit_cost', round(v_unit_cost, 6),
    'fg_new_stock', v_new_qty,
    'warnings', v_warnings
  );
END;
$$;


--
-- Name: rpc_consume_reserved_materials(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_consume_reserved_materials(p_mo_id uuid, p_consumptions jsonb) RETURNS jsonb
