--
-- Name: rpc_consume_reserved_materials_v2(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_consume_reserved_materials_v2(p_mo_id uuid, p_stage_id uuid, p_consumptions jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org uuid; v_mo_number text; v_stage uuid:=p_stage_id; v_wip_id uuid;
  v_row jsonb; v_res public.material_reservations%rowtype; v_product uuid;
  v_uom uuid; v_qty_entered numeric; v_qty_base numeric; v_factor numeric;
  v_warehouse uuid; v_count integer; v_remaining numeric; v_work_order uuid;
  v_stock jsonb; v_cogs numeric; v_total_cogs numeric:=0; v_unit_cost numeric;
BEGIN
  SELECT org_id,order_number INTO v_org,v_mo_number
  FROM public.manufacturing_orders WHERE id=p_mo_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MANUFACTURING_ORDER_NOT_FOUND'; END IF;
  PERFORM public.wardah_assert_org_member(v_org);
  IF jsonb_typeof(p_consumptions)<>'array' OR jsonb_array_length(p_consumptions)=0 THEN RAISE EXCEPTION 'CONSUMPTIONS_REQUIRED'; END IF;

  IF v_stage IS NULL THEN
    v_stage:=NULLIF(p_consumptions->0->>'stage_id','')::uuid;
  END IF;
  IF v_stage IS NULL THEN
    SELECT count(*),min(stage_id) INTO v_count,v_stage
    FROM public.stage_wip_log
    WHERE org_id=v_org AND mo_id=p_mo_id AND COALESCE(is_closed,false)=false
      AND CURRENT_DATE BETWEEN period_start AND period_end;
    IF v_count<>1 THEN RAISE EXCEPTION 'STAGE_REQUIRED_FOR_MATERIAL_CONSUMPTION'; END IF;
  END IF;

  SELECT id INTO v_wip_id FROM public.stage_wip_log
  WHERE org_id=v_org AND mo_id=p_mo_id AND stage_id=v_stage
    AND COALESCE(is_closed,false)=false
    AND CURRENT_DATE BETWEEN period_start AND period_end
  ORDER BY period_end DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'OPEN_STAGE_WIP_LOG_NOT_FOUND'; END IF;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_consumptions) LOOP
    IF NULLIF(v_row->>'reservation_id','') IS NOT NULL THEN
      SELECT * INTO v_res FROM public.material_reservations
      WHERE id=(v_row->>'reservation_id')::uuid AND org_id=v_org
        AND mo_id=p_mo_id AND status='reserved' FOR UPDATE;
    ELSE
      SELECT * INTO v_res FROM public.material_reservations
      WHERE org_id=v_org AND mo_id=p_mo_id
        AND item_id=(v_row->>'item_id')::uuid AND status='reserved'
      ORDER BY created_at,id LIMIT 1 FOR UPDATE;
    END IF;
    IF NOT FOUND THEN RAISE EXCEPTION 'ACTIVE_RESERVATION_NOT_FOUND'; END IF;

    v_product:=COALESCE(v_res.product_id,public.wardah_resolve_product_id(v_org,v_res.item_id,now()));
    SELECT COALESCE(NULLIF(v_row->>'uom_id','')::uuid,v_res.uom_id,p.base_uom_id)
      INTO v_uom FROM public.products p WHERE p.id=v_product AND p.org_id=v_org;
    v_qty_entered:=NULLIF(v_row->>'quantity','')::numeric;
    IF v_qty_entered IS NULL OR v_qty_entered<=0 THEN RAISE EXCEPTION 'INVALID_CONSUMPTION_QUANTITY'; END IF;
    v_factor:=public.wardah_uom_factor(v_org,v_product,v_uom,now());
    v_qty_base:=round(v_qty_entered*v_factor,6);

    v_remaining:=v_res.quantity_reserved-COALESCE(v_res.quantity_consumed,0)-COALESCE(v_res.quantity_released,0);
    IF v_qty_base>v_remaining THEN RAISE EXCEPTION 'CONSUMPTION_EXCEEDS_RESERVATION: remaining=%, requested_base=%',v_remaining,v_qty_base; END IF;

    v_warehouse:=NULLIF(v_row->>'warehouse_id','')::uuid;
    IF v_warehouse IS NULL THEN
      SELECT count(*),min(warehouse_id) INTO v_count,v_warehouse
      FROM public.bins WHERE org_id=v_org AND product_id=v_product AND actual_qty>=v_qty_base;
      IF v_count<>1 THEN RAISE EXCEPTION 'WAREHOUSE_REQUIRED_FOR_CONSUMPTION'; END IF;
    END IF;

    v_work_order:=NULLIF(v_row->>'work_order_id','')::uuid;
    IF v_work_order IS NULL THEN
      SELECT count(*),min(id) INTO v_count,v_work_order
      FROM public.work_orders
      WHERE org_id=v_org AND mo_id=p_mo_id AND status NOT IN ('COMPLETED','CANCELLED');
      IF v_count<>1 THEN RAISE EXCEPTION 'WORK_ORDER_REQUIRED_FOR_CONSUMPTION'; END IF;
    ELSIF NOT EXISTS (
      SELECT 1 FROM public.work_orders WHERE id=v_work_order AND org_id=v_org AND mo_id=p_mo_id
    ) THEN RAISE EXCEPTION 'WORK_ORDER_NOT_FOUND_OR_WRONG_MO';
    END IF;

    v_stock:=public.wardah_apply_stock_outgoing(v_org,v_product,v_warehouse,v_qty_base,
      'Material Consumption',p_mo_id,v_mo_number,CURRENT_DATE);
    IF NOT COALESCE((v_stock->>'applied')::boolean,false) THEN RAISE EXCEPTION 'STOCK_OUT_NOT_APPLIED'; END IF;
    v_cogs:=COALESCE((v_stock->>'cogs')::numeric,0);
    v_unit_cost:=CASE WHEN v_qty_base>0 THEN v_cogs/v_qty_base ELSE 0 END;

    INSERT INTO public.material_consumption(
      org_id,work_order_id,mo_id,item_id,product_id,reservation_id,stage_id,
      planned_quantity,consumed_quantity,consumption_type,warehouse_id,
      unit_cost,total_cost,status,consumption_date,notes,created_by,
      uom_id,qty_entered,conversion_factor_snapshot,stock_valuation_result
    ) VALUES (
      v_org,v_work_order,p_mo_id,v_res.item_id,v_product,v_res.id,v_stage,
      v_res.quantity_reserved,v_qty_base,COALESCE(NULLIF(v_row->>'consumption_type',''),'MANUAL'),v_warehouse,
      v_unit_cost,v_cogs,'POSTED',now(),NULLIF(v_row->>'notes',''),auth.uid(),
      v_uom,v_qty_entered,v_factor,v_stock
    );

    UPDATE public.stage_wip_log
    SET cost_material=COALESCE(cost_material,0)+v_cogs,updated_at=now(),updated_by=auth.uid()
    WHERE id=v_wip_id;

    UPDATE public.material_reservations
    SET product_id=v_product,uom_id=v_uom,
        qty_entered=COALESCE(qty_entered,quantity_reserved),
        conversion_factor_snapshot=COALESCE(conversion_factor_snapshot,1),
        quantity_consumed=COALESCE(quantity_consumed,0)+v_qty_base,
        status=CASE WHEN COALESCE(quantity_consumed,0)+v_qty_base+COALESCE(quantity_released,0)>=quantity_reserved
                    THEN 'consumed' ELSE 'reserved' END,
        consumed_at=now(),updated_at=now()
    WHERE id=v_res.id;

    v_total_cogs:=v_total_cogs+v_cogs;
  END LOOP;

  RETURN jsonb_build_object('success',true,'mo_id',p_mo_id,'stage_id',v_stage,
    'stage_wip_log_id',v_wip_id,'consumption_count',jsonb_array_length(p_consumptions),
    'material_cost_posted',round(v_total_cogs,6),'inventory_atomic',true,
    'wip_cost_atomic',true,'uom_atomic',true);
END;
$$;


--
-- Name: rpc_convert_product_uom(uuid, numeric, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_convert_product_uom(p_product_id uuid, p_quantity numeric, p_uom_id uuid, p_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_org uuid; v_base_uom uuid; v_factor numeric; v_base_quantity numeric;
BEGIN
  IF p_quantity IS NULL OR p_quantity<0 THEN RAISE EXCEPTION 'UOM_QUANTITY_MUST_BE_NONNEGATIVE'; END IF;
  SELECT org_id,base_uom_id INTO v_org,v_base_uom FROM public.products WHERE id=p_product_id;
  IF NOT FOUND OR v_org IS NULL THEN RAISE EXCEPTION 'PRODUCT_NOT_FOUND'; END IF;
  PERFORM public.wardah_assert_org_member(v_org);
  v_factor:=public.wardah_uom_factor(v_org,p_product_id,p_uom_id,p_at);
  v_base_quantity:=round(p_quantity*v_factor,6);
  RETURN jsonb_build_object('success',true,'product_id',p_product_id,'uom_id',COALESCE(p_uom_id,v_base_uom),
    'base_uom_id',v_base_uom,'quantity_entered',p_quantity,'conversion_factor',v_factor,'base_quantity',v_base_quantity);
END;
$$;


--
-- Name: rpc_cost_of_production_report(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_cost_of_production_report(p_mo_id uuid, p_stage_no integer DEFAULT NULL::integer, p_tenant uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_org        UUID;
    v_mo         RECORD;
    v_stage      RECORD;
    v_stages     JSONB := '[]'::JSONB;
    v_stage_rpt  JSONB;

    -- أعمدة ديناميكية (org_id/tenant_id على غرار Migrations 67-69)
    v_tenant_col TEXT;
    v_mo_col     TEXT;
    v_stage_col  TEXT;
    v_sql        TEXT;

    -- الخطوة 1: جدول الكميات
    v_units_in           NUMERIC;  -- الوحدات الواجب حسابها
    v_units_out          NUMERIC;  -- الوحدات المحسوبة
    v_qty_balanced       BOOLEAN;

    -- الخطوة 2: EUP
    v_eup_dm             NUMERIC;
    v_eup_cc             NUMERIC;

    -- الخطوة 3: التكاليف الواجب حسابها
    v_cc_cost            NUMERIC;  -- تكاليف التحويل = عمالة + أوفرهيد
    v_costs_in           NUMERIC;

    -- الخطوة 4: تكلفة الوحدة المكافئة
    v_ti_per_eu          NUMERIC := 0;
    v_dm_per_eu          NUMERIC := 0;
    v_cc_per_eu          NUMERIC := 0;
    v_unit_cost_total    NUMERIC := 0;
    v_ti_eup_base        NUMERIC;

    -- الخطوة 5: توزيع التكاليف
    v_cost_completed     NUMERIC;
    v_cost_ending_wip    NUMERIC;
    v_cost_abnormal      NUMERIC;
    v_costs_out          NUMERIC;
    v_reconcile_diff     NUMERIC;
    v_is_balanced        BOOLEAN;

    -- إجماليات على مستوى الأمر كاملاً
    v_grand_costs_in     NUMERIC := 0;
    v_grand_completed    NUMERIC := 0;
    v_grand_ending_wip   NUMERIC := 0;
    v_grand_abnormal     NUMERIC := 0;
    v_all_balanced       BOOLEAN := TRUE;
BEGIN
    -- ===== هوية المؤسسة =====
    v_org := wardah_org_id(p_tenant);
    IF v_org IS NULL THEN
        RAISE EXCEPTION 'ORG_NOT_RESOLVED: تعذر تحديد هوية المؤسسة';
    END IF;

    -- ===== كشف أسماء الأعمدة (نفس نمط Migrations 67-69) =====
    SELECT column_name INTO v_tenant_col
    FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'stage_costs'
      AND column_name IN ('tenant_id', 'org_id')
    ORDER BY CASE column_name WHEN 'tenant_id' THEN 1 ELSE 2 END
    LIMIT 1;

    SELECT column_name INTO v_mo_col
    FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'stage_costs'
      AND column_name IN ('mo_id', 'manufacturing_order_id')
    ORDER BY CASE column_name WHEN 'mo_id' THEN 1 ELSE 2 END
    LIMIT 1;

    SELECT column_name INTO v_stage_col
    FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'stage_costs'
      AND column_name IN ('stage_no', 'stage_number')
    ORDER BY CASE column_name WHEN 'stage_no' THEN 1 ELSE 2 END
    LIMIT 1;

    IF v_tenant_col IS NULL OR v_mo_col IS NULL OR v_stage_col IS NULL THEN
        RAISE EXCEPTION 'SCHEMA_MISMATCH: جدول stage_costs لا يحتوي الأعمدة المتوقعة';
    END IF;

    -- ===== رأس التقرير: بيانات أمر التصنيع =====
    SELECT * INTO v_mo
    FROM manufacturing_orders
    WHERE id = p_mo_id AND org_id = v_org;

    IF v_mo IS NULL THEN
        RAISE EXCEPTION 'MO_NOT_FOUND: أمر التصنيع غير موجود أو لا يتبع مؤسستك';
    END IF;

    -- ===== المرور على المراحل =====
    v_sql := format(
        'SELECT *,
                %I  AS k_stage_no
         FROM stage_costs
         WHERE %I = $1 AND %I = $2
           AND ($3::INTEGER IS NULL OR %I = $3)
         ORDER BY %I',
        v_stage_col, v_tenant_col, v_mo_col, v_stage_col, v_stage_col
    );

    FOR v_stage IN EXECUTE v_sql USING v_org, p_mo_id, p_stage_no
    LOOP
        -- ============================================================
        -- الخطوة 1: جدول الكميات
        -- الوحدات الواجب حسابها = WIP أول المدة + وحدات بدأت
        -- الوحدات المحسوبة = مكتمل + WIP آخر المدة + تالف طبيعي + تالف غير طبيعي
        -- ============================================================
        v_units_in  := COALESCE(v_stage.wip_beginning_qty, 0)
                     + COALESCE(v_stage.input_qty, 0);
        v_units_out := COALESCE(v_stage.good_qty, 0)
                     + COALESCE(v_stage.wip_end_qty, 0)
                     + COALESCE(v_stage.normal_scrap_qty, 0)
                     + COALESCE(v_stage.abnormal_scrap_qty, 0)
                     + COALESCE(v_stage.rework_qty, 0);
        v_qty_balanced := ABS(v_units_in - v_units_out) < 0.000001;

        -- ============================================================
        -- الخطوة 2: EUP — نفس معادلات upsert_stage_cost حرفياً
        -- ============================================================
        IF COALESCE(v_stage.costing_method, 'weighted_average') = 'fifo' THEN
            IF v_stage.k_stage_no = 1 THEN
                v_eup_dm := COALESCE(v_stage.good_qty, 0)
                          + COALESCE(v_stage.wip_end_qty, 0) * COALESCE(v_stage.wip_end_dm_completion_pct, 0) / 100
                          - COALESCE(v_stage.wip_beginning_qty, 0) * COALESCE(v_stage.wip_beginning_dm_completion_pct, 0) / 100;
            ELSE
                v_eup_dm := COALESCE(v_stage.good_qty, 0);
            END IF;
            v_eup_cc := COALESCE(v_stage.good_qty, 0)
                      + COALESCE(v_stage.wip_end_qty, 0) * COALESCE(v_stage.wip_end_cc_completion_pct, 0) / 100
                      - COALESCE(v_stage.wip_beginning_qty, 0) * COALESCE(v_stage.wip_beginning_cc_completion_pct, 0) / 100;
        ELSE
            -- المتوسط المرجّح
            IF v_stage.k_stage_no = 1 THEN
                v_eup_dm := COALESCE(v_stage.good_qty, 0)
                          + COALESCE(v_stage.wip_end_qty, 0) * COALESCE(v_stage.wip_end_dm_completion_pct, 0) / 100;
            ELSE
                v_eup_dm := COALESCE(v_stage.good_qty, 0);
            END IF;
            v_eup_cc := COALESCE(v_stage.good_qty, 0)
                      + COALESCE(v_stage.wip_end_qty, 0) * COALESCE(v_stage.wip_end_cc_completion_pct, 0) / 100;
        END IF;

        -- ============================================================
        -- الخطوة 3: التكاليف الواجب حسابها
        -- WIP أول + محوَّل وارد + مواد + تحويل (عمالة+أوفرهيد) + إعادة طحن − رصيد خردة
        -- ============================================================
        v_cc_cost  := COALESCE(v_stage.dl_cost, 0) + COALESCE(v_stage.moh_cost, 0);
        v_costs_in := COALESCE(v_stage.wip_beginning_cost, 0)
                    + COALESCE(v_stage.transferred_in, 0)
                    + COALESCE(v_stage.dm_cost, 0)
                    + v_cc_cost
                    + COALESCE(v_stage.regrind_proc_cost, 0)
                    - COALESCE(v_stage.waste_credit, 0);

        -- ============================================================
        -- الخطوة 4: تكلفة الوحدة المكافئة لكل عنصر
        -- المحوَّل الوارد مكتمل 100% دائماً ⇒ قاعدته = مكتمل + WIP نهائي كامل
        -- ============================================================
        v_ti_eup_base := COALESCE(v_stage.good_qty, 0) + COALESCE(v_stage.wip_end_qty, 0);

        v_ti_per_eu := CASE WHEN v_ti_eup_base > 0
                            THEN COALESCE(v_stage.transferred_in, 0) / v_ti_eup_base
                            ELSE 0 END;
        v_dm_per_eu := CASE WHEN v_eup_dm > 0
                            THEN COALESCE(v_stage.dm_cost, 0) / v_eup_dm
                            ELSE 0 END;
        -- تكاليف التحويل تشمل تسويات إعادة الطحن ورصيد الخردة (نفس منطق 69)
        v_cc_per_eu := CASE WHEN v_eup_cc > 0
                            THEN (v_cc_cost
                                  + COALESCE(v_stage.regrind_proc_cost, 0)
                                  - COALESCE(v_stage.waste_credit, 0)
                                  + COALESCE(v_stage.wip_beginning_cost, 0)) / v_eup_cc
                            ELSE 0 END;
        v_unit_cost_total := v_ti_per_eu + v_dm_per_eu + v_cc_per_eu;

        -- ============================================================
        -- الخطوة 5: توزيع التكاليف
        -- مكتمل ومحوَّل = بالباقي (يمتص التالف الطبيعي تلقائياً — لا تسريب)
        -- WIP نهائي = كمية × (TI كامل + DM بنسبته + CC بنسبته)
        -- تالف غير طبيعي = القيمة المخزنة (احتُسبت وقت الترحيل — خسارة فترة)
        -- ============================================================
        v_cost_ending_wip := COALESCE(v_stage.wip_end_qty, 0) * (
                                 v_ti_per_eu
                               + v_dm_per_eu * COALESCE(v_stage.wip_end_dm_completion_pct, 0) / 100
                               + v_cc_per_eu * COALESCE(v_stage.wip_end_cc_completion_pct, 0) / 100
                             );
        v_cost_abnormal   := COALESCE(v_stage.abnormal_scrap_cost, 0);
        v_cost_completed  := v_costs_in - v_cost_ending_wip - v_cost_abnormal;

        v_costs_out      := v_cost_completed + v_cost_ending_wip + v_cost_abnormal;
        v_reconcile_diff := v_costs_in - v_costs_out;
        v_is_balanced    := ABS(v_reconcile_diff) < 0.01;

        v_all_balanced     := v_all_balanced AND v_is_balanced AND v_qty_balanced;
        v_grand_costs_in   := v_grand_costs_in   + v_costs_in;
        v_grand_completed  := v_grand_completed  + v_cost_completed;
        v_grand_ending_wip := v_grand_ending_wip + v_cost_ending_wip;
        v_grand_abnormal   := v_grand_abnormal   + v_cost_abnormal;

        -- ===== بناء JSON المرحلة =====
        v_stage_rpt := jsonb_build_object(
            'stage_no',       v_stage.k_stage_no,
            'work_center_id', v_stage.wc_id,
            'costing_method', COALESCE(v_stage.costing_method, 'weighted_average'),
            'mode',           v_stage.mode,

            'quantity_schedule', jsonb_build_object(
                'wip_beginning_qty',   COALESCE(v_stage.wip_beginning_qty, 0),
                'units_started',       COALESCE(v_stage.input_qty, 0),
                'units_to_account',    v_units_in,
                'units_completed',     COALESCE(v_stage.good_qty, 0),
                'wip_ending_qty',      COALESCE(v_stage.wip_end_qty, 0),
                'normal_scrap_qty',    COALESCE(v_stage.normal_scrap_qty, 0),
                'abnormal_scrap_qty',  COALESCE(v_stage.abnormal_scrap_qty, 0),
                'rework_qty',          COALESCE(v_stage.rework_qty, 0),
                'units_accounted',     v_units_out,
                'qty_difference',      v_units_in - v_units_out,
                'is_balanced',         v_qty_balanced
            ),

            'equivalent_units', jsonb_build_object(
                'eup_dm',                       ROUND(v_eup_dm, 6),
                'eup_cc',                       ROUND(v_eup_cc, 6),
                'wip_end_dm_completion_pct',    COALESCE(v_stage.wip_end_dm_completion_pct, 0),
                'wip_end_cc_completion_pct',    COALESCE(v_stage.wip_end_cc_completion_pct, 0),
                'wip_beg_dm_completion_pct',    COALESCE(v_stage.wip_beginning_dm_completion_pct, 0),
                'wip_beg_cc_completion_pct',    COALESCE(v_stage.wip_beginning_cc_completion_pct, 0)
            ),

            'costs_to_account', jsonb_build_object(
                'wip_beginning_cost', COALESCE(v_stage.wip_beginning_cost, 0),
                'transferred_in',     COALESCE(v_stage.transferred_in, 0),
                'direct_materials',   COALESCE(v_stage.dm_cost, 0),
                'direct_labor',       COALESCE(v_stage.dl_cost, 0),
                'overhead_applied',   COALESCE(v_stage.moh_cost, 0),
                'conversion_costs',   v_cc_cost,
                'regrind_cost',       COALESCE(v_stage.regrind_proc_cost, 0),
                'waste_credit',       COALESCE(v_stage.waste_credit, 0),
                'total_costs_in',     ROUND(v_costs_in, 6)
            ),

            'cost_per_eu', jsonb_build_object(
                'transferred_in_per_eu', ROUND(v_ti_per_eu, 6),
                'dm_per_eu',             ROUND(v_dm_per_eu, 6),
                'cc_per_eu',             ROUND(v_cc_per_eu, 6),
                'total_per_eu',          ROUND(v_unit_cost_total, 6),
                'stored_unit_cost',      COALESCE(v_stage.unit_cost, 0)
            ),

            'cost_assignment', jsonb_build_object(
                'completed_and_transferred', ROUND(v_cost_completed, 6),
                'ending_wip',                ROUND(v_cost_ending_wip, 6),
                'abnormal_scrap_loss',       ROUND(v_cost_abnormal, 6),
                'normal_scrap_absorbed',     COALESCE(v_stage.normal_scrap_cost, 0),
                'total_costs_out',           ROUND(v_costs_out, 6)
            ),

            'reconciliation', jsonb_build_object(
                'costs_in',          ROUND(v_costs_in, 6),
                'costs_out',         ROUND(v_costs_out, 6),
                'difference',        ROUND(v_reconcile_diff, 6),
                'is_balanced',       v_is_balanced,
                'stored_total_cost', COALESCE(v_stage.total_cost, 0),
                'stored_vs_computed_diff', ROUND(COALESCE(v_stage.total_cost, 0) - v_cost_completed, 6)
            )
        );

        v_stages := v_stages || v_stage_rpt;
    END LOOP;

    IF jsonb_array_length(v_stages) = 0 THEN
        RAISE EXCEPTION 'NO_STAGE_DATA: لا توجد بيانات مراحل لهذا الأمر%',
            CASE WHEN p_stage_no IS NOT NULL
                 THEN format(' (المرحلة %s)', p_stage_no) ELSE '' END;
    END IF;

    -- ===== التقرير الكامل =====
    RETURN jsonb_build_object(
        'success', TRUE,
        'report_type', 'cost_of_production',
        'generated_at', now(),
        'manufacturing_order', jsonb_build_object(
            'id',             v_mo.id,
            'order_number',   v_mo.order_number,
            'product_id',     v_mo.product_id,
            'status',         v_mo.status,
            'qty_planned',    v_mo.qty_planned
        ),
        'stages', v_stages,
        'totals', jsonb_build_object(
            'total_costs_in',            ROUND(v_grand_costs_in, 6),
            'total_completed',           ROUND(v_grand_completed, 6),
            'total_ending_wip',          ROUND(v_grand_ending_wip, 6),
            'total_abnormal_scrap_loss', ROUND(v_grand_abnormal, 6),
            'all_stages_balanced',       v_all_balanced
        )
    );
END;
$_$;


--
-- Name: rpc_create_customer_receipt(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_customer_receipt(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF public.get_current_tenant_id() IS NULL
     OR NOT public.wardah_is_org_member(public.get_current_tenant_id()) THEN
    RAISE EXCEPTION 'TENANT_MEMBERSHIP_REQUIRED';
  END IF;
  PERFORM public.wardah_169_enter_write_context();
  BEGIN
    v_result := public.wardah_169_internal_create_customer_receipt(p_payload);
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.wardah_169_leave_write_context();
    RAISE;
  END;
  PERFORM public.wardah_169_leave_write_context();
  RETURN v_result;
END $$;


--
-- Name: rpc_create_journal_entry(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_journal_entry(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_org uuid;
    v_journal_id uuid;
    v_entry_id uuid;
    v_entry_number text;
    v_entry_date date;
    v_total_debit numeric := 0;
    v_total_credit numeric := 0;
    v_line_count integer := 0;
    v_idem text;
    v_hash text;
    v_auto_post boolean := COALESCE((p_payload ->> 'auto_post')::boolean, false);
    v_existing record;
    v_constraint text;
BEGIN
    -- Preserve the Migration 76 tenant contract.
    v_org := public.wardah_org_id(NULLIF(p_payload ->> 'org_id', '')::uuid);
    IF v_org IS NULL THEN
        RAISE EXCEPTION 'TENANT_MISSING: تعذر تحديد هوية المؤسسة';
    END IF;

    v_entry_date := COALESCE(NULLIF(p_payload ->> 'entry_date', '')::date, CURRENT_DATE);
    PERFORM public.assert_period_open(v_org, v_entry_date);

    v_idem := NULLIF(p_payload ->> 'idempotency_key', '');
    IF v_idem IS NOT NULL THEN
        -- Match Migration 150's newer convention: canonical jsonb::text, SHA-256,
        -- with idempotency_key intentionally included in request identity.
        v_hash := encode(extensions.digest(convert_to(p_payload::text, 'UTF8'), 'sha256'), 'hex');

        SELECT ge.id, ge.entry_number, ge.request_hash
          INTO v_existing
        FROM public.gl_entries ge
        WHERE ge.org_id = v_org
          AND ge.idempotency_key = v_idem
        LIMIT 1;

        IF FOUND THEN
            IF v_existing.request_hash IS NULL THEN
                RETURN jsonb_build_object(
                    'success', true,
                    'entry_id', v_existing.id,
                    'entry_number', v_existing.entry_number,
                    'duplicate', true,
                    'payload_verified', false,
                    'legacy_replay', true
                );
            END IF;

            IF v_existing.request_hash IS DISTINCT FROM v_hash THEN
                RAISE EXCEPTION
                  'IDEMPOTENCY_KEY_CONFLICT: المفتاح استُخدم سابقًا مع حمولة مختلفة';
            END IF;

            RETURN jsonb_build_object(
                'success', true,
                'entry_id', v_existing.id,
                'entry_number', v_existing.entry_number,
                'duplicate', true,
                'payload_verified', true,
                'legacy_replay', false
            );
        END IF;
    END IF;

    SELECT COALESCE(SUM(COALESCE((l ->> 'debit')::numeric, 0)), 0),
           COALESCE(SUM(COALESCE((l ->> 'credit')::numeric, 0)), 0),
           COUNT(*)
    INTO v_total_debit, v_total_credit, v_line_count
    FROM jsonb_array_elements(p_payload -> 'lines') l;

    IF v_line_count < 2 THEN
        RAISE EXCEPTION 'EMPTY_ENTRY: القيد يحتاج سطرين على الأقل';
    END IF;
    IF round(v_total_debit, 2) <> round(v_total_credit, 2) THEN
        RAISE EXCEPTION 'UNBALANCED_ENTRY: مدين=% دائن=%', v_total_debit, v_total_credit;
    END IF;
    IF round(v_total_debit, 2) = 0 THEN
        RAISE EXCEPTION 'ZERO_ENTRY: قيمة القيد صفر';
    END IF;

    v_journal_id := NULLIF(p_payload ->> 'journal_id', '')::uuid;
    IF v_journal_id IS NULL AND to_regclass('public.journals') IS NOT NULL THEN
        SELECT id INTO v_journal_id
        FROM public.journals
        WHERE org_id = v_org AND is_active = true
        ORDER BY created_at ASC
        LIMIT 1;
    END IF;

    BEGIN
        v_entry_number := public.generate_entry_number(v_journal_id);
    EXCEPTION WHEN OTHERS THEN
        BEGIN
            v_entry_number := public.generate_entry_number(v_org, v_entry_date);
        EXCEPTION WHEN OTHERS THEN
            v_entry_number := 'JE-' || to_char(v_entry_date, 'YYYY') || '-' ||
                              lpad(floor(random() * 1000000)::text, 6, '0');
        END;
    END;

    INSERT INTO public.gl_entries (
        org_id, journal_id, entry_number, entry_date, entry_type,
        description, description_ar, reference_type, reference_number,
        status, total_debit, total_credit, idempotency_key, request_hash
    ) VALUES (
        v_org, v_journal_id, v_entry_number, v_entry_date, 'manual',
        NULLIF(p_payload ->> 'description', ''),
        NULLIF(p_payload ->> 'description_ar', ''),
        NULLIF(p_payload ->> 'reference_type', ''),
        NULLIF(p_payload ->> 'reference_number', ''),
        'draft', v_total_debit, v_total_credit, v_idem, v_hash
    )
    RETURNING id INTO v_entry_id;

    INSERT INTO public.gl_entry_lines (
        org_id, tenant_id, entry_id, line_number, account_id,
        debit, credit, currency_code, description, description_ar
    )
    SELECT
        v_org, v_org, v_entry_id,
        COALESCE((l.value ->> 'line_number')::int, l.ord::int),
        (l.value ->> 'account_id')::uuid,
        COALESCE((l.value ->> 'debit')::numeric, 0),
        COALESCE((l.value ->> 'credit')::numeric, 0),
        COALESCE(NULLIF(l.value ->> 'currency_code', ''), 'SAR'),
        NULLIF(l.value ->> 'description', ''),
        NULLIF(l.value ->> 'description_ar', '')
    FROM jsonb_array_elements(p_payload -> 'lines') WITH ORDINALITY AS l(value, ord);

    IF v_auto_post THEN
        UPDATE public.gl_entries
        SET status = 'posted', posted_at = NOW()
        WHERE id = v_entry_id;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'entry_id', v_entry_id,
        'entry_number', v_entry_number,
        'total_debit', v_total_debit,
        'total_credit', v_total_credit,
        'status', CASE WHEN v_auto_post THEN 'posted' ELSE 'draft' END,
        'duplicate', false,
        'payload_verified', (v_idem IS NOT NULL),
        'legacy_replay', false
    );

EXCEPTION
    WHEN unique_violation THEN
        -- gl_entries has more than one unique boundary. Only the Migration 76
        -- idempotency index is eligible for replay handling; all others keep the
        -- original PostgreSQL error unchanged.
        GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
        IF v_idem IS NULL OR v_constraint IS DISTINCT FROM 'uq_gl_entries_org_idem' THEN
            RAISE;
        END IF;

        SELECT ge.id, ge.entry_number, ge.request_hash
          INTO v_existing
        FROM public.gl_entries ge
        WHERE ge.org_id = v_org
          AND ge.idempotency_key = v_idem
        LIMIT 1;

        IF NOT FOUND THEN
            RAISE;
        END IF;

        IF v_existing.request_hash IS NULL THEN
            -- Compatibility only for a historical keyed row. 179 never fills it.
            RETURN jsonb_build_object(
                'success', true,
                'entry_id', v_existing.id,
                'entry_number', v_existing.entry_number,
                'duplicate', true,
                'payload_verified', false,
                'legacy_replay', true
            );
        END IF;

        IF v_existing.request_hash IS DISTINCT FROM v_hash THEN
            RAISE EXCEPTION
              'IDEMPOTENCY_KEY_CONFLICT: المفتاح استُخدم سابقًا مع حمولة مختلفة';
        END IF;

        RETURN jsonb_build_object(
            'success', true,
            'entry_id', v_existing.id,
            'entry_number', v_existing.entry_number,
            'duplicate', true,
            'payload_verified', true,
            'legacy_replay', false
        );
END;
$$;


--
-- Name: rpc_create_manual_journal_entry(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_manual_journal_entry(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_payload jsonb;
  v_result jsonb;
  v_entry uuid;
  v_client_idem text;
  v_internal_idem text;
  v_existing_origin text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED'; END IF;

  v_org := public.wardah_org_id(NULLIF(p_payload->>'org_id','')::uuid);
  PERFORM public.wardah_178_assert_permission(v_org, 'accounting.journals.create');

  IF COALESCE((p_payload->>'auto_post')::boolean, false) THEN
    RAISE EXCEPTION 'JOURNAL_AUTO_POST_FORBIDDEN: use rpc_post_manual_journal_entry';
  END IF;

  PERFORM public.wardah_178_validate_manual_lines(v_org, p_payload->'lines');

  v_client_idem := NULLIF(p_payload->>'idempotency_key','');
  IF v_client_idem IS NOT NULL THEN
    v_internal_idem := 'manual:' || v_org::text || ':' || v_client_idem;
    SELECT journal_origin INTO v_existing_origin
    FROM public.gl_entries
    WHERE org_id = v_org AND idempotency_key = v_internal_idem
    LIMIT 1;
    IF v_existing_origin IS NOT NULL
       AND v_existing_origin NOT IN ('manual','manual_legacy') THEN
      RAISE EXCEPTION 'JOURNAL_IDEMPOTENCY_NAMESPACE_COLLISION';
    END IF;
  END IF;

  v_payload := p_payload || jsonb_build_object(
    'org_id', v_org::text,
    'auto_post', false
  );
  IF v_internal_idem IS NOT NULL THEN
    v_payload := v_payload || jsonb_build_object('idempotency_key', v_internal_idem);
  ELSE
    v_payload := v_payload - 'idempotency_key';
  END IF;

  v_result := public.rpc_create_journal_entry(v_payload);
  v_entry := NULLIF(v_result->>'entry_id','')::uuid;
  IF v_entry IS NULL THEN RAISE EXCEPTION 'JOURNAL_CREATE_RETURNED_NO_ENTRY'; END IF;

  UPDATE public.gl_entries
  SET journal_origin = 'manual',
      created_by = COALESCE(created_by, v_uid),
      updated_at = now()
  WHERE id = v_entry AND org_id = v_org
    AND journal_origin IN ('system','manual','manual_legacy');

  IF NOT FOUND THEN RAISE EXCEPTION 'JOURNAL_CREATE_ORIGIN_MISMATCH'; END IF;

  INSERT INTO public.audit_logs(org_id,user_id,action,entity_type,entity_id,metadata)
  VALUES (v_org,v_uid,'journal.manual.create','gl_entry',v_entry::text,
          jsonb_build_object('migration',178));

  RETURN v_result || jsonb_build_object('journal_origin','manual');
END;
$$;


--
-- Name: rpc_create_matched_supplier_invoice(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_matched_supplier_invoice(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org            uuid;
  v_vendor         uuid;
  v_invoice_number text;
  v_idem           text;
  v_hash           text;
  v_existing       record;
  v_bad_grn        record;
  v_result         jsonb;
  v_invoice_id     uuid;
BEGIN
  v_org            := NULLIF(p_payload ->> 'org_id', '')::uuid;
  v_vendor         := NULLIF(p_payload ->> 'vendor_id', '')::uuid;
  v_invoice_number := btrim(COALESCE(p_payload ->> 'invoice_number', ''));
  v_idem           := NULLIF(btrim(COALESCE(p_payload ->> 'idempotency_key', '')), '');

  PERFORM public.wardah_assert_org_member(v_org);
  IF NOT public.has_permission(auth.uid(), v_org, 'purchasing.purchase_invoices.approve') THEN
    RAISE EXCEPTION
      'AP_POST_PERMISSION_DENIED: هذا المسار ينشئ الفاتورة ويرحّل قيدها معًا، ويتطلب صلاحية purchasing.purchase_invoices.approve';
  END IF;

  IF v_idem IS NULL THEN
    RAISE EXCEPTION 'AP_IDEMPOTENCY_KEY_REQUIRED: مفتاح إعادة المحاولة مطلوب للمطابقة الذرية';
  END IF;

  v_hash := encode(extensions.digest(convert_to(p_payload::text, 'UTF8'), 'sha256'), 'hex');

  SELECT id, request_hash, journal_entry_id, subtotal, tax_amount, total_amount
    INTO v_existing
  FROM public.supplier_invoices
  WHERE org_id = v_org AND idempotency_key = v_idem;

  IF FOUND THEN
    IF v_existing.request_hash IS DISTINCT FROM v_hash THEN
      RAISE EXCEPTION
        'AP_IDEMPOTENCY_KEY_REUSED: المفتاح استُخدم سابقًا مع حمولة مختلفة';
    END IF;

    RETURN jsonb_build_object(
      'success', true,
      'idempotent_replay', true,
      'invoice_id', v_existing.id,
      'invoice_status', 'approved',
      'journal_entry_id', v_existing.journal_entry_id,
      'journal_status', 'posted',
      'subtotal', v_existing.subtotal,
      'tax_amount', v_existing.tax_amount,
      'total_amount', v_existing.total_amount
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.supplier_invoices si
    WHERE si.org_id = v_org
      AND si.vendor_id = v_vendor
      AND si.match_status = 'matched'
      AND upper(btrim(si.invoice_number)) = upper(v_invoice_number)
  ) THEN
    RAISE EXCEPTION
      'AP_DUPLICATE_VENDOR_INVOICE_NUMBER: رقم فاتورة المورد مستخدم مسبقًا داخل المؤسسة والمورد';
  END IF;

  IF jsonb_typeof(p_payload -> 'lines') <> 'array'
     OR jsonb_array_length(p_payload -> 'lines') = 0 THEN
    RAISE EXCEPTION 'AP_LINES_REQUIRED: الفاتورة تحتاج سطرًا واحدًا على الأقل';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_payload -> 'lines') l
    GROUP BY NULLIF(l ->> 'goods_receipt_line_id', '')::uuid
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION
      'AP_DUPLICATE_GRN_LINE: لا يجوز تكرار سطر الاستلام نفسه أكثر من مرة داخل الفاتورة';
  END IF;

  SELECT gr.id, gr.status
    INTO v_bad_grn
  FROM jsonb_array_elements(p_payload -> 'lines') l
  JOIN public.goods_receipt_lines grl
    ON grl.id = NULLIF(l ->> 'goods_receipt_line_id', '')::uuid
  JOIN public.goods_receipts gr ON gr.id = grl.goods_receipt_id
  WHERE gr.org_id <> v_org
     OR gr.status NOT IN ('confirmed', 'posted')
  ORDER BY gr.id
  LIMIT 1;

  IF FOUND THEN
    IF EXISTS (
      SELECT 1 FROM public.goods_receipts gr
      WHERE gr.id = v_bad_grn.id AND gr.org_id <> v_org
    ) THEN
      RAISE EXCEPTION 'AP_CROSS_ORG_REFERENCE: سند الاستلام خارج المؤسسة';
    END IF;
    RAISE EXCEPTION
      'AP_GRN_NOT_INVOICEABLE: حالة سند الاستلام % لا تسمح بالفوترة',
      v_bad_grn.status;
  END IF;

  v_result := public.rpc_create_matched_supplier_invoice_v149(p_payload);
  v_invoice_id := NULLIF(v_result ->> 'invoice_id', '')::uuid;

  IF v_invoice_id IS NULL THEN
    RAISE EXCEPTION 'AP_MATCHED_INVOICE_ID_MISSING: تنفيذ 149 لم يُعد معرّف الفاتورة — %', v_result;
  END IF;

  UPDATE public.supplier_invoices
  SET idempotency_key = v_idem,
      request_hash = v_hash,
      updated_at = now()
  WHERE id = v_invoice_id;

  RETURN v_result || jsonb_build_object('idempotency_key', v_idem);
EXCEPTION
  WHEN unique_violation THEN
    IF EXISTS (
      SELECT 1 FROM public.supplier_invoices si
      WHERE si.org_id = v_org
        AND si.idempotency_key = v_idem
        AND si.request_hash = v_hash
    ) THEN
      SELECT id, request_hash, journal_entry_id, subtotal, tax_amount, total_amount
        INTO v_existing
      FROM public.supplier_invoices
      WHERE org_id = v_org AND idempotency_key = v_idem;
      RETURN jsonb_build_object(
        'success', true,
        'idempotent_replay', true,
        'invoice_id', v_existing.id,
        'invoice_status', 'approved',
        'journal_entry_id', v_existing.journal_entry_id,
        'journal_status', 'posted',
        'subtotal', v_existing.subtotal,
        'tax_amount', v_existing.tax_amount,
        'total_amount', v_existing.total_amount
      );
    END IF;
    RAISE EXCEPTION
      'AP_DUPLICATE_VENDOR_INVOICE_NUMBER: رقم فاتورة المورد أو مفتاح إعادة المحاولة مستخدم مسبقًا';
END $$;


--
-- Name: rpc_create_matched_supplier_invoice_v149(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_matched_supplier_invoice_v149(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org             uuid;
  v_vendor          uuid;
  v_invoice_number  text;
  v_number_norm     text;
  v_invoice_date    date;
  v_due_date        date;
  v_idem_invoice    text;
  v_idem_journal    text;
  v_existing        record;
  v_line            jsonb;
  v_invoice_id      uuid;
  v_invoice_line_id uuid;
  v_line_no         integer := 0;
  v_grl             record;
  v_pol             record;
  v_available       numeric(18,6);
  v_qty             numeric(18,6);
  v_qty_raw         numeric;
  v_price           numeric(18,6);
  v_disc            numeric(5,2);
  v_tax             numeric(5,2);
  v_net             numeric(18,6);
  v_goods_total     numeric(18,2) := 0;
  v_vat_total       numeric(18,2) := 0;
  v_map_goods       record;
  v_map_vat         record;
  v_acc_grni        uuid;
  v_acc_vat         uuid;
  v_acc_ap          uuid;
  v_journal         jsonb;
  v_entry_id        uuid;
  v_entry_status    text;
  v_drift           numeric(18,6);
  v_lines           jsonb;
BEGIN
  v_org := NULLIF(p_payload ->> 'org_id', '')::uuid;
  PERFORM public.wardah_assert_org_member(v_org);

  IF NOT public.has_permission(auth.uid(), v_org, 'purchasing.purchase_invoices.approve') THEN
    RAISE EXCEPTION
      'AP_POST_PERMISSION_DENIED: هذا المسار ينشئ الفاتورة ويرحّل قيدها معًا، ويتطلب صلاحية purchasing.purchase_invoices.approve';
  END IF;

  v_vendor         := NULLIF(p_payload ->> 'vendor_id', '')::uuid;
  v_invoice_number := btrim(COALESCE(p_payload ->> 'invoice_number', ''));
  v_number_norm    := upper(v_invoice_number);
  v_invoice_date   := COALESCE(NULLIF(p_payload ->> 'invoice_date', '')::date, CURRENT_DATE);
  v_due_date       := NULLIF(p_payload ->> 'due_date', '')::date;

  IF v_vendor IS NULL THEN
    RAISE EXCEPTION 'AP_VENDOR_REQUIRED: معرّف المورد مطلوب';
  END IF;
  IF v_invoice_number = '' THEN
    RAISE EXCEPTION 'AP_INVOICE_NUMBER_REQUIRED: رقم فاتورة المورد مطلوب';
  END IF;
  IF v_due_date IS NOT NULL AND v_due_date < v_invoice_date THEN
    RAISE EXCEPTION 'AP_DUE_DATE_BEFORE_INVOICE_DATE: تاريخ الاستحقاق قبل تاريخ الفاتورة';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.vendors v WHERE v.id = v_vendor AND v.org_id = v_org) THEN
    RAISE EXCEPTION 'AP_VENDOR_MISMATCH: المورد لا ينتمي إلى المؤسسة المحددة';
  END IF;

  PERFORM public.assert_period_open(v_org, v_invoice_date);

  v_idem_invoice := 'ap-invoice:' || v_org::text || ':' || v_vendor::text || ':' || v_number_norm;

  SELECT id, journal_entry_id, total_amount INTO v_existing
  FROM public.supplier_invoices
  WHERE org_id = v_org AND idempotency_key = v_idem_invoice;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'idempotent_replay', true,
      'invoice_id', v_existing.id,
      'journal_entry_id', v_existing.journal_entry_id,
      'total_amount', v_existing.total_amount
    );
  END IF;

  IF jsonb_typeof(p_payload -> 'lines') <> 'array'
     OR jsonb_array_length(p_payload -> 'lines') = 0 THEN
    RAISE EXCEPTION 'AP_LINES_REQUIRED: الفاتورة تحتاج سطرًا واحدًا على الأقل';
  END IF;

  PERFORM 1
  FROM public.purchase_order_lines pol
  WHERE pol.id IN (
    SELECT grl.purchase_order_line_id
    FROM public.goods_receipt_lines grl
    WHERE grl.id IN (
      SELECT (l ->> 'goods_receipt_line_id')::uuid
      FROM jsonb_array_elements(p_payload -> 'lines') l
    )
  )
  ORDER BY pol.id
  FOR UPDATE;

  PERFORM 1
  FROM public.goods_receipt_lines grl
  WHERE grl.id IN (
    SELECT (l ->> 'goods_receipt_line_id')::uuid
    FROM jsonb_array_elements(p_payload -> 'lines') l
  )
  ORDER BY grl.id
  FOR UPDATE;

  INSERT INTO public.supplier_invoices (
    org_id, invoice_number, vendor_id, invoice_date, due_date,
    subtotal, tax_amount, total_amount, status,
    idempotency_key, match_status, matched_at, matched_by, created_by
  ) VALUES (
    v_org, v_invoice_number, v_vendor, v_invoice_date, v_due_date,
    0, 0, 0, 'approved',
    v_idem_invoice, 'matched', now(), auth.uid(), auth.uid()
  )
  RETURNING id INTO v_invoice_id;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_payload -> 'lines')
  LOOP
    v_line_no := v_line_no + 1;

    SELECT grl.*, gr.org_id AS receipt_org
      INTO v_grl
    FROM public.goods_receipt_lines grl
    JOIN public.goods_receipts gr ON gr.id = grl.goods_receipt_id
    WHERE grl.id = (v_line ->> 'goods_receipt_line_id')::uuid;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'AP_GRN_LINE_NOT_FOUND: سطر استلام غير موجود (السطر %)', v_line_no;
    END IF;
    IF v_grl.org_id <> v_org OR v_grl.receipt_org <> v_org THEN
      RAISE EXCEPTION 'AP_CROSS_ORG_REFERENCE: سطر الاستلام خارج المؤسسة (السطر %)', v_line_no;
    END IF;
    IF v_grl.quality_status <> 'accepted' THEN
      RAISE EXCEPTION
        'AP_GRN_LINE_NOT_ACCEPTED: لا تُفوتر كمية غير مقبولة — حالة الجودة % (السطر %)',
        v_grl.quality_status, v_line_no;
    END IF;
    IF v_grl.purchase_order_line_id IS NULL THEN
      RAISE EXCEPTION
        'AP_GRN_LINE_WITHOUT_PO: هذا المسار للفواتير المستندة إلى أمر شراء (السطر %)', v_line_no;
    END IF;

    SELECT pol.*, po.status AS order_status, po.vendor_id AS order_vendor
      INTO v_pol
    FROM public.purchase_order_lines pol
    JOIN public.purchase_orders po ON po.id = pol.purchase_order_id
    WHERE pol.id = v_grl.purchase_order_line_id;

    IF v_pol.org_id <> v_org THEN
      RAISE EXCEPTION 'AP_CROSS_ORG_REFERENCE: سطر أمر الشراء خارج المؤسسة (السطر %)', v_line_no;
    END IF;
    IF v_pol.order_vendor <> v_vendor THEN
      RAISE EXCEPTION 'AP_VENDOR_MISMATCH: أمر الشراء يخص موردًا آخر (السطر %)', v_line_no;
    END IF;
    IF v_pol.order_status NOT IN ('approved', 'partially_received', 'fully_received', 'received', 'closed') THEN
      RAISE EXCEPTION
        'AP_PO_NOT_INVOICEABLE: حالة أمر الشراء % لا تسمح بالفوترة (السطر %)',
        v_pol.order_status, v_line_no;
    END IF;
    IF v_pol.product_id <> v_grl.product_id THEN
      RAISE EXCEPTION 'AP_PRODUCT_MISMATCH: المنتج يختلف بين الأمر والاستلام (السطر %)', v_line_no;
    END IF;

    v_qty_raw := (v_line ->> 'quantity_base')::numeric;
    IF v_qty_raw IS NULL OR v_qty_raw <= 0 THEN
      RAISE EXCEPTION 'AP_QUANTITY_INVALID: الكمية يجب أن تكون موجبة (السطر %)', v_line_no;
    END IF;
    IF v_qty_raw <> round(v_qty_raw, 6) THEN
      RAISE EXCEPTION
        'AP_QUANTITY_PRECISION: الكمية % تتجاوز ست منازل عشرية — الفوترة لا تقرّب الكمية صامتًا (السطر %)',
        v_qty_raw, v_line_no;
    END IF;
    v_qty := v_qty_raw;

    v_available := public.wardah_receipt_line_uninvoiced_base(v_grl.id);
    IF v_qty > v_available THEN
      RAISE EXCEPTION
        'AP_QUANTITY_EXCEEDS_RECEIPT: المطلوب % والمتاح المقبول غير المفوتر % (السطر %)',
        v_qty, v_available, v_line_no;
    END IF;

    v_price := (v_line ->> 'unit_price')::numeric;
    IF v_price IS NULL OR v_price < 0 THEN
      RAISE EXCEPTION 'AP_PRICE_INVALID: سعر الوحدة مطلوب وغير سالب (السطر %)', v_line_no;
    END IF;
    IF round(v_price, 6) <> round(COALESCE(v_pol.unit_price, -1), 6) THEN
      RAISE EXCEPTION
        'AP_PRICE_VARIANCE_REQUIRES_APPROVAL: سعر الفاتورة % يخالف لقطة أمر الشراء % (السطر %)',
        v_price, v_pol.unit_price, v_line_no;
    END IF;

    v_disc := COALESCE((v_line ->> 'discount_percentage')::numeric, COALESCE(v_pol.discount_percentage, 0));
    v_tax  := COALESCE((v_line ->> 'tax_percentage')::numeric, COALESCE(v_pol.tax_percentage, 0));

    INSERT INTO public.supplier_invoice_lines (
      org_id, supplier_invoice_id, goods_receipt_line_id, purchase_order_line_id,
      line_number, product_id, quantity, unit_cost,
      discount_percentage, tax_percentage,
      uom_id, conversion_factor_snapshot, po_unit_price_snapshot,
      quantity_variance, price_variance, match_status
    ) VALUES (
      v_org, v_invoice_id, v_grl.id, v_pol.id,
      v_line_no, v_grl.product_id, v_qty, v_price,
      v_disc, v_tax,
      v_grl.uom_id, v_grl.conversion_factor_snapshot, v_pol.unit_price,
      0, 0, 'matched'
    )
    RETURNING id INTO v_invoice_line_id;

    INSERT INTO public.supplier_invoice_receipt_allocations (
      org_id, supplier_invoice_id, supplier_invoice_line_id,
      goods_receipt_line_id, purchase_order_line_id,
      quantity_base, idempotency_key, created_by
    ) VALUES (
      v_org, v_invoice_id, v_invoice_line_id,
      v_grl.id, v_pol.id,
      v_qty, v_idem_invoice || ':' || v_line_no::text, auth.uid()
    );

    v_net         := v_qty * v_price * (1 - v_disc / 100);
    v_goods_total := v_goods_total + round(v_net, 2);
    v_vat_total   := v_vat_total   + round(v_net * v_tax / 100, 2);
  END LOOP;

  SELECT max(over_alloc) INTO v_drift
  FROM (
    SELECT SUM(CASE WHEN a.reversal_of_allocation_id IS NULL
                    THEN a.quantity_base ELSE -a.quantity_base END)
             - CASE WHEN grl.quality_status = 'accepted'
                    THEN COALESCE(grl.received_quantity, 0) ELSE 0 END AS over_alloc
    FROM public.supplier_invoice_receipt_allocations a
    JOIN public.goods_receipt_lines grl ON grl.id = a.goods_receipt_line_id
    WHERE a.goods_receipt_line_id IN (
      SELECT goods_receipt_line_id
      FROM public.supplier_invoice_receipt_allocations
      WHERE supplier_invoice_id = v_invoice_id
    )
    GROUP BY a.goods_receipt_line_id, grl.quality_status, grl.received_quantity
  ) s;

  IF COALESCE(v_drift, 0) > 0 THEN
    RAISE EXCEPTION 'AP_ALLOCATION_EXCEEDS_RECEIPT: التخصيصات تتجاوز المقبول بمقدار %', v_drift;
  END IF;

  SELECT max(over_alloc) INTO v_drift
  FROM (
    SELECT SUM(CASE WHEN a.reversal_of_allocation_id IS NULL
                    THEN a.quantity_base ELSE -a.quantity_base END)
             - COALESCE(pol.accepted_quantity, 0) AS over_alloc
    FROM public.supplier_invoice_receipt_allocations a
    JOIN public.purchase_order_lines pol ON pol.id = a.purchase_order_line_id
    WHERE a.purchase_order_line_id IN (
      SELECT purchase_order_line_id
      FROM public.supplier_invoice_receipt_allocations
      WHERE supplier_invoice_id = v_invoice_id
    )
    GROUP BY a.purchase_order_line_id, pol.accepted_quantity
  ) s;

  IF COALESCE(v_drift, 0) > 0 THEN
    RAISE EXCEPTION
      'AP_ALLOCATION_EXCEEDS_PO_ACCEPTED: تخصيصات سطر الأمر تتجاوز المقبول المسجّل بمقدار % — انحراف بين تراكم الأمر وسطور الاستلام',
      v_drift;
  END IF;

  IF v_goods_total + v_vat_total <= 0 THEN
    RAISE EXCEPTION 'AP_ZERO_INVOICE: إجمالي الفاتورة صفر أو سالب';
  END IF;

  UPDATE public.supplier_invoices
  SET subtotal     = v_goods_total,
      tax_amount   = v_vat_total,
      total_amount = v_goods_total + v_vat_total,
      updated_at   = now()
  WHERE id = v_invoice_id;

  SELECT * INTO v_map_goods FROM public.gl_event_mappings
  WHERE org_id = v_org AND event_code = 'AP_MATCHED_INVOICE_GOODS'
    AND work_center_code IS NULL AND is_active = true
  LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION
      'AP_ACCOUNT_MAPPING_MISSING: لا خريطة للحدث AP_MATCHED_INVOICE_GOODS (مدين تصفية GRNI / دائن الذمم الدائنة)';
  END IF;

  SELECT * INTO v_map_vat FROM public.gl_event_mappings
  WHERE org_id = v_org AND event_code = 'AP_MATCHED_INVOICE_VAT'
    AND work_center_code IS NULL AND is_active = true
  LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION
      'AP_ACCOUNT_MAPPING_MISSING: لا خريطة للحدث AP_MATCHED_INVOICE_VAT (مدين ضريبة المدخلات / دائن الذمم الدائنة)';
  END IF;

  IF v_map_goods.credit_account_code <> v_map_vat.credit_account_code THEN
    RAISE EXCEPTION
      'AP_ACCOUNT_MAPPING_INCONSISTENT: خريطتا البضاعة والضريبة تدلّان على حسابي دائن مختلفين (% و%) — الذمم الدائنة حساب واحد في هذا القيد',
      v_map_goods.credit_account_code, v_map_vat.credit_account_code;
  END IF;

  SELECT id INTO v_acc_grni FROM public.gl_accounts
  WHERE org_id = v_org AND code = v_map_goods.debit_account_code;
  SELECT id INTO v_acc_vat  FROM public.gl_accounts
  WHERE org_id = v_org AND code = v_map_vat.debit_account_code;
  SELECT id INTO v_acc_ap   FROM public.gl_accounts
  WHERE org_id = v_org AND code = v_map_goods.credit_account_code;

  IF v_acc_grni IS NULL OR v_acc_vat IS NULL OR v_acc_ap IS NULL THEN
    RAISE EXCEPTION
      'AP_ACCOUNT_NOT_FOUND: حساب من حسابات القيد غير موجود (GRNI=% VAT=% AP=%)',
      v_map_goods.debit_account_code, v_map_vat.debit_account_code, v_map_goods.credit_account_code;
  END IF;

  v_idem_journal := 'ap-invoice-journal:' || v_invoice_id::text;

  v_lines := jsonb_build_array(
    jsonb_build_object('line_number', 1, 'account_id', v_acc_grni,
                       'debit', v_goods_total, 'credit', 0,
                       'description', 'GRNI clearing')
  );
  IF v_vat_total > 0 THEN
    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object('line_number', 2, 'account_id', v_acc_vat,
                         'debit', v_vat_total, 'credit', 0,
                         'description', 'Input VAT')
    );
  END IF;
  v_lines := v_lines || jsonb_build_array(
    jsonb_build_object('line_number', 3, 'account_id', v_acc_ap,
                       'debit', 0, 'credit', v_goods_total + v_vat_total,
                       'description', 'Accounts payable')
  );

  v_journal := public.rpc_create_journal_entry(jsonb_build_object(
    'org_id', v_org,
    'entry_date', v_invoice_date,
    'description', 'Matched supplier invoice ' || v_invoice_number,
    'reference_type', 'supplier_invoice',
    'reference_number', v_invoice_id::text,
    'idempotency_key', v_idem_journal,
    'auto_post', true,
    'lines', v_lines
  ));

  v_entry_id := NULLIF(v_journal ->> 'entry_id', '')::uuid;

  IF COALESCE((v_journal ->> 'success')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'AP_JOURNAL_NOT_CREATED: النواة المحاسبية لم تُبلّغ بالنجاح — %', v_journal;
  END IF;
  IF v_entry_id IS NULL THEN
    RAISE EXCEPTION 'AP_JOURNAL_ENTRY_ID_MISSING: القيد بلا معرّف — %', v_journal;
  END IF;

  SELECT status INTO v_entry_status FROM public.gl_entries WHERE id = v_entry_id;
  IF v_entry_status IS DISTINCT FROM 'posted' THEN
    RAISE EXCEPTION
      'AP_JOURNAL_NOT_POSTED: القيد بحالة % لا posted — لا تُقبل فاتورة معتمدة بقيد غير مرحَّل',
      COALESCE(v_entry_status, '(غير موجود)');
  END IF;

  UPDATE public.supplier_invoices
  SET journal_entry_id = v_entry_id, updated_at = now()
  WHERE id = v_invoice_id;

  RETURN jsonb_build_object(
    'success', true,
    'idempotent_replay', false,
    'invoice_id', v_invoice_id,
    'invoice_status', 'approved',
    'journal_entry_id', v_entry_id,
    'journal_status', 'posted',
    'subtotal', v_goods_total,
    'tax_amount', v_vat_total,
    'total_amount', v_goods_total + v_vat_total,
    'lines', v_line_no
  );
END $$;


--
-- Name: rpc_create_mo_with_reservation(jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_mo_with_reservation(p_order jsonb, p_materials jsonb DEFAULT '[]'::jsonb, p_tenant uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org uuid;
  v_mo_id uuid;
  v_mo_number text;
  v_mat jsonb;
  v_item_id uuid;
  v_item_ids jsonb;
  v_product_id uuid;
  v_uom_id uuid;
  v_qty numeric;
  v_on_hand numeric;
  v_bin_reserved numeric;
  v_mo_reserved numeric;
  v_avail numeric;
  v_insufficient jsonb := '[]'::jsonb;
  v_reserved integer := 0;
  v_init_status text;
BEGIN
  v_org := public.wardah_org_id(
    COALESCE(NULLIF(p_order ->> 'org_id', '')::uuid, p_tenant)
  );
  PERFORM public.wardah_assert_org_member(v_org);

  IF jsonb_typeof(COALESCE(p_materials, 'null'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'INVALID_MATERIALS: p_materials must be a JSON array';
  END IF;

  -- Validate casts separately so malformed payloads fail before taking locks.
  FOR v_mat IN SELECT value FROM jsonb_array_elements(p_materials)
  LOOP
    BEGIN
      v_item_id := NULLIF(v_mat ->> 'item_id', '')::uuid;
      v_qty := NULLIF(v_mat ->> 'quantity', '')::numeric;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'INVALID_MATERIAL: item_id and quantity must be valid values';
    END;

    IF jsonb_typeof(v_mat) <> 'object' OR v_item_id IS NULL OR v_qty IS NULL OR v_qty <= 0 THEN
      RAISE EXCEPTION 'INVALID_MATERIAL: item_id and a positive quantity are required';
    END IF;
  END LOOP;

  FOR v_product_id, v_qty, v_item_ids IN
    WITH resolved_demand AS (
      SELECT
        (entry ->> 'item_id')::uuid AS item_id,
        public.wardah_resolve_product_id(
          v_org,
          (entry ->> 'item_id')::uuid,
          now()
        ) AS product_id,
        (entry ->> 'quantity')::numeric AS quantity
      FROM jsonb_array_elements(p_materials) AS materials(entry)
    )
    SELECT
      product_id,
      SUM(quantity),
      to_jsonb(array_agg(DISTINCT item_id ORDER BY item_id))
    FROM resolved_demand
    GROUP BY product_id
    ORDER BY product_id
  LOOP
    -- The canonical stock writers lock bins before updating them. Taking the
    -- same locks and order here serializes reservation-vs-stock and concurrent
    -- reservation decisions without introducing the opposite lock order.
    PERFORM 1
    FROM public.bins
    WHERE org_id = v_org AND product_id = v_product_id
    ORDER BY warehouse_id, id
    FOR UPDATE;

    SELECT COALESCE(SUM(actual_qty), 0), COALESCE(SUM(reserved_qty), 0)
    INTO v_on_hand, v_bin_reserved
    FROM public.bins
    WHERE org_id = v_org AND product_id = v_product_id;

    SELECT COALESCE(SUM(
      GREATEST(
        quantity_reserved - COALESCE(quantity_consumed, 0) - COALESCE(quantity_released, 0),
        0
      )
    ), 0)
    INTO v_mo_reserved
    FROM public.material_reservations
    WHERE org_id = v_org
      AND product_id = v_product_id
      AND status = 'reserved';

    v_avail := v_on_hand - v_bin_reserved - v_mo_reserved;
    IF v_avail < v_qty THEN
      v_insufficient := v_insufficient || jsonb_build_object(
        'item_ids', v_item_ids,
        'product_id', v_product_id,
        'required', v_qty,
        'available', v_avail
      );
    END IF;
  END LOOP;

  IF jsonb_array_length(v_insufficient) > 0 THEN
    RAISE EXCEPTION 'INSUFFICIENT_STOCK: مواد غير كافية: %', v_insufficient::text;
  END IF;

  v_init_status := public.normalize_mo_status(COALESCE(p_order ->> 'status', 'draft'));
  v_mo_number := COALESCE(
    NULLIF(p_order ->> 'order_number', ''),
    'MO-' || to_char(now(), 'YYYYMMDD') || '-' || lpad(nextval('public.mo_seq')::text, 4, '0')
  );

  INSERT INTO public.manufacturing_orders (
    org_id, order_number, product_id, item_id, quantity,
    status, notes, start_date, due_date
  )
  VALUES (
    v_org,
    v_mo_number,
    NULLIF(p_order ->> 'product_id', '')::uuid,
    NULLIF(p_order ->> 'item_id', '')::uuid,
    COALESCE(NULLIF(p_order ->> 'quantity', '')::numeric, 0),
    v_init_status,
    NULLIF(p_order ->> 'notes', ''),
    NULLIF(p_order ->> 'start_date', '')::date,
    NULLIF(p_order ->> 'due_date', '')::date
  )
  RETURNING id INTO v_mo_id;

  FOR v_mat IN SELECT value FROM jsonb_array_elements(p_materials)
  LOOP
    v_item_id := (v_mat ->> 'item_id')::uuid;
    v_qty := (v_mat ->> 'quantity')::numeric;
    v_product_id := public.wardah_resolve_product_id(v_org, v_item_id, now());
    SELECT base_uom_id INTO v_uom_id
    FROM public.products
    WHERE id = v_product_id AND org_id = v_org;

    INSERT INTO public.material_reservations (
      org_id, mo_id, item_id, product_id,
      quantity_reserved, status, expires_at,
      uom_id, qty_entered, conversion_factor_snapshot
    )
    VALUES (
      v_org, v_mo_id, v_item_id, v_product_id,
      v_qty, 'reserved', NULLIF(v_mat ->> 'expires_at', '')::timestamptz,
      v_uom_id, v_qty, 1
    );
    v_reserved := v_reserved + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'mo_id', v_mo_id,
    'mo_number', v_mo_number,
    'status', v_init_status,
    'materials_reserved', v_reserved
  );
END;
$$;


--
-- Name: rpc_create_org_uom(uuid, uuid, text, text, text, text, numeric, boolean, smallint, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_org_uom(p_org_id uuid, p_category_id uuid, p_code text, p_name text, p_name_ar text, p_symbol text, p_factor_to_category_base numeric DEFAULT NULL::numeric, p_is_product_specific boolean DEFAULT false, p_decimal_places smallint DEFAULT 6, p_aliases text[] DEFAULT ARRAY[]::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE v_code text; v_id uuid; v_alias text; v_normalized text;
BEGIN
  PERFORM public.wardah_assert_org_admin(p_org_id);
  v_code:=upper(regexp_replace(trim(COALESCE(p_code,'')),'[^A-Za-z0-9_]+','_','g'));
  IF v_code='' OR v_code!~'^[A-Z][A-Z0-9_]*$' THEN RAISE EXCEPTION 'UOM_CODE_INVALID'; END IF;
  IF NULLIF(trim(p_name),'') IS NULL OR NULLIF(trim(p_symbol),'') IS NULL THEN RAISE EXCEPTION 'UOM_NAME_AND_SYMBOL_REQUIRED'; END IF;
  IF p_decimal_places NOT BETWEEN 0 AND 12 THEN RAISE EXCEPTION 'UOM_DECIMAL_PLACES_INVALID'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.uom_categories WHERE id=p_category_id) THEN RAISE EXCEPTION 'UOM_CATEGORY_NOT_FOUND'; END IF;
  IF EXISTS (SELECT 1 FROM public.uoms WHERE org_id IS NULL AND code=v_code) THEN
    RAISE EXCEPTION 'SYSTEM_UOM_CODE_RESERVED: %',v_code;
  END IF;
  IF COALESCE(p_is_product_specific,false) THEN
    IF p_factor_to_category_base IS NOT NULL THEN RAISE EXCEPTION 'PRODUCT_SPECIFIC_UOM_FACTOR_MUST_BE_NULL'; END IF;
  ELSIF p_factor_to_category_base IS NULL OR p_factor_to_category_base<=0 THEN
    RAISE EXCEPTION 'STANDARD_UOM_FACTOR_MUST_BE_POSITIVE';
  END IF;

  INSERT INTO public.uoms(
    org_id,category_id,code,name,name_ar,symbol,factor_to_category_base,
    is_category_base,is_product_specific,decimal_places,is_active
  ) VALUES (
    p_org_id,p_category_id,v_code,trim(p_name),NULLIF(trim(p_name_ar),''),trim(p_symbol),
    p_factor_to_category_base,false,COALESCE(p_is_product_specific,false),p_decimal_places,true
  ) RETURNING id INTO v_id;

  FOREACH v_alias IN ARRAY COALESCE(p_aliases,ARRAY[]::text[]) LOOP
    v_normalized:=public.uom_normalize_alias(v_alias);
    IF v_normalized<>'' THEN
      IF EXISTS (SELECT 1 FROM public.uom_aliases WHERE org_id IS NULL AND alias_normalized=v_normalized) THEN
        RAISE EXCEPTION 'SYSTEM_UOM_ALIAS_RESERVED: %',v_alias;
      END IF;
      INSERT INTO public.uom_aliases(org_id,alias_normalized,alias_display,uom_id,source)
      VALUES(p_org_id,v_normalized,trim(v_alias),v_id,'tenant_admin');
    END IF;
  END LOOP;

  RETURN jsonb_build_object('success',true,'uom_id',v_id,'org_id',p_org_id,
    'code',v_code,'is_product_specific',COALESCE(p_is_product_specific,false));
END;
$_$;


--
-- Name: rpc_create_stock_adjustment(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_stock_adjustment(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_id uuid := gen_random_uuid();
  v_number text;
  v_date date;
  v_total_value numeric;
  v_total_qty numeric;
  v_count integer;
BEGIN
  v_org := public.wardah_org_id(NULLIF(p_payload ->> 'org_id', '')::uuid);
  PERFORM public.wardah_assert_org_member(v_org);

  v_date := COALESCE(NULLIF(p_payload ->> 'adjustment_date', '')::date, CURRENT_DATE);
  v_number := COALESCE(
    NULLIF(p_payload ->> 'adjustment_number', ''),
    'ADJ-' || to_char(v_date, 'YYYYMMDD') || '-' || upper(substr(replace(v_id::text, '-', ''), 1, 8))
  );

  SELECT COUNT(*),
         COALESCE(SUM((x ->> 'difference_qty')::numeric), 0),
         COALESCE(SUM((x ->> 'value_difference')::numeric), 0)
  INTO v_count, v_total_qty, v_total_value
  FROM jsonb_array_elements(COALESCE(p_payload -> 'items', '[]'::jsonb)) x;

  IF v_count = 0 THEN RAISE EXCEPTION 'ADJUSTMENT_REQUIRES_ITEMS'; END IF;

  -- Accounts may be selected after draft creation. rpc_submit_stock_adjustment
  -- remains fail-closed and refuses posting until all required accounts exist.
  INSERT INTO public.stock_adjustments (
    id, organization_id, org_id, adjustment_number, adjustment_date, posting_date,
    adjustment_type, reason, reference_number, warehouse_id, status,
    requires_approval, total_items, total_qty_difference, total_value_difference,
    created_by, inventory_account_id, increase_account_id, decrease_account_id
  ) VALUES (
    v_id, v_org, v_org, v_number, v_date,
    COALESCE(NULLIF(p_payload ->> 'posting_date', '')::date, v_date),
    p_payload ->> 'adjustment_type', p_payload ->> 'reason',
    NULLIF(p_payload ->> 'reference_number', ''),
    NULLIF(p_payload ->> 'warehouse_id', '')::uuid,
    'DRAFT',
    COALESCE((p_payload ->> 'requires_approval')::boolean, abs(v_total_value) > 10000),
    v_count, v_total_qty, v_total_value, auth.uid(),
    NULLIF(p_payload ->> 'inventory_account_id', '')::uuid,
    NULLIF(p_payload ->> 'increase_account_id', '')::uuid,
    NULLIF(p_payload ->> 'decrease_account_id', '')::uuid
  );

  INSERT INTO public.stock_adjustment_items (
    adjustment_id, organization_id, product_id, warehouse_id,
    current_qty, new_qty, difference_qty, current_rate, new_rate,
    value_difference, reason, serial_numbers, batch_numbers
  )
  SELECT
    v_id, v_org, (x ->> 'product_id')::uuid,
    NULLIF(x ->> 'warehouse_id', '')::uuid,
    COALESCE((x ->> 'current_qty')::numeric, 0),
    (x ->> 'new_qty')::numeric, (x ->> 'difference_qty')::numeric,
    COALESCE((x ->> 'current_rate')::numeric, 0),
    NULLIF(x ->> 'new_rate', '')::numeric,
    (x ->> 'value_difference')::numeric, NULLIF(x ->> 'reason', ''),
    CASE WHEN jsonb_typeof(x -> 'serial_nos') = 'array'
      THEN ARRAY(SELECT jsonb_array_elements_text(x -> 'serial_nos')) ELSE NULL END,
    CASE WHEN NULLIF(x ->> 'batch_no', '') IS NOT NULL
      THEN ARRAY[x ->> 'batch_no'] ELSE NULL END
  FROM jsonb_array_elements(p_payload -> 'items') x;

  RETURN jsonb_build_object('success', true, 'adjustment_id', v_id, 'adjustment_number', v_number);
END;
$$;


--
-- Name: rpc_create_supplier_payment(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_supplier_payment(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF public.get_current_tenant_id() IS NULL
     OR NOT public.wardah_is_org_member(public.get_current_tenant_id()) THEN
    RAISE EXCEPTION 'TENANT_MEMBERSHIP_REQUIRED';
  END IF;
  PERFORM public.wardah_169_enter_write_context();
  BEGIN
    v_result := public.wardah_169_internal_create_supplier_payment(p_payload);
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.wardah_169_leave_write_context();
    RAISE;
  END;
  PERFORM public.wardah_169_leave_write_context();
  RETURN v_result;
END $$;


--
-- Name: rpc_create_uom_purchase_order(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_create_uom_purchase_order(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org uuid;
  v_order_id uuid := gen_random_uuid();
  v_order_number text;
  v_vendor_id uuid;
  v_order_date date;
  v_expected_date date;
  v_lines jsonb;
  v_line jsonb;
  v_line_count integer;
  v_line_number integer := 0;
  v_product_id uuid;
  v_uom_id uuid;
  v_qty_entered numeric;
  v_price_entered numeric;
  v_discount numeric;
  v_tax numeric;
  v_description text;
  v_enabled boolean := false;
  v_gross numeric := 0;
  v_discount_amount numeric := 0;
  v_subtotal numeric := 0;
  v_tax_amount numeric := 0;
  v_total numeric := 0;
BEGIN
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'PO_PAYLOAD_OBJECT_REQUIRED';
  END IF;

  v_org := public.wardah_org_id(NULLIF(p_payload ->> 'org_id', '')::uuid);
  PERFORM public.wardah_assert_org_member(v_org);

  SELECT CASE
    WHEN jsonb_typeof(os.value -> 'enabled') = 'boolean'
      THEN (os.value ->> 'enabled')::boolean
    WHEN lower(COALESCE(os.value ->> 'enabled', '')) IN ('true', 'false')
      THEN (os.value ->> 'enabled')::boolean
    ELSE false
  END
  INTO v_enabled
  FROM public.org_settings os
  WHERE os.org_id = v_org
    AND os.key = 'uom_engine_enabled'
  LIMIT 1;

  IF NOT COALESCE(v_enabled, false) THEN
    RAISE EXCEPTION 'UOM_ENGINE_NOT_ENABLED_FOR_ORG';
  END IF;

  v_vendor_id := NULLIF(p_payload ->> 'vendor_id', '')::uuid;
  IF v_vendor_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.vendors v
    WHERE v.id = v_vendor_id
      AND v.org_id = v_org
      AND COALESCE(v.is_active, true)
  ) THEN
    RAISE EXCEPTION 'VENDOR_NOT_FOUND_OR_WRONG_ORG';
  END IF;

  v_order_date := COALESCE(NULLIF(p_payload ->> 'order_date', '')::date, CURRENT_DATE);
  v_expected_date := NULLIF(p_payload ->> 'expected_delivery_date', '')::date;
  IF v_expected_date IS NOT NULL AND v_expected_date < v_order_date THEN
    RAISE EXCEPTION 'EXPECTED_DELIVERY_BEFORE_ORDER_DATE';
  END IF;

  v_lines := COALESCE(p_payload -> 'lines', '[]'::jsonb);
  IF jsonb_typeof(v_lines) <> 'array' THEN
    RAISE EXCEPTION 'PO_LINES_ARRAY_REQUIRED';
  END IF;

  v_line_count := jsonb_array_length(v_lines);
  IF v_line_count = 0 THEN
    RAISE EXCEPTION 'PO_REQUIRES_LINES';
  END IF;
  IF v_line_count > 500 THEN
    RAISE EXCEPTION 'PO_LINE_LIMIT_EXCEEDED';
  END IF;

  v_order_number := COALESCE(
    NULLIF(trim(p_payload ->> 'order_number'), ''),
    'PO-' || to_char(v_order_date, 'YYYYMMDD') || '-' || upper(substr(replace(v_order_id::text, '-', ''), 1, 8))
  );

  INSERT INTO public.purchase_orders (
    id, org_id, order_number, vendor_id, order_date, expected_delivery_date,
    status, subtotal, discount_amount, tax_amount, total_amount, notes, created_by
  ) VALUES (
    v_order_id, v_org, v_order_number, v_vendor_id, v_order_date, v_expected_date,
    'draft', 0, 0, 0, 0, NULLIF(trim(p_payload ->> 'notes'), ''), auth.uid()
  );

  FOR v_line IN SELECT value FROM jsonb_array_elements(v_lines)
  LOOP
    v_line_number := v_line_number + 1;
    IF jsonb_typeof(v_line) <> 'object' THEN
      RAISE EXCEPTION 'PO_LINE_OBJECT_REQUIRED: line=%', v_line_number;
    END IF;

    v_product_id := NULLIF(v_line ->> 'product_id', '')::uuid;
    v_uom_id := NULLIF(v_line ->> 'uom_id', '')::uuid;
    v_qty_entered := NULLIF(v_line ->> 'qty_entered', '')::numeric;
    v_price_entered := NULLIF(v_line ->> 'unit_price_entered', '')::numeric;
    v_discount := COALESCE(NULLIF(v_line ->> 'discount_percentage', '')::numeric, 0);
    v_tax := COALESCE(NULLIF(v_line ->> 'tax_percentage', '')::numeric, 0);
    v_description := NULLIF(trim(v_line ->> 'description'), '');

    IF v_product_id IS NULL OR NOT EXISTS (
      SELECT 1
      FROM public.products p
      JOIN public.uoms base_uom ON base_uom.id = p.base_uom_id
      WHERE p.id = v_product_id
        AND p.org_id = v_org
        AND p.is_active
        AND p.uom_migration_status = 'MAPPED'
        AND base_uom.is_active
        AND (base_uom.org_id IS NULL OR base_uom.org_id = v_org)
    ) THEN
      RAISE EXCEPTION 'PO_PRODUCT_NOT_MAPPED_OR_WRONG_ORG: line=%', v_line_number;
    END IF;

    IF v_uom_id IS NULL OR NOT EXISTS (
      SELECT 1
      FROM public.products p
      JOIN public.uoms u ON u.id = v_uom_id
      WHERE p.id = v_product_id
        AND p.org_id = v_org
        AND u.is_active
        AND (u.org_id IS NULL OR u.org_id = v_org)
        AND (
          u.id = p.base_uom_id
          OR EXISTS (
            SELECT 1 FROM public.product_uom_conversions c
            WHERE c.org_id = v_org
              AND c.product_id = v_product_id
              AND c.uom_id = v_uom_id
              AND c.is_active
              AND c.use_for_purchase
              AND c.valid_from <= now()
              AND (c.valid_to IS NULL OR c.valid_to > now())
          )
        )
    ) THEN
      RAISE EXCEPTION 'PO_UOM_NOT_LEGAL_FOR_PURCHASE: line=%', v_line_number;
    END IF;

    IF v_qty_entered IS NULL OR v_qty_entered <= 0 THEN
      RAISE EXCEPTION 'PO_LINE_QUANTITY_MUST_BE_POSITIVE: line=%', v_line_number;
    END IF;
    IF v_price_entered IS NULL OR v_price_entered < 0 THEN
      RAISE EXCEPTION 'PO_LINE_PRICE_MUST_BE_NONNEGATIVE: line=%', v_line_number;
    END IF;
    IF v_discount < 0 OR v_discount > 100 THEN
      RAISE EXCEPTION 'PO_LINE_DISCOUNT_OUT_OF_RANGE: line=%', v_line_number;
    END IF;
    IF v_tax < 0 OR v_tax > 100 THEN
      RAISE EXCEPTION 'PO_LINE_TAX_OUT_OF_RANGE: line=%', v_line_number;
    END IF;

    INSERT INTO public.purchase_order_lines (
      org_id, purchase_order_id, line_number, product_id, description,
      uom_id, qty_entered, unit_price_entered,
      discount_percentage, tax_percentage
    ) VALUES (
      v_org, v_order_id, v_line_number, v_product_id, v_description,
      v_uom_id, v_qty_entered, v_price_entered,
      v_discount, v_tax
    );
  END LOOP;

  SELECT
    COALESCE(SUM(round(l.quantity * l.unit_price, 2)), 0),
    COALESCE(SUM(round(l.quantity * l.unit_price * (1 - l.discount_percentage / 100), 2)), 0),
    COALESCE(SUM(l.line_total), 0)
  INTO v_gross, v_subtotal, v_total
  FROM public.purchase_order_lines l
  WHERE l.purchase_order_id = v_order_id
    AND l.org_id = v_org;

  v_discount_amount := round(v_gross - v_subtotal, 2);
  v_tax_amount := round(v_total - v_subtotal, 2);

  UPDATE public.purchase_orders
  SET subtotal = v_subtotal,
      discount_amount = v_discount_amount,
      tax_amount = v_tax_amount,
      total_amount = v_total,
      updated_at = now()
  WHERE id = v_order_id
    AND org_id = v_org;

  RETURN jsonb_build_object(
    'success', true,
    'purchase_order_id', v_order_id,
    'order_number', v_order_number,
    'line_count', v_line_count,
    'subtotal', v_subtotal,
    'discount_amount', v_discount_amount,
    'tax_amount', v_tax_amount,
    'total_amount', v_total
  );
END;
$$;


--
-- Name: rpc_delete_manual_journal_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_delete_manual_journal_entry(p_entry_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_entry public.gl_entries%rowtype;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED'; END IF;
  SELECT ge.* INTO v_entry
  FROM public.gl_entries ge
  WHERE ge.id = p_entry_id
    AND (
      EXISTS (
        SELECT 1 FROM public.super_admins sa
        WHERE sa.user_id = v_uid AND sa.is_active = true
      )
      OR EXISTS (
        SELECT 1 FROM public.user_organizations uo
        WHERE uo.user_id = v_uid
          AND uo.org_id = ge.org_id
          AND COALESCE(uo.is_active, true)
      )
    )
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'JOURNAL_ENTRY_NOT_FOUND'; END IF;

  PERFORM public.wardah_178_assert_permission(v_entry.org_id,'accounting.journals.delete');
  IF v_entry.journal_origin NOT IN ('manual','manual_legacy') THEN
    RAISE EXCEPTION 'JOURNAL_SYSTEM_ENTRY_NOT_MANUAL_DELETABLE';
  END IF;
  IF v_entry.status <> 'draft' THEN RAISE EXCEPTION 'JOURNAL_ONLY_DRAFT_DELETABLE'; END IF;

  DELETE FROM public.gl_entry_lines WHERE entry_id=p_entry_id;
  DELETE FROM public.gl_entries WHERE id=p_entry_id;

  INSERT INTO public.audit_logs(org_id,user_id,action,entity_type,entity_id,metadata)
  VALUES (v_entry.org_id,v_uid,'journal.manual.delete','gl_entry',p_entry_id::text,
          jsonb_build_object('migration',178,'entry_number',v_entry.entry_number));

  RETURN jsonb_build_object('success',true,'entry_id',p_entry_id,'deleted',true);
END;
$$;


--
-- Name: rpc_delete_org_role(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_delete_org_role(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org     uuid := NULLIF(p_payload->>'org_id','')::uuid;
  v_role_id uuid := NULLIF(p_payload->>'role_id','')::uuid;
  v_old       jsonb;
  v_users     int;
  v_old_keys  jsonb := '[]'::jsonb;
  v_sensitive text[];
BEGIN
  IF v_org IS NULL OR v_role_id IS NULL THEN
    RAISE EXCEPTION 'RBAC_174_ORG_AND_ROLE_REQUIRED';
  END IF;
  PERFORM public.wardah_assert_org_admin(v_org);

  SELECT to_jsonb(r) INTO v_old
  FROM public.roles r
  WHERE r.id = v_role_id AND r.org_id = v_org
  FOR UPDATE;

  IF v_old IS NULL THEN
    RAISE EXCEPTION 'RBAC_174_ROLE_NOT_FOUND_IN_ORG';
  END IF;
  IF COALESCE((v_old->>'is_system_role')::boolean, false) THEN
    RAISE EXCEPTION 'RBAC_174_SYSTEM_ROLE_IMMUTABLE';
  END IF;

  -- Refuse while users still hold it. Revoking access is a separate,
  -- deliberate act (rpc_replace_user_roles) and must be visible as one.
  SELECT count(*) INTO v_users
  FROM public.user_roles ur WHERE ur.role_id = v_role_id;
  IF v_users > 0 THEN
    RAISE EXCEPTION 'RBAC_174_ROLE_STILL_ASSIGNED: % user(s)', v_users;
  END IF;

  -- Record what is being destroyed, before destroying it. A delete row that
  -- names the role but not its permissions cannot answer "did this role carry
  -- a sensitive key at the moment it was removed?" — which is precisely the
  -- question an audit of sensitive access has to answer.
  SELECT COALESCE(jsonb_agg(p.permission_key ORDER BY p.permission_key), '[]'::jsonb)
    INTO v_old_keys
  FROM public.role_permissions rp
  JOIN public.permissions p ON p.id = rp.permission_id
  WHERE rp.role_id = v_role_id;

  SELECT COALESCE(array_agg(k ORDER BY k), ARRAY[]::text[]) INTO v_sensitive
  FROM jsonb_array_elements_text(v_old_keys) AS t(k)
  WHERE public.wardah_is_sensitive_permission(k);

  DELETE FROM public.role_permissions WHERE role_id = v_role_id;
  DELETE FROM public.roles WHERE id = v_role_id AND org_id = v_org;

  INSERT INTO public.audit_logs (org_id, user_id, action, entity_type, entity_id, old_data, new_data, metadata)
  VALUES (v_org, auth.uid(), 'rbac.role.delete', 'role', v_role_id::text,
          jsonb_build_object('role', v_old, 'permission_keys', v_old_keys),
          NULL,
          jsonb_build_object(
            'migration', 174,
            'permission_count', jsonb_array_length(v_old_keys),
            'sensitive_keys_removed', to_jsonb(v_sensitive),
            'removed_sensitive', COALESCE(array_length(v_sensitive, 1), 0) > 0));

  RETURN jsonb_build_object('role_id', v_role_id, 'deleted', true);
END;
$$;


--
-- Name: rpc_generate_fiscal_periods(integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_generate_fiscal_periods(p_year integer, p_tenant uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_org     UUID := wardah_org_id(p_tenant);
    v_col     TEXT := wardah_periods_org_col();
    v_month   INTEGER;
    v_start   DATE;
    v_end     DATE;
    v_code    TEXT;
    v_created INTEGER := 0;
    v_rows    INTEGER;
BEGIN
    IF v_org IS NULL THEN
        RAISE EXCEPTION 'TENANT_MISSING: تعذر تحديد هوية المؤسسة';
    END IF;
    IF v_col IS NULL THEN
        RAISE EXCEPTION 'PERIODS_TABLE_MISSING: جدول accounting_periods غير موجود أو بنيته غير معروفة';
    END IF;
    IF p_year IS NULL OR p_year < 2000 OR p_year > 2100 THEN
        RAISE EXCEPTION 'INVALID_YEAR: السنة المالية غير صالحة (%)', p_year;
    END IF;

    FOR v_month IN 1..12 LOOP
        v_start := make_date(p_year, v_month, 1);
        v_end   := (v_start + INTERVAL '1 month' - INTERVAL '1 day')::date;
        v_code  := to_char(v_start, 'YYYY-MM');

        EXECUTE format(
            'INSERT INTO accounting_periods
                (%I, period_code, period_name, period_type,
                 start_date, end_date, fiscal_year, status)
             VALUES ($1, $2, $3, ''month'', $4, $5, $6, ''open'')
             ON CONFLICT DO NOTHING',
            v_col
        )
        USING v_org, v_code,
              'الفترة ' || v_code, v_start, v_end, p_year;

        GET DIAGNOSTICS v_rows = ROW_COUNT;
        v_created := v_created + v_rows;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'fiscal_year', p_year,
        'periods_created', v_created,
        'periods_existing', 12 - v_created
    );
END;
$_$;


--
-- Name: rpc_get_invitation_preview(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_invitation_preview(p_token text) RETURNS TABLE(email text, org_name text, org_name_ar text, status text, expires_at timestamp with time zone, is_valid boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_hash TEXT;
BEGIN
    v_hash := encode(sha256(p_token::bytea), 'hex');
    RETURN QUERY
    SELECT inv.email::TEXT, org.name::TEXT, org.name_ar::TEXT,
           inv.status::TEXT, inv.expires_at,
           (inv.status = 'pending' AND inv.expires_at > NOW()) AS is_valid
    FROM invitations inv
    JOIN organizations org ON org.id = inv.org_id
    WHERE inv.token_hash = v_hash;
END;
$$;


--
-- Name: rpc_get_org_uom_engine_enabled(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_org_uom_engine_enabled(p_org_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_enabled boolean;
BEGIN
  PERFORM public.wardah_assert_org_member(p_org_id);

  SELECT COALESCE((value ->> 'enabled')::boolean, false)
    INTO v_enabled
  FROM public.org_settings
  WHERE org_id = p_org_id
    AND key = 'uom_engine_enabled';

  RETURN COALESCE(v_enabled, false);
END;
$$;


--
-- Name: rpc_get_product_weight(uuid, numeric, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_product_weight(p_product_id uuid, p_quantity numeric, p_uom_id uuid, p_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_org uuid; v_net numeric; v_gross numeric; v_weight_uom uuid;
  v_factor numeric; v_base_qty numeric;
BEGIN
  SELECT org_id,net_weight,gross_weight,weight_uom_id
  INTO v_org,v_net,v_gross,v_weight_uom FROM public.products WHERE id=p_product_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'PRODUCT_NOT_FOUND'; END IF;
  PERFORM public.wardah_assert_org_member(v_org);
  IF p_quantity IS NULL OR p_quantity<0 THEN RAISE EXCEPTION 'UOM_QUANTITY_MUST_BE_NONNEGATIVE'; END IF;
  IF v_net IS NULL OR v_weight_uom IS NULL THEN RAISE EXCEPTION 'PRODUCT_WEIGHT_NOT_DECLARED'; END IF;
  v_factor:=public.wardah_uom_factor(v_org,p_product_id,p_uom_id,p_at);
  v_base_qty:=round(p_quantity*v_factor,6);
  RETURN jsonb_build_object('success',true,'product_id',p_product_id,
    'quantity_entered',p_quantity,'uom_id',p_uom_id,'base_quantity',v_base_qty,
    'weight_uom_id',v_weight_uom,'net_weight',round(v_base_qty*v_net,6),
    'gross_weight',CASE WHEN v_gross IS NULL THEN NULL ELSE round(v_base_qty*v_gross,6) END);
END;
$$;


--
-- Name: rpc_get_purchase_product_uoms(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_purchase_product_uoms(p_org_id uuid, p_product_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org uuid;
  v_base_uom uuid;
BEGIN
  v_org := public.wardah_org_id(p_org_id);
  PERFORM public.wardah_assert_org_member(v_org);

  SELECT p.base_uom_id
  INTO v_base_uom
  FROM public.products p
  WHERE p.id = p_product_id
    AND p.org_id = v_org
    AND p.is_active
    AND p.uom_migration_status = 'MAPPED';

  IF NOT FOUND OR v_base_uom IS NULL THEN
    RAISE EXCEPTION 'PO_PRODUCT_NOT_MAPPED_OR_WRONG_ORG';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(row_data ORDER BY is_base DESC, code)
    FROM (
      SELECT
        jsonb_build_object(
          'id', u.id,
          'code', u.code,
          'name', u.name,
          'name_ar', u.name_ar,
          'symbol', u.symbol,
          'category_id', u.category_id,
          'is_category_base', u.is_category_base,
          'is_product_specific', u.is_product_specific,
          'decimal_places', u.decimal_places,
          'factor_to_base', 1,
          'is_base', true,
          'use_for_purchase', true,
          'use_for_sale', true,
          'barcode', NULL
        ) AS row_data,
        true AS is_base,
        u.code
      FROM public.uoms u
      WHERE u.id = v_base_uom
        AND u.is_active
        AND (u.org_id IS NULL OR u.org_id = v_org)

      UNION ALL

      SELECT
        jsonb_build_object(
          'id', u.id,
          'code', u.code,
          'name', u.name,
          'name_ar', u.name_ar,
          'symbol', u.symbol,
          'category_id', u.category_id,
          'is_category_base', u.is_category_base,
          'is_product_specific', u.is_product_specific,
          'decimal_places', u.decimal_places,
          'factor_to_base', c.factor_to_base,
          'is_base', false,
          'use_for_purchase', c.use_for_purchase,
          'use_for_sale', c.use_for_sale,
          'barcode', c.barcode
        ) AS row_data,
        false AS is_base,
        u.code
      FROM public.product_uom_conversions c
      JOIN public.uoms u ON u.id = c.uom_id
      WHERE c.org_id = v_org
        AND c.product_id = p_product_id
        AND c.is_active
        AND c.valid_from <= now()
        AND (c.valid_to IS NULL OR c.valid_to > now())
        AND u.is_active
        AND (u.org_id IS NULL OR u.org_id = v_org)
    ) options
  ), '[]'::jsonb);
END;
$$;


--
-- Name: rpc_get_trial_balance(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_get_trial_balance(p_tenant uuid, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS TABLE(account_code text, account_name text, account_name_ar text, account_type text, opening_debit numeric, opening_credit numeric, period_debit numeric, period_credit numeric, closing_debit numeric, closing_credit numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_org            uuid;
    v_fy_start       date;
    v_fy_start_month integer;
BEGIN
    -- [120] Guard: p_tenant must be the caller's organization; NULL derives it
    -- from active membership. Preserved verbatim from the previous definition.
    v_org := p_tenant;
    IF v_org IS NULL AND auth.uid() IS NOT NULL THEN
        SELECT org_id INTO v_org
        FROM user_organizations
        WHERE user_id = auth.uid() AND COALESCE(is_active, TRUE)
        ORDER BY joined_at NULLS LAST
        LIMIT 1;
    END IF;
    PERFORM public.wardah_assert_org_member(v_org);
    PERFORM public.wardah_178_assert_permission(
        v_org, 'reports.financial.read');

    -- Fiscal-year start for the opening/period split. accounting_periods is
    -- authoritative when it covers the requested date. Otherwise honor the
    -- organization's configured start month, including the preceding calendar
    -- year when p_as_of_date falls before that month.
    SELECT MIN(p2.start_date)
    INTO v_fy_start
    FROM accounting_periods p1
    JOIN accounting_periods p2
      ON p2.org_id = p1.org_id
     AND p2.fiscal_year = p1.fiscal_year
    WHERE p1.org_id = v_org
      AND p_as_of_date BETWEEN p1.start_date AND p1.end_date;

    IF v_fy_start IS NULL THEN
        SELECT CASE
                   WHEN o.fiscal_year_start BETWEEN 1 AND 12
                   THEN o.fiscal_year_start
                   ELSE 1
               END
        INTO v_fy_start_month
        FROM organizations o
        WHERE o.id = v_org;

        v_fy_start_month := COALESCE(v_fy_start_month, 1);
        v_fy_start := make_date(
            CASE
                WHEN EXTRACT(MONTH FROM p_as_of_date)::integer < v_fy_start_month
                THEN EXTRACT(YEAR FROM p_as_of_date)::integer - 1
                ELSE EXTRACT(YEAR FROM p_as_of_date)::integer
            END,
            v_fy_start_month,
            1
        );
    END IF;

    RETURN QUERY
    WITH posted_lines AS (
        SELECT
            COALESCE(a.code, l.account_code)::text          AS code,
            COALESCE(a.name, l.account_name, l.account_code)::text AS name,
            COALESCE(a.name_ar, a.name, l.account_name)::text      AS name_ar,
            COALESCE(a.category, '')::text                  AS category,
            e.entry_date                                    AS entry_date,
            COALESCE(l.debit, 0)                            AS debit,
            COALESCE(l.credit, 0)                           AS credit
        FROM gl_entry_lines l
        JOIN gl_entries e
          ON e.id = l.entry_id
        LEFT JOIN gl_accounts a
          ON a.org_id = e.org_id
         AND (
              a.id = l.account_id
              OR (l.account_id IS NULL AND a.code = l.account_code)
             )
        WHERE e.org_id = v_org
          AND e.status = 'posted'
          AND e.entry_date <= p_as_of_date
    ),
    per_account AS (
        SELECT
            pl.code,
            MAX(pl.name)     AS name,
            MAX(pl.name_ar)  AS name_ar,
            MAX(pl.category) AS category,
            COALESCE(SUM(pl.debit)  FILTER (WHERE pl.entry_date <  v_fy_start), 0) AS open_dr,
            COALESCE(SUM(pl.credit) FILTER (WHERE pl.entry_date <  v_fy_start), 0) AS open_cr,
            COALESCE(SUM(pl.debit)  FILTER (WHERE pl.entry_date >= v_fy_start), 0) AS per_dr,
            COALESCE(SUM(pl.credit) FILTER (WHERE pl.entry_date >= v_fy_start), 0) AS per_cr
        FROM posted_lines pl
        GROUP BY pl.code
    )
    SELECT
        pa.code,
        pa.name,
        pa.name_ar,
        pa.category,
        -- Opening is presented netted on its natural side, so a single account
        -- never reports both an opening debit and an opening credit.
        GREATEST(pa.open_dr - pa.open_cr, 0)::numeric(18,4),
        GREATEST(pa.open_cr - pa.open_dr, 0)::numeric(18,4),
        pa.per_dr::numeric(18,4),
        pa.per_cr::numeric(18,4),
        GREATEST((pa.open_dr + pa.per_dr) - (pa.open_cr + pa.per_cr), 0)::numeric(18,4),
        GREATEST((pa.open_cr + pa.per_cr) - (pa.open_dr + pa.per_dr), 0)::numeric(18,4)
    FROM per_account pa
    -- Any account with movement is reported, including one whose activity is
    -- entirely in the opening balance.
    WHERE pa.open_dr <> 0 OR pa.open_cr <> 0
       OR pa.per_dr  <> 0 OR pa.per_cr  <> 0
    ORDER BY pa.code;
END;
$$;


--
-- Name: rpc_ignore_uom_backfill_issue(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_ignore_uom_backfill_issue(p_org_id uuid, p_issue_id uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_status text;
BEGIN
  PERFORM public.wardah_assert_org_admin(p_org_id);

  IF p_issue_id IS NULL THEN
    RAISE EXCEPTION 'UOM_BACKFILL_ISSUE_REQUIRED';
  END IF;
  IF NULLIF(trim(p_note), '') IS NULL THEN
    RAISE EXCEPTION 'UOM_BACKFILL_IGNORE_NOTE_REQUIRED';
  END IF;

  SELECT status
  INTO v_status
  FROM public.uom_backfill_issues
  WHERE id = p_issue_id
    AND org_id = p_org_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'UOM_BACKFILL_ISSUE_NOT_FOUND: issue=%', p_issue_id;
  END IF;
  IF v_status <> 'OPEN' THEN
    RAISE EXCEPTION 'UOM_BACKFILL_ISSUE_NOT_OPEN: issue=%, status=%', p_issue_id, v_status;
  END IF;

  UPDATE public.uom_backfill_issues
  SET status = 'IGNORED',
      resolved_by = auth.uid(),
      resolved_at = v_now,
      details = COALESCE(details, '{}'::jsonb)
        || jsonb_build_object('ignore_note', trim(p_note))
  WHERE id = p_issue_id
    AND org_id = p_org_id;

  RETURN jsonb_build_object(
    'success', true,
    'issue_id', p_issue_id,
    'status', 'IGNORED'
  );
END;
$$;


--
-- Name: rpc_list_periods(integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_list_periods(p_fiscal_year integer DEFAULT NULL::integer, p_tenant uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_org UUID := wardah_org_id(p_tenant);
    v_col TEXT := wardah_periods_org_col();
    v_out JSONB;
BEGIN
    IF v_org IS NULL THEN
        RAISE EXCEPTION 'TENANT_MISSING: تعذر تحديد هوية المؤسسة';
    END IF;
    IF v_col IS NULL THEN
        RETURN '[]'::jsonb;
    END IF;

    EXECUTE format(
        'SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.start_date), ''[]''::jsonb)
         FROM (
            SELECT id, period_code, period_name, period_type,
                   start_date, end_date, fiscal_year, status
            FROM accounting_periods
            WHERE %I = $1 AND ($2 IS NULL OR fiscal_year = $2)
         ) t',
        v_col
    )
    INTO v_out
    USING v_org, p_fiscal_year;

    RETURN v_out;
END;
$_$;


--
-- Name: rpc_list_supplier_invoice_candidates(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_list_supplier_invoice_candidates(p_org_id uuid, p_vendor_id uuid DEFAULT NULL::uuid, p_purchase_order_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  v_org := public.wardah_org_id(p_org_id);
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'ORG_NOT_RESOLVED';
  END IF;

  PERFORM public.wardah_assert_org_member(v_org);

  IF NOT public.has_permission(
       auth.uid(), v_org, 'purchasing.purchase_orders.read'
     )
     OR NOT public.has_permission(
       auth.uid(), v_org, 'purchasing.purchase_invoices.read'
     ) THEN
    RAISE EXCEPTION
      'AP_CANDIDATE_PERMISSION_DENIED: requires purchasing.purchase_orders.read and purchasing.purchase_invoices.read';
  END IF;

  IF p_vendor_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.vendors v
       WHERE v.id = p_vendor_id
         AND v.org_id = v_org
     ) THEN
    RAISE EXCEPTION 'AP_VENDOR_MISMATCH: vendor is outside the selected organization';
  END IF;

  IF p_purchase_order_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.purchase_orders po
       WHERE po.id = p_purchase_order_id
         AND po.org_id = v_org
     ) THEN
    RAISE EXCEPTION 'AP_PO_NOT_FOUND: purchase order is not visible in the selected organization';
  END IF;

  IF p_vendor_id IS NOT NULL
     AND p_purchase_order_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.purchase_orders po
       WHERE po.id = p_purchase_order_id
         AND po.org_id = v_org
         AND po.vendor_id = p_vendor_id
     ) THEN
    RAISE EXCEPTION 'AP_VENDOR_MISMATCH: purchase order belongs to another vendor';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(
      q.candidate
      ORDER BY q.receipt_date DESC, q.receipt_number DESC, q.goods_receipt_line_id
    )
    FROM (
      SELECT
        gr.receipt_date,
        gr.receipt_number,
        grl.id AS goods_receipt_line_id,
        jsonb_build_object(
          'organization_id', v_org,
          'vendor_id', po.vendor_id,
          'vendor', jsonb_build_object(
            'id', v.id,
            'code', v.code,
            'name', v.name
          ),
          'purchase_order_id', po.id,
          'purchase_order_number', po.order_number,
          'purchase_order_status', po.status,
          'purchase_order_line_id', pol.id,
          'goods_receipt_id', gr.id,
          'goods_receipt_number', gr.receipt_number,
          'goods_receipt_status', gr.status,
          'goods_receipt_line_id', grl.id,
          'quality_status', grl.quality_status,
          'product_id', grl.product_id,
          'product', jsonb_build_object(
            'id', p.id,
            'code', p.code,
            'name', p.name,
            'name_ar', p.name_ar
          ),
          'uom_id', grl.uom_id,
          'uom', jsonb_build_object(
            'id', u.id,
            'code', u.code,
            'name', u.name,
            'name_ar', u.name_ar,
            'symbol', u.symbol,
            'decimal_places', u.decimal_places
          ),
          'conversion_factor_snapshot', grl.conversion_factor_snapshot,
          'accepted_qty_base', grl.received_quantity,
          'accepted_qty_entered', COALESCE(
            grl.qty_entered,
            round(grl.received_quantity / grl.conversion_factor_snapshot, 6)
          ),
          'allocated_qty_base', alloc.allocated_qty_base,
          'allocated_qty_entered', round(
            alloc.allocated_qty_base / grl.conversion_factor_snapshot,
            6
          ),
          'remaining_qty_base', grl.received_quantity - alloc.allocated_qty_base,
          'remaining_qty_entered', round(
            (grl.received_quantity - alloc.allocated_qty_base)
            / grl.conversion_factor_snapshot,
            6
          ),
          'po_unit_price_base', pol.unit_price,
          'po_unit_price_entered', COALESCE(
            pol.unit_price_entered,
            round(pol.unit_price * pol.conversion_factor_snapshot, 6)
          ),
          'discount_percentage', COALESCE(pol.discount_percentage, 0),
          'tax_percentage', COALESCE(pol.tax_percentage, 0)
        ) AS candidate
      FROM public.goods_receipt_lines grl
      JOIN public.goods_receipts gr
        ON gr.id = grl.goods_receipt_id
       AND gr.org_id = v_org
      JOIN public.purchase_order_lines pol
        ON pol.id = grl.purchase_order_line_id
       AND pol.org_id = v_org
      JOIN public.purchase_orders po
        ON po.id = pol.purchase_order_id
       AND po.org_id = v_org
      JOIN public.vendors v
        ON v.id = po.vendor_id
       AND v.org_id = v_org
      JOIN public.products p
        ON p.id = grl.product_id
       AND p.org_id = v_org
      JOIN public.uoms u
        ON u.id = grl.uom_id
       AND (u.org_id IS NULL OR u.org_id = v_org)
      LEFT JOIN LATERAL (
        SELECT COALESCE(SUM(
          CASE
            WHEN a.reversal_of_allocation_id IS NULL THEN a.quantity_base
            ELSE -a.quantity_base
          END
        ), 0)::numeric(18,6) AS allocated_qty_base
        FROM public.supplier_invoice_receipt_allocations a
        WHERE a.org_id = v_org
          AND a.goods_receipt_line_id = grl.id
      ) alloc ON true
      WHERE grl.org_id = v_org
        AND grl.quality_status = 'accepted'
        AND gr.status IN ('confirmed', 'posted')
        AND po.status IN (
          'approved',
          'partially_received',
          'fully_received',
          'received',
          'closed'
        )
        AND gr.vendor_id = po.vendor_id
        AND grl.product_id = pol.product_id
        AND grl.uom_id IS NOT NULL
        AND grl.conversion_factor_snapshot IS NOT NULL
        AND grl.conversion_factor_snapshot > 0
        AND pol.uom_id IS NOT NULL
        AND pol.conversion_factor_snapshot IS NOT NULL
        AND pol.conversion_factor_snapshot > 0
        AND pol.uom_id = grl.uom_id
        AND pol.conversion_factor_snapshot = grl.conversion_factor_snapshot
        AND alloc.allocated_qty_base >= 0
        AND alloc.allocated_qty_base < grl.received_quantity
        AND (p_vendor_id IS NULL OR po.vendor_id = p_vendor_id)
        AND (p_purchase_order_id IS NULL OR po.id = p_purchase_order_id)
    ) q
  ), '[]'::jsonb);
END;
$$;


--
-- Name: rpc_list_uom_purchase_order_options(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_list_uom_purchase_order_options(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org uuid;
  v_enabled boolean := false;
BEGIN
  v_org := public.wardah_org_id(p_org_id);
  PERFORM public.wardah_assert_org_member(v_org);

  SELECT CASE
    WHEN jsonb_typeof(os.value -> 'enabled') = 'boolean'
      THEN (os.value ->> 'enabled')::boolean
    WHEN lower(COALESCE(os.value ->> 'enabled', '')) IN ('true', 'false')
      THEN (os.value ->> 'enabled')::boolean
    ELSE false
  END
  INTO v_enabled
  FROM public.org_settings os
  WHERE os.org_id = v_org
    AND os.key = 'uom_engine_enabled'
  LIMIT 1;

  IF NOT COALESCE(v_enabled, false) THEN
    RAISE EXCEPTION 'UOM_ENGINE_NOT_ENABLED_FOR_ORG';
  END IF;

  RETURN jsonb_build_object(
    'vendors', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', v.id,
        'code', v.code,
        'name', v.name
      ) ORDER BY v.name, v.id)
      FROM public.vendors v
      WHERE v.org_id = v_org
        AND COALESCE(v.is_active, true)
    ), '[]'::jsonb),
    'products', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', p.id,
        'code', p.code,
        'name', p.name,
        'name_ar', p.name_ar,
        'cost_price', p.cost_price,
        'uom_migration_status', p.uom_migration_status
      ) ORDER BY p.code, p.id)
      FROM public.products p
      JOIN public.uoms base_uom ON base_uom.id = p.base_uom_id
      WHERE p.org_id = v_org
        AND p.is_active
        AND p.uom_migration_status = 'MAPPED'
        AND base_uom.is_active
        AND (base_uom.org_id IS NULL OR base_uom.org_id = v_org)
    ), '[]'::jsonb)
  );
END;
$$;


--
-- Name: rpc_list_uom_receivable_purchase_orders(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_list_uom_receivable_purchase_orders(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org uuid;
  v_enabled boolean := false;
BEGIN
  v_org := public.wardah_org_id(p_org_id);
  PERFORM public.wardah_assert_org_member(v_org);

  SELECT CASE
    WHEN jsonb_typeof(os.value -> 'enabled') = 'boolean'
      THEN (os.value ->> 'enabled')::boolean
    WHEN lower(COALESCE(os.value ->> 'enabled', '')) IN ('true', 'false')
      THEN (os.value ->> 'enabled')::boolean
    ELSE false
  END
  INTO v_enabled
  FROM public.org_settings os
  WHERE os.org_id = v_org
    AND os.key = 'uom_engine_enabled'
  LIMIT 1;

  IF NOT COALESCE(v_enabled, false) THEN
    RAISE EXCEPTION 'UOM_ENGINE_NOT_ENABLED_FOR_ORG';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', po.id,
        'order_number', po.order_number,
        'vendor_id', po.vendor_id,
        'vendor', jsonb_build_object(
          'id', v.id,
          'code', v.code,
          'name', v.name
        ),
        'order_date', po.order_date,
        'expected_delivery_date', po.expected_delivery_date,
        'status', po.status,
        'total_amount', COALESCE(po.total_amount, 0),
        'lines', COALESCE((
          SELECT jsonb_agg(
            jsonb_build_object(
              'id', pol.id,
              'line_number', pol.line_number,
              'product_id', pol.product_id,
              'product', jsonb_build_object(
                'code', p.code,
                'name', p.name,
                'name_ar', p.name_ar
              ),
              'uom_id', COALESCE(pol.uom_id, p.base_uom_id),
              'uom', jsonb_build_object(
                'id', u.id,
                'code', u.code,
                'name', u.name,
                'name_ar', u.name_ar,
                'symbol', u.symbol,
                'decimal_places', u.decimal_places
              ),
              'conversion_factor_snapshot',
                COALESCE(NULLIF(pol.conversion_factor_snapshot, 0), 1),
              'ordered_qty_entered', COALESCE(
                pol.qty_entered,
                round(pol.quantity / COALESCE(NULLIF(pol.conversion_factor_snapshot, 0), 1), 6)
              ),
              'ordered_qty_base', pol.quantity,
              'received_qty_entered', round(
                COALESCE(pol.received_quantity, 0)
                / COALESCE(NULLIF(pol.conversion_factor_snapshot, 0), 1),
                6
              ),
              'received_qty_base', COALESCE(pol.received_quantity, 0),
              'accepted_qty_base', COALESCE(pol.accepted_quantity, 0),
              'rejected_qty_base', COALESCE(pol.rejected_quantity, 0),
              'pending_qty_base', GREATEST(
                COALESCE(pol.received_quantity, 0)
                - COALESCE(pol.accepted_quantity, 0)
                - COALESCE(pol.rejected_quantity, 0),
                0
              ),
              'remaining_qty_entered', round(
                GREATEST(
                  pol.quantity
                  - COALESCE(pol.accepted_quantity, 0)
                  - GREATEST(
                      COALESCE(pol.received_quantity, 0)
                      - COALESCE(pol.accepted_quantity, 0)
                      - COALESCE(pol.rejected_quantity, 0),
                      0
                    ),
                  0
                )
                / COALESCE(NULLIF(pol.conversion_factor_snapshot, 0), 1),
                6
              ),
              'remaining_qty_base', GREATEST(
                pol.quantity
                - COALESCE(pol.accepted_quantity, 0)
                - GREATEST(
                    COALESCE(pol.received_quantity, 0)
                    - COALESCE(pol.accepted_quantity, 0)
                    - COALESCE(pol.rejected_quantity, 0),
                    0
                  ),
                0
              ),
              'unit_cost_entered', COALESCE(
                pol.unit_price_entered,
                round(pol.unit_price * COALESCE(NULLIF(pol.conversion_factor_snapshot, 0), 1), 6)
              ),
              'unit_cost_base', pol.unit_price
            ) ORDER BY pol.line_number, pol.id
          )
          FROM public.purchase_order_lines pol
          JOIN public.products p
            ON p.id = pol.product_id
           AND p.org_id = v_org
          LEFT JOIN public.uoms u
            ON u.id = COALESCE(pol.uom_id, p.base_uom_id)
           AND (u.org_id IS NULL OR u.org_id = v_org)
          WHERE pol.purchase_order_id = po.id
            AND pol.org_id = v_org
            AND COALESCE(pol.accepted_quantity, 0)
                + GREATEST(
                    COALESCE(pol.received_quantity, 0)
                    - COALESCE(pol.accepted_quantity, 0)
                    - COALESCE(pol.rejected_quantity, 0),
                    0
                  ) < pol.quantity
        ), '[]'::jsonb)
      ) ORDER BY po.order_date DESC, po.order_number DESC, po.id
    )
    FROM public.purchase_orders po
    JOIN public.vendors v
      ON v.id = po.vendor_id
     AND v.org_id = v_org
    WHERE po.org_id = v_org
      AND po.status IN ('approved', 'partially_received')
      AND EXISTS (
        SELECT 1
        FROM public.purchase_order_lines open_line
        WHERE open_line.purchase_order_id = po.id
          AND open_line.org_id = v_org
          AND COALESCE(open_line.accepted_quantity, 0)
              + GREATEST(
                  COALESCE(open_line.received_quantity, 0)
                  - COALESCE(open_line.accepted_quantity, 0)
                  - COALESCE(open_line.rejected_quantity, 0),
                  0
                ) < open_line.quantity
      )
  ), '[]'::jsonb);
END;
$$;


--
-- Name: rpc_manual_stock_movement(uuid, numeric, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_manual_stock_movement(p_product_id uuid, p_quantity numeric, p_movement_type text, p_warehouse_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT public.rpc_manual_stock_movement_v2(jsonb_build_object(
    'product_id',p_product_id,'quantity',p_quantity,'movement_type',p_movement_type,
    'warehouse_id',p_warehouse_id,'notes',p_notes));
$$;


--
-- Name: rpc_manual_stock_movement_v2(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_manual_stock_movement_v2(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_product uuid; v_org uuid; v_warehouse uuid; v_uom uuid;
  v_qty_entered numeric; v_qty_base numeric; v_factor numeric; v_current numeric;
  v_delta numeric; v_rate_entered numeric; v_rate_base numeric;
  v_voucher uuid:=gen_random_uuid(); v_count integer; v_result jsonb;
BEGIN
  v_product:=NULLIF(p_payload->>'product_id','')::uuid;
  v_warehouse:=NULLIF(p_payload->>'warehouse_id','')::uuid;
  v_qty_entered:=COALESCE(NULLIF(p_payload->>'qty_entered','')::numeric,NULLIF(p_payload->>'quantity','')::numeric);
  SELECT org_id,COALESCE(NULLIF(p_payload->>'uom_id','')::uuid,base_uom_id),
         COALESCE(NULLIF(p_payload->>'unit_cost_entered','')::numeric,cost_price,0)
  INTO v_org,v_uom,v_rate_entered FROM public.products WHERE id=v_product;
  IF NOT FOUND THEN RAISE EXCEPTION 'PRODUCT_NOT_FOUND'; END IF;
  PERFORM public.wardah_assert_org_member(v_org);
  IF v_qty_entered IS NULL OR v_qty_entered<0 THEN RAISE EXCEPTION 'INVALID_MOVEMENT_QUANTITY'; END IF;
  v_factor:=public.wardah_uom_factor(v_org,v_product,v_uom,now());
  v_qty_base:=round(v_qty_entered*v_factor,6); v_rate_base:=round(v_rate_entered/v_factor,6);
  IF v_warehouse IS NULL THEN
    SELECT count(*),min(warehouse_id) INTO v_count,v_warehouse FROM public.bins WHERE org_id=v_org AND product_id=v_product;
    IF v_count<>1 THEN RAISE EXCEPTION 'WAREHOUSE_REQUIRED'; END IF;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.warehouses WHERE id=v_warehouse AND org_id=v_org) THEN RAISE EXCEPTION 'WAREHOUSE_NOT_FOUND_OR_WRONG_ORG'; END IF;
  SELECT COALESCE(actual_qty,0) INTO v_current FROM public.bins
  WHERE org_id=v_org AND product_id=v_product AND warehouse_id=v_warehouse FOR UPDATE;
  v_current:=COALESCE(v_current,0);
  CASE lower(COALESCE(p_payload->>'movement_type',''))
    WHEN 'in' THEN v_delta:=v_qty_base;
    WHEN 'out' THEN v_delta:=-v_qty_base;
    WHEN 'adjustment' THEN v_delta:=v_qty_base-v_current;
    ELSE RAISE EXCEPTION 'INVALID_MOVEMENT_TYPE';
  END CASE;
  IF v_delta>0 THEN
    v_result:=public.wardah_apply_stock_incoming(v_org,v_product,v_warehouse,v_delta,v_rate_base,
      'Manual Stock Movement',v_voucher,'MAN-'||substr(v_voucher::text,1,8),CURRENT_DATE);
  ELSIF v_delta<0 THEN
    v_result:=public.wardah_apply_stock_outgoing(v_org,v_product,v_warehouse,abs(v_delta),
      'Manual Stock Movement',v_voucher,'MAN-'||substr(v_voucher::text,1,8),CURRENT_DATE);
  ELSE v_result:=jsonb_build_object('applied',false,'reason','NO_CHANGE'); END IF;
  RETURN v_result||jsonb_build_object('uom_atomic',true,'uom_id',v_uom,'qty_entered',v_qty_entered,
    'conversion_factor',v_factor,'base_quantity',v_qty_base,'notes',NULLIF(p_payload->>'notes',''));
END;
$$;


--
-- Name: rpc_permission_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_permission_snapshot(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid           uuid := auth.uid();
  v_is_super      boolean;
  v_is_org_admin  boolean;
  v_keys          text[];
  v_sensitive_all text[];
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;
  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'ORG_UNRESOLVED';
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.super_admins sa
                  WHERE sa.user_id = v_uid AND sa.is_active = true)
    INTO v_is_super;

  -- Membership guard: a snapshot is only ever about the caller, in an org the
  -- caller belongs to — EXCEPT for a platform super admin, whose override in
  -- has_permission() is deliberately independent of org membership. Asserting
  -- membership first would make the snapshot contradict the very function it
  -- exists to mirror, and would break the emergency-access path precisely when
  -- it is needed: an incident responder who is not a member of the affected
  -- organization. The super-admin check therefore runs first, and the guard
  -- applies only to everyone else.
  IF NOT v_is_super THEN
    PERFORM public.wardah_assert_org_member(p_org_id);
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.user_organizations uo
                  WHERE uo.user_id = v_uid AND uo.org_id = p_org_id
                    AND uo.is_active = true AND uo.is_org_admin = true)
    INTO v_is_org_admin;

  SELECT COALESCE(array_agg(p.permission_key ORDER BY p.permission_key), ARRAY[]::text[])
    INTO v_sensitive_all
  FROM public.permissions p
  WHERE public.wardah_is_sensitive_permission(p.permission_key);

  IF v_is_super THEN
    -- Full override including sensitive keys.
    SELECT COALESCE(array_agg(p.permission_key ORDER BY p.permission_key), ARRAY[]::text[])
      INTO v_keys
    FROM public.permissions p;
  ELSE
    SELECT COALESCE(array_agg(DISTINCT k ORDER BY k), ARRAY[]::text[]) INTO v_keys
    FROM (
      -- Ordinary keys via the org-admin override (never sensitive ones).
      SELECT p.permission_key AS k
      FROM public.permissions p
      WHERE v_is_org_admin
        AND NOT public.wardah_is_sensitive_permission(p.permission_key)
      UNION
      -- Explicit grants through an active, unexpired, org-scoped role.
      SELECT p.permission_key
      FROM public.user_roles ur
      JOIN public.roles r ON r.id = ur.role_id
        AND r.org_id = p_org_id AND COALESCE(r.is_active, true)
      JOIN public.role_permissions rp ON rp.role_id = ur.role_id
      JOIN public.permissions p ON p.id = rp.permission_id
      WHERE ur.user_id = v_uid
        AND ur.org_id = p_org_id
        AND (ur.expires_at IS NULL OR ur.expires_at > now())
    ) AS effective;
  END IF;

  RETURN jsonb_build_object(
    'user_id', v_uid,
    'org_id', p_org_id,
    'is_super_admin', v_is_super,
    'is_org_admin', v_is_org_admin,
    'permission_keys', to_jsonb(v_keys),
    'sensitive_permission_keys', to_jsonb(v_sensitive_all),
    'generated_at', now());
END;
$$;


--
-- Name: rpc_post_customer_receipt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_post_customer_receipt(p_receipt_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF public.get_current_tenant_id() IS NULL
     OR NOT public.wardah_is_org_member(public.get_current_tenant_id()) THEN
    RAISE EXCEPTION 'TENANT_MEMBERSHIP_REQUIRED';
  END IF;
  PERFORM public.wardah_169_enter_write_context();
  BEGIN
    v_result := public.wardah_169_internal_post_customer_receipt(p_receipt_id);
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.wardah_169_leave_write_context();
    RAISE;
  END;
  PERFORM public.wardah_169_leave_write_context();
  RETURN v_result;
END $$;


--
-- Name: rpc_post_delivery_note(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_post_delivery_note(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_org uuid; v_uid uuid; v_dn_id uuid; v_dn_number text; v_invoice_id uuid;
  v_inv_customer uuid; v_payload_customer uuid; v_idem_key text; v_req_hash text;
  v_existing_id uuid; v_existing_no text; v_existing_hash text; v_allow_over boolean;
  v_line jsonb; v_inv_line record; v_product uuid; v_uom uuid; v_qty_entered numeric;
  v_qty_base numeric; v_factor numeric; v_root_warehouse uuid; v_warehouse uuid; v_bin_count integer;
  v_stock jsonb; v_line_cogs numeric; v_unit_cost numeric; v_total_cogs numeric:=0; v_line_no integer:=0; v_date date;
BEGIN
  v_org:=public.wardah_org_id(NULLIF(p_payload->>'tenant_id','')::uuid);
  IF v_org IS NULL THEN RAISE EXCEPTION 'ORG_NOT_RESOLVED'; END IF;
  v_uid:=auth.uid(); PERFORM public.wardah_assert_org_member(v_org);
  v_invoice_id:=NULLIF(p_payload->>'sales_invoice_id','')::uuid;
  IF v_invoice_id IS NULL THEN RAISE EXCEPTION 'INVALID_PAYLOAD: sales_invoice_id required'; END IF;
  IF jsonb_typeof(COALESCE(p_payload->'lines','[]'::jsonb))<>'array' OR jsonb_array_length(COALESCE(p_payload->'lines','[]'::jsonb))=0 THEN
    RAISE EXCEPTION 'INVALID_PAYLOAD: delivery lines required'; END IF;
  v_allow_over:=COALESCE(NULLIF(p_payload->>'allow_over_delivery','')::boolean,false);
  IF v_allow_over AND NOT public.wardah_is_org_admin(v_org) THEN v_allow_over:=false; END IF;
  v_date:=COALESCE(NULLIF(p_payload->>'delivery_date','')::date,CURRENT_DATE); PERFORM public.assert_period_open(v_org,v_date);
  v_root_warehouse:=NULLIF(p_payload->>'warehouse_id','')::uuid;
  IF v_root_warehouse IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.warehouses WHERE id=v_root_warehouse AND org_id=v_org) THEN
    RAISE EXCEPTION 'WAREHOUSE_NOT_FOUND_OR_WRONG_ORG'; END IF;

  PERFORM pg_advisory_xact_lock(hashtext('delivery_notes:'||v_org::text));
  v_req_hash:=md5((p_payload-'idempotency_key')::text); v_idem_key:=NULLIF(p_payload->>'idempotency_key','');
  IF v_idem_key IS NOT NULL THEN
    SELECT id,delivery_number,request_hash INTO v_existing_id,v_existing_no,v_existing_hash
    FROM public.delivery_notes WHERE org_id=v_org AND idempotency_key=v_idem_key;
    IF FOUND THEN
      IF v_existing_hash IS NULL OR v_existing_hash<>v_req_hash THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_REUSED'; END IF;
      SELECT COALESCE(sum(quantity_delivered*unit_cost_at_delivery),0) INTO v_total_cogs
      FROM public.delivery_note_lines WHERE delivery_note_id=v_existing_id;
      RETURN jsonb_build_object('success',true,'delivery_id',v_existing_id,'delivery_number',v_existing_no,
        'total_cogs',round(v_total_cogs,6),'idempotent_replay',true,'inventory_atomic',true,'uom_atomic',true);
    END IF;
  END IF;

  SELECT customer_id INTO v_inv_customer FROM public.sales_invoices WHERE id=v_invoice_id AND org_id=v_org FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'INVOICE_NOT_FOUND'; END IF;
  v_payload_customer:=NULLIF(p_payload->>'customer_id','')::uuid;
  IF v_payload_customer IS NOT NULL AND v_payload_customer<>v_inv_customer THEN RAISE EXCEPTION 'CUSTOMER_MISMATCH'; END IF;
  SELECT 'DN-'||lpad((COALESCE(max(NULLIF(regexp_replace(delivery_number,'\D','','g'),''))::bigint,0)+1)::text,6,'0')
    INTO v_dn_number FROM public.delivery_notes WHERE org_id=v_org AND delivery_number~'^DN-\d+$';
  v_dn_number:=COALESCE(v_dn_number,'DN-000001');
  INSERT INTO public.delivery_notes(org_id,delivery_number,sales_invoice_id,customer_id,delivery_date,warehouse_id,
    vehicle_number,driver_name,status,notes,idempotency_key,request_hash,created_by)
  VALUES(v_org,v_dn_number,v_invoice_id,v_inv_customer,v_date,v_root_warehouse,NULLIF(p_payload->>'vehicle_number',''),
    NULLIF(p_payload->>'driver_name',''),'delivered',NULLIF(p_payload->>'notes',''),v_idem_key,v_req_hash,v_uid)
  RETURNING id INTO v_dn_id;

  FOR v_line IN SELECT value FROM jsonb_array_elements(p_payload->'lines') LOOP
    v_line_no:=v_line_no+1;
    IF NULLIF(v_line->>'sales_invoice_line_id','') IS NULL THEN RAISE EXCEPTION 'LINE_REQUIRED: sales_invoice_line_id line=%',v_line_no; END IF;
    SELECT id,product_id,quantity,unit_price,COALESCE(delivered_quantity,0) AS delivered INTO v_inv_line
    FROM public.sales_invoice_lines WHERE id=(v_line->>'sales_invoice_line_id')::uuid AND invoice_id=v_invoice_id AND org_id=v_org FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_INVOICE_LINE: line=%',v_line_no; END IF;
    v_product:=v_inv_line.product_id;
    IF NULLIF(v_line->>'item_id','') IS NOT NULL AND (v_line->>'item_id')::uuid<>v_product THEN RAISE EXCEPTION 'PRODUCT_MISMATCH: line=%',v_line_no; END IF;
    SELECT COALESCE(NULLIF(v_line->>'uom_id','')::uuid,p.base_uom_id) INTO v_uom FROM public.products p WHERE p.id=v_product AND p.org_id=v_org;
    v_qty_entered:=COALESCE(NULLIF(v_line->>'qty_entered','')::numeric,NULLIF(v_line->>'delivered_quantity','')::numeric);
    IF v_qty_entered IS NULL OR v_qty_entered<=0 THEN RAISE EXCEPTION 'INVALID_DELIVERY_QUANTITY: line=%',v_line_no; END IF;
    v_factor:=public.wardah_uom_factor(v_org,v_product,v_uom,v_date::timestamptz); v_qty_base:=round(v_qty_entered*v_factor,6);
    IF NOT v_allow_over AND v_inv_line.delivered+v_qty_base>v_inv_line.quantity THEN
      RAISE EXCEPTION 'OVER_DELIVERY: remaining=%, requested_base=%',v_inv_line.quantity-v_inv_line.delivered,v_qty_base; END IF;
    v_warehouse:=COALESCE(NULLIF(v_line->>'warehouse_id','')::uuid,v_root_warehouse);
    IF v_warehouse IS NULL THEN
      SELECT count(*),min(warehouse_id) INTO v_bin_count,v_warehouse FROM public.bins
      WHERE org_id=v_org AND product_id=v_product AND actual_qty>=v_qty_base;
      IF v_bin_count<>1 THEN RAISE EXCEPTION 'WAREHOUSE_REQUIRED_FOR_DELIVERY'; END IF;
    END IF;
    v_stock:=public.wardah_apply_stock_outgoing(v_org,v_product,v_warehouse,v_qty_base,
      'Delivery Note',v_dn_id,v_dn_number,v_date);
    IF NOT COALESCE((v_stock->>'applied')::boolean,false) THEN RAISE EXCEPTION 'STOCK_OUT_NOT_APPLIED: %',v_stock; END IF;
    v_line_cogs:=COALESCE((v_stock->>'cogs')::numeric,0); v_unit_cost:=CASE WHEN v_qty_base>0 THEN v_line_cogs/v_qty_base ELSE 0 END;
    v_total_cogs:=v_total_cogs+v_line_cogs;
    INSERT INTO public.delivery_note_lines(org_id,delivery_note_id,sales_invoice_line_id,product_id,invoiced_quantity,
      delivered_quantity,quantity_delivered,unit_price,unit_cost_at_delivery,notes,uom_id,qty_entered,
      conversion_factor_snapshot,unit_price_entered,warehouse_id)
    VALUES(v_org,v_dn_id,v_inv_line.id,v_product,v_inv_line.quantity,v_qty_base,v_qty_base,v_inv_line.unit_price,
      v_unit_cost,NULLIF(v_line->>'notes',''),v_uom,v_qty_entered,v_factor,
      COALESCE(NULLIF(v_line->>'unit_price_entered','')::numeric,v_inv_line.unit_price*v_factor),v_warehouse);
    -- Cumulative weighted average across partial deliveries, so the generated
    -- invoice-line cogs equals the exact summed delivery COGS once fully delivered.
    UPDATE public.sales_invoice_lines
    SET delivered_quantity=v_inv_line.delivered+v_qty_base,
        unit_cost_at_sale=round(
          (v_inv_line.delivered*COALESCE(unit_cost_at_sale,0)+v_line_cogs)
          /(v_inv_line.delivered+v_qty_base),6)
    WHERE id=v_inv_line.id;
  END LOOP;

  IF v_total_cogs>0 THEN PERFORM public.rpc_post_event_journal('COGS_DELIVERY',v_total_cogs,
    'تكلفة بضاعة مباعة - '||v_dn_number,'DELIVERY_NOTE',v_dn_id,v_org,'COGS_DELIVERY:'||v_dn_id::text,NULL); END IF;
  UPDATE public.sales_invoices si SET delivery_status=CASE WHEN NOT EXISTS(
    SELECT 1 FROM public.sales_invoice_lines l WHERE l.invoice_id=si.id AND COALESCE(l.delivered_quantity,0)<l.quantity
  ) THEN 'fully_delivered' ELSE 'partially_delivered' END WHERE si.id=v_invoice_id;
  RETURN jsonb_build_object('success',true,'delivery_id',v_dn_id,'delivery_number',v_dn_number,
    'total_cogs',round(v_total_cogs,6),'lines_processed',v_line_no,'inventory_atomic',true,'uom_atomic',true,'warnings','[]'::jsonb);
END;
$_$;


--
-- Name: rpc_post_event_journal(text, numeric, text, text, uuid, uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_post_event_journal(p_event text, p_amount numeric, p_memo text, p_ref_type text, p_ref_id uuid DEFAULT NULL::uuid, p_tenant uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_jv_date date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_org UUID := wardah_org_id(p_tenant);
    v_map RECORD;
    v_debit_id UUID;
    v_credit_id UUID;
    v_result JSONB;
BEGIN
    IF v_org IS NULL THEN
        RAISE EXCEPTION 'TENANT_MISSING: تعذر تحديد هوية المؤسسة';
    END IF;
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'INVALID_AMOUNT: مبلغ الحدث يجب أن يكون موجباً (المستلم: %)', p_amount;
    END IF;

    -- الخريطة — خطأ واضح بدل حسابات افتراضية صامتة
    SELECT * INTO v_map
    FROM gl_event_mappings
    WHERE org_id = v_org AND event_code = upper(p_event)
      AND work_center_code IS NULL AND is_active = true
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'MAPPING_MISSING: لا توجد خريطة حسابات للحدث "%" — أضفها عبر rpc_upsert_event_mapping', p_event;
    END IF;

    -- تحويل أكواد الحسابات إلى معرفات
    SELECT id INTO v_debit_id FROM gl_accounts WHERE org_id = v_org AND code = v_map.debit_account_code;
    SELECT id INTO v_credit_id FROM gl_accounts WHERE org_id = v_org AND code = v_map.credit_account_code;
    IF v_debit_id IS NULL OR v_credit_id IS NULL THEN
        RAISE EXCEPTION 'ACCOUNT_NOT_FOUND: أحد حسابي الخريطة (% / %) غير موجود',
            v_map.debit_account_code, v_map.credit_account_code;
    END IF;

    v_result := rpc_create_journal_entry(jsonb_build_object(
        'org_id', v_org,
        'entry_date', COALESCE(p_jv_date, CURRENT_DATE),
        'description', p_memo,
        'reference_type', p_ref_type,
        'reference_number', p_ref_id::text,
        'idempotency_key', p_idempotency_key,
        'auto_post', false,  -- يبقى Draft للمراجعة — يُفعَّل الترحيل الفوري لاحقاً بقرار
        'lines', jsonb_build_array(
            jsonb_build_object('line_number', 1, 'account_id', v_debit_id,
                               'debit', p_amount, 'credit', 0, 'description', p_memo),
            jsonb_build_object('line_number', 2, 'account_id', v_credit_id,
                               'debit', 0, 'credit', p_amount, 'description', p_memo)
        )
    ));

    RETURN (v_result ->> 'entry_id')::uuid;
END;
$$;


--
-- Name: rpc_post_goods_receipt(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_post_goods_receipt(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  c_lines_key CONSTANT text := 'lines';
  c_number_attempt_limit CONSTANT integer := 100;
  c_quality_accepted CONSTANT text := 'accepted';
  c_quality_rejected CONSTANT text := 'rejected';
  c_receipt_sequence CONSTANT regclass := 'public.goods_receipt_number_seq'::regclass;
  v_org uuid; v_uid uuid; v_gr_id uuid; v_gr_number text; v_po_id uuid;
  v_po_status text; v_po_vendor uuid; v_vendor_id uuid; v_wh_id uuid;
  v_idem_key text; v_req_hash text; v_existing_id uuid; v_existing_no text; v_existing_hash text;
  v_line jsonb; v_line_no integer:=0; v_product uuid; v_uom uuid; v_base_uom uuid;
  v_payload_uom uuid; v_qty_entered numeric; v_qty_base numeric;
  v_ordered_entered numeric; v_ordered_base numeric; v_factor numeric;
  v_cost_entered numeric; v_cost_base numeric; v_payload_cost numeric;
  v_payload_cost_base numeric; v_quality text;
  v_total numeric:=0; v_pol record; v_pol_id uuid; v_recv_date date; v_stock jsonb;
  v_pending numeric; v_committed numeric; v_consumes boolean;
  v_number_attempt integer:=0;
  v_receipt_sequence bigint;
BEGIN
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'GR_PAYLOAD_OBJECT_REQUIRED';
  END IF;

  v_org:=public.wardah_org_id(NULLIF(p_payload->>'tenant_id','')::uuid);
  IF v_org IS NULL THEN RAISE EXCEPTION 'ORG_NOT_RESOLVED'; END IF;
  v_uid:=auth.uid(); PERFORM public.wardah_assert_org_member(v_org);

  -- Idempotent replay is resolved before every business gate below.
  -- A retry of the receipt that closed a purchase order must return the original
  -- document, not PO_NOT_RECEIVABLE: by then the order is legitimately
  -- 'fully_received', and the same is true once a period closes or a line is
  -- exhausted. Gating a replay on state that the original call itself produced
  -- makes the final receipt of every order unconfirmable after a timeout.
  -- The lock is taken first so a concurrent duplicate serializes here and finds
  -- the committed row instead of racing past this check into a second insert.
  PERFORM pg_advisory_xact_lock(hashtext('goods_receipts:'||v_org::text));
  v_req_hash:=md5((p_payload-'idempotency_key')::text);
  v_idem_key:=NULLIF(p_payload->>'idempotency_key','');
  IF v_idem_key IS NOT NULL THEN
    SELECT id,receipt_number,request_hash INTO v_existing_id,v_existing_no,v_existing_hash
    FROM public.goods_receipts
    WHERE org_id=v_org AND idempotency_key=v_idem_key;
    IF FOUND THEN
      IF v_existing_hash IS NULL OR v_existing_hash<>v_req_hash THEN
        RAISE EXCEPTION 'IDEMPOTENCY_KEY_REUSED';
      END IF;
      RETURN jsonb_build_object(
        'success',true,
        'goods_receipt_id',v_existing_id,
        'receipt_number',v_existing_no,
        'idempotent_replay',true,
        'inventory_atomic',true,
        'uom_atomic',true,
        'po_snapshot_atomic',true,
        'quality_aware_contract',true
      );
    END IF;
  END IF;

  v_vendor_id:=NULLIF(p_payload->>'vendor_id','')::uuid;
  IF v_vendor_id IS NULL THEN RAISE EXCEPTION 'INVALID_PAYLOAD: vendor_id required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.vendors WHERE id=v_vendor_id AND org_id=v_org) THEN
    RAISE EXCEPTION 'VENDOR_NOT_FOUND';
  END IF;
  IF jsonb_typeof(COALESCE(p_payload->c_lines_key,'[]'::jsonb))<>'array'
     OR jsonb_array_length(COALESCE(p_payload->c_lines_key,'[]'::jsonb))=0 THEN
    RAISE EXCEPTION 'INVALID_PAYLOAD: receipt lines required';
  END IF;
  v_wh_id:=NULLIF(p_payload->>'warehouse_id','')::uuid;
  IF v_wh_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.warehouses WHERE id=v_wh_id AND org_id=v_org
  ) THEN
    RAISE EXCEPTION 'WAREHOUSE_REQUIRED_OR_WRONG_ORG';
  END IF;

  v_po_id:=NULLIF(p_payload->>'purchase_order_id','')::uuid;
  IF v_po_id IS NOT NULL THEN
    SELECT status,vendor_id INTO v_po_status,v_po_vendor
    FROM public.purchase_orders
    WHERE id=v_po_id AND org_id=v_org
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'PO_NOT_FOUND'; END IF;
    -- 'submitted' is not receivable: receiving an unapproved order would bypass
    -- the approval gate that governs inventory and GL impact.
    IF v_po_status NOT IN ('approved','partially_received') THEN
      RAISE EXCEPTION 'PO_NOT_RECEIVABLE: %',v_po_status;
    END IF;
    IF v_po_vendor IS NOT NULL AND v_po_vendor<>v_vendor_id THEN
      RAISE EXCEPTION 'VENDOR_MISMATCH';
    END IF;
  END IF;

  v_recv_date:=COALESCE(NULLIF(p_payload->>'receipt_date','')::date,CURRENT_DATE);
  PERFORM public.assert_period_open(v_org,v_recv_date);

  -- Migration 177: a database sequence is global (matching the global UNIQUE
  -- constraint), concurrency-safe, and never truncates legacy timestamp-shaped
  -- receipt numbers through lpad(..., 6). The retry closes the narrow upgrade
  -- race where an invocation of the old allocator commits after sequence seed.
  LOOP
    v_number_attempt:=v_number_attempt+1;
    SELECT nextval(c_receipt_sequence) INTO v_receipt_sequence;
    v_gr_number := 'GR-' || CASE
      WHEN v_receipt_sequence < 1000000
        THEN lpad(v_receipt_sequence::text, 6, '0')
      ELSE v_receipt_sequence::text
    END;

    BEGIN
      INSERT INTO public.goods_receipts(
        org_id,receipt_number,purchase_order_id,vendor_id,receipt_date,warehouse_id,
        warehouse_location,receiver_name,status,notes,idempotency_key,request_hash,created_by
      ) VALUES(
        v_org,v_gr_number,v_po_id,v_vendor_id,v_recv_date,v_wh_id,
        NULLIF(p_payload->>'warehouse_location',''),NULLIF(p_payload->>'receiver_name',''),
        'confirmed',NULLIF(p_payload->>'notes',''),v_idem_key,v_req_hash,v_uid
      ) RETURNING id INTO v_gr_id;
      EXIT;
    EXCEPTION
      WHEN unique_violation THEN
        IF v_number_attempt<c_number_attempt_limit AND EXISTS (
          SELECT 1
          FROM public.goods_receipts
          WHERE receipt_number=v_gr_number
        ) THEN
          CONTINUE;
        END IF;
        RAISE;
    END;
  END LOOP;

  FOR v_line IN SELECT value FROM jsonb_array_elements(p_payload->c_lines_key) LOOP
    v_line_no:=v_line_no+1;
    IF jsonb_typeof(v_line) <> 'object' THEN
      RAISE EXCEPTION 'GR_LINE_OBJECT_REQUIRED: line=%',v_line_no;
    END IF;

    v_product:=NULLIF(v_line->>'product_id','')::uuid;
    SELECT p.base_uom_id INTO v_base_uom
    FROM public.products p
    WHERE p.id=v_product AND p.org_id=v_org;
    IF v_product IS NULL OR NOT FOUND THEN
      RAISE EXCEPTION 'ITEM_NOT_FOUND: line=%',v_line_no;
    END IF;

    v_quality:=COALESCE(NULLIF(v_line->>'quality_status',''),c_quality_accepted);
    IF v_quality NOT IN (c_quality_accepted,c_quality_rejected,'pending_inspection') THEN
      RAISE EXCEPTION 'INVALID_QUALITY_STATUS: line=%',v_line_no;
    END IF;

    v_pol_id:=NULLIF(v_line->>'purchase_order_line_id','')::uuid;
    v_payload_uom:=NULLIF(v_line->>'uom_id','')::uuid;
    v_payload_cost:=NULLIF(v_line->>'unit_cost_entered','')::numeric;
    v_payload_cost_base:=NULLIF(v_line->>'unit_cost','')::numeric;

    IF v_pol_id IS NOT NULL THEN
      IF v_po_id IS NULL THEN RAISE EXCEPTION 'PO_REQUIRED: line=%',v_line_no; END IF;

      -- No resolution flow exists to move a pending quantity to accepted or
      -- rejected, so accepting one here would strand the contract balance
      -- permanently: no inventory, no GRNI, and no way to close or reopen the
      -- order. Refuse at the entry point instead of creating unresolvable state.
      IF v_quality='pending_inspection' THEN
        RAISE EXCEPTION 'PENDING_INSPECTION_REQUIRES_RESOLUTION_FLOW: line=%',v_line_no;
      END IF;

      SELECT
        purchase_order_id,
        product_id,
        quantity,
        COALESCE(received_quantity,0) AS received,
        COALESCE(accepted_quantity,0) AS accepted,
        COALESCE(rejected_quantity,0) AS rejected,
        uom_id,
        qty_entered,
        conversion_factor_snapshot,
        unit_price,
        unit_price_entered
      INTO v_pol
      FROM public.purchase_order_lines
      WHERE id=v_pol_id AND org_id=v_org
      FOR UPDATE;

      IF NOT FOUND OR v_pol.purchase_order_id<>v_po_id THEN
        RAISE EXCEPTION 'INVALID_PO_LINE: line=%',v_line_no;
      END IF;
      IF v_pol.product_id<>v_product THEN RAISE EXCEPTION 'PRODUCT_MISMATCH'; END IF;

      v_uom:=COALESCE(v_pol.uom_id,v_base_uom);

      -- Fail closed instead of silently assuming factor 1. A line denominated in a
      -- non-base unit with no legal snapshot cannot be converted without guessing,
      -- and guessing writes a wrong base quantity and cost with no error at all.
      IF v_pol.conversion_factor_snapshot IS NULL OR v_pol.conversion_factor_snapshot<=0 THEN
        IF v_uom IS DISTINCT FROM v_base_uom THEN
          RAISE EXCEPTION 'PO_LINE_SNAPSHOT_MISSING: line=%',v_line_no;
        END IF;
        -- Base unit and no snapshot: entered and base are the same quantity by
        -- definition, so factor 1 is a fact here rather than an assumption.
        v_factor:=1;
      ELSE
        v_factor:=v_pol.conversion_factor_snapshot;
      END IF;

      v_ordered_base:=v_pol.quantity;
      v_ordered_entered:=COALESCE(v_pol.qty_entered,round(v_pol.quantity/v_factor,6));
      v_cost_base:=v_pol.unit_price;
      v_cost_entered:=COALESCE(v_pol.unit_price_entered,round(v_pol.unit_price*v_factor,6));

      v_qty_entered:=NULLIF(v_line->>'qty_entered','')::numeric;
      IF v_qty_entered IS NULL THEN
        -- Legacy callers send received_quantity/unit_cost in base units while the
        -- snapshot contract is expressed in entered units. The two are provably
        -- identical only at factor 1; anywhere else the payload is ambiguous and
        -- must be refused rather than silently inflated by the factor.
        IF v_factor<>1 THEN
          RAISE EXCEPTION 'RECEIPT_SNAPSHOT_CONTRACT_REQUIRED: line=%',v_line_no;
        END IF;
        v_qty_entered:=NULLIF(v_line->>'received_quantity','')::numeric;
      END IF;
      IF v_qty_entered IS NULL OR v_qty_entered<=0 THEN
        RAISE EXCEPTION 'RECEIPT_QUANTITY_MUST_BE_POSITIVE: line=%',v_line_no;
      END IF;

      IF v_payload_uom IS NOT NULL AND v_payload_uom<>v_uom THEN
        RAISE EXCEPTION 'RECEIPT_UOM_MISMATCH: line=%',v_line_no;
      END IF;
      IF v_payload_cost IS NOT NULL AND abs(v_payload_cost-v_cost_entered)>0.000001 THEN
        RAISE EXCEPTION 'RECEIPT_COST_MISMATCH: line=%',v_line_no;
      END IF;
      -- Legacy base-unit cost is only unambiguous at factor 1, where entered and
      -- base rates coincide. Beyond that the explicit field is mandatory above.
      IF v_payload_cost IS NULL AND v_payload_cost_base IS NOT NULL
         AND abs(v_payload_cost_base-v_cost_base)>0.000001 THEN
        RAISE EXCEPTION 'RECEIPT_COST_MISMATCH: line=%',v_line_no;
      END IF;

      v_qty_base:=round(v_qty_entered*v_factor,6);
      IF v_qty_base<=0 THEN
        RAISE EXCEPTION 'RECEIPT_BASE_QUANTITY_MUST_BE_POSITIVE: line=%',v_line_no;
      END IF;

      -- Contract balance, not physical balance. Accepted units are final and any
      -- pending units are still claimable, so both hold the balance; rejected
      -- units release it so a replacement delivery does not trip OVER_RECEIPT.
      v_pending:=GREATEST(v_pol.received-v_pol.accepted-v_pol.rejected,0);
      v_committed:=v_pol.accepted+v_pending;
      v_consumes:=(v_quality=c_quality_accepted);

      IF v_consumes AND v_committed+v_qty_base>v_pol.quantity THEN
        RAISE EXCEPTION 'OVER_RECEIPT: remaining=%, requested_base=%',
          v_pol.quantity-v_committed,v_qty_base;
      END IF;

      -- A rejected quantity releases balance rather than consuming it, so it is
      -- not covered by OVER_RECEIPT above. Without its own ceiling a vendor could
      -- be recorded as delivering — and the buyer as rejecting — an unbounded
      -- quantity against a finite order. A single shipment may not exceed the
      -- balance that was open when it arrived.
      IF v_quality=c_quality_rejected THEN
        IF v_qty_base>v_pol.quantity-v_committed THEN
          RAISE EXCEPTION 'REJECTED_QUANTITY_EXCEEDS_OPEN_BALANCE: remaining=%, requested_base=%',
            v_pol.quantity-v_committed,v_qty_base;
        END IF;
      END IF;

      -- received_quantity keeps its physical meaning for every quality status.
      -- Only the accepted/rejected split is quality driven.
      UPDATE public.purchase_order_lines
      SET received_quantity=v_pol.received+v_qty_base,
          accepted_quantity=v_pol.accepted+CASE WHEN v_quality=c_quality_accepted THEN v_qty_base ELSE 0 END,
          rejected_quantity=v_pol.rejected+CASE WHEN v_quality=c_quality_rejected THEN v_qty_base ELSE 0 END
      WHERE id=v_pol_id;
    ELSE
      v_qty_entered:=COALESCE(
        NULLIF(v_line->>'qty_entered','')::numeric,
        NULLIF(v_line->>'received_quantity','')::numeric
      );
      IF v_qty_entered IS NULL OR v_qty_entered<=0 THEN
        RAISE EXCEPTION 'RECEIPT_QUANTITY_MUST_BE_POSITIVE: line=%',v_line_no;
      END IF;
      v_uom:=COALESCE(v_payload_uom,v_base_uom);
      v_ordered_entered:=COALESCE(
        NULLIF(v_line->>'ordered_qty_entered','')::numeric,
        NULLIF(v_line->>'ordered_quantity','')::numeric,
        v_qty_entered
      );
      v_cost_entered:=COALESCE(v_payload_cost,v_payload_cost_base);
      IF v_ordered_entered IS NULL OR v_ordered_entered<0
         OR v_cost_entered IS NULL OR v_cost_entered<0 THEN
        RAISE EXCEPTION 'INVALID_LINE: line=%',v_line_no;
      END IF;
      v_factor:=public.wardah_uom_factor(v_org,v_product,v_uom,v_recv_date::timestamptz);
      v_qty_base:=round(v_qty_entered*v_factor,6);
      v_ordered_base:=round(v_ordered_entered*v_factor,6);
      v_cost_base:=round(v_cost_entered/v_factor,6);
    END IF;

    INSERT INTO public.goods_receipt_lines(
      org_id,goods_receipt_id,purchase_order_line_id,product_id,
      ordered_quantity,received_quantity,unit_cost,quality_status,notes,
      uom_id,qty_entered,conversion_factor_snapshot,unit_cost_entered
    ) VALUES(
      v_org,v_gr_id,v_pol_id,v_product,
      v_ordered_base,v_qty_base,v_cost_base,v_quality,NULLIF(v_line->>'notes',''),
      v_uom,v_qty_entered,v_factor,v_cost_entered
    );

    IF v_quality=c_quality_accepted AND v_qty_base>0 THEN
      v_stock:=public.wardah_apply_stock_incoming(
        v_org,v_product,v_wh_id,v_qty_base,v_cost_base,
        'Goods Receipt',v_gr_id,v_gr_number,v_recv_date
      );
      IF NOT COALESCE((v_stock->>'applied')::boolean,false) THEN
        RAISE EXCEPTION 'STOCK_IN_NOT_APPLIED: %',v_stock;
      END IF;
      v_total:=v_total+(v_qty_base*v_cost_base);
    END IF;
  END LOOP;

  -- Receipt status follows the accepted quantity: a rejected delivery must never
  -- close a purchase order that produced no inventory and no GRNI value.
  IF v_po_id IS NOT NULL THEN
    UPDATE public.purchase_orders po
    SET status=CASE WHEN NOT EXISTS(
      SELECT 1
      FROM public.purchase_order_lines l
      WHERE l.purchase_order_id=po.id
        AND COALESCE(l.accepted_quantity,0)<l.quantity
    ) THEN 'fully_received' ELSE 'partially_received' END
    WHERE po.id=v_po_id;
  END IF;

  IF v_total>0 THEN
    PERFORM public.rpc_post_event_journal(
      'GR_RECEIPT',v_total,'استلام بضاعة '||v_gr_number,
      'GOODS_RECEIPT',v_gr_id,v_org,'GR_RECEIPT:'||v_gr_id::text,NULL
    );
  END IF;

  RETURN jsonb_build_object(
    'success',true,
    'goods_receipt_id',v_gr_id,
    'receipt_number',v_gr_number,
    'total_value',round(v_total,6),
    'lines_processed',v_line_no,
    'inventory_atomic',true,
    'uom_atomic',true,
    'po_snapshot_atomic',true,
    'quality_aware_contract',true
  );
END;
$$;


--
-- Name: rpc_post_manual_event_journal(text, numeric, text, text, uuid, uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_post_manual_event_journal(p_event text, p_amount numeric, p_memo text, p_ref_type text DEFAULT NULL::text, p_ref_id uuid DEFAULT NULL::uuid, p_tenant uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_jv_date date DEFAULT CURRENT_DATE) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_org uuid;
BEGIN
  v_org := public.wardah_org_id(p_tenant);
  PERFORM public.wardah_178_assert_permission(v_org,'accounting.journals.create');
  PERFORM public.wardah_178_assert_permission(v_org,'accounting.journals.post');
  RETURN public.rpc_post_event_journal(
    p_event,p_amount,p_memo,p_ref_type,p_ref_id,v_org,p_idempotency_key,p_jv_date);
END;
$$;


--
-- Name: rpc_post_manual_journal_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_post_manual_journal_entry(p_entry_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_entry public.gl_entries%rowtype;
  v_debit numeric;
  v_credit numeric;
  v_lines integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED'; END IF;
  SELECT ge.* INTO v_entry
  FROM public.gl_entries ge
  WHERE ge.id = p_entry_id
    AND (
      EXISTS (
        SELECT 1 FROM public.super_admins sa
        WHERE sa.user_id = v_uid AND sa.is_active = true
      )
      OR EXISTS (
        SELECT 1 FROM public.user_organizations uo
        WHERE uo.user_id = v_uid
          AND uo.org_id = ge.org_id
          AND COALESCE(uo.is_active, true)
      )
    )
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'JOURNAL_ENTRY_NOT_FOUND'; END IF;

  PERFORM public.wardah_178_assert_permission(v_entry.org_id,'accounting.journals.post');
  IF v_entry.journal_origin NOT IN ('manual','manual_legacy') THEN
    RAISE EXCEPTION 'JOURNAL_SYSTEM_ENTRY_NOT_MANUAL_POSTABLE';
  END IF;
  IF v_entry.status='posted' THEN
    RETURN jsonb_build_object('success',true,'entry_id',p_entry_id,'status','posted','duplicate',true);
  END IF;
  IF v_entry.status <> 'draft' THEN RAISE EXCEPTION 'JOURNAL_ONLY_DRAFT_POSTABLE'; END IF;

  SELECT COALESCE(sum(debit),0),COALESCE(sum(credit),0),count(*)
  INTO v_debit,v_credit,v_lines
  FROM public.gl_entry_lines WHERE entry_id=p_entry_id AND org_id=v_entry.org_id;
  IF v_lines < 2 OR round(v_debit,2) <> round(v_credit,2) OR round(v_debit,2)=0 THEN
    RAISE EXCEPTION 'JOURNAL_ENTRY_NOT_BALANCED';
  END IF;
  IF round(v_debit,2) <> round(v_entry.total_debit,2)
     OR round(v_credit,2) <> round(v_entry.total_credit,2) THEN
    RAISE EXCEPTION 'JOURNAL_HEADER_LINE_TOTAL_MISMATCH';
  END IF;

  PERFORM public.assert_period_open(v_entry.org_id,v_entry.entry_date);

  UPDATE public.gl_entries
  SET status='posted',posted_at=now(),posted_by=v_uid,updated_at=now()
  WHERE id=p_entry_id;

  INSERT INTO public.audit_logs(org_id,user_id,action,entity_type,entity_id,metadata)
  VALUES (v_entry.org_id,v_uid,'journal.manual.post','gl_entry',p_entry_id::text,
          jsonb_build_object('migration',178,'entry_number',v_entry.entry_number));

  RETURN jsonb_build_object('success',true,'entry_id',p_entry_id,'status','posted');
END;
$$;


--
-- Name: rpc_post_manual_work_center_oh(text, numeric, text, text, uuid, uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_post_manual_work_center_oh(p_work_center text, p_amount numeric, p_memo text, p_ref_type text DEFAULT NULL::text, p_ref_id uuid DEFAULT NULL::uuid, p_tenant uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_jv_date date DEFAULT CURRENT_DATE) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_org uuid;
BEGIN
  v_org := public.wardah_org_id(p_tenant);
  PERFORM public.wardah_178_assert_permission(v_org,'accounting.journals.create');
  PERFORM public.wardah_178_assert_permission(v_org,'accounting.journals.post');
  RETURN public.rpc_post_work_center_oh(
