--
-- Name: rpc_resolve_uom_backfill_issue(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_resolve_uom_backfill_issue(p_org_id uuid, p_issue_id uuid, p_resolved_uom_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_status text;
  v_source_table text;
  v_source_id uuid;
  v_effective_uom uuid;
BEGIN
  PERFORM public.wardah_assert_org_admin(p_org_id);

  IF p_issue_id IS NULL THEN
    RAISE EXCEPTION 'UOM_BACKFILL_ISSUE_REQUIRED';
  END IF;

  SELECT status, source_table, source_id
  INTO v_status, v_source_table, v_source_id
  FROM public.uom_backfill_issues
  WHERE id = p_issue_id
    AND org_id = p_org_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'UOM_BACKFILL_ISSUE_NOT_FOUND: issue=%', p_issue_id;
  END IF;
  IF v_status <> 'OPEN' THEN
    RAISE EXCEPTION 'UOM_BACKFILL_ISSUE_NOT_OPEN: issue=%, status=%', p_issue_id, v_status;
  END IF;

  IF v_source_table = 'products' THEN
    SELECT p.base_uom_id
    INTO v_effective_uom
    FROM public.products p
    WHERE p.id = v_source_id
      AND p.org_id = p_org_id
      AND p.uom_migration_status = 'MAPPED'
      AND p.base_uom_id IS NOT NULL;

  ELSIF v_source_table = 'items' THEN
    SELECT i.base_uom_id
    INTO v_effective_uom
    FROM public.items i
    WHERE i.id = v_source_id
      AND i.org_id = p_org_id
      AND i.uom_migration_status = 'MAPPED'
      AND i.base_uom_id IS NOT NULL;

    IF NOT FOUND THEN
      SELECT p.base_uom_id
      INTO v_effective_uom
      FROM public.item_product_map m
      JOIN public.products p
        ON p.id = m.product_id
       AND p.org_id = p_org_id
      WHERE m.item_id = v_source_id
        AND m.org_id = p_org_id
        AND m.is_active
        AND m.valid_to IS NULL
        AND p.uom_migration_status = 'MAPPED'
        AND p.base_uom_id IS NOT NULL
      LIMIT 1;
    END IF;

  ELSIF v_source_table = 'bom_lines' THEN
    SELECT bl.uom_id
    INTO v_effective_uom
    FROM public.bom_lines bl
    WHERE bl.id = v_source_id
      AND bl.org_id = p_org_id
      AND bl.uom_id IS NOT NULL
      AND bl.product_id IS NOT NULL;

  ELSE
    RAISE EXCEPTION
      'UOM_BACKFILL_SOURCE_UNSUPPORTED: issue=%, source=%',
      p_issue_id, v_source_table;
  END IF;

  IF v_effective_uom IS NULL THEN
    RAISE EXCEPTION
      'UOM_BACKFILL_SOURCE_NOT_RESOLVED: issue=%, source=%',
      p_issue_id, v_source_table;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.uoms u
    WHERE u.id = v_effective_uom
      AND u.is_active
      AND (u.org_id IS NULL OR u.org_id = p_org_id)
  ) THEN
    RAISE EXCEPTION
      'UOM_BACKFILL_SOURCE_NOT_RESOLVED: issue=%, source=%, uom=%',
      p_issue_id, v_source_table, v_effective_uom;
  END IF;

  IF p_resolved_uom_id IS NOT NULL
     AND p_resolved_uom_id IS DISTINCT FROM v_effective_uom THEN
    RAISE EXCEPTION
      'UOM_BACKFILL_RESOLUTION_UOM_MISMATCH: issue=%, expected=%, provided=%',
      p_issue_id, v_effective_uom, p_resolved_uom_id;
  END IF;

  UPDATE public.uom_backfill_issues
  SET status = 'RESOLVED',
      resolved_uom_id = v_effective_uom,
      resolved_by = auth.uid(),
      resolved_at = v_now,
      details = COALESCE(details, '{}'::jsonb)
        || jsonb_strip_nulls(jsonb_build_object(
          'resolution_note', NULLIF(trim(p_note), ''),
          'resolution_source', v_source_table
        ))
  WHERE id = p_issue_id
    AND org_id = p_org_id;

  RETURN jsonb_build_object(
    'success', true,
    'issue_id', p_issue_id,
    'status', 'RESOLVED',
    'resolved_uom_id', v_effective_uom
  );
END;
$$;


--
-- Name: rpc_reverse_manual_journal_entry(uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_reverse_manual_journal_entry(p_entry_id uuid, p_reversal_reason text DEFAULT NULL::text, p_reversal_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_original public.gl_entries%rowtype;
  v_existing uuid;
  v_lines jsonb;
  v_result jsonb;
  v_reversal uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED'; END IF;
  SELECT ge.* INTO v_original
  FROM public.gl_entries ge
  WHERE ge.id = p_entry_id
    AND (
      EXISTS (
        SELECT 1 FROM public.super_admins sa
        WHERE sa.user_id = v_uid AND sa.is_active = true
      )
      OR EXISTS (
        SELECT 1 FROM public.user_organizations uo
        WHERE uo.user_id = v_uid
          AND uo.org_id = ge.org_id
          AND COALESCE(uo.is_active, true)
      )
    )
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'JOURNAL_ENTRY_NOT_FOUND'; END IF;

  PERFORM public.wardah_178_assert_permission(v_original.org_id,'accounting.journals.reverse');
  IF v_original.journal_origin NOT IN ('manual','manual_legacy') THEN
    RAISE EXCEPTION 'JOURNAL_SYSTEM_ENTRY_REQUIRES_SOURCE_DOCUMENT_REVERSAL';
  END IF;

  SELECT id INTO v_existing
  FROM public.gl_entries
  WHERE org_id=v_original.org_id
    AND reference_type='JOURNAL_REVERSAL'
    AND reference_id=p_entry_id
    AND status='posted'
  LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('success',true,'original_entry_id',p_entry_id,
      'reversal_entry_id',v_existing,'duplicate',true);
  END IF;

  IF v_original.status <> 'posted' THEN
    RAISE EXCEPTION 'JOURNAL_ONLY_POSTED_REVERSIBLE';
  END IF;
  PERFORM public.assert_period_open(v_original.org_id,p_reversal_date);

  SELECT jsonb_agg(jsonb_build_object(
    'line_number',line_number,'account_id',account_id,
    'debit',credit,'credit',debit,'currency_code',COALESCE(currency_code,'SAR'),
    'description',COALESCE(description,'Reversal')
  ) ORDER BY line_number)
  INTO v_lines
  FROM public.gl_entry_lines
  WHERE entry_id=p_entry_id AND org_id=v_original.org_id;

  IF v_lines IS NULL OR jsonb_array_length(v_lines)<2 THEN
    RAISE EXCEPTION 'JOURNAL_REVERSAL_LINES_MISSING';
  END IF;

  v_result := public.rpc_create_journal_entry(jsonb_build_object(
    'org_id',v_original.org_id::text,
    'journal_id',v_original.journal_id,
    'entry_date',p_reversal_date,
    'description','Reversal: ' || COALESCE(v_original.description,v_original.entry_number),
    'description_ar','عكس: ' || COALESCE(v_original.description_ar,v_original.entry_number),
    'reference_type','JOURNAL_REVERSAL',
    'reference_number','REV-' || v_original.entry_number,
    'idempotency_key','manual-reversal:' || p_entry_id::text,
    'auto_post',true,
    'lines',v_lines
  ));
  v_reversal := NULLIF(v_result->>'entry_id','')::uuid;
  IF v_reversal IS NULL THEN RAISE EXCEPTION 'JOURNAL_REVERSAL_CREATE_FAILED'; END IF;

  UPDATE public.gl_entries
  SET journal_origin='manual_reversal',reference_id=p_entry_id,
      created_by=COALESCE(created_by,v_uid),posted_by=v_uid,updated_at=now()
  WHERE id=v_reversal AND org_id=v_original.org_id;

  UPDATE public.gl_entries
  SET status='reversed',updated_at=now()
  WHERE id=p_entry_id;

  INSERT INTO public.audit_logs(org_id,user_id,action,entity_type,entity_id,metadata)
  VALUES (v_original.org_id,v_uid,'journal.manual.reverse','gl_entry',p_entry_id::text,
          jsonb_build_object('migration',178,'reversal_entry_id',v_reversal,
                             'reason',p_reversal_reason));

  RETURN jsonb_build_object('success',true,'original_entry_id',p_entry_id,
    'reversal_entry_id',v_reversal,'reversal_number',v_result->>'entry_number');
END;
$$;


--
-- Name: rpc_set_org_admin(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_set_org_admin(p_target_user_id uuid, p_org_id uuid, p_value boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller_id uuid := auth.uid();
  v_admins_count int;
  v_target_is_active_admin boolean;
  v_caller_member_active boolean;
  v_caller_member_admin boolean;
  v_caller_super_admin boolean := false;
BEGIN
  IF NOT (public.wardah_is_org_admin(p_org_id) OR public.is_super_admin()) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_ORG_ADMIN');
  END IF;
  IF p_target_user_id = v_caller_id AND p_value = true THEN
    RETURN jsonb_build_object('ok', false, 'error', 'CANNOT_PROMOTE_SELF');
  END IF;

  PERFORM 1
  FROM public.organizations o
  WHERE o.id = p_org_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ORG_NOT_FOUND');
  END IF;

  -- Re-authorize from locked rows after acquiring the shared organization
  -- lock. A second call to a STABLE helper would not be as explicit about
  -- observing a membership changed by the transaction that held this lock.
  SELECT uo.is_active IS TRUE,
         (uo.is_org_admin IS TRUE OR uo.role IN ('admin', 'owner'))
    INTO v_caller_member_active, v_caller_member_admin
  FROM public.user_organizations uo
  WHERE uo.user_id = v_caller_id
    AND uo.org_id = p_org_id
  FOR UPDATE;

  SELECT sa.is_active IS TRUE
    INTO v_caller_super_admin
  FROM public.super_admins sa
  WHERE sa.user_id = v_caller_id
  FOR UPDATE;

  IF NOT COALESCE(v_caller_super_admin, false)
     AND NOT (
       COALESCE(v_caller_member_active, false)
       AND COALESCE(v_caller_member_admin, false)
     ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_ORG_ADMIN');
  END IF;

  SELECT (uo.is_active IS TRUE AND uo.is_org_admin IS TRUE)
    INTO v_target_is_active_admin
  FROM public.user_organizations uo
  WHERE uo.user_id = p_target_user_id
    AND uo.org_id = p_org_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'USER_NOT_MEMBER');
  END IF;

  IF p_value = false AND v_target_is_active_admin THEN
    SELECT COUNT(*) INTO v_admins_count
    FROM public.user_organizations
    WHERE org_id = p_org_id
      AND is_org_admin = true
      AND is_active = true
      AND user_id <> p_target_user_id;
    IF v_admins_count = 0 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'LAST_ORG_ADMIN');
    END IF;
  END IF;

  UPDATE public.user_organizations
  SET is_org_admin = p_value
  WHERE user_id = p_target_user_id
    AND org_id = p_org_id;

  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: rpc_set_period_status(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_set_period_status(p_period_code text, p_status text, p_tenant uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_org     UUID := wardah_org_id(p_tenant);
    v_col     TEXT := wardah_periods_org_col();
    v_current TEXT;
    v_id      UUID;
BEGIN
    IF v_org IS NULL THEN
        RAISE EXCEPTION 'TENANT_MISSING: تعذر تحديد هوية المؤسسة';
    END IF;
    IF v_col IS NULL THEN
        RAISE EXCEPTION 'PERIODS_TABLE_MISSING: جدول accounting_periods غير موجود أو بنيته غير معروفة';
    END IF;
    IF p_status NOT IN ('open', 'closed', 'permanently_closed') THEN
        RAISE EXCEPTION 'INVALID_STATUS: الحالة "%" غير صالحة — المسموح: open / closed / permanently_closed', p_status;
    END IF;

    EXECUTE format(
        'SELECT id, status FROM accounting_periods WHERE %I = $1 AND period_code = $2 LIMIT 1',
        v_col
    )
    INTO v_id, v_current
    USING v_org, p_period_code;

    IF v_id IS NULL THEN
        RAISE EXCEPTION 'PERIOD_NOT_FOUND: الفترة "%" غير موجودة', p_period_code;
    END IF;

    IF v_current = 'permanently_closed' THEN
        RAISE EXCEPTION 'PERIOD_LOCKED: الفترة "%" مقفلة نهائياً ولا يمكن تغيير حالتها', p_period_code;
    END IF;

    IF v_current = p_status THEN
        RETURN jsonb_build_object(
            'success', true, 'period_code', p_period_code,
            'status', p_status, 'changed', false
        );
    END IF;

    EXECUTE format(
        'UPDATE accounting_periods SET status = $1, updated_at = now()
         WHERE %I = $2 AND period_code = $3',
        v_col
    )
    USING p_status, v_org, p_period_code;

    RETURN jsonb_build_object(
        'success', true,
        'period_code', p_period_code,
        'previous_status', v_current,
        'status', p_status,
        'changed', true
    );
END;
$_$;


--
-- Name: rpc_set_product_physical_weight(uuid, numeric, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_set_product_physical_weight(p_product_id uuid, p_net_weight numeric, p_gross_weight numeric, p_weight_uom_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org uuid; v_base_uom uuid; v_base_category uuid; v_weight_category uuid;
  v_now timestamptz:=clock_timestamp(); v_conversion_id uuid; v_factor numeric;
BEGIN
  SELECT p.org_id,p.base_uom_id,b.category_id INTO v_org,v_base_uom,v_base_category
  FROM public.products p LEFT JOIN public.uoms b ON b.id=p.base_uom_id
  WHERE p.id=p_product_id FOR UPDATE OF p;
  IF NOT FOUND THEN RAISE EXCEPTION 'PRODUCT_NOT_FOUND'; END IF;
  PERFORM public.wardah_assert_org_admin(v_org);
  IF p_net_weight IS NULL OR p_net_weight<=0 THEN RAISE EXCEPTION 'NET_WEIGHT_MUST_BE_POSITIVE'; END IF;
  IF p_gross_weight IS NOT NULL AND p_gross_weight<p_net_weight THEN RAISE EXCEPTION 'GROSS_WEIGHT_BELOW_NET_WEIGHT'; END IF;
  SELECT u.category_id INTO v_weight_category
  FROM public.uoms u JOIN public.uom_categories c ON c.id=u.category_id
  WHERE u.id=p_weight_uom_id AND u.is_active AND c.dimension='mass';
  IF NOT FOUND THEN RAISE EXCEPTION 'WEIGHT_UOM_MUST_BE_ACTIVE_MASS_UNIT'; END IF;
  IF v_base_uom IS NULL THEN RAISE EXCEPTION 'PRODUCT_BASE_UOM_REQUIRED'; END IF;

  UPDATE public.products
  SET net_weight=p_net_weight,gross_weight=p_gross_weight,
      weight_uom_id=p_weight_uom_id,updated_at=v_now
  WHERE id=p_product_id AND org_id=v_org;

  IF p_weight_uom_id<>v_base_uom THEN
    v_factor:=round(1/p_net_weight,12);
    UPDATE public.product_uom_conversions
    SET is_active=false,valid_to=v_now,updated_at=v_now
    WHERE org_id=v_org AND product_id=p_product_id AND uom_id=p_weight_uom_id
      AND is_active AND valid_to IS NULL;
    INSERT INTO public.product_uom_conversions(
      org_id,product_id,uom_id,factor_to_base,valid_from,is_active,
      use_for_purchase,use_for_sale,notes,allow_cross_dimension,
      created_by,created_at,updated_at
    ) VALUES (
      v_org,p_product_id,p_weight_uom_id,v_factor,v_now,true,
      false,false,'Generated from declared net product weight',
      v_weight_category<>v_base_category,auth.uid(),v_now,v_now
    ) RETURNING id INTO v_conversion_id;
  END IF;

  RETURN jsonb_build_object('success',true,'product_id',p_product_id,
    'net_weight',p_net_weight,'gross_weight',p_gross_weight,
    'weight_uom_id',p_weight_uom_id,'generated_conversion_id',v_conversion_id,
    'weight_uom_to_base_factor',v_factor);
END;
$$;


--
-- Name: rpc_set_product_uom_conversion(uuid, uuid, uuid, numeric, boolean, boolean, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_set_product_uom_conversion(p_org_id uuid, p_product_id uuid, p_uom_id uuid, p_factor_to_base numeric, p_use_for_purchase boolean DEFAULT false, p_use_for_sale boolean DEFAULT false, p_barcode text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_allow_cross_dimension boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_now timestamptz:=clock_timestamp(); v_id uuid; v_base_uom uuid;
  v_base_category uuid; v_target_category uuid;
BEGIN
  PERFORM public.wardah_assert_org_admin(p_org_id);
  IF p_product_id IS NULL OR p_uom_id IS NULL THEN RAISE EXCEPTION 'PRODUCT_AND_UOM_REQUIRED'; END IF;
  IF p_factor_to_base IS NULL OR p_factor_to_base<=0 THEN RAISE EXCEPTION 'UOM_FACTOR_MUST_BE_POSITIVE'; END IF;

  SELECT p.base_uom_id,b.category_id INTO v_base_uom,v_base_category
  FROM public.products p LEFT JOIN public.uoms b ON b.id=p.base_uom_id
  WHERE p.id=p_product_id AND p.org_id=p_org_id FOR UPDATE OF p;
  IF NOT FOUND THEN RAISE EXCEPTION 'PRODUCT_NOT_FOUND_OR_WRONG_ORG'; END IF;
  IF v_base_uom IS NULL OR v_base_category IS NULL THEN RAISE EXCEPTION 'PRODUCT_BASE_UOM_REQUIRED'; END IF;
  SELECT category_id INTO v_target_category FROM public.uoms WHERE id=p_uom_id AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'UOM_NOT_FOUND_OR_INACTIVE'; END IF;
  IF p_uom_id=v_base_uom AND abs(p_factor_to_base-1)>0.000000000001 THEN RAISE EXCEPTION 'BASE_UOM_FACTOR_MUST_EQUAL_ONE'; END IF;
  IF v_target_category<>v_base_category AND NOT COALESCE(p_allow_cross_dimension,false) THEN
    RAISE EXCEPTION 'PRODUCT_UOM_CROSS_DIMENSION_REQUIRES_EXPLICIT_FLAG';
  END IF;

  UPDATE public.product_uom_conversions
  SET is_active=false,valid_to=v_now,updated_at=v_now
  WHERE org_id=p_org_id AND product_id=p_product_id AND uom_id=p_uom_id
    AND is_active AND valid_to IS NULL;

  INSERT INTO public.product_uom_conversions(
    org_id,product_id,uom_id,factor_to_base,valid_from,valid_to,is_active,
    use_for_purchase,use_for_sale,barcode,notes,allow_cross_dimension,
    created_by,created_at,updated_at
  ) VALUES (
    p_org_id,p_product_id,p_uom_id,p_factor_to_base,v_now,NULL,true,
    COALESCE(p_use_for_purchase,false),COALESCE(p_use_for_sale,false),
    NULLIF(trim(p_barcode),''),NULLIF(trim(p_notes),''),
    COALESCE(p_allow_cross_dimension,false),auth.uid(),v_now,v_now
  ) RETURNING id INTO v_id;

  RETURN jsonb_build_object('success',true,'conversion_id',v_id,'org_id',p_org_id,
    'product_id',p_product_id,'uom_id',p_uom_id,'factor_to_base',p_factor_to_base,
    'allow_cross_dimension',COALESCE(p_allow_cross_dimension,false),'valid_from',v_now);
END;
$$;


--
-- Name: rpc_subledger_gl_reconciliation(date, uuid, text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_subledger_gl_reconciliation(p_as_of_date date DEFAULT CURRENT_DATE, p_tenant uuid DEFAULT NULL::uuid, p_inventory_prefixes text[] DEFAULT ARRAY['131'::text, '132'::text, '133'::text, '135'::text], p_wip_prefixes text[] DEFAULT ARRAY['134'::text]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_org UUID;

    -- كشف أعمدة gl_entry_lines (الأرشيف: debit_amount/account_code — الحي: debit/account_id)
    v_debit_col   TEXT;
    v_credit_col  TEXT;
    v_has_acct_id BOOLEAN;
    v_sql         TEXT;

    -- أرصدة GL لكل قسم + تفصيل الحسابات
    v_gl_inventory      NUMERIC := 0;
    v_gl_wip            NUMERIC := 0;
    v_inv_accounts      JSONB   := '[]'::JSONB;
    v_wip_accounts      JSONB   := '[]'::JSONB;
    v_gl_available      BOOLEAN := FALSE;

    -- الدفاتر الفرعية
    v_sub_inventory        NUMERIC := NULL;  -- NULL = غير متاح
    v_sub_inventory_source TEXT    := NULL;
    v_sub_wip              NUMERIC := NULL;
    v_sub_wip_source       TEXT    := NULL;
    v_open_mo_count        INTEGER := 0;

    -- تسوية
    v_inv_diff      NUMERIC;
    v_wip_diff      NUMERIC;
    v_inv_balanced  BOOLEAN;
    v_wip_balanced  BOOLEAN;

    -- أعمدة stage_costs الديناميكية
    v_sc_tenant_col TEXT;
    v_sc_mo_col     TEXT;
BEGIN
    -- ===== هوية المؤسسة =====
    v_org := wardah_org_id(p_tenant);
    IF v_org IS NULL THEN
        RAISE EXCEPTION 'ORG_NOT_RESOLVED: تعذر تحديد هوية المؤسسة';
    END IF;
    PERFORM public.wardah_assert_org_member(v_org);
    PERFORM public.wardah_178_assert_permission(
        v_org, 'reports.financial.read');

    -- ================================================================
    -- جانب GL: أرصدة الحسابات من القيود المرحَّلة حتى التاريخ المطلوب
    -- ================================================================
    IF to_regclass('public.gl_entries') IS NOT NULL
       AND to_regclass('public.gl_entry_lines') IS NOT NULL THEN

        SELECT column_name INTO v_debit_col
        FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'gl_entry_lines'
          AND column_name IN ('debit', 'debit_amount')
        ORDER BY CASE column_name WHEN 'debit' THEN 1 ELSE 2 END
        LIMIT 1;

        SELECT column_name INTO v_credit_col
        FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'gl_entry_lines'
          AND column_name IN ('credit', 'credit_amount')
        ORDER BY CASE column_name WHEN 'credit' THEN 1 ELSE 2 END
        LIMIT 1;

        v_has_acct_id := EXISTS (
            SELECT 1 FROM information_schema.columns
            WHERE table_schema = 'public' AND table_name = 'gl_entry_lines'
              AND column_name = 'account_id'
        ) AND to_regclass('public.gl_accounts') IS NOT NULL;

        IF v_debit_col IS NOT NULL AND v_credit_col IS NOT NULL THEN
            v_gl_available := TRUE;

            -- الرصيد المدين الصافي لكل حساب (طبيعة حسابات الأصول)
            IF v_has_acct_id THEN
                v_sql := format(
                    'SELECT COALESCE(a.code, '''') AS code,
                            COALESCE(a.name, a.name_ar, '''') AS name,
                            SUM(COALESCE(l.%I,0) - COALESCE(l.%I,0)) AS balance
                     FROM gl_entry_lines l
                     JOIN gl_entries e ON e.id = l.entry_id
                     JOIN gl_accounts a ON a.id = l.account_id
                     WHERE e.org_id = $1
                       AND e.status = ''posted''
                       AND e.entry_date <= $2
                       AND a.code LIKE ANY (SELECT unnest($3) || ''%%'')
                     GROUP BY a.code, COALESCE(a.name, a.name_ar, '''')
                     ORDER BY a.code',
                    v_debit_col, v_credit_col
                );
            ELSE
                v_sql := format(
                    'SELECT l.account_code AS code,
                            COALESCE(MAX(l.account_name), '''') AS name,
                            SUM(COALESCE(l.%I,0) - COALESCE(l.%I,0)) AS balance
                     FROM gl_entry_lines l
                     JOIN gl_entries e ON e.id = l.entry_id
                     WHERE e.org_id = $1
                       AND e.status = ''posted''
                       AND e.entry_date <= $2
                       AND l.account_code LIKE ANY (SELECT unnest($3) || ''%%'')
                     GROUP BY l.account_code
                     ORDER BY l.account_code',
                    v_debit_col, v_credit_col
                );
            END IF;

            -- قسم المخزون
            EXECUTE format(
                'SELECT COALESCE(SUM(balance),0),
                        COALESCE(jsonb_agg(jsonb_build_object(
                            ''code'', code, ''name'', name,
                            ''balance'', ROUND(balance,6))), ''[]''::jsonb)
                 FROM (%s) t', v_sql)
            INTO v_gl_inventory, v_inv_accounts
            USING v_org, p_as_of_date, p_inventory_prefixes;

            -- قسم WIP
            EXECUTE format(
                'SELECT COALESCE(SUM(balance),0),
                        COALESCE(jsonb_agg(jsonb_build_object(
                            ''code'', code, ''name'', name,
                            ''balance'', ROUND(balance,6))), ''[]''::jsonb)
                 FROM (%s) t', v_sql)
            INTO v_gl_wip, v_wip_accounts
            USING v_org, p_as_of_date, p_wip_prefixes;
        END IF;
    END IF;

    -- ================================================================
    -- الدفتر الفرعي للمخزون: آخر رصيد جارٍ لكل صنف حتى التاريخ
    -- ================================================================
    IF to_regclass('public.inventory_ledger') IS NOT NULL THEN
        BEGIN
            SELECT COALESCE(SUM(running_value), 0), 'inventory_ledger'
            INTO v_sub_inventory, v_sub_inventory_source
            FROM (
                SELECT DISTINCT ON (item_id) running_value
                FROM inventory_ledger
                WHERE tenant_id = v_org
                  AND moved_at::date <= p_as_of_date
                ORDER BY item_id, moved_at DESC, created_at DESC
            ) latest;
        EXCEPTION WHEN OTHERS THEN
            v_sub_inventory := NULL;  -- بنية أعمدة مختلفة — نجرّب المصدر الآخر
        END;
    END IF;

    IF v_sub_inventory IS NULL
       AND to_regclass('public.stock_ledger_entries') IS NOT NULL THEN
        BEGIN
            SELECT COALESCE(SUM(stock_value), 0), 'stock_ledger_entries'
            INTO v_sub_inventory, v_sub_inventory_source
            FROM (
                SELECT DISTINCT ON (product_id, warehouse_id) stock_value
                FROM stock_ledger_entries
                WHERE org_id = v_org
                  AND posting_date <= p_as_of_date
                  AND COALESCE(is_cancelled, FALSE) = FALSE
                ORDER BY product_id, warehouse_id, posting_datetime DESC
            ) latest;
        EXCEPTION WHEN OTHERS THEN
            v_sub_inventory := NULL;
        END;
    END IF;

    -- ================================================================
    -- الدفتر الفرعي لـ WIP: تكاليف مراحل الأوامر المفتوحة
    -- (أمر مكتمل/ملغى يجب أن يكون WIP الخاص به صفراً — تحوَّل لـ FG)
    -- ================================================================
    IF to_regclass('public.stage_costs') IS NOT NULL
       AND to_regclass('public.manufacturing_orders') IS NOT NULL THEN

        SELECT column_name INTO v_sc_tenant_col
        FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'stage_costs'
          AND column_name IN ('tenant_id', 'org_id')
        ORDER BY CASE column_name WHEN 'tenant_id' THEN 1 ELSE 2 END
        LIMIT 1;

        SELECT column_name INTO v_sc_mo_col
        FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'stage_costs'
          AND column_name IN ('mo_id', 'manufacturing_order_id')
        ORDER BY CASE column_name WHEN 'mo_id' THEN 1 ELSE 2 END
        LIMIT 1;

        IF v_sc_tenant_col IS NOT NULL AND v_sc_mo_col IS NOT NULL THEN
            BEGIN
                EXECUTE format(
                    'SELECT COALESCE(SUM(sc.total_cost),0), COUNT(DISTINCT mo.id)
                     FROM stage_costs sc
                     JOIN manufacturing_orders mo ON mo.id = sc.%I
                     WHERE sc.%I = $1
                       AND mo.org_id = $1
                       AND lower(replace(mo.status, ''-'', ''_''))
                           NOT IN (''done'', ''completed'', ''cancelled'', ''closed'')',
                    v_sc_mo_col, v_sc_tenant_col
                )
                INTO v_sub_wip, v_open_mo_count
                USING v_org;
                v_sub_wip_source := 'stage_costs (أوامر مفتوحة)';
            EXCEPTION WHEN OTHERS THEN
                v_sub_wip := NULL;
            END;
        END IF;
    END IF;

    -- ================================================================
    -- التسوية
    -- ================================================================
    v_inv_diff     := CASE WHEN v_gl_available AND v_sub_inventory IS NOT NULL
                           THEN v_gl_inventory - v_sub_inventory ELSE NULL END;
    v_wip_diff     := CASE WHEN v_gl_available AND v_sub_wip IS NOT NULL
                           THEN v_gl_wip - v_sub_wip ELSE NULL END;
    v_inv_balanced := v_inv_diff IS NOT NULL AND ABS(v_inv_diff) < 0.01;
    v_wip_balanced := v_wip_diff IS NOT NULL AND ABS(v_wip_diff) < 0.01;

    RETURN jsonb_build_object(
        'success', TRUE,
        'report_type', 'subledger_gl_reconciliation',
        'as_of_date', p_as_of_date,
        'generated_at', now(),
        'gl_available', v_gl_available,
        'sections', jsonb_build_array(
            jsonb_build_object(
                'section', 'inventory',
                'title_ar', 'المخزون (مواد خام + إنتاج تام)',
                'gl_prefixes', to_jsonb(p_inventory_prefixes),
                'gl_balance', CASE WHEN v_gl_available THEN ROUND(v_gl_inventory, 6) END,
                'gl_accounts', v_inv_accounts,
                'subledger_balance', CASE WHEN v_sub_inventory IS NOT NULL
                                          THEN ROUND(v_sub_inventory, 6) END,
                'subledger_source', v_sub_inventory_source,
                'difference', CASE WHEN v_inv_diff IS NOT NULL
                                   THEN ROUND(v_inv_diff, 6) END,
                'is_balanced', v_inv_balanced,
                'status', CASE
                    WHEN NOT v_gl_available          THEN 'gl_unavailable'
                    WHEN v_sub_inventory IS NULL     THEN 'subledger_unavailable'
                    WHEN v_inv_balanced              THEN 'balanced'
                    ELSE 'unbalanced' END
            ),
            jsonb_build_object(
                'section', 'wip',
                'title_ar', 'الإنتاج تحت التشغيل',
                'gl_prefixes', to_jsonb(p_wip_prefixes),
                'gl_balance', CASE WHEN v_gl_available THEN ROUND(v_gl_wip, 6) END,
                'gl_accounts', v_wip_accounts,
                'subledger_balance', CASE WHEN v_sub_wip IS NOT NULL
                                          THEN ROUND(v_sub_wip, 6) END,
                'subledger_source', v_sub_wip_source,
                'open_mo_count', v_open_mo_count,
                'difference', CASE WHEN v_wip_diff IS NOT NULL
                                   THEN ROUND(v_wip_diff, 6) END,
                'is_balanced', v_wip_balanced,
                'status', CASE
                    WHEN NOT v_gl_available      THEN 'gl_unavailable'
                    WHEN v_sub_wip IS NULL       THEN 'subledger_unavailable'
                    WHEN v_wip_balanced          THEN 'balanced'
                    ELSE 'unbalanced' END
            )
        ),
        'all_balanced', v_inv_balanced AND v_wip_balanced
    );
END;
$_$;


--
-- Name: rpc_submit_purchase_order(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_submit_purchase_order(p_org_id uuid, p_purchase_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org uuid;
  v_status text;
  v_lines integer;
BEGIN
  v_org := public.wardah_org_id(p_org_id);
  IF v_org IS NULL THEN RAISE EXCEPTION 'ORG_NOT_RESOLVED'; END IF;
  PERFORM public.wardah_assert_org_member(v_org);

  IF p_purchase_order_id IS NULL THEN
    RAISE EXCEPTION 'PO_ID_REQUIRED';
  END IF;

  SELECT status INTO v_status
  FROM public.purchase_orders
  WHERE id = p_purchase_order_id AND org_id = v_org
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'PO_NOT_FOUND'; END IF;
  IF v_status <> 'draft' THEN
    RAISE EXCEPTION 'PO_NOT_SUBMITTABLE: %', v_status;
  END IF;

  SELECT count(*) INTO v_lines
  FROM public.purchase_order_lines
  WHERE purchase_order_id = p_purchase_order_id AND org_id = v_org;

  IF v_lines = 0 THEN RAISE EXCEPTION 'PO_HAS_NO_LINES'; END IF;

  UPDATE public.purchase_orders
  SET status = 'submitted'
  WHERE id = p_purchase_order_id;

  RETURN jsonb_build_object(
    'success', true,
    'purchase_order_id', p_purchase_order_id,
    'status', 'submitted'
  );
END;
$$;


--
-- Name: rpc_submit_settlement_review(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_submit_settlement_review(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_org        UUID;
    v_settlement hr_settlements%ROWTYPE;
    v_snapshot   JSONB;
BEGIN
    v_org := wardah_org_id(NULLIF(p_payload->>'tenant_id','')::uuid);
    IF v_org IS NULL THEN RAISE EXCEPTION 'ORG_NOT_RESOLVED'; END IF;
    IF NOT EXISTS (SELECT 1 FROM user_organizations
                   WHERE user_id = auth.uid() AND org_id = v_org) THEN
        RAISE EXCEPTION 'NOT_ORG_MEMBER';
    END IF;
    IF NOT wardah_is_org_admin(v_org) THEN
        RAISE EXCEPTION 'NOT_AUTHORIZED_SETTLEMENT_POST: إرسال التسوية للمراجعة يتطلب صلاحية مدير المؤسسة';
    END IF;

    SELECT * INTO v_settlement FROM hr_settlements
    WHERE id = (p_payload->>'settlement_id')::uuid AND org_id = v_org
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'SETTLEMENT_NOT_FOUND'; END IF;
    IF v_settlement.status <> 'draft' THEN
        RAISE EXCEPTION 'SETTLEMENT_NOT_DRAFT: الحالة % — المراجعة تبدأ من مسودة', v_settlement.status;
    END IF;
    IF ROUND(COALESCE(v_settlement.payable_amount, v_settlement.calculated_amount, 0), 2) <= 0 THEN
        RAISE EXCEPTION 'SETTLEMENT_ZERO_AMOUNT';
    END IF;

    v_snapshot := wardah_settlement_snapshot(v_settlement.id);

    UPDATE hr_settlements
    SET status = 'review',
        reviewed_by = auth.uid(),
        reviewed_at = NOW(),
        review_hash = md5(v_snapshot::text),
        updated_at = NOW()
    WHERE id = v_settlement.id;

    RETURN jsonb_build_object('success', true,
        'settlement_id', v_settlement.id, 'status', 'review',
        'review_hash', md5(v_snapshot::text));
END;
$$;


--
-- Name: rpc_submit_stock_adjustment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_submit_stock_adjustment(p_adjustment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_adj public.stock_adjustments%rowtype;
  v_item record;
  v_warehouse uuid;
  v_result jsonb;
  v_gl jsonb;
  v_debit uuid;
  v_credit uuid;
  v_amount numeric;
  v_signed_value numeric;
  v_actual_qty numeric;
  v_item_count integer;
  v_distinct_count integer;
BEGIN
  SELECT * INTO v_adj
  FROM public.stock_adjustments
  WHERE id = p_adjustment_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ADJUSTMENT_NOT_FOUND'; END IF;

  v_adj.org_id := COALESCE(v_adj.org_id, v_adj.organization_id);
  PERFORM public.wardah_assert_org_admin(v_adj.org_id);

  IF v_adj.status = 'SUBMITTED' THEN
    RETURN jsonb_build_object(
      'success', true,
      'duplicate', true,
      'adjustment_id', v_adj.id,
      'gl_entry_id', v_adj.canonical_gl_entry_id
    );
  END IF;
  IF v_adj.status <> 'DRAFT' THEN RAISE EXCEPTION 'ADJUSTMENT_NOT_DRAFT'; END IF;
  IF COALESCE(v_adj.requires_approval, false) AND v_adj.approved_by IS NULL THEN
    RAISE EXCEPTION 'ADJUSTMENT_APPROVAL_REQUIRED';
  END IF;

  SELECT count(*),
         count(DISTINCT ROW(product_id, COALESCE(warehouse_id, v_adj.warehouse_id)))
  INTO v_item_count, v_distinct_count
  FROM public.stock_adjustment_items
  WHERE adjustment_id = v_adj.id;

  IF v_item_count = 0 THEN RAISE EXCEPTION 'ADJUSTMENT_REQUIRES_ITEMS'; END IF;
  IF v_item_count <> v_distinct_count THEN
    RAISE EXCEPTION 'DUPLICATE_PRODUCT_WAREHOUSE_LINES';
  END IF;

  FOR v_item IN
    SELECT *
    FROM public.stock_adjustment_items
    WHERE adjustment_id = v_adj.id
    ORDER BY id
  LOOP
    v_warehouse := COALESCE(v_item.warehouse_id, v_adj.warehouse_id);
    IF v_warehouse IS NULL THEN RAISE EXCEPTION 'WAREHOUSE_REQUIRED'; END IF;

    IF v_item.difference_qty > 0 THEN
      v_result := public.wardah_apply_stock_incoming(
        v_adj.org_id,
        v_item.product_id,
        v_warehouse,
        v_item.difference_qty,
        COALESCE(v_item.new_rate, v_item.current_rate, 0),
        'Stock Adjustment',
        v_adj.id,
        v_adj.adjustment_number,
        v_adj.posting_date,
        v_item.id
      );
      IF NOT COALESCE((v_result ->> 'applied')::boolean, false) THEN
        RAISE EXCEPTION 'STOCK_IN_NOT_APPLIED: %', v_result;
      END IF;
    ELSIF v_item.difference_qty < 0 THEN
      PERFORM public.wardah_apply_stock_outgoing(
        v_adj.org_id,
        v_item.product_id,
        v_warehouse,
        abs(v_item.difference_qty),
        'Stock Adjustment',
        v_adj.id,
        v_adj.adjustment_number,
        v_adj.posting_date,
        v_item.id
      );
    END IF;
  END LOOP;

  SELECT COALESCE(SUM(actual_qty), 0),
         COALESCE(SUM(stock_value_difference), 0)
  INTO v_actual_qty, v_signed_value
  FROM public.stock_ledger_entries
  WHERE org_id = v_adj.org_id
    AND voucher_type = 'Stock Adjustment'
    AND voucher_id = v_adj.id
    AND COALESCE(is_cancelled, false) = false;

  v_amount := abs(v_signed_value);
  IF v_amount > 0 THEN
    IF v_adj.inventory_account_id IS NULL THEN
      RAISE EXCEPTION 'INVENTORY_ACCOUNT_REQUIRED';
    END IF;
    IF v_signed_value > 0 THEN
      IF v_adj.increase_account_id IS NULL THEN
        RAISE EXCEPTION 'INCREASE_ACCOUNT_REQUIRED';
      END IF;
      v_debit := v_adj.inventory_account_id;
      v_credit := v_adj.increase_account_id;
    ELSE
      IF v_adj.decrease_account_id IS NULL THEN
        RAISE EXCEPTION 'DECREASE_ACCOUNT_REQUIRED';
      END IF;
      v_debit := v_adj.decrease_account_id;
      v_credit := v_adj.inventory_account_id;
    END IF;

    v_gl := public.rpc_create_journal_entry(jsonb_build_object(
      'org_id', v_adj.org_id,
      'entry_date', v_adj.posting_date,
      'reference_type', 'Stock Adjustment',
      'reference_number', v_adj.adjustment_number,
      'description', v_adj.reason,
      'idempotency_key', 'stock-adjustment:' || v_adj.id::text,
      'auto_post', true,
      'lines', jsonb_build_array(
        jsonb_build_object(
          'line_number', 1,
          'account_id', v_debit,
          'debit', v_amount,
          'credit', 0,
          'description', v_adj.reason
        ),
        jsonb_build_object(
          'line_number', 2,
          'account_id', v_credit,
          'debit', 0,
          'credit', v_amount,
          'description', v_adj.reason
        )
      )
    ));
  END IF;

  UPDATE public.stock_adjustments
  SET status = 'SUBMITTED',
      total_qty_difference = v_actual_qty,
      total_value_difference = v_signed_value,
      submitted_by = auth.uid(),
      submitted_at = now(),
      canonical_gl_entry_id = NULLIF(v_gl ->> 'entry_id', '')::uuid,
      updated_by = auth.uid(),
      updated_at = now()
  WHERE id = v_adj.id;

  RETURN jsonb_build_object(
    'success', true,
    'adjustment_id', v_adj.id,
    'actual_qty_difference', v_actual_qty,
    'actual_value_difference', v_signed_value,
    'gl_entry_id', NULLIF(v_gl ->> 'entry_id', '')::uuid
  );
END;
$$;


--
-- Name: rpc_transition_mo_status(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_transition_mo_status(p_mo_id uuid, p_status text, p_notes text DEFAULT NULL::text, p_tenant uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_org  UUID;
    v_uid  UUID;
    v_prev TEXT;
    v_norm TEXT;
    v_mo   RECORD;
BEGIN
    v_org  := wardah_org_id(p_tenant);
    IF v_org IS NULL THEN
        RAISE EXCEPTION 'ORG_NOT_RESOLVED: تعذر تحديد هوية المؤسسة';
    END IF;

    v_uid := auth.uid();
    IF v_uid IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM user_organizations WHERE user_id = v_uid AND org_id = v_org
    ) THEN
        RAISE EXCEPTION 'FORBIDDEN_ORG: المستخدم ليس عضواً في المؤسسة المطلوبة';
    END IF;

    v_norm := normalize_mo_status(p_status);

    SELECT id, status, order_number INTO v_mo
    FROM manufacturing_orders
    WHERE id = p_mo_id AND org_id = v_org;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'MO_NOT_FOUND: أمر التصنيع "%" غير موجود ضمن مؤسستك', p_mo_id;
    END IF;
    v_prev := normalize_mo_status(v_mo.status);

    PERFORM validate_mo_transition(v_mo.status, v_norm);

    UPDATE manufacturing_orders
    SET status = v_norm, notes = COALESCE(p_notes, notes)
    WHERE id = p_mo_id AND org_id = v_org;

    SELECT id, order_number, status, start_date, completed_date, updated_at
    INTO v_mo
    FROM manufacturing_orders WHERE id = p_mo_id;

    RETURN jsonb_build_object(
        'success', TRUE,
        'mo_id', p_mo_id,
        'order_number', v_mo.order_number,
        'previous_status', v_prev,
        'new_status', v_norm,
        'start_date', v_mo.start_date,
        'completed_date', v_mo.completed_date,
        'updated_at', v_mo.updated_at
    );
END;
$$;


--
-- Name: rpc_update_customer_receipt_draft(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_customer_receipt_draft(p_receipt_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF public.get_current_tenant_id() IS NULL
     OR NOT public.wardah_is_org_member(public.get_current_tenant_id()) THEN
    RAISE EXCEPTION 'TENANT_MEMBERSHIP_REQUIRED';
  END IF;
  PERFORM public.wardah_169_enter_write_context();
  BEGIN
    v_result := public.wardah_169_internal_update_customer_receipt_draft(p_receipt_id, p_payload);
  EXCEPTION WHEN OTHERS THEN
    PERFORM public.wardah_169_leave_write_context();
    RAISE;
  END;
  PERFORM public.wardah_169_leave_write_context();
  RETURN v_result;
END $$;


--
-- Name: rpc_update_manual_journal_entry(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_update_manual_journal_entry(p_entry_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_old public.gl_entries%rowtype;
  v_entry_date date;
  v_journal uuid;
  v_total_debit numeric;
  v_total_credit numeric;
  v_line_count integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED'; END IF;

  SELECT ge.* INTO v_old
  FROM public.gl_entries ge
  WHERE ge.id = p_entry_id
    AND (
      EXISTS (
        SELECT 1 FROM public.super_admins sa
        WHERE sa.user_id = v_uid AND sa.is_active = true
      )
      OR EXISTS (
        SELECT 1 FROM public.user_organizations uo
        WHERE uo.user_id = v_uid
          AND uo.org_id = ge.org_id
          AND COALESCE(uo.is_active, true)
      )
    )
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'JOURNAL_ENTRY_NOT_FOUND'; END IF;

  PERFORM public.wardah_178_assert_permission(v_old.org_id, 'accounting.journals.update');
  IF v_old.journal_origin NOT IN ('manual','manual_legacy') THEN
    RAISE EXCEPTION 'JOURNAL_SYSTEM_ENTRY_NOT_MANUAL_EDITABLE';
  END IF;
  IF v_old.status <> 'draft' THEN
    RAISE EXCEPTION 'JOURNAL_ONLY_DRAFT_EDITABLE';
  END IF;

  PERFORM public.wardah_178_validate_manual_lines(v_old.org_id, p_payload->'lines');

  SELECT COALESCE(sum(COALESCE((l->>'debit')::numeric,0)),0),
         COALESCE(sum(COALESCE((l->>'credit')::numeric,0)),0), count(*)
  INTO v_total_debit,v_total_credit,v_line_count
  FROM jsonb_array_elements(p_payload->'lines') l;
  IF round(v_total_debit,2) <> round(v_total_credit,2) OR round(v_total_debit,2)=0 THEN
    RAISE EXCEPTION 'UNBALANCED_ENTRY';
  END IF;

  v_entry_date := COALESCE(NULLIF(p_payload->>'entry_date','')::date, v_old.entry_date);
  PERFORM public.assert_period_open(v_old.org_id, v_entry_date);

  v_journal := COALESCE(NULLIF(p_payload->>'journal_id','')::uuid, v_old.journal_id);
  IF v_journal IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.journals j
    WHERE j.id=v_journal AND j.org_id=v_old.org_id AND COALESCE(j.is_active,true)
  ) THEN
    RAISE EXCEPTION 'JOURNAL_NOT_ACTIVE_IN_ORG';
  END IF;

  UPDATE public.gl_entries
  SET journal_id=v_journal,
      entry_date=v_entry_date,
      description=NULLIF(p_payload->>'description',''),
      description_ar=NULLIF(p_payload->>'description_ar',''),
      reference_type=NULLIF(p_payload->>'reference_type',''),
      reference_number=NULLIF(p_payload->>'reference_number',''),
      total_debit=v_total_debit,
      total_credit=v_total_credit,
      updated_at=now()
  WHERE id=p_entry_id;

  DELETE FROM public.gl_entry_lines WHERE entry_id=p_entry_id;
  INSERT INTO public.gl_entry_lines(
    org_id,tenant_id,entry_id,line_number,account_id,debit,credit,
    currency_code,description,description_ar
  )
  SELECT v_old.org_id,v_old.org_id,p_entry_id,
         COALESCE((l.value->>'line_number')::int,l.ord::int),
         (l.value->>'account_id')::uuid,
         COALESCE((l.value->>'debit')::numeric,0),
         COALESCE((l.value->>'credit')::numeric,0),
         COALESCE(NULLIF(l.value->>'currency_code',''),'SAR'),
         NULLIF(l.value->>'description',''),NULLIF(l.value->>'description_ar','')
  FROM jsonb_array_elements(p_payload->'lines') WITH ORDINALITY AS l(value,ord);

  INSERT INTO public.audit_logs(org_id,user_id,action,entity_type,entity_id,metadata)
  VALUES (v_old.org_id,v_uid,'journal.manual.update','gl_entry',p_entry_id::text,
          jsonb_build_object('migration',178));

  RETURN jsonb_build_object('success',true,'entry_id',p_entry_id,'status','draft');
END;
$$;


