--
-- Name: rpc_upsert_event_mapping(text, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_upsert_event_mapping(p_event_code text, p_debit_account_code text, p_credit_account_code text, p_work_center_code text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_tenant uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_org UUID := wardah_org_id(p_tenant);
    v_id UUID;
BEGIN
    IF v_org IS NULL THEN
        RAISE EXCEPTION 'TENANT_MISSING: تعذر تحديد هوية المؤسسة';
    END IF;

    IF to_regclass('public.gl_accounts') IS NOT NULL THEN
        IF NOT EXISTS (SELECT 1 FROM gl_accounts WHERE org_id = v_org AND code = p_debit_account_code) THEN
            RAISE EXCEPTION 'ACCOUNT_NOT_FOUND: الحساب المدين % غير موجود في شجرة الحسابات', p_debit_account_code;
        END IF;
        IF NOT EXISTS (SELECT 1 FROM gl_accounts WHERE org_id = v_org AND code = p_credit_account_code) THEN
            RAISE EXCEPTION 'ACCOUNT_NOT_FOUND: الحساب الدائن % غير موجود في شجرة الحسابات', p_credit_account_code;
        END IF;
    END IF;

    INSERT INTO gl_event_mappings (org_id, event_code, work_center_code,
                                   debit_account_code, credit_account_code, description)
    VALUES (v_org, upper(p_event_code), p_work_center_code,
            p_debit_account_code, p_credit_account_code, p_description)
    ON CONFLICT (org_id, event_code, COALESCE(work_center_code, ''))
    DO UPDATE SET debit_account_code = EXCLUDED.debit_account_code,
                  credit_account_code = EXCLUDED.credit_account_code,
                  description = COALESCE(EXCLUDED.description, gl_event_mappings.description),
                  is_active = true,
                  updated_at = NOW()
    RETURNING id INTO v_id;

    RETURN v_id;
END;
$$;


--
-- Name: rpc_upsert_org_role(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rpc_upsert_org_role(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org         uuid := NULLIF(p_payload->>'org_id','')::uuid;
  v_role_id     uuid := NULLIF(p_payload->>'role_id','')::uuid;
  v_name        text := btrim(COALESCE(p_payload->>'name',''));
  v_name_ar     text := NULLIF(btrim(COALESCE(p_payload->>'name_ar','')),'');
  v_description text := NULLIF(btrim(COALESCE(p_payload->>'description','')),'');
  v_is_active   boolean := COALESCE((p_payload->>'is_active')::boolean, true);
  v_keys        text[];
  v_missing     text[];
  v_old         jsonb;
  v_created     boolean := false;
  v_sensitive   text[];
  v_old_keys    jsonb := '[]'::jsonb;
BEGIN
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'RBAC_174_ORG_REQUIRED';
  END IF;
  PERFORM public.wardah_assert_org_admin(v_org);

  IF v_name = '' THEN
    RAISE EXCEPTION 'RBAC_174_ROLE_NAME_REQUIRED';
  END IF;

  -- Permission keys are optional (a role may legitimately have none yet) but
  -- must all exist when supplied — an unknown key is a client bug, not a
  -- silently-dropped grant.
  SELECT COALESCE(array_agg(DISTINCT k), ARRAY[]::text[])
    INTO v_keys
  FROM jsonb_array_elements_text(COALESCE(p_payload->'permission_keys','[]'::jsonb)) AS t(k);

  SELECT COALESCE(array_agg(k), ARRAY[]::text[]) INTO v_missing
  FROM unnest(v_keys) AS k
  WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.permission_key = k);

  IF array_length(v_missing, 1) IS NOT NULL THEN
    RAISE EXCEPTION 'RBAC_174_UNKNOWN_PERMISSION_KEY: %', array_to_string(v_missing, ', ');
  END IF;

  IF v_role_id IS NULL THEN
    -- Create. Name must be unique within the organization.
    IF EXISTS (
      SELECT 1 FROM public.roles r
      WHERE r.org_id = v_org AND lower(r.name) = lower(v_name)
    ) THEN
      RAISE EXCEPTION 'RBAC_174_ROLE_NAME_TAKEN';
    END IF;

    -- roles.name_ar is NOT NULL in this schema with no default; fall back to
    -- the Latin name rather than failing on a client that omits it.
    INSERT INTO public.roles (org_id, name, name_ar, description, is_active, is_system_role, created_by)
    VALUES (v_org, v_name, COALESCE(v_name_ar, v_name), v_description, v_is_active, false, auth.uid())
    RETURNING id INTO v_role_id;

    v_created := true;
  ELSE
    -- Update. Lock the row so two concurrent editors cannot interleave.
    SELECT to_jsonb(r) INTO v_old
    FROM public.roles r
    WHERE r.id = v_role_id AND r.org_id = v_org
    FOR UPDATE;

    IF v_old IS NULL THEN
      RAISE EXCEPTION 'RBAC_174_ROLE_NOT_FOUND_IN_ORG';
    END IF;
    IF COALESCE((v_old->>'is_system_role')::boolean, false) THEN
      RAISE EXCEPTION 'RBAC_174_SYSTEM_ROLE_IMMUTABLE';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.roles r
      WHERE r.org_id = v_org AND lower(r.name) = lower(v_name) AND r.id <> v_role_id
    ) THEN
      RAISE EXCEPTION 'RBAC_174_ROLE_NAME_TAKEN';
    END IF;

    UPDATE public.roles
       SET name = v_name,
           name_ar = COALESCE(v_name_ar, v_name),
           description = v_description,
           is_active = v_is_active,
           updated_at = now()
     WHERE id = v_role_id AND org_id = v_org;
  END IF;

  -- Capture the OUTGOING permission set before it is deleted. Without this the
  -- audit row records what a role became but not what it lost, which is the
  -- half that matters when reconstructing how someone came to hold a sensitive
  -- key — or stopped holding it.
  SELECT COALESCE(jsonb_agg(p.permission_key ORDER BY p.permission_key), '[]'::jsonb)
    INTO v_old_keys
  FROM public.role_permissions rp
  JOIN public.permissions p ON p.id = rp.permission_id
  WHERE rp.role_id = v_role_id;

  -- Replace the permission set atomically: both statements are in the same
  -- transaction as the role row itself, so a failure leaves neither applied.
  DELETE FROM public.role_permissions WHERE role_id = v_role_id;

  IF array_length(v_keys, 1) IS NOT NULL THEN
    INSERT INTO public.role_permissions (role_id, permission_id, created_by)
    SELECT v_role_id, p.id, auth.uid()
    FROM public.permissions p
    WHERE p.permission_key = ANY (v_keys);
  END IF;

  SELECT COALESCE(array_agg(k), ARRAY[]::text[]) INTO v_sensitive
  FROM unnest(v_keys) AS k
  WHERE public.wardah_is_sensitive_permission(k);

  INSERT INTO public.audit_logs (org_id, user_id, action, entity_type, entity_id, old_data, new_data, metadata)
  VALUES (
    v_org, auth.uid(),
    CASE WHEN v_created THEN 'rbac.role.create' ELSE 'rbac.role.update' END,
    'role', v_role_id::text,
    -- Complete before/after snapshots, same shape on both sides, so a reader
    -- can diff them without knowing which fields the RPC happened to touch.
    jsonb_build_object('role', v_old, 'permission_keys', v_old_keys),
    jsonb_build_object(
      'role', jsonb_build_object(
        'id', v_role_id, 'org_id', v_org, 'name', v_name,
        'name_ar', COALESCE(v_name_ar, v_name), 'description', v_description,
        'is_active', v_is_active, 'is_system_role', false),
      'permission_keys', to_jsonb(v_keys)),
    jsonb_build_object(
      'migration', 174,
      'permission_count', COALESCE(array_length(v_keys, 1), 0),
      'permissions_added', to_jsonb(ARRAY(
        SELECT k FROM unnest(v_keys) AS k
        WHERE NOT v_old_keys @> to_jsonb(k) ORDER BY k)),
      'permissions_removed', to_jsonb(ARRAY(
        SELECT ok FROM jsonb_array_elements_text(v_old_keys) AS o(ok)
        WHERE NOT (ok = ANY (v_keys)) ORDER BY ok)),
      'sensitive_keys', to_jsonb(v_sensitive),
      'grants_sensitive', COALESCE(array_length(v_sensitive, 1), 0) > 0)
  );

  RETURN jsonb_build_object(
    'role_id', v_role_id,
    'created', v_created,
    'permission_count', COALESCE(array_length(v_keys, 1), 0),
    'sensitive_keys', to_jsonb(v_sensitive));
END;
$$;


--
-- Name: schedule_details; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.schedule_details (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    schedule_id uuid NOT NULL,
    work_order_id uuid NOT NULL,
    schedule_sequence integer NOT NULL,
    scheduled_start timestamp with time zone NOT NULL,
    scheduled_end timestamp with time zone NOT NULL,
    priority integer DEFAULT 5,
    schedule_status character varying(20) DEFAULT 'SCHEDULED'::character varying,
    delay_reason text,
    delay_hours numeric(10,2),
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT schedule_details_schedule_status_check CHECK (((schedule_status)::text = ANY (ARRAY[('SCHEDULED'::character varying)::text, ('CONFIRMED'::character varying)::text, ('STARTED'::character varying)::text, ('COMPLETED'::character varying)::text, ('DELAYED'::character varying)::text, ('CANCELLED'::character varying)::text])))
);


--
-- Name: schedule_work_order(uuid, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_work_order(p_work_order_id uuid, p_scheduled_start timestamp with time zone, p_schedule_id uuid DEFAULT NULL::uuid) RETURNS public.schedule_details
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_work_order work_orders;
    v_scheduled_end TIMESTAMP WITH TIME ZONE;
    v_result schedule_details;
    v_sequence INTEGER;
BEGIN
    -- الحصول على أمر العمل
    SELECT * INTO v_work_order FROM work_orders WHERE id = p_work_order_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Work order not found: %', p_work_order_id;
    END IF;

    -- [120] حارس عضوية على مؤسسة أمر العمل
    PERFORM public.wardah_assert_org_member(v_work_order.org_id);

    -- حساب وقت الانتهاء المتوقع
    v_scheduled_end := p_scheduled_start +
        ((v_work_order.planned_setup_time + v_work_order.planned_run_time) * INTERVAL '1 minute');

    -- تحديث أمر العمل
    UPDATE work_orders SET
        planned_start_date = p_scheduled_start,
        planned_end_date = v_scheduled_end,
        updated_at = NOW()
    WHERE id = p_work_order_id;

    -- إذا تم تحديد جدول
    IF p_schedule_id IS NOT NULL THEN
        -- الحصول على التسلسل التالي
        SELECT COALESCE(MAX(schedule_sequence), 0) + 1 INTO v_sequence
        FROM schedule_details WHERE schedule_id = p_schedule_id;

        -- إدراج تفاصيل الجدولة
        INSERT INTO schedule_details (
            org_id, schedule_id, work_order_id, schedule_sequence,
            scheduled_start, scheduled_end, priority, schedule_status
        ) VALUES (
            v_work_order.org_id, p_schedule_id, p_work_order_id, v_sequence,
            p_scheduled_start, v_scheduled_end, v_work_order.priority, 'SCHEDULED'
        )
        ON CONFLICT (schedule_id, work_order_id)
        DO UPDATE SET
            scheduled_start = EXCLUDED.scheduled_start,
            scheduled_end = EXCLUDED.scheduled_end,
            updated_at = NOW()
        RETURNING * INTO v_result;

        RETURN v_result;
    END IF;

    RETURN NULL;
END;
$$;


--
-- Name: search_accounts(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_accounts(p_org_id uuid, p_search_term character varying) RETURNS TABLE(account_id uuid, code character varying, name character varying, category character varying, subtype character varying)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        id,
        gl_accounts.code,
        gl_accounts.name,
        gl_accounts.category,
        gl_accounts.subtype
    FROM gl_accounts
    WHERE gl_accounts.org_id = p_org_id
    AND is_active = true
    AND (
        LOWER(gl_accounts.code) LIKE LOWER('%' || p_search_term || '%')
        OR LOWER(gl_accounts.name) LIKE LOWER('%' || p_search_term || '%')
    )
    ORDER BY gl_accounts.code
    LIMIT 50;
END;
$$;


--
-- Name: select_optimal_bom(uuid, numeric, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.select_optimal_bom(p_item_id uuid, p_quantity numeric, p_order_date date DEFAULT CURRENT_DATE, p_org_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_selected_bom_id UUID;
    v_primary_bom_id UUID;
    v_alternative_bom_id UUID;
    v_rule bom_selection_rules%ROWTYPE;
    v_condition_met BOOLEAN;
    v_min_cost NUMERIC;
    v_bom_cost NUMERIC;
    v_primary_cost NUMERIC;
BEGIN
    -- البحث عن BOM الأساسي
    SELECT id INTO v_primary_bom_id
    FROM bom_headers
    WHERE item_id = p_item_id
    AND is_active = true
    AND status = 'APPROVED'
    AND (p_org_id IS NULL OR org_id = p_org_id)
    ORDER BY bom_version DESC, effective_date DESC
    LIMIT 1;

    IF v_primary_bom_id IS NULL THEN
        RAISE EXCEPTION 'No active BOM found for item';
    END IF;

    -- حساب تكلفة BOM الأساسي
    SELECT COALESCE(calculate_bom_cost(v_primary_bom_id, p_quantity), 0) INTO v_primary_cost;
    v_min_cost := v_primary_cost;
    v_selected_bom_id := v_primary_bom_id;

    -- البحث عن BOMs بديلة
    FOR v_alternative_bom_id IN
        SELECT alternative_bom_id
        FROM bom_alternatives
        WHERE primary_bom_id = v_primary_bom_id
        AND is_active = true
        AND (p_org_id IS NULL OR org_id = p_org_id)
        AND (min_quantity IS NULL OR p_quantity >= min_quantity)
        AND (max_quantity IS NULL OR p_quantity <= max_quantity)
        AND (effective_from IS NULL OR p_order_date >= effective_from)
        AND (effective_to IS NULL OR p_order_date <= effective_to)
        ORDER BY priority, is_default DESC
    LOOP
        -- التحقق من القواعد
        v_condition_met := true; -- افتراضياً، الشرط محقق
        
        -- تقييم القواعد (مبسط - يمكن تطويره)
        FOR v_rule IN
            SELECT * FROM bom_selection_rules
            WHERE org_id = p_org_id
            AND is_active = true
            ORDER BY priority
        LOOP
            -- تقييم الشرط بناءً على rule_type
            IF v_rule.rule_type = 'COST' THEN
                -- اختيار BOM الأقل تكلفة
                SELECT COALESCE(calculate_bom_cost(v_alternative_bom_id, p_quantity), 0) INTO v_bom_cost;
                
                IF v_bom_cost < v_min_cost THEN
                    v_min_cost := v_bom_cost;
                    v_selected_bom_id := v_alternative_bom_id;
                END IF;
            ELSIF v_rule.rule_type = 'QUANTITY' THEN
                -- التحقق من شروط الكمية
                v_condition_met := true; -- TODO: تقييم condition_json
            ELSE
                v_condition_met := true;
            END IF;
        END LOOP;
        
        -- إذا لم تكن هناك قواعد، استخدم BOM الأقل تكلفة
        IF NOT EXISTS (SELECT 1 FROM bom_selection_rules WHERE org_id = p_org_id AND is_active = true) THEN
            SELECT COALESCE(calculate_bom_cost(v_alternative_bom_id, p_quantity), 0) INTO v_bom_cost;
            
            IF v_bom_cost < v_min_cost THEN
                v_min_cost := v_bom_cost;
                v_selected_bom_id := v_alternative_bom_id;
            END IF;
        END IF;
    END LOOP;

    RETURN v_selected_bom_id;
END;
$$;


