--
-- Name: trg_normalize_stock_adjustment_uom(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_normalize_stock_adjustment_uom() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_org uuid:=NEW.organization_id; v_uom uuid; v_factor numeric;
BEGIN
  SELECT COALESCE(NEW.uom_id,p.base_uom_id) INTO v_uom
  FROM public.products p WHERE p.id=NEW.product_id AND p.org_id=v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'ADJUSTMENT_PRODUCT_NOT_FOUND_OR_WRONG_ORG'; END IF;
  v_factor:=public.wardah_uom_factor(v_org,NEW.product_id,v_uom,now());
  NEW.uom_id:=v_uom; NEW.conversion_factor_snapshot:=v_factor;
  IF NEW.current_qty_entered IS NOT NULL THEN NEW.current_qty:=round(NEW.current_qty_entered*v_factor,6);
  ELSE NEW.current_qty_entered:=round(NEW.current_qty/v_factor,6); END IF;
  IF NEW.new_qty_entered IS NOT NULL THEN NEW.new_qty:=round(NEW.new_qty_entered*v_factor,6);
  ELSE NEW.new_qty_entered:=round(NEW.new_qty/v_factor,6); END IF;
  NEW.qty_entered:=NEW.new_qty_entered;
  NEW.difference_qty:=round(NEW.new_qty-NEW.current_qty,6);
  NEW.value_difference:=round(NEW.difference_qty*COALESCE(NEW.new_rate,NEW.current_rate,0),2);
  RETURN NEW;
END;
$$;


--
-- Name: trg_resolve_item_product_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_resolve_item_product_reference() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.item_id IS NOT NULL THEN
    NEW.product_id:=public.wardah_resolve_product_id(NEW.org_id,NEW.item_id,COALESCE(NEW.created_at,now()));
  ELSIF NEW.product_id IS NULL THEN
    RAISE EXCEPTION 'ITEM_OR_PRODUCT_REQUIRED';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_validate_product_uom_conversion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_validate_product_uom_conversion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_product_org uuid; v_base_category uuid; v_target_category uuid;
BEGIN
  SELECT p.org_id,base.category_id INTO v_product_org,v_base_category
  FROM public.products p JOIN public.uoms base ON base.id=p.base_uom_id
  WHERE p.id=NEW.product_id AND (base.org_id IS NULL OR base.org_id=p.org_id);
  IF NOT FOUND OR v_product_org IS DISTINCT FROM NEW.org_id THEN RAISE EXCEPTION 'PRODUCT_UOM_WRONG_ORG_OR_BASE_MISSING'; END IF;
  SELECT category_id INTO v_target_category FROM public.uoms
  WHERE id=NEW.uom_id AND is_active AND (org_id IS NULL OR org_id=NEW.org_id);
  IF NOT FOUND THEN RAISE EXCEPTION 'PRODUCT_UOM_TARGET_INVALID_OR_WRONG_ORG'; END IF;
  IF v_target_category<>v_base_category AND NOT COALESCE(NEW.allow_cross_dimension,false) THEN
    RAISE EXCEPTION 'PRODUCT_UOM_CROSS_DIMENSION_REQUIRES_EXPLICIT_FLAG';
  END IF;
  NEW.updated_at:=now(); RETURN NEW;
END;
$$;


