--
-- Name: uom_normalize_alias(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uom_normalize_alias(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
