--
-- Name: wardah_169_internal_cancel_customer_receipt(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_169_internal_cancel_customer_receipt(p_receipt_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_receipt public.customer_collections%ROWTYPE;
  v_entry public.gl_entries%ROWTYPE;
  v_reset_id uuid;
  v_gl_rows integer;
  v_path text;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF length(trim(coalesce(p_reason, ''))) < 5 THEN
    RAISE EXCEPTION 'VOUCHER_CANCEL_REASON_REQUIRED';
  END IF;

  v_org := public.get_current_tenant_id();
  IF v_org IS NULL OR NOT public.wardah_is_org_member(v_org) THEN
    RAISE EXCEPTION 'TENANT_MEMBERSHIP_REQUIRED';
  END IF;
  IF NOT public.wardah_has_exact_permission(v_actor, v_org, 'accounting.vouchers.cancel') THEN
    RAISE EXCEPTION 'VOUCHER_CANCEL_PERMISSION_REQUIRED';
  END IF;

  SELECT * INTO v_receipt
  FROM public.customer_collections
  WHERE id = p_receipt_id AND org_id = v_org
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'CUSTOMER_RECEIPT_NOT_FOUND_OR_CROSS_ORG'; END IF;

  IF v_receipt.status = 'cancelled' THEN
    RETURN jsonb_build_object('success', true, 'duplicate', true,
      'receipt_id', v_receipt.id, 'status', 'cancelled',
      'entry_id', v_receipt.gl_entry_id);
  END IF;
  IF v_receipt.status = 'posted' THEN
    RAISE EXCEPTION 'VOUCHER_CANCEL_REQUIRES_RESET: reset the receipt before cancelling it';
  END IF;
  IF v_receipt.status <> 'draft' THEN
    RAISE EXCEPTION 'CUSTOMER_RECEIPT_NOT_CANCELLABLE: status=%', v_receipt.status;
  END IF;

  SELECT a.id INTO v_reset_id
  FROM public.audit_logs a
  WHERE a.org_id = v_org
    AND a.action = 'voucher_reset_to_draft'
    AND a.entity_type = 'customer_receipt'
    AND a.entity_id = v_receipt.id::text
  ORDER BY a.created_at DESC NULLS LAST, a.id DESC
  LIMIT 1;

  IF v_receipt.gl_entry_id IS NULL THEN
    IF v_reset_id IS NOT NULL THEN
      RAISE EXCEPTION 'CUSTOMER_RECEIPT_CANCEL_STATE_INCONSISTENT: reset record without GL identity';
    END IF;
    v_path := 'never_posted';
  ELSE
    IF v_reset_id IS NULL THEN
      RAISE EXCEPTION 'CUSTOMER_RECEIPT_CANCEL_UNPROVEN: GL identity without a trusted reset record';
    END IF;
    v_path := 'corrected';

    SELECT * INTO v_entry
    FROM public.gl_entries
    WHERE id = v_receipt.gl_entry_id AND org_id = v_org
    FOR UPDATE;
    IF NOT FOUND
       OR v_entry.status <> 'draft'
       OR v_entry.reference_type <> 'CUSTOMER_RECEIPT'
       OR v_entry.reference_id <> v_receipt.id THEN
      RAISE EXCEPTION 'CUSTOMER_RECEIPT_CANCEL_GL_INVALID';
    END IF;

    PERFORM set_config('wardah.voucher_gl_cancel', 'on', true);
    UPDATE public.gl_entries
    SET status = 'cancelled', updated_at = now()
    WHERE id = v_entry.id AND org_id = v_org AND status = 'draft';
    GET DIAGNOSTICS v_gl_rows = ROW_COUNT;
    PERFORM set_config('wardah.voucher_gl_cancel', 'off', true);
    IF v_gl_rows <> 1 THEN RAISE EXCEPTION 'CUSTOMER_RECEIPT_CANCEL_GL_STATE_CHANGED'; END IF;
  END IF;

  UPDATE public.customer_collections
  SET status = 'cancelled', updated_at = now()
  WHERE id = v_receipt.id AND org_id = v_org AND status = 'draft';
  IF NOT FOUND THEN RAISE EXCEPTION 'CUSTOMER_RECEIPT_STATE_CHANGED'; END IF;

  INSERT INTO public.audit_logs(
    org_id, user_id, action, entity_type, entity_id, old_data, new_data, changes, metadata
  ) VALUES (
    v_org, v_actor, 'voucher_cancelled', 'customer_receipt', v_receipt.id::text,
    jsonb_build_object('status', 'draft', 'gl_entry_id', v_receipt.gl_entry_id,
                       'gl_status', CASE WHEN v_path = 'corrected' THEN v_entry.status ELSE NULL END,
                       'entry_number', CASE WHEN v_path = 'corrected' THEN v_entry.entry_number ELSE NULL END),
    jsonb_build_object('status', 'cancelled', 'gl_entry_id', v_receipt.gl_entry_id,
                       'gl_status', CASE WHEN v_path = 'corrected' THEN 'cancelled' ELSE NULL END,
                       'entry_number', CASE WHEN v_path = 'corrected' THEN v_entry.entry_number ELSE NULL END),
    jsonb_build_object('reason', trim(p_reason), 'path', v_path),
    jsonb_build_object('source', 'rpc_cancel_customer_receipt',
                       'reset_audit_id', v_reset_id)
  );

  RETURN jsonb_build_object('success', true, 'duplicate', false,
    'receipt_id', v_receipt.id, 'status', 'cancelled',
    'entry_id', v_receipt.gl_entry_id, 'path', v_path);
END
$$;


--
-- Name: wardah_169_internal_cancel_supplier_payment(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_169_internal_cancel_supplier_payment(p_payment_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_payment public.supplier_payments%ROWTYPE;
  v_entry public.gl_entries%ROWTYPE;
  v_reset_id uuid;
  v_gl_rows integer;
  v_path text;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF length(trim(coalesce(p_reason, ''))) < 5 THEN
    RAISE EXCEPTION 'VOUCHER_CANCEL_REASON_REQUIRED';
  END IF;

  v_org := public.get_current_tenant_id();
  IF v_org IS NULL OR NOT public.wardah_is_org_member(v_org) THEN
    RAISE EXCEPTION 'TENANT_MEMBERSHIP_REQUIRED';
  END IF;
  IF NOT public.wardah_has_exact_permission(v_actor, v_org, 'accounting.vouchers.cancel') THEN
    RAISE EXCEPTION 'VOUCHER_CANCEL_PERMISSION_REQUIRED';
  END IF;

  SELECT * INTO v_payment
  FROM public.supplier_payments
  WHERE id = p_payment_id AND org_id = v_org
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'SUPPLIER_PAYMENT_NOT_FOUND_OR_CROSS_ORG'; END IF;

  IF v_payment.status = 'cancelled' THEN
    RETURN jsonb_build_object('success', true, 'duplicate', true,
      'payment_id', v_payment.id, 'status', 'cancelled',
      'entry_id', v_payment.gl_entry_id);
  END IF;
  IF v_payment.status = 'posted' THEN
    RAISE EXCEPTION 'VOUCHER_CANCEL_REQUIRES_RESET: reset the payment before cancelling it';
  END IF;
  IF v_payment.status <> 'draft' THEN
    RAISE EXCEPTION 'SUPPLIER_PAYMENT_NOT_CANCELLABLE: status=%', v_payment.status;
  END IF;

  SELECT a.id INTO v_reset_id
  FROM public.audit_logs a
  WHERE a.org_id = v_org
    AND a.action = 'voucher_reset_to_draft'
    AND a.entity_type = 'supplier_payment'
    AND a.entity_id = v_payment.id::text
  ORDER BY a.created_at DESC NULLS LAST, a.id DESC
  LIMIT 1;

  IF v_payment.gl_entry_id IS NULL THEN
    IF v_reset_id IS NOT NULL THEN
      RAISE EXCEPTION 'SUPPLIER_PAYMENT_CANCEL_STATE_INCONSISTENT: reset record without GL identity';
    END IF;
    v_path := 'never_posted';
  ELSE
    IF v_reset_id IS NULL THEN
      RAISE EXCEPTION 'SUPPLIER_PAYMENT_CANCEL_UNPROVEN: GL identity without a trusted reset record';
    END IF;
    v_path := 'corrected';

    SELECT * INTO v_entry
    FROM public.gl_entries
    WHERE id = v_payment.gl_entry_id AND org_id = v_org
    FOR UPDATE;
    IF NOT FOUND
       OR v_entry.status <> 'draft'
       OR v_entry.reference_type <> 'SUPPLIER_PAYMENT'
       OR v_entry.reference_id <> v_payment.id THEN
      RAISE EXCEPTION 'SUPPLIER_PAYMENT_CANCEL_GL_INVALID';
    END IF;

    PERFORM set_config('wardah.voucher_gl_cancel', 'on', true);
    UPDATE public.gl_entries
    SET status = 'cancelled', updated_at = now()
    WHERE id = v_entry.id AND org_id = v_org AND status = 'draft';
    GET DIAGNOSTICS v_gl_rows = ROW_COUNT;
    PERFORM set_config('wardah.voucher_gl_cancel', 'off', true);
    IF v_gl_rows <> 1 THEN RAISE EXCEPTION 'SUPPLIER_PAYMENT_CANCEL_GL_STATE_CHANGED'; END IF;
  END IF;

  UPDATE public.supplier_payments
  SET status = 'cancelled', updated_at = now()
  WHERE id = v_payment.id AND org_id = v_org AND status = 'draft';
  IF NOT FOUND THEN RAISE EXCEPTION 'SUPPLIER_PAYMENT_STATE_CHANGED'; END IF;

  INSERT INTO public.audit_logs(
    org_id, user_id, action, entity_type, entity_id, old_data, new_data, changes, metadata
  ) VALUES (
    v_org, v_actor, 'voucher_cancelled', 'supplier_payment', v_payment.id::text,
    jsonb_build_object('status', 'draft', 'gl_entry_id', v_payment.gl_entry_id,
                       'gl_status', CASE WHEN v_path = 'corrected' THEN v_entry.status ELSE NULL END,
                       'entry_number', CASE WHEN v_path = 'corrected' THEN v_entry.entry_number ELSE NULL END),
    jsonb_build_object('status', 'cancelled', 'gl_entry_id', v_payment.gl_entry_id,
                       'gl_status', CASE WHEN v_path = 'corrected' THEN 'cancelled' ELSE NULL END,
                       'entry_number', CASE WHEN v_path = 'corrected' THEN v_entry.entry_number ELSE NULL END),
    jsonb_build_object('reason', trim(p_reason), 'path', v_path),
    jsonb_build_object('source', 'rpc_cancel_supplier_payment',
                       'reset_audit_id', v_reset_id)
  );

  RETURN jsonb_build_object('success', true, 'duplicate', false,
    'payment_id', v_payment.id, 'status', 'cancelled',
    'entry_id', v_payment.gl_entry_id, 'path', v_path);
END
$$;


--
-- Name: wardah_169_internal_create_customer_receipt(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_169_internal_create_customer_receipt(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_receipt_id uuid := gen_random_uuid();
  v_number text;
  v_customer uuid;
  v_date date;
  v_amount numeric;
  v_method text;
  v_account uuid;
  v_line jsonb;
  v_invoice_id uuid;
  v_allocated numeric;
  v_discount numeric;
  v_seen uuid[] := ARRAY[]::uuid[];
  v_total numeric := 0;
  v_count integer := 0;
  v_open numeric;
  v_invoice record;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  v_org := public.get_current_tenant_id();
  IF v_org IS NULL OR NOT public.wardah_is_org_member(v_org) THEN
    RAISE EXCEPTION 'TENANT_MEMBERSHIP_REQUIRED';
  END IF;

  v_customer := nullif(p_payload->>'customer_id', '')::uuid;
  v_date := coalesce(nullif(p_payload->>'receipt_date', '')::date, current_date);
  v_amount := round(coalesce(nullif(p_payload->>'amount', '')::numeric, 0), 2);
  v_method := coalesce(nullif(p_payload->>'payment_method', ''), 'cash');
  v_account := nullif(p_payload->>'payment_account_id', '')::uuid;

  IF v_customer IS NULL THEN RAISE EXCEPTION 'CUSTOMER_RECEIPT_CUSTOMER_REQUIRED'; END IF;
  IF v_amount <= 0 THEN RAISE EXCEPTION 'VOUCHER_AMOUNT_INVALID: amount must be positive'; END IF;
  IF v_account IS NULL THEN RAISE EXCEPTION 'VOUCHER_PAYMENT_ACCOUNT_REQUIRED'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.customers c WHERE c.id = v_customer AND c.org_id = v_org
  ) THEN
    RAISE EXCEPTION 'CUSTOMER_RECEIPT_CUSTOMER_CROSS_ORG';
  END IF;

  v_number := public.wardah_next_voucher_number(v_org, 'CUSTOMER_RECEIPT');

  INSERT INTO public.customer_collections (
    id, org_id, collection_number, customer_id, collection_date, amount,
    payment_method, payment_account_id, check_number, check_date,
    reference_number, notes, status, created_by
  ) VALUES (
    v_receipt_id, v_org, v_number, v_customer, v_date, v_amount,
    v_method, v_account,
    nullif(p_payload->>'check_number', ''),
    nullif(p_payload->>'check_date', '')::date,
    nullif(p_payload->>'reference_number', ''),
    nullif(p_payload->>'notes', ''),
    'draft', v_actor
  );

  FOR v_line IN
    SELECT value FROM jsonb_array_elements(coalesce(p_payload->'lines', '[]'::jsonb))
  LOOP
    v_invoice_id := nullif(v_line->>'invoice_id', '')::uuid;
    v_allocated := round(coalesce(nullif(v_line->>'allocated_amount', '')::numeric, 0), 2);
    v_discount := round(coalesce(nullif(v_line->>'discount_amount', '')::numeric, 0), 2);

    IF v_invoice_id IS NULL THEN
      RAISE EXCEPTION 'CUSTOMER_RECEIPT_ALLOCATION_INVOICE_REQUIRED';
    END IF;
    IF v_allocated <= 0 THEN
      RAISE EXCEPTION 'CUSTOMER_RECEIPT_ALLOCATION_AMOUNT_INVALID: invoice=%', v_invoice_id;
    END IF;
    IF v_discount <> 0 THEN
      RAISE EXCEPTION 'VOUCHER_DISCOUNT_UNSUPPORTED: discount accounting mapping is required';
    END IF;
    IF v_invoice_id = ANY (v_seen) THEN
      RAISE EXCEPTION 'CUSTOMER_RECEIPT_ALLOCATION_DUPLICATE_INVOICE: invoice=%', v_invoice_id;
    END IF;
    v_seen := v_seen || v_invoice_id;

    SELECT i.total_amount, coalesce(i.paid_amount, 0) AS paid_amount
    INTO v_invoice
    FROM public.sales_invoices i
    WHERE i.id = v_invoice_id AND i.org_id = v_org AND i.customer_id = v_customer
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'CUSTOMER_RECEIPT_ALLOCATION_CROSS_SCOPE: invoice=%', v_invoice_id;
    END IF;

    v_open := round(v_invoice.total_amount - v_invoice.paid_amount, 2);
    IF v_allocated > v_open THEN
      RAISE EXCEPTION 'CUSTOMER_RECEIPT_OVER_ALLOCATION: invoice=% open=% allocated=%',
        v_invoice_id, v_open, v_allocated;
    END IF;

    INSERT INTO public.customer_collection_lines (
      collection_id, invoice_id, allocated_amount, discount_amount, notes
    ) VALUES (
      v_receipt_id, v_invoice_id, v_allocated, 0, nullif(v_line->>'notes', '')
    );

    v_total := v_total + v_allocated;
    v_count := v_count + 1;
  END LOOP;

  IF v_count > 0 AND round(v_total, 2) <> v_amount THEN
    RAISE EXCEPTION 'CUSTOMER_RECEIPT_ALLOCATION_TOTAL_MISMATCH: allocations=% receipt=%',
      v_total, v_amount;
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'receipt_id', v_receipt_id, 'receipt_number', v_number,
    'status', 'draft', 'line_count', v_count
  );
END
$$;


--
-- Name: wardah_169_internal_create_supplier_payment(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_169_internal_create_supplier_payment(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_payment_id uuid := gen_random_uuid();
  v_number text;
  v_vendor uuid;
  v_date date;
  v_amount numeric;
  v_method text;
  v_account uuid;
  v_line jsonb;
  v_invoice_id uuid;
  v_allocated numeric;
  v_discount numeric;
  v_seen uuid[] := ARRAY[]::uuid[];
  v_total numeric := 0;
  v_count integer := 0;
  v_open numeric;
  v_invoice record;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  v_org := public.get_current_tenant_id();
  IF v_org IS NULL OR NOT public.wardah_is_org_member(v_org) THEN
    RAISE EXCEPTION 'TENANT_MEMBERSHIP_REQUIRED';
  END IF;

  v_vendor := nullif(p_payload->>'vendor_id', '')::uuid;
  v_date := coalesce(nullif(p_payload->>'payment_date', '')::date, current_date);
  v_amount := round(coalesce(nullif(p_payload->>'amount', '')::numeric, 0), 2);
  v_method := coalesce(nullif(p_payload->>'payment_method', ''), 'bank_transfer');
  v_account := nullif(p_payload->>'payment_account_id', '')::uuid;

  IF v_vendor IS NULL THEN RAISE EXCEPTION 'SUPPLIER_PAYMENT_VENDOR_REQUIRED'; END IF;
  IF v_amount <= 0 THEN RAISE EXCEPTION 'VOUCHER_AMOUNT_INVALID: amount must be positive'; END IF;
  IF v_account IS NULL THEN RAISE EXCEPTION 'VOUCHER_PAYMENT_ACCOUNT_REQUIRED'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.vendors v WHERE v.id = v_vendor AND v.org_id = v_org
  ) THEN
    RAISE EXCEPTION 'SUPPLIER_PAYMENT_VENDOR_CROSS_ORG';
  END IF;

  v_number := public.wardah_next_voucher_number(v_org, 'SUPPLIER_PAYMENT');

  INSERT INTO public.supplier_payments (
    id, org_id, payment_number, vendor_id, payment_date, amount,
    payment_method, payment_account_id, check_number, check_date, check_bank,
    reference_number, notes, status, created_by
  ) VALUES (
    v_payment_id, v_org, v_number, v_vendor, v_date, v_amount,
    v_method, v_account,
    nullif(p_payload->>'check_number', ''),
    nullif(p_payload->>'check_date', '')::date,
    nullif(p_payload->>'check_bank', ''),
    nullif(p_payload->>'reference_number', ''),
    nullif(p_payload->>'notes', ''),
    'draft', v_actor
  );

  FOR v_line IN
    SELECT value FROM jsonb_array_elements(coalesce(p_payload->'lines', '[]'::jsonb))
  LOOP
    v_invoice_id := nullif(v_line->>'invoice_id', '')::uuid;
    v_allocated := round(coalesce(nullif(v_line->>'allocated_amount', '')::numeric, 0), 2);
    v_discount := round(coalesce(nullif(v_line->>'discount_amount', '')::numeric, 0), 2);

    IF v_invoice_id IS NULL THEN
      RAISE EXCEPTION 'SUPPLIER_PAYMENT_ALLOCATION_INVOICE_REQUIRED';
    END IF;
    IF v_allocated <= 0 THEN
      RAISE EXCEPTION 'SUPPLIER_PAYMENT_ALLOCATION_AMOUNT_INVALID: invoice=%', v_invoice_id;
    END IF;
    IF v_discount <> 0 THEN
      RAISE EXCEPTION 'VOUCHER_DISCOUNT_UNSUPPORTED: discount accounting mapping is required';
    END IF;
    IF v_invoice_id = ANY (v_seen) THEN
      RAISE EXCEPTION 'SUPPLIER_PAYMENT_ALLOCATION_DUPLICATE_INVOICE: invoice=%', v_invoice_id;
    END IF;
    v_seen := v_seen || v_invoice_id;

    SELECT i.total_amount, coalesce(i.paid_amount, 0) AS paid_amount, i.status
    INTO v_invoice
    FROM public.supplier_invoices i
    WHERE i.id = v_invoice_id AND i.org_id = v_org AND i.vendor_id = v_vendor
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'SUPPLIER_PAYMENT_ALLOCATION_CROSS_SCOPE: invoice=%', v_invoice_id;
    END IF;
    IF v_invoice.status NOT IN ('approved', 'partially_paid', 'overdue') THEN
      RAISE EXCEPTION 'SUPPLIER_INVOICE_NOT_PAYABLE: invoice=% status=%',
        v_invoice_id, v_invoice.status;
    END IF;

    v_open := round(v_invoice.total_amount - v_invoice.paid_amount, 2);
    IF v_allocated > v_open THEN
      RAISE EXCEPTION 'SUPPLIER_PAYMENT_OVER_ALLOCATION: invoice=% open=% allocated=%',
        v_invoice_id, v_open, v_allocated;
    END IF;

    INSERT INTO public.supplier_payment_lines (
      payment_id, invoice_id, allocated_amount, discount_amount, notes
    ) VALUES (
      v_payment_id, v_invoice_id, v_allocated, 0, nullif(v_line->>'notes', '')
    );

    v_total := v_total + v_allocated;
    v_count := v_count + 1;
  END LOOP;

  IF v_count > 0 AND round(v_total, 2) <> v_amount THEN
    RAISE EXCEPTION 'SUPPLIER_PAYMENT_ALLOCATION_TOTAL_MISMATCH: allocations=% payment=%',
      v_total, v_amount;
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'payment_id', v_payment_id, 'payment_number', v_number,
    'status', 'draft', 'line_count', v_count
  );
END
$$;


--
-- Name: wardah_169_internal_post_customer_receipt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_169_internal_post_customer_receipt(p_receipt_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid(); v_org uuid;
  v_receipt public.customer_collections%ROWTYPE;
  v_payment_account uuid; v_ar_account uuid; v_entry_id uuid;
  v_line record; v_allocation_total numeric:=0; v_open numeric;
  v_new_paid numeric; v_line_count integer:=0;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  v_org:=public.get_current_tenant_id();
  IF v_org IS NULL OR NOT public.wardah_is_org_member(v_org) THEN RAISE EXCEPTION 'TENANT_MEMBERSHIP_REQUIRED'; END IF;
  SELECT * INTO v_receipt FROM public.customer_collections WHERE id=p_receipt_id AND org_id=v_org FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'CUSTOMER_RECEIPT_NOT_FOUND_OR_CROSS_ORG'; END IF;
  IF v_receipt.status='posted' AND v_receipt.gl_entry_id IS NOT NULL THEN
    IF NOT EXISTS(SELECT 1 FROM public.gl_entries e WHERE e.id=v_receipt.gl_entry_id AND e.org_id=v_org AND e.status='posted') THEN RAISE EXCEPTION 'CUSTOMER_RECEIPT_POSTED_GL_INVALID'; END IF;
    RETURN jsonb_build_object('success',true,'duplicate',true,'receipt_id',v_receipt.id,'entry_id',v_receipt.gl_entry_id,'status','posted');
  END IF;
  IF v_receipt.status<>'draft' THEN RAISE EXCEPTION 'CUSTOMER_RECEIPT_NOT_DRAFT: status=%',v_receipt.status; END IF;
  v_payment_account:=v_receipt.payment_account_id;
  IF v_payment_account IS NULL THEN SELECT a.id INTO v_payment_account FROM public.gl_accounts a WHERE a.org_id=v_org AND a.subtype=CASE WHEN v_receipt.payment_method IN ('cash','check') THEN 'CASH' ELSE 'BANK' END AND coalesce(a.is_active,true) AND coalesce(a.allow_posting,true) ORDER BY a.code,a.id LIMIT 1; END IF;
  SELECT a.id INTO v_ar_account FROM public.gl_accounts a WHERE a.org_id=v_org AND a.subtype IN ('ACCOUNTS_RECEIVABLE','AR') AND coalesce(a.is_active,true) AND coalesce(a.allow_posting,true) ORDER BY a.code,a.id LIMIT 1;
  IF v_payment_account IS NULL OR v_ar_account IS NULL THEN RAISE EXCEPTION 'CUSTOMER_RECEIPT_GL_ACCOUNTS_MISSING'; END IF;
  FOR v_line IN SELECT l.invoice_id,l.allocated_amount,coalesce(l.discount_amount,0) discount_amount,i.org_id,i.customer_id,i.total_amount,coalesce(i.paid_amount,0) paid_amount FROM public.customer_collection_lines l JOIN public.sales_invoices i ON i.id=l.invoice_id WHERE l.collection_id=v_receipt.id ORDER BY i.id FOR UPDATE OF i LOOP
    v_line_count:=v_line_count+1;
    IF v_line.org_id<>v_org OR v_line.customer_id<>v_receipt.customer_id THEN RAISE EXCEPTION 'CUSTOMER_RECEIPT_ALLOCATION_CROSS_SCOPE'; END IF;
    IF v_line.discount_amount<>0 THEN RAISE EXCEPTION 'VOUCHER_DISCOUNT_UNSUPPORTED: discount accounting mapping is required'; END IF;
    v_open:=round(v_line.total_amount-v_line.paid_amount,2);
    IF round(v_line.allocated_amount,2)>v_open THEN RAISE EXCEPTION 'CUSTOMER_RECEIPT_OVER_ALLOCATION: invoice=% open=% allocated=%',v_line.invoice_id,v_open,v_line.allocated_amount; END IF;
    v_allocation_total:=v_allocation_total+round(v_line.allocated_amount,2);
  END LOOP;
  IF v_line_count>0 AND round(v_allocation_total,2)<>round(v_receipt.amount,2) THEN RAISE EXCEPTION 'CUSTOMER_RECEIPT_ALLOCATION_TOTAL_MISMATCH: allocations=% receipt=%',v_allocation_total,v_receipt.amount; END IF;
  v_entry_id:=public.wardah_create_posted_voucher_gl(v_org,'CUSTOMER_RECEIPT',v_receipt.id,v_receipt.collection_number,v_receipt.collection_date,'سند قبض '||v_receipt.collection_number,v_payment_account,v_ar_account,v_receipt.amount,v_actor);
  FOR v_line IN SELECT l.invoice_id,l.allocated_amount,i.total_amount,coalesce(i.paid_amount,0) paid_amount FROM public.customer_collection_lines l JOIN public.sales_invoices i ON i.id=l.invoice_id WHERE l.collection_id=v_receipt.id ORDER BY i.id FOR UPDATE OF i LOOP
    v_new_paid:=round(v_line.paid_amount+v_line.allocated_amount,2);
    UPDATE public.sales_invoices SET paid_amount=v_new_paid,payment_status=CASE WHEN v_new_paid>=round(total_amount,2) THEN 'paid' ELSE 'partially_paid' END,updated_at=now() WHERE id=v_line.invoice_id AND org_id=v_org;
  END LOOP;
  UPDATE public.customer_collections SET status='posted',gl_entry_id=v_entry_id,posted_at=now(),posted_by=v_actor,updated_at=now() WHERE id=v_receipt.id AND org_id=v_org AND status='draft';
  IF NOT FOUND THEN RAISE EXCEPTION 'CUSTOMER_RECEIPT_STATE_CHANGED'; END IF;
  RETURN jsonb_build_object('success',true,'duplicate',false,'receipt_id',v_receipt.id,'entry_id',v_entry_id,'status','posted');
END
$$;


--
-- Name: wardah_169_internal_post_supplier_payment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_169_internal_post_supplier_payment(p_payment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid:=auth.uid(); v_org uuid;
  v_payment public.supplier_payments%ROWTYPE;
  v_payment_account uuid; v_ap_account uuid; v_entry_id uuid;
  v_line record; v_allocation_total numeric:=0; v_open numeric;
  v_new_paid numeric; v_line_count integer:=0;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  v_org:=public.get_current_tenant_id();
  IF v_org IS NULL OR NOT public.wardah_is_org_member(v_org) THEN RAISE EXCEPTION 'TENANT_MEMBERSHIP_REQUIRED'; END IF;
  SELECT * INTO v_payment FROM public.supplier_payments WHERE id=p_payment_id AND org_id=v_org FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'SUPPLIER_PAYMENT_NOT_FOUND_OR_CROSS_ORG'; END IF;
  IF v_payment.status='posted' AND v_payment.gl_entry_id IS NOT NULL THEN
    IF NOT EXISTS(SELECT 1 FROM public.gl_entries e WHERE e.id=v_payment.gl_entry_id AND e.org_id=v_org AND e.status='posted') THEN RAISE EXCEPTION 'SUPPLIER_PAYMENT_POSTED_GL_INVALID'; END IF;
    RETURN jsonb_build_object('success',true,'duplicate',true,'payment_id',v_payment.id,'entry_id',v_payment.gl_entry_id,'status','posted');
  END IF;
  IF v_payment.status<>'draft' THEN RAISE EXCEPTION 'SUPPLIER_PAYMENT_NOT_DRAFT: status=%',v_payment.status; END IF;
  v_payment_account:=v_payment.payment_account_id;
  IF v_payment_account IS NULL THEN SELECT a.id INTO v_payment_account FROM public.gl_accounts a WHERE a.org_id=v_org AND a.subtype=CASE WHEN v_payment.payment_method='cash' THEN 'CASH' ELSE 'BANK' END AND coalesce(a.is_active,true) AND coalesce(a.allow_posting,true) ORDER BY a.code,a.id LIMIT 1; END IF;
  SELECT a.id INTO v_ap_account FROM public.gl_accounts a WHERE a.org_id=v_org AND a.subtype IN ('ACCOUNTS_PAYABLE','AP') AND coalesce(a.is_active,true) AND coalesce(a.allow_posting,true) ORDER BY a.code,a.id LIMIT 1;
  IF v_payment_account IS NULL OR v_ap_account IS NULL THEN RAISE EXCEPTION 'SUPPLIER_PAYMENT_GL_ACCOUNTS_MISSING'; END IF;
  FOR v_line IN SELECT l.invoice_id,l.allocated_amount,coalesce(l.discount_amount,0) discount_amount,i.org_id,i.vendor_id,i.total_amount,coalesce(i.paid_amount,0) paid_amount,i.status FROM public.supplier_payment_lines l JOIN public.supplier_invoices i ON i.id=l.invoice_id WHERE l.payment_id=v_payment.id ORDER BY i.id FOR UPDATE OF i LOOP
    v_line_count:=v_line_count+1;
    IF v_line.org_id<>v_org OR v_line.vendor_id<>v_payment.vendor_id THEN RAISE EXCEPTION 'SUPPLIER_PAYMENT_ALLOCATION_CROSS_SCOPE'; END IF;
    IF v_line.status NOT IN ('approved','partially_paid','overdue') THEN RAISE EXCEPTION 'SUPPLIER_INVOICE_NOT_PAYABLE: invoice=% status=%',v_line.invoice_id,v_line.status; END IF;
    IF v_line.discount_amount<>0 THEN RAISE EXCEPTION 'VOUCHER_DISCOUNT_UNSUPPORTED: discount accounting mapping is required'; END IF;
    v_open:=round(v_line.total_amount-v_line.paid_amount,2);
    IF round(v_line.allocated_amount,2)>v_open THEN RAISE EXCEPTION 'SUPPLIER_PAYMENT_OVER_ALLOCATION: invoice=% open=% allocated=%',v_line.invoice_id,v_open,v_line.allocated_amount; END IF;
    v_allocation_total:=v_allocation_total+round(v_line.allocated_amount,2);
  END LOOP;
  IF v_line_count>0 AND round(v_allocation_total,2)<>round(v_payment.amount,2) THEN RAISE EXCEPTION 'SUPPLIER_PAYMENT_ALLOCATION_TOTAL_MISMATCH: allocations=% payment=%',v_allocation_total,v_payment.amount; END IF;
  v_entry_id:=public.wardah_create_posted_voucher_gl(v_org,'SUPPLIER_PAYMENT',v_payment.id,v_payment.payment_number,v_payment.payment_date,'سند صرف '||v_payment.payment_number,v_ap_account,v_payment_account,v_payment.amount,v_actor);
  FOR v_line IN SELECT l.invoice_id,l.allocated_amount,i.total_amount,coalesce(i.paid_amount,0) paid_amount FROM public.supplier_payment_lines l JOIN public.supplier_invoices i ON i.id=l.invoice_id WHERE l.payment_id=v_payment.id ORDER BY i.id FOR UPDATE OF i LOOP
    v_new_paid:=round(v_line.paid_amount+v_line.allocated_amount,2);
    UPDATE public.supplier_invoices SET paid_amount=v_new_paid,status=CASE WHEN v_new_paid>=round(total_amount,2) THEN 'paid' ELSE 'partially_paid' END,updated_at=now() WHERE id=v_line.invoice_id AND org_id=v_org;
  END LOOP;
  UPDATE public.supplier_payments SET status='posted',gl_entry_id=v_entry_id,posted_at=now(),posted_by=v_actor,updated_at=now() WHERE id=v_payment.id AND org_id=v_org AND status='draft';
  IF NOT FOUND THEN RAISE EXCEPTION 'SUPPLIER_PAYMENT_STATE_CHANGED'; END IF;
  RETURN jsonb_build_object('success',true,'duplicate',false,'payment_id',v_payment.id,'entry_id',v_entry_id,'status','posted');
END
$$;


--
-- Name: wardah_169_internal_reset_customer_receipt_to_draft(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_169_internal_reset_customer_receipt_to_draft(p_receipt_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_receipt public.customer_collections%ROWTYPE;
  v_entry public.gl_entries%ROWTYPE;
  v_line record;
  v_new_paid numeric;
  v_gl_update_count integer;
  v_allocations jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF length(trim(coalesce(p_reason,''))) < 5 THEN
    RAISE EXCEPTION 'VOUCHER_UNPOST_REASON_REQUIRED';
  END IF;

  v_org := public.get_current_tenant_id();
  IF v_org IS NULL OR NOT public.wardah_is_org_member(v_org) THEN
    RAISE EXCEPTION 'TENANT_MEMBERSHIP_REQUIRED';
  END IF;
  IF NOT public.wardah_has_exact_permission(v_actor, v_org, 'accounting.vouchers.unpost') THEN
    RAISE EXCEPTION 'VOUCHER_UNPOST_PERMISSION_REQUIRED';
  END IF;

  SELECT * INTO v_receipt
  FROM public.customer_collections
  WHERE id = p_receipt_id AND org_id = v_org
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'CUSTOMER_RECEIPT_NOT_FOUND_OR_CROSS_ORG'; END IF;

  IF v_receipt.status = 'draft' THEN
    IF v_receipt.gl_entry_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.gl_entries e
      WHERE e.id=v_receipt.gl_entry_id AND e.org_id=v_org AND e.status='draft'
    ) THEN
      RAISE EXCEPTION 'CUSTOMER_RECEIPT_DRAFT_GL_INVALID';
    END IF;
    RETURN jsonb_build_object('success',true,'duplicate',true,'receipt_id',v_receipt.id,
      'entry_id',v_receipt.gl_entry_id,'status','draft');
  END IF;
  IF v_receipt.status <> 'posted' OR v_receipt.gl_entry_id IS NULL THEN
    RAISE EXCEPTION 'CUSTOMER_RECEIPT_NOT_POSTED';
  END IF;

  SELECT * INTO v_entry
  FROM public.gl_entries
  WHERE id=v_receipt.gl_entry_id AND org_id=v_org
  FOR UPDATE;
  IF NOT FOUND
     OR v_entry.status <> 'posted'
     OR v_entry.reference_type <> 'CUSTOMER_RECEIPT'
     OR v_entry.reference_id <> v_receipt.id THEN
    RAISE EXCEPTION 'CUSTOMER_RECEIPT_POSTED_GL_INVALID';
  END IF;

  PERFORM public.assert_period_open(v_org, v_entry.entry_date);

  SELECT coalesce(
    jsonb_agg(
      jsonb_build_object(
        'line_id', l.id,
        'invoice_id', l.invoice_id,
        'allocated_amount', l.allocated_amount,
        'discount_amount', coalesce(l.discount_amount,0),
        'notes', l.notes
      ) ORDER BY l.id
    ),
    '[]'::jsonb
  ) INTO v_allocations
  FROM public.customer_collection_lines l
  WHERE l.collection_id = v_receipt.id;

  FOR v_line IN
    SELECT l.invoice_id, round(l.allocated_amount,2) AS allocated_amount,
           i.total_amount, coalesce(i.paid_amount,0) AS paid_amount
    FROM public.customer_collection_lines l
    JOIN public.sales_invoices i ON i.id=l.invoice_id
    WHERE l.collection_id=v_receipt.id
    ORDER BY i.id
    FOR UPDATE OF i
  LOOP
    IF round(v_line.paid_amount,2) < v_line.allocated_amount THEN
      RAISE EXCEPTION 'CUSTOMER_RECEIPT_UNPOST_INVOICE_DRIFT: invoice=% paid=% allocated=%',
        v_line.invoice_id, v_line.paid_amount, v_line.allocated_amount;
    END IF;
    v_new_paid := round(v_line.paid_amount - v_line.allocated_amount,2);
    UPDATE public.sales_invoices
    SET paid_amount=v_new_paid,
        payment_status=CASE
          WHEN v_new_paid <= 0 THEN 'unpaid'
          WHEN v_new_paid >= round(total_amount,2) THEN 'paid'
          ELSE 'partially_paid'
        END,
        updated_at=now()
    WHERE id=v_line.invoice_id AND org_id=v_org;
  END LOOP;

  PERFORM set_config('wardah.voucher_unpost','on',true);
  UPDATE public.gl_entries
  SET status='draft', posted_at=NULL, posted_by=NULL, updated_at=now()
  WHERE id=v_entry.id AND org_id=v_org AND status='posted';
  GET DIAGNOSTICS v_gl_update_count = ROW_COUNT;
  PERFORM set_config('wardah.voucher_unpost','off',true);
  IF v_gl_update_count <> 1 THEN RAISE EXCEPTION 'CUSTOMER_RECEIPT_GL_STATE_CHANGED'; END IF;

  UPDATE public.customer_collections
  SET status='draft', posted_at=NULL, posted_by=NULL, updated_at=now()
  WHERE id=v_receipt.id AND org_id=v_org AND status='posted';
  IF NOT FOUND THEN RAISE EXCEPTION 'CUSTOMER_RECEIPT_STATE_CHANGED'; END IF;

  INSERT INTO public.audit_logs(
    org_id,user_id,action,entity_type,entity_id,old_data,new_data,changes,metadata
  ) VALUES (
    v_org,v_actor,'voucher_reset_to_draft','customer_receipt',v_receipt.id::text,
    jsonb_build_object(
      'status',v_receipt.status,
      'posted_at',v_receipt.posted_at,
      'posted_by',v_receipt.posted_by,
      'gl_status',v_entry.status,
      'gl_entry_id',v_entry.id,
      'entry_number',v_entry.entry_number,
      'gl_posted_at',v_entry.posted_at,
      'gl_posted_by',v_entry.posted_by,
      'reference_number',v_entry.reference_number,
      'allocations',v_allocations
    ),
    jsonb_build_object(
      'status','draft','posted_at',NULL,'posted_by',NULL,
      'gl_status','draft','gl_entry_id',v_entry.id,
      'entry_number',v_entry.entry_number,
      'allocations',v_allocations
    ),
    jsonb_build_object('reason',trim(p_reason)),
    jsonb_build_object('source','rpc_reset_customer_receipt_to_draft','audit_contract','167')
  );

  RETURN jsonb_build_object('success',true,'duplicate',false,'receipt_id',v_receipt.id,
    'entry_id',v_entry.id,'status','draft');
END
$$;


--
-- Name: wardah_169_internal_reset_supplier_payment_to_draft(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_169_internal_reset_supplier_payment_to_draft(p_payment_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_payment public.supplier_payments%ROWTYPE;
  v_entry public.gl_entries%ROWTYPE;
  v_line record;
  v_new_paid numeric;
  v_gl_update_count integer;
  v_allocations jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF length(trim(coalesce(p_reason,''))) < 5 THEN
    RAISE EXCEPTION 'VOUCHER_UNPOST_REASON_REQUIRED';
  END IF;

  v_org := public.get_current_tenant_id();
  IF v_org IS NULL OR NOT public.wardah_is_org_member(v_org) THEN
    RAISE EXCEPTION 'TENANT_MEMBERSHIP_REQUIRED';
  END IF;
  IF NOT public.wardah_has_exact_permission(v_actor, v_org, 'accounting.vouchers.unpost') THEN
    RAISE EXCEPTION 'VOUCHER_UNPOST_PERMISSION_REQUIRED';
  END IF;

  SELECT * INTO v_payment
  FROM public.supplier_payments
  WHERE id=p_payment_id AND org_id=v_org
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'SUPPLIER_PAYMENT_NOT_FOUND_OR_CROSS_ORG'; END IF;

  IF v_payment.status='draft' THEN
    IF v_payment.gl_entry_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.gl_entries e
      WHERE e.id=v_payment.gl_entry_id AND e.org_id=v_org AND e.status='draft'
    ) THEN
      RAISE EXCEPTION 'SUPPLIER_PAYMENT_DRAFT_GL_INVALID';
    END IF;
    RETURN jsonb_build_object('success',true,'duplicate',true,'payment_id',v_payment.id,
      'entry_id',v_payment.gl_entry_id,'status','draft');
  END IF;
  IF v_payment.status <> 'posted' OR v_payment.gl_entry_id IS NULL THEN
    RAISE EXCEPTION 'SUPPLIER_PAYMENT_NOT_POSTED';
  END IF;

  SELECT * INTO v_entry
  FROM public.gl_entries
  WHERE id=v_payment.gl_entry_id AND org_id=v_org
  FOR UPDATE;
  IF NOT FOUND
     OR v_entry.status <> 'posted'
     OR v_entry.reference_type <> 'SUPPLIER_PAYMENT'
     OR v_entry.reference_id <> v_payment.id THEN
    RAISE EXCEPTION 'SUPPLIER_PAYMENT_POSTED_GL_INVALID';
  END IF;

  PERFORM public.assert_period_open(v_org, v_entry.entry_date);

  SELECT coalesce(
    jsonb_agg(
      jsonb_build_object(
        'line_id', l.id,
        'invoice_id', l.invoice_id,
        'allocated_amount', l.allocated_amount,
        'discount_amount', coalesce(l.discount_amount,0),
        'notes', l.notes
      ) ORDER BY l.id
    ),
    '[]'::jsonb
  ) INTO v_allocations
  FROM public.supplier_payment_lines l
  WHERE l.payment_id = v_payment.id;

  FOR v_line IN
    SELECT l.invoice_id, round(l.allocated_amount,2) AS allocated_amount,
           i.total_amount, coalesce(i.paid_amount,0) AS paid_amount, i.due_date
    FROM public.supplier_payment_lines l
    JOIN public.supplier_invoices i ON i.id=l.invoice_id
    WHERE l.payment_id=v_payment.id
    ORDER BY i.id
    FOR UPDATE OF i
  LOOP
    IF round(v_line.paid_amount,2) < v_line.allocated_amount THEN
      RAISE EXCEPTION 'SUPPLIER_PAYMENT_UNPOST_INVOICE_DRIFT: invoice=% paid=% allocated=%',
        v_line.invoice_id, v_line.paid_amount, v_line.allocated_amount;
    END IF;
    v_new_paid := round(v_line.paid_amount-v_line.allocated_amount,2);
    UPDATE public.supplier_invoices
    SET paid_amount=v_new_paid,
        status=CASE
          WHEN v_new_paid >= round(total_amount,2) THEN 'paid'
          WHEN v_new_paid > 0 THEN 'partially_paid'
          WHEN due_date IS NOT NULL AND due_date < current_date THEN 'overdue'
          ELSE 'approved'
        END,
        updated_at=now()
    WHERE id=v_line.invoice_id AND org_id=v_org;
  END LOOP;

  PERFORM set_config('wardah.voucher_unpost','on',true);
  UPDATE public.gl_entries
  SET status='draft', posted_at=NULL, posted_by=NULL, updated_at=now()
  WHERE id=v_entry.id AND org_id=v_org AND status='posted';
  GET DIAGNOSTICS v_gl_update_count = ROW_COUNT;
  PERFORM set_config('wardah.voucher_unpost','off',true);
  IF v_gl_update_count <> 1 THEN RAISE EXCEPTION 'SUPPLIER_PAYMENT_GL_STATE_CHANGED'; END IF;

  UPDATE public.supplier_payments
  SET status='draft', posted_at=NULL, posted_by=NULL, updated_at=now()
  WHERE id=v_payment.id AND org_id=v_org AND status='posted';
  IF NOT FOUND THEN RAISE EXCEPTION 'SUPPLIER_PAYMENT_STATE_CHANGED'; END IF;

  INSERT INTO public.audit_logs(
    org_id,user_id,action,entity_type,entity_id,old_data,new_data,changes,metadata
  ) VALUES (
    v_org,v_actor,'voucher_reset_to_draft','supplier_payment',v_payment.id::text,
    jsonb_build_object(
      'status',v_payment.status,
      'posted_at',v_payment.posted_at,
      'posted_by',v_payment.posted_by,
      'gl_status',v_entry.status,
      'gl_entry_id',v_entry.id,
      'entry_number',v_entry.entry_number,
      'gl_posted_at',v_entry.posted_at,
      'gl_posted_by',v_entry.posted_by,
      'reference_number',v_entry.reference_number,
      'allocations',v_allocations
    ),
    jsonb_build_object(
      'status','draft','posted_at',NULL,'posted_by',NULL,
      'gl_status','draft','gl_entry_id',v_entry.id,
      'entry_number',v_entry.entry_number,
      'allocations',v_allocations
    ),
    jsonb_build_object('reason',trim(p_reason)),
    jsonb_build_object('source','rpc_reset_supplier_payment_to_draft','audit_contract','167')
  );

  RETURN jsonb_build_object('success',true,'duplicate',false,'payment_id',v_payment.id,
    'entry_id',v_entry.id,'status','draft');
END
$$;


--
-- Name: wardah_169_internal_update_customer_receipt_draft(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_169_internal_update_customer_receipt_draft(p_receipt_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_receipt public.customer_collections%ROWTYPE;
  v_amount numeric;
  v_date date;
  v_method text;
  v_account uuid;
  v_line jsonb;
  v_invoice_id uuid;
  v_allocated numeric;
  v_discount numeric;
  v_seen uuid[] := ARRAY[]::uuid[];
  v_total numeric := 0;
  v_count integer := 0;
  v_deleted integer;
  v_stored integer;
  v_open numeric;
  v_invoice record;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  v_org := public.get_current_tenant_id();
  IF v_org IS NULL OR NOT public.wardah_is_org_member(v_org) THEN
    RAISE EXCEPTION 'TENANT_MEMBERSHIP_REQUIRED';
  END IF;
  IF NOT (p_payload ? 'lines') THEN
    RAISE EXCEPTION 'VOUCHER_UPDATE_LINES_REQUIRED: send the complete allocation set';
  END IF;

  SELECT * INTO v_receipt
  FROM public.customer_collections
  WHERE id = p_receipt_id AND org_id = v_org
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'CUSTOMER_RECEIPT_NOT_FOUND_OR_CROSS_ORG'; END IF;
  IF v_receipt.status <> 'draft' THEN
    RAISE EXCEPTION 'CUSTOMER_RECEIPT_NOT_DRAFT: status=%', v_receipt.status;
  END IF;

  IF v_receipt.gl_entry_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.gl_entries e
      WHERE e.id = v_receipt.gl_entry_id AND e.org_id = v_org AND e.status = 'draft'
      FOR UPDATE
    ) THEN
      RAISE EXCEPTION 'CUSTOMER_RECEIPT_DRAFT_GL_INVALID';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.audit_logs a
      WHERE a.org_id = v_org
        AND a.action = 'voucher_reset_to_draft'
        AND a.entity_type = 'customer_receipt'
        AND a.entity_id = v_receipt.id::text
    ) THEN
      RAISE EXCEPTION 'CUSTOMER_RECEIPT_CORRECTION_UNPROVEN: no trusted reset record';
    END IF;
  END IF;

  IF nullif(p_payload->>'customer_id', '') IS NOT NULL
     AND (p_payload->>'customer_id')::uuid <> v_receipt.customer_id THEN
    RAISE EXCEPTION 'CUSTOMER_RECEIPT_PARTY_IMMUTABLE: cancel and create a new voucher';
  END IF;

  v_amount := round(coalesce(nullif(p_payload->>'amount', '')::numeric, v_receipt.amount), 2);
  v_date := coalesce(nullif(p_payload->>'receipt_date', '')::date, v_receipt.collection_date);
  v_method := coalesce(nullif(p_payload->>'payment_method', ''), v_receipt.payment_method);
  v_account := coalesce(nullif(p_payload->>'payment_account_id', '')::uuid,
                        v_receipt.payment_account_id);
  IF v_amount <= 0 THEN RAISE EXCEPTION 'VOUCHER_AMOUNT_INVALID: amount must be positive'; END IF;

  UPDATE public.customer_collections
  SET amount = v_amount,
      collection_date = v_date,
      payment_method = v_method,
      payment_account_id = v_account,
      check_number = coalesce(nullif(p_payload->>'check_number', ''), check_number),
      check_date = coalesce(nullif(p_payload->>'check_date', '')::date, check_date),
      reference_number = coalesce(nullif(p_payload->>'reference_number', ''), reference_number),
      notes = coalesce(nullif(p_payload->>'notes', ''), notes),
      updated_at = now()
  WHERE id = v_receipt.id AND org_id = v_org AND status = 'draft';
  IF NOT FOUND THEN RAISE EXCEPTION 'CUSTOMER_RECEIPT_STATE_CHANGED'; END IF;

  PERFORM set_config('wardah.voucher_lines_write', 'on', true);

  DELETE FROM public.customer_collection_lines WHERE collection_id = v_receipt.id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  FOR v_line IN
    SELECT value FROM jsonb_array_elements(p_payload->'lines')
  LOOP
    v_invoice_id := nullif(v_line->>'invoice_id', '')::uuid;
    v_allocated := round(coalesce(nullif(v_line->>'allocated_amount', '')::numeric, 0), 2);
    v_discount := round(coalesce(nullif(v_line->>'discount_amount', '')::numeric, 0), 2);

    IF v_invoice_id IS NULL
       OR v_allocated <= 0
       OR v_discount <> 0
       OR v_invoice_id = ANY (v_seen) THEN
      PERFORM set_config('wardah.voucher_lines_write', 'off', true);
      RAISE EXCEPTION 'CUSTOMER_RECEIPT_ALLOCATION_INVALID: invoice=% allocated=% discount=%',
        v_invoice_id, v_allocated, v_discount;
    END IF;
    v_seen := v_seen || v_invoice_id;

    SELECT i.total_amount, coalesce(i.paid_amount, 0) AS paid_amount
    INTO v_invoice
    FROM public.sales_invoices i
    WHERE i.id = v_invoice_id AND i.org_id = v_org AND i.customer_id = v_receipt.customer_id
    FOR UPDATE;
    IF NOT FOUND THEN
      PERFORM set_config('wardah.voucher_lines_write', 'off', true);
      RAISE EXCEPTION 'CUSTOMER_RECEIPT_ALLOCATION_CROSS_SCOPE: invoice=%', v_invoice_id;
    END IF;

    v_open := round(v_invoice.total_amount - v_invoice.paid_amount, 2);
    IF v_allocated > v_open THEN
      PERFORM set_config('wardah.voucher_lines_write', 'off', true);
      RAISE EXCEPTION 'CUSTOMER_RECEIPT_OVER_ALLOCATION: invoice=% open=% allocated=%',
        v_invoice_id, v_open, v_allocated;
    END IF;

    INSERT INTO public.customer_collection_lines (
      collection_id, invoice_id, allocated_amount, discount_amount, notes
    ) VALUES (
      v_receipt.id, v_invoice_id, v_allocated, 0, nullif(v_line->>'notes', '')
    );

    v_total := v_total + v_allocated;
    v_count := v_count + 1;
  END LOOP;

  PERFORM set_config('wardah.voucher_lines_write', 'off', true);

  SELECT count(*) INTO v_stored
  FROM public.customer_collection_lines WHERE collection_id = v_receipt.id;
  IF v_stored <> v_count THEN
    RAISE EXCEPTION 'CUSTOMER_RECEIPT_LINE_REPLACEMENT_MISMATCH: stored=% expected=%',
      v_stored, v_count;
  END IF;
  IF v_count > 0 AND round(v_total, 2) <> v_amount THEN
    RAISE EXCEPTION 'CUSTOMER_RECEIPT_ALLOCATION_TOTAL_MISMATCH: allocations=% receipt=%',
      v_total, v_amount;
  END IF;

  INSERT INTO public.audit_logs(
    org_id, user_id, action, entity_type, entity_id, old_data, new_data, changes, metadata
  ) VALUES (
    v_org, v_actor, 'voucher_draft_updated', 'customer_receipt', v_receipt.id::text,
    jsonb_build_object('amount', v_receipt.amount, 'collection_date', v_receipt.collection_date,
                       'payment_method', v_receipt.payment_method,
                       'payment_account_id', v_receipt.payment_account_id,
                       'line_count', v_deleted),
    jsonb_build_object('amount', v_amount, 'collection_date', v_date,
                       'payment_method', v_method, 'payment_account_id', v_account,
                       'line_count', v_count),
    jsonb_build_object('lines_replaced', v_deleted || ' -> ' || v_count),
    jsonb_build_object('source', 'rpc_update_customer_receipt_draft',
                       'gl_entry_id', v_receipt.gl_entry_id)
  );

  RETURN jsonb_build_object(
    'success', true, 'receipt_id', v_receipt.id, 'status', 'draft',
    'line_count', v_count, 'lines_removed', v_deleted
  );
END
$$;


--
-- Name: wardah_169_internal_update_supplier_payment_draft(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_169_internal_update_supplier_payment_draft(p_payment_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_payment public.supplier_payments%ROWTYPE;
  v_amount numeric;
  v_date date;
  v_method text;
  v_account uuid;
  v_line jsonb;
  v_invoice_id uuid;
  v_allocated numeric;
  v_discount numeric;
  v_seen uuid[] := ARRAY[]::uuid[];
  v_total numeric := 0;
  v_count integer := 0;
  v_deleted integer;
  v_stored integer;
  v_open numeric;
  v_invoice record;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  v_org := public.get_current_tenant_id();
  IF v_org IS NULL OR NOT public.wardah_is_org_member(v_org) THEN
    RAISE EXCEPTION 'TENANT_MEMBERSHIP_REQUIRED';
  END IF;
  IF NOT (p_payload ? 'lines') THEN
    RAISE EXCEPTION 'VOUCHER_UPDATE_LINES_REQUIRED: send the complete allocation set';
  END IF;

  SELECT * INTO v_payment
  FROM public.supplier_payments
  WHERE id = p_payment_id AND org_id = v_org
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'SUPPLIER_PAYMENT_NOT_FOUND_OR_CROSS_ORG'; END IF;
  IF v_payment.status <> 'draft' THEN
    RAISE EXCEPTION 'SUPPLIER_PAYMENT_NOT_DRAFT: status=%', v_payment.status;
  END IF;

  IF v_payment.gl_entry_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.gl_entries e
      WHERE e.id = v_payment.gl_entry_id AND e.org_id = v_org AND e.status = 'draft'
      FOR UPDATE
    ) THEN
      RAISE EXCEPTION 'SUPPLIER_PAYMENT_DRAFT_GL_INVALID';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.audit_logs a
      WHERE a.org_id = v_org
        AND a.action = 'voucher_reset_to_draft'
        AND a.entity_type = 'supplier_payment'
        AND a.entity_id = v_payment.id::text
    ) THEN
      RAISE EXCEPTION 'SUPPLIER_PAYMENT_CORRECTION_UNPROVEN: no trusted reset record';
    END IF;
  END IF;

  IF nullif(p_payload->>'vendor_id', '') IS NOT NULL
     AND (p_payload->>'vendor_id')::uuid <> v_payment.vendor_id THEN
    RAISE EXCEPTION 'SUPPLIER_PAYMENT_PARTY_IMMUTABLE: cancel and create a new voucher';
  END IF;

  v_amount := round(coalesce(nullif(p_payload->>'amount', '')::numeric, v_payment.amount), 2);
  v_date := coalesce(nullif(p_payload->>'payment_date', '')::date, v_payment.payment_date);
  v_method := coalesce(nullif(p_payload->>'payment_method', ''), v_payment.payment_method);
  v_account := coalesce(nullif(p_payload->>'payment_account_id', '')::uuid,
                        v_payment.payment_account_id);
  IF v_amount <= 0 THEN RAISE EXCEPTION 'VOUCHER_AMOUNT_INVALID: amount must be positive'; END IF;

  UPDATE public.supplier_payments
  SET amount = v_amount,
      payment_date = v_date,
      payment_method = v_method,
      payment_account_id = v_account,
      check_number = coalesce(nullif(p_payload->>'check_number', ''), check_number),
      check_date = coalesce(nullif(p_payload->>'check_date', '')::date, check_date),
      check_bank = coalesce(nullif(p_payload->>'check_bank', ''), check_bank),
      reference_number = coalesce(nullif(p_payload->>'reference_number', ''), reference_number),
      notes = coalesce(nullif(p_payload->>'notes', ''), notes),
      updated_at = now()
  WHERE id = v_payment.id AND org_id = v_org AND status = 'draft';
  IF NOT FOUND THEN RAISE EXCEPTION 'SUPPLIER_PAYMENT_STATE_CHANGED'; END IF;

  PERFORM set_config('wardah.voucher_lines_write', 'on', true);

  DELETE FROM public.supplier_payment_lines WHERE payment_id = v_payment.id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  FOR v_line IN
    SELECT value FROM jsonb_array_elements(p_payload->'lines')
  LOOP
    v_invoice_id := nullif(v_line->>'invoice_id', '')::uuid;
    v_allocated := round(coalesce(nullif(v_line->>'allocated_amount', '')::numeric, 0), 2);
    v_discount := round(coalesce(nullif(v_line->>'discount_amount', '')::numeric, 0), 2);

    IF v_invoice_id IS NULL
       OR v_allocated <= 0
       OR v_discount <> 0
       OR v_invoice_id = ANY (v_seen) THEN
      PERFORM set_config('wardah.voucher_lines_write', 'off', true);
      RAISE EXCEPTION 'SUPPLIER_PAYMENT_ALLOCATION_INVALID: invoice=% allocated=% discount=%',
        v_invoice_id, v_allocated, v_discount;
    END IF;
    v_seen := v_seen || v_invoice_id;

    SELECT i.total_amount, coalesce(i.paid_amount, 0) AS paid_amount, i.status
    INTO v_invoice
    FROM public.supplier_invoices i
    WHERE i.id = v_invoice_id AND i.org_id = v_org AND i.vendor_id = v_payment.vendor_id
    FOR UPDATE;
    IF NOT FOUND THEN
      PERFORM set_config('wardah.voucher_lines_write', 'off', true);
      RAISE EXCEPTION 'SUPPLIER_PAYMENT_ALLOCATION_CROSS_SCOPE: invoice=%', v_invoice_id;
    END IF;
    IF v_invoice.status NOT IN ('approved', 'partially_paid', 'overdue') THEN
      PERFORM set_config('wardah.voucher_lines_write', 'off', true);
      RAISE EXCEPTION 'SUPPLIER_INVOICE_NOT_PAYABLE: invoice=% status=%',
        v_invoice_id, v_invoice.status;
    END IF;

    v_open := round(v_invoice.total_amount - v_invoice.paid_amount, 2);
    IF v_allocated > v_open THEN
      PERFORM set_config('wardah.voucher_lines_write', 'off', true);
      RAISE EXCEPTION 'SUPPLIER_PAYMENT_OVER_ALLOCATION: invoice=% open=% allocated=%',
        v_invoice_id, v_open, v_allocated;
    END IF;

    INSERT INTO public.supplier_payment_lines (
      payment_id, invoice_id, allocated_amount, discount_amount, notes
    ) VALUES (
      v_payment.id, v_invoice_id, v_allocated, 0, nullif(v_line->>'notes', '')
    );

    v_total := v_total + v_allocated;
    v_count := v_count + 1;
  END LOOP;

  PERFORM set_config('wardah.voucher_lines_write', 'off', true);

  SELECT count(*) INTO v_stored
  FROM public.supplier_payment_lines WHERE payment_id = v_payment.id;
  IF v_stored <> v_count THEN
    RAISE EXCEPTION 'SUPPLIER_PAYMENT_LINE_REPLACEMENT_MISMATCH: stored=% expected=%',
      v_stored, v_count;
  END IF;
  IF v_count > 0 AND round(v_total, 2) <> v_amount THEN
    RAISE EXCEPTION 'SUPPLIER_PAYMENT_ALLOCATION_TOTAL_MISMATCH: allocations=% payment=%',
      v_total, v_amount;
  END IF;

  INSERT INTO public.audit_logs(
    org_id, user_id, action, entity_type, entity_id, old_data, new_data, changes, metadata
  ) VALUES (
    v_org, v_actor, 'voucher_draft_updated', 'supplier_payment', v_payment.id::text,
    jsonb_build_object('amount', v_payment.amount, 'payment_date', v_payment.payment_date,
                       'payment_method', v_payment.payment_method,
                       'payment_account_id', v_payment.payment_account_id,
                       'line_count', v_deleted),
    jsonb_build_object('amount', v_amount, 'payment_date', v_date,
                       'payment_method', v_method, 'payment_account_id', v_account,
                       'line_count', v_count),
    jsonb_build_object('lines_replaced', v_deleted || ' -> ' || v_count),
    jsonb_build_object('source', 'rpc_update_supplier_payment_draft',
                       'gl_entry_id', v_payment.gl_entry_id)
  );

  RETURN jsonb_build_object(
    'success', true, 'payment_id', v_payment.id, 'status', 'draft',
    'line_count', v_count, 'lines_removed', v_deleted
  );
END
$$;


--
-- Name: wardah_169_leave_write_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_169_leave_write_context() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM set_config('wardah.voucher_header_write', 'off', true);
  PERFORM set_config('wardah.voucher_lines_write', 'off', true);
  PERFORM set_config('wardah.voucher_invoice_payment_write', 'off', true);
END
$$;


--
-- Name: wardah_175_internal_replace_user_roles(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_175_internal_replace_user_roles(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org       uuid := NULLIF(p_payload->>'org_id','')::uuid;
  v_user      uuid := NULLIF(p_payload->>'user_id','')::uuid;
  v_expires   timestamptz := NULLIF(p_payload->>'expires_at','')::timestamptz;
  v_role_ids  uuid[];
  v_bad       int;
  v_old       jsonb;
  v_sensitive text[];
  v_existing_expiry jsonb;
  v_requested jsonb;
  v_new       jsonb;
  v_total     int;
  v_distinct  int;
BEGIN
  IF v_org IS NULL OR v_user IS NULL THEN
    RAISE EXCEPTION 'RBAC_174_ORG_AND_USER_REQUIRED';
  END IF;
  PERFORM public.wardah_assert_org_admin(v_org);

  -- The target must be a member of this organization; role assignment must
  -- never be a way to reach across tenants.
  IF NOT EXISTS (
    SELECT 1 FROM public.user_organizations uo
    WHERE uo.user_id = v_user AND uo.org_id = v_org AND uo.is_active IS TRUE
    FOR UPDATE
  ) THEN
    RAISE EXCEPTION 'RBAC_174_TARGET_NOT_ACTIVE_ORG_MEMBER';
  END IF;

  -- The `FOR UPDATE` above is not only a membership check: it takes a
  -- transaction-scoped lock on the membership row, which is the stable parent
  -- of this user's assignments in this org. Without it, two administrators
  -- replacing the same user's roles concurrently can each delete a set the
  -- other has not yet inserted and both commit, leaving the union of the two
  -- requests rather than either one. Serializing on the membership row makes
  -- "replace" actually mean replace.

  -- Requested roles. Two accepted shapes, so a caller can express per-role
  -- expiry without a second round-trip:
  --   ["<role_id>", ...]
  --   [{"role_id": "...", "expires_at": "..."}, ...]   (expires_at may be null)
  -- Normalized in a local jsonb value rather than a temp table: an unqualified
  -- temp-table name inside a SECURITY DEFINER function whose search_path puts
  -- `public` first could be shadowed by a same-named table in public.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'role_id', rid, 'has_explicit', has_exp, 'expires_at', exp) ORDER BY rid), '[]'::jsonb),
         count(*), count(DISTINCT rid)
    INTO v_requested, v_total, v_distinct
  FROM (
    SELECT
      CASE WHEN jsonb_typeof(elem) = 'object'
           THEN NULLIF(elem->>'role_id','')::uuid
           ELSE NULLIF(elem #>> '{}','')::uuid END AS rid,
      CASE WHEN jsonb_typeof(elem) = 'object' AND elem ? 'expires_at'
           THEN NULLIF(elem->>'expires_at','')::timestamptz END AS exp,
      (jsonb_typeof(elem) = 'object' AND elem ? 'expires_at') AS has_exp
    FROM jsonb_array_elements(COALESCE(p_payload->'role_ids','[]'::jsonb)) AS t(elem)
  ) raw
  WHERE rid IS NOT NULL;

  -- Reject a repeated role_id rather than silently keeping one of them. With
  -- per-role expiry a duplicate can carry two conflicting deadlines, and any
  -- de-duplication rule would be picking one on the caller's behalf without
  -- telling them — for a sensitive grant that is the difference between a
  -- 30-day authorization and a permanent one. This runs before any mutation,
  -- so a rejected payload leaves the existing assignments untouched.
  IF v_total <> v_distinct THEN
    RAISE EXCEPTION 'RBAC_174_DUPLICATE_ROLE_ID';
  END IF;

  SELECT COALESCE(array_agg((elem->>'role_id')::uuid), ARRAY[]::uuid[])
    INTO v_role_ids
  FROM jsonb_array_elements(v_requested) AS t(elem);

  -- Every role must belong to this organization.
  SELECT count(*) INTO v_bad
  FROM unnest(v_role_ids) AS rid
  WHERE NOT EXISTS (
    SELECT 1 FROM public.roles r WHERE r.id = rid AND r.org_id = v_org
  );
  IF v_bad > 0 THEN
    RAISE EXCEPTION 'RBAC_174_ROLE_NOT_IN_ORG';
  END IF;

  -- Full before snapshot: role_id AND its deadline. Recording ids alone loses
  -- the change this RPC is most likely to make invisibly — a grant's expiry
  -- moving, or being cleared.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'role_id', ur.role_id, 'expires_at', ur.expires_at) ORDER BY ur.role_id), '[]'::jsonb)
    INTO v_old
  FROM public.user_roles ur
  WHERE ur.user_id = v_user AND ur.org_id = v_org;

  -- Capture the expiry of each CURRENT assignment before deleting, so a
  -- retained role keeps its own deadline. Replacing the whole set is a
  -- statement about WHICH roles are held, not a licence to quietly extend a
  -- time-boxed one to permanent — which is exactly what a single payload-level
  -- expires_at applied to every row would do when the caller omits it.
  SELECT COALESCE(jsonb_object_agg(role_id::text, to_jsonb(expires_at)), '{}'::jsonb)
    INTO v_existing_expiry
  FROM (
    SELECT ur.role_id, max(ur.expires_at) AS expires_at
    FROM public.user_roles ur
    WHERE ur.user_id = v_user AND ur.org_id = v_org
    GROUP BY ur.role_id
  ) cur;

  DELETE FROM public.user_roles WHERE user_id = v_user AND org_id = v_org;

  INSERT INTO public.user_roles (user_id, role_id, org_id, assigned_by, expires_at)
  SELECT v_user, (elem->>'role_id')::uuid, v_org, auth.uid(),
         CASE
           -- 1. An explicit per-role value always wins, including explicit null.
           WHEN (elem->>'has_explicit')::boolean
             THEN NULLIF(elem->>'expires_at','')::timestamptz
           -- 2. A retained role keeps the deadline it already had.
           WHEN v_existing_expiry ? (elem->>'role_id')
             THEN (v_existing_expiry->>(elem->>'role_id'))::timestamptz
           -- 3. Only genuinely new assignments take the payload-level default.
           ELSE v_expires
         END
  FROM jsonb_array_elements(v_requested) AS t(elem);

  SELECT COALESCE(array_agg(DISTINCT p.permission_key), ARRAY[]::text[])
    INTO v_sensitive
  FROM public.role_permissions rp
  JOIN public.permissions p ON p.id = rp.permission_id
  WHERE rp.role_id = ANY (v_role_ids)
    AND public.wardah_is_sensitive_permission(p.permission_key);

  -- Full after snapshot, read back from the rows actually written rather than
  -- reconstructed from the payload, so the audit records what the database now
  -- holds — including deadlines resolved from the retained-expiry rule above.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'role_id', ur.role_id, 'expires_at', ur.expires_at) ORDER BY ur.role_id), '[]'::jsonb)
    INTO v_new
  FROM public.user_roles ur
  WHERE ur.user_id = v_user AND ur.org_id = v_org;

  INSERT INTO public.audit_logs (org_id, user_id, action, entity_type, entity_id, old_data, new_data, metadata)
  VALUES (
    v_org, auth.uid(), 'rbac.user_roles.replace', 'user', v_user::text,
    v_old, v_new,
    jsonb_build_object(
      'migration', 174,
      'role_count', COALESCE(array_length(v_role_ids, 1), 0),
      'payload_default_expires_at', v_expires,
      'sensitive_keys_granted', to_jsonb(v_sensitive),
      'self_assignment', v_user = auth.uid())
  );

  RETURN jsonb_build_object(
    'user_id', v_user,
    'role_count', COALESCE(array_length(v_role_ids, 1), 0),
    'sensitive_keys_granted', to_jsonb(v_sensitive));
END;
$$;


--
-- Name: wardah_175_protect_role_membership_parent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_175_protect_role_membership_parent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_invalidates_membership boolean := false;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_invalidates_membership := true;
  ELSE
    v_invalidates_membership :=
      OLD.user_id IS DISTINCT FROM NEW.user_id
      OR OLD.org_id IS DISTINCT FROM NEW.org_id;
  END IF;

  IF v_invalidates_membership AND EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id = OLD.user_id
      AND ur.org_id = OLD.org_id
  ) THEN
    RAISE EXCEPTION 'RBAC_175_MEMBERSHIP_HAS_ROLE_ASSIGNMENTS';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: wardah_175_reject_direct_role_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_175_reject_direct_role_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  RAISE EXCEPTION
    'RBAC_175_DIRECT_USER_ROLES_UPDATE_FORBIDDEN_USE_RPC_REPLACE_USER_ROLES';
END;
$$;


--
-- Name: wardah_175_require_active_role_membership(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_175_require_active_role_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_active boolean;
BEGIN
  -- Lock order is organization -> membership everywhere. The organization
  -- lock also prevents the audit FK from forming a member<->org deadlock with
  -- rpc_remove_org_member, which holds the org row before deleting membership.
  PERFORM 1
  FROM public.organizations o
  WHERE o.id = NEW.org_id
  FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RBAC_175_ACTIVE_MEMBERSHIP_REQUIRED';
  END IF;

  SELECT uo.is_active
    INTO v_active
  FROM public.user_organizations uo
  WHERE uo.user_id = NEW.user_id
    AND uo.org_id = NEW.org_id
  FOR UPDATE;

  IF NOT FOUND OR v_active IS NOT TRUE THEN
    RAISE EXCEPTION 'RBAC_175_ACTIVE_MEMBERSHIP_REQUIRED';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: wardah_178_assert_permission(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_178_assert_permission(p_org uuid, p_permission_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;
  IF p_org IS NULL THEN
    RAISE EXCEPTION 'ORG_UNRESOLVED';
  END IF;
  IF NOT public.wardah_has_exact_permission(v_uid, p_org, p_permission_key) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: %', p_permission_key;
  END IF;
END;
$$;


--
-- Name: wardah_178_validate_manual_lines(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_178_validate_manual_lines(p_org uuid, p_lines jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count integer;
  v_bad integer;
BEGIN
  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' THEN
    RAISE EXCEPTION 'JOURNAL_LINES_REQUIRED';
  END IF;

  SELECT count(*) INTO v_count FROM jsonb_array_elements(p_lines);
  IF v_count < 2 THEN
    RAISE EXCEPTION 'EMPTY_ENTRY: at least two lines are required';
  END IF;

  SELECT count(*) INTO v_bad
  FROM jsonb_array_elements(p_lines) l
  WHERE NULLIF(l->>'account_id','') IS NULL
     OR COALESCE((l->>'debit')::numeric, 0) < 0
     OR COALESCE((l->>'credit')::numeric, 0) < 0
     OR (COALESCE((l->>'debit')::numeric, 0) > 0
         AND COALESCE((l->>'credit')::numeric, 0) > 0)
     OR (COALESCE((l->>'debit')::numeric, 0) = 0
         AND COALESCE((l->>'credit')::numeric, 0) = 0);
  IF v_bad > 0 THEN
    RAISE EXCEPTION 'JOURNAL_INVALID_LINE_SHAPE';
  END IF;

  SELECT count(*) INTO v_bad
  FROM jsonb_array_elements(p_lines) l
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.gl_accounts a
    WHERE a.id = (l->>'account_id')::uuid
      AND a.org_id = p_org
      AND COALESCE(a.is_active, true)
      AND COALESCE(a.allow_posting, true)
  );
  IF v_bad > 0 THEN
    RAISE EXCEPTION 'JOURNAL_ACCOUNT_NOT_POSTABLE_IN_ORG';
  END IF;
END;
$$;


--
-- Name: wardah_184_assert_posted_entry_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_184_assert_posted_entry_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_entry_id uuid;
  v_entry_ids uuid[];
  v_status text;
  v_entry_number text;
  v_header_debit numeric;
  v_header_credit numeric;
  v_line_count bigint;
  v_line_debit numeric;
  v_line_credit numeric;
BEGIN
  IF TG_TABLE_NAME = 'gl_entries' THEN
    v_entry_ids := ARRAY[COALESCE(NEW.id, OLD.id)];
  ELSE
    v_entry_ids := ARRAY_REMOVE(
      ARRAY[CASE WHEN TG_OP <> 'DELETE' THEN NEW.entry_id END,
            CASE WHEN TG_OP <> 'INSERT' THEN OLD.entry_id END],
      NULL
    );
  END IF;

  FOREACH v_entry_id IN ARRAY v_entry_ids LOOP
    SELECT e.status, e.entry_number, e.total_debit, e.total_credit
    INTO v_status, v_entry_number, v_header_debit, v_header_credit
    FROM public.gl_entries e
    WHERE e.id = v_entry_id;

    IF NOT FOUND OR v_status IS DISTINCT FROM 'posted' THEN
      CONTINUE;
    END IF;

    SELECT COUNT(*),
           COALESCE(SUM(l.debit), 0),
           COALESCE(SUM(l.credit), 0)
    INTO v_line_count, v_line_debit, v_line_credit
    FROM public.gl_entry_lines l
    WHERE l.entry_id = v_entry_id;

    IF v_line_count < 2 THEN
      RAISE EXCEPTION
        'POSTED_ENTRY_LINES_MISSING: entry=% line_count=%',
        v_entry_number, v_line_count;
    END IF;

    IF ABS(v_line_debit - v_line_credit) >= 0.01 THEN
      RAISE EXCEPTION
        'POSTED_ENTRY_LINES_UNBALANCED: entry=% debit=% credit=%',
        v_entry_number, v_line_debit, v_line_credit;
    END IF;

    IF ABS(v_header_debit - v_line_debit) >= 0.01
       OR ABS(v_header_credit - v_line_credit) >= 0.01 THEN
      RAISE EXCEPTION
        'POSTED_ENTRY_HEADER_LINES_MISMATCH: entry=% header=(%,%) lines=(%,%)',
        v_entry_number, v_header_debit, v_header_credit,
        v_line_debit, v_line_credit;
    END IF;
  END LOOP;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: wardah_187_require_stock_source_line(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_187_require_stock_source_line() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF lower(btrim(NEW.voucher_type::text)) = 'stock adjustment' THEN
    IF NEW.source_line_id IS NULL THEN
      IF TG_OP = 'INSERT' THEN
        RAISE EXCEPTION 'STOCK_SOURCE_LINE_REQUIRED';
      END IF;

      IF OLD.source_line_id IS NOT NULL
         OR NEW.voucher_type IS DISTINCT FROM OLD.voucher_type
         OR NEW.voucher_id IS DISTINCT FROM OLD.voucher_id
         OR NEW.product_id IS DISTINCT FROM OLD.product_id
         OR NEW.warehouse_id IS DISTINCT FROM OLD.warehouse_id
         OR NEW.org_id IS DISTINCT FROM OLD.org_id THEN
        RAISE EXCEPTION 'STOCK_SOURCE_LINE_REQUIRED';
      END IF;

      -- Historical NULL-source rows remain updateable for cancellation and
      -- provenance-neutral maintenance.
      RETURN NEW;
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.stock_adjustment_items sai
      JOIN public.stock_adjustments sa ON sa.id = sai.adjustment_id
      WHERE sai.id = NEW.source_line_id
        AND sai.adjustment_id = NEW.voucher_id
        AND sai.organization_id = NEW.org_id
        AND sai.product_id = NEW.product_id
        AND COALESCE(sai.warehouse_id, sa.warehouse_id) = NEW.warehouse_id
        AND COALESCE(sa.org_id, sa.organization_id) = NEW.org_id
    ) THEN
      RAISE EXCEPTION 'STOCK_SOURCE_LINE_MISMATCH';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: wardah_apply_stock_incoming(uuid, uuid, uuid, numeric, numeric, text, uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_apply_stock_incoming(p_org uuid, p_product uuid, p_warehouse uuid, p_qty numeric, p_rate numeric, p_voucher_type text, p_voucher_id uuid, p_voucher_number text, p_posting_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_method     TEXT;
    v_prev_qty   NUMERIC := 0;
    v_prev_value NUMERIC := 0;
    v_prev_queue JSONB   := '[]'::JSONB;
    v_new_qty    NUMERIC;
    v_new_value  NUMERIC;
    v_new_rate   NUMERIC;
    v_new_queue  JSONB;
    v_len        INTEGER;
    v_prod_qty   NUMERIC;
    v_prod_rate  NUMERIC;
BEGIN
    -- لا مخزن ⇒ لا دفتر مخزون (المخزن اختياري في سند الاستلام)
    IF p_warehouse IS NULL OR p_qty IS NULL OR p_qty <= 0 THEN
        RETURN jsonb_build_object('applied', FALSE, 'reason', 'NO_WAREHOUSE_OR_QTY');
    END IF;

    -- طريقة التقييم (افتراضي: متوسط مرجّح)
    SELECT COALESCE(valuation_method, 'Weighted Average')
    INTO v_method
    FROM products WHERE id = p_product AND org_id = p_org;
    v_method := COALESCE(v_method, 'Weighted Average');

    -- قفل صف الـ bin (أو غيابه) — يمنع سباق القراءة/الكتابة.
    SELECT actual_qty, stock_value, stock_queue
    INTO v_prev_qty, v_prev_value, v_prev_queue
    FROM bins
    WHERE product_id = p_product AND warehouse_id = p_warehouse
    FOR UPDATE;

    v_prev_qty   := COALESCE(v_prev_qty, 0);
    v_prev_value := COALESCE(v_prev_value, 0);
    v_prev_queue := COALESCE(v_prev_queue, '[]'::JSONB);

    v_new_qty   := v_prev_qty + p_qty;
    v_new_value := v_prev_value + (p_qty * p_rate);
    v_new_queue := v_prev_queue
                   || jsonb_build_array(jsonb_build_object('qty', p_qty, 'rate', p_rate));

    IF v_method = 'FIFO' THEN
        v_new_rate := COALESCE((v_new_queue->0->>'rate')::NUMERIC, p_rate);
    ELSIF v_method = 'LIFO' THEN
        v_len := jsonb_array_length(v_new_queue);
        v_new_rate := COALESCE((v_new_queue->(v_len - 1)->>'rate')::NUMERIC, p_rate);
    ELSE
        v_new_rate  := CASE WHEN v_new_qty > 0 THEN v_new_value / v_new_qty ELSE 0 END;
        v_new_queue := jsonb_build_array(jsonb_build_object('qty', v_new_qty, 'rate', v_new_rate));
    END IF;

    INSERT INTO stock_ledger_entries (
        voucher_type, voucher_id, voucher_number, product_id, warehouse_id,
        posting_date, actual_qty, qty_after_transaction, incoming_rate,
        valuation_rate, stock_value, stock_value_difference, stock_queue,
        docstatus, org_id, created_by
    ) VALUES (
        p_voucher_type, p_voucher_id, p_voucher_number, p_product, p_warehouse,
        COALESCE(p_posting_date, CURRENT_DATE), p_qty, v_new_qty, p_rate,
        v_new_rate, v_new_value, (p_qty * p_rate), v_new_queue,
        1, p_org, auth.uid()
    );

    -- Bin: upsert (فهرس فريد على product_id, warehouse_id)
    INSERT INTO bins (
        org_id, product_id, warehouse_id, actual_qty,
        valuation_rate, stock_value, stock_queue, updated_at
    ) VALUES (
        p_org, p_product, p_warehouse, v_new_qty,
        v_new_rate, v_new_value, v_new_queue, NOW()
    )
    ON CONFLICT (product_id, warehouse_id) DO UPDATE SET
        actual_qty     = EXCLUDED.actual_qty,
        valuation_rate = EXCLUDED.valuation_rate,
        stock_value    = EXCLUDED.stock_value,
        stock_queue    = EXCLUDED.stock_queue,
        updated_at     = NOW();

    -- ✅ توحيد المخزون (Migration 97): مزامنة products من مجموع bins لهذا المنتج
    --    عبر كل المخازن — اشتقاق idempotent (لا يضاعف عند إعادة التطبيق). يجعل
    --    products المجمّع المرجعي الذي تقرؤه التقارير/اللوحة/تقييم المخزون.
    SELECT COALESCE(SUM(actual_qty), 0),
           CASE WHEN COALESCE(SUM(actual_qty), 0) > 0
                THEN SUM(stock_value) / SUM(actual_qty) ELSE NULL END
    INTO v_prod_qty, v_prod_rate
    FROM bins WHERE product_id = p_product AND org_id = p_org;

    UPDATE products
    SET stock_quantity = v_prod_qty,
        cost_price     = COALESCE(v_prod_rate, cost_price),
        updated_at     = NOW()
    WHERE id = p_product AND org_id = p_org;

    RETURN jsonb_build_object(
        'applied', TRUE, 'new_qty', v_new_qty,
        'new_rate', ROUND(v_new_rate, 6), 'new_value', ROUND(v_new_value, 6),
        'method', v_method,
        'product_synced', jsonb_build_object(
            'stock_quantity', v_prod_qty,
            'cost_price', ROUND(COALESCE(v_prod_rate, 0), 6))
    );
END;
$$;


--
-- Name: wardah_apply_stock_incoming(uuid, uuid, uuid, numeric, numeric, text, uuid, text, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_apply_stock_incoming(p_org uuid, p_product uuid, p_warehouse uuid, p_qty numeric, p_rate numeric, p_voucher_type text, p_voucher_id uuid, p_voucher_number text, p_posting_date date, p_source_line_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_method text;
  v_prev_qty numeric := 0;
  v_prev_value numeric := 0;
  v_prev_queue jsonb := '[]'::jsonb;
  v_new_qty numeric;
  v_new_value numeric;
  v_new_rate numeric;
  v_new_queue jsonb;
  v_len integer;
  v_prod_qty numeric;
  v_prod_rate numeric;
BEGIN
  IF p_warehouse IS NULL OR p_qty IS NULL OR p_qty <= 0 THEN
    RETURN jsonb_build_object('applied', false, 'reason', 'NO_WAREHOUSE_OR_QTY');
  END IF;

  IF lower(btrim(COALESCE(p_voucher_type, ''))) = 'stock adjustment' THEN
    IF p_source_line_id IS NULL THEN
      RAISE EXCEPTION 'STOCK_SOURCE_LINE_REQUIRED';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.stock_adjustment_items sai
      JOIN public.stock_adjustments sa ON sa.id = sai.adjustment_id
      WHERE sai.id = p_source_line_id
        AND sai.adjustment_id = p_voucher_id
        AND sai.organization_id = p_org
        AND sai.product_id = p_product
        AND COALESCE(sai.warehouse_id, sa.warehouse_id) = p_warehouse
        AND COALESCE(sa.org_id, sa.organization_id) = p_org
    ) THEN
      RAISE EXCEPTION 'STOCK_SOURCE_LINE_MISMATCH';
    END IF;
  END IF;

  SELECT COALESCE(valuation_method, 'Weighted Average')
  INTO v_method
  FROM public.products
  WHERE id = p_product AND org_id = p_org;
  v_method := COALESCE(v_method, 'Weighted Average');

  SELECT actual_qty, stock_value, stock_queue
  INTO v_prev_qty, v_prev_value, v_prev_queue
  FROM public.bins
  WHERE product_id = p_product AND warehouse_id = p_warehouse
  FOR UPDATE;

  v_prev_qty := COALESCE(v_prev_qty, 0);
  v_prev_value := COALESCE(v_prev_value, 0);
  v_prev_queue := COALESCE(v_prev_queue, '[]'::jsonb);

  v_new_qty := v_prev_qty + p_qty;
  v_new_value := v_prev_value + (p_qty * p_rate);
  v_new_queue := v_prev_queue
    || jsonb_build_array(jsonb_build_object('qty', p_qty, 'rate', p_rate));

  IF v_method = 'FIFO' THEN
    v_new_rate := COALESCE((v_new_queue -> 0 ->> 'rate')::numeric, p_rate);
  ELSIF v_method = 'LIFO' THEN
    v_len := jsonb_array_length(v_new_queue);
    v_new_rate := COALESCE((v_new_queue -> (v_len - 1) ->> 'rate')::numeric, p_rate);
  ELSE
    v_new_rate := CASE WHEN v_new_qty > 0 THEN v_new_value / v_new_qty ELSE 0 END;
    v_new_queue := jsonb_build_array(
      jsonb_build_object('qty', v_new_qty, 'rate', v_new_rate)
    );
  END IF;

  INSERT INTO public.stock_ledger_entries (
    voucher_type,
    voucher_id,
    voucher_number,
    product_id,
    warehouse_id,
    posting_date,
    actual_qty,
    qty_after_transaction,
    incoming_rate,
    valuation_rate,
    stock_value,
    stock_value_difference,
    stock_queue,
    docstatus,
    org_id,
    created_by,
    source_line_id
  ) VALUES (
    p_voucher_type,
    p_voucher_id,
    p_voucher_number,
    p_product,
    p_warehouse,
    COALESCE(p_posting_date, CURRENT_DATE),
    p_qty,
    v_new_qty,
    p_rate,
    v_new_rate,
    v_new_value,
    p_qty * p_rate,
    v_new_queue,
    1,
    p_org,
    auth.uid(),
    p_source_line_id
  );

  INSERT INTO public.bins (
    org_id,
    product_id,
    warehouse_id,
    actual_qty,
    valuation_rate,
    stock_value,
    stock_queue,
    updated_at
  ) VALUES (
    p_org,
    p_product,
    p_warehouse,
    v_new_qty,
    v_new_rate,
    v_new_value,
    v_new_queue,
    now()
  )
  ON CONFLICT (product_id, warehouse_id) DO UPDATE SET
    actual_qty = EXCLUDED.actual_qty,
    valuation_rate = EXCLUDED.valuation_rate,
    stock_value = EXCLUDED.stock_value,
    stock_queue = EXCLUDED.stock_queue,
    updated_at = now();

  SELECT COALESCE(SUM(actual_qty), 0),
         CASE
           WHEN COALESCE(SUM(actual_qty), 0) > 0
             THEN SUM(stock_value) / SUM(actual_qty)
           ELSE NULL
         END
  INTO v_prod_qty, v_prod_rate
  FROM public.bins
  WHERE product_id = p_product AND org_id = p_org;

  UPDATE public.products
  SET stock_quantity = v_prod_qty,
      cost_price = COALESCE(v_prod_rate, cost_price),
      updated_at = now()
  WHERE id = p_product AND org_id = p_org;

  RETURN jsonb_build_object(
    'applied', true,
    'new_qty', v_new_qty,
    'new_rate', round(v_new_rate, 6),
    'new_value', round(v_new_value, 6),
    'method', v_method,
    'source_line_id', p_source_line_id,
    'product_synced', jsonb_build_object(
      'stock_quantity', v_prod_qty,
      'cost_price', round(COALESCE(v_prod_rate, 0), 6)
    )
  );
END;
$$;


--
-- Name: wardah_apply_stock_outgoing(uuid, uuid, uuid, numeric, text, uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_apply_stock_outgoing(p_org uuid, p_product uuid, p_warehouse uuid, p_qty numeric, p_voucher_type text, p_voucher_id uuid, p_voucher_number text, p_posting_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_method text;
  v_prev_qty numeric;
  v_prev_value numeric;
  v_prev_queue jsonb;
  v_new_qty numeric;
  v_new_value numeric;
  v_new_rate numeric;
  v_new_queue jsonb;
  v_remaining numeric;
  v_take numeric;
  v_batch_qty numeric;
  v_batch_rate numeric;
  v_cogs numeric := 0;
  v_idx integer;
  v_len integer;
  v_prod_qty numeric;
  v_prod_value numeric;
  v_prod_rate numeric;
  v_total_on_hand numeric;
  v_other_mo_reserved numeric;
BEGIN
  PERFORM public.wardah_assert_org_member(p_org);

  IF p_product IS NULL OR p_warehouse IS NULL OR p_qty IS NULL OR p_qty <= 0 THEN
    RAISE EXCEPTION 'INVALID_STOCK_OUT_PARAMETERS';
  END IF;

  SELECT COALESCE(valuation_method::text, 'Weighted Average')
  INTO v_method
  FROM public.products
  WHERE id = p_product AND org_id = p_org;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PRODUCT_NOT_FOUND_OR_WRONG_ORG';
  END IF;

  PERFORM 1
  FROM public.bins
  WHERE org_id = p_org AND product_id = p_product
  ORDER BY warehouse_id, id
  FOR UPDATE;

  SELECT COALESCE(SUM(actual_qty), 0)
  INTO v_total_on_hand
  FROM public.bins
  WHERE org_id = p_org AND product_id = p_product;

  SELECT COALESCE(SUM(GREATEST(
    quantity_reserved - COALESCE(quantity_consumed, 0) - COALESCE(quantity_released, 0),
    0
  )), 0)
  INTO v_other_mo_reserved
  FROM public.material_reservations
  WHERE org_id = p_org
    AND product_id = p_product
    AND status = 'reserved'
    AND NOT (
      lower(COALESCE(p_voucher_type, '')) = 'material consumption'
      AND p_voucher_id IS NOT NULL
      AND mo_id = p_voucher_id
    );

  IF v_total_on_hand - p_qty < v_other_mo_reserved THEN
    RAISE EXCEPTION
      'INSUFFICIENT_UNRESERVED_STOCK: on_hand=%, protected_mo=%, requested=%',
      v_total_on_hand, v_other_mo_reserved, p_qty;
  END IF;

  SELECT COALESCE(actual_qty, 0), COALESCE(stock_value, 0),
         COALESCE(stock_queue, '[]'::jsonb)
  INTO v_prev_qty, v_prev_value, v_prev_queue
  FROM public.bins
  WHERE org_id = p_org AND product_id = p_product AND warehouse_id = p_warehouse
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BIN_NOT_FOUND';
  END IF;
  IF v_prev_qty < p_qty THEN
    RAISE EXCEPTION 'INSUFFICIENT_STOCK: available=%, required=%', v_prev_qty, p_qty;
  END IF;

  v_new_qty := v_prev_qty - p_qty;
  v_new_queue := v_prev_queue;

  IF v_method IN ('FIFO', 'LIFO') AND jsonb_array_length(v_new_queue) > 0 THEN
    v_remaining := p_qty;
    WHILE v_remaining > 0 LOOP
      v_len := jsonb_array_length(v_new_queue);
      IF v_len = 0 THEN
        RAISE EXCEPTION 'STOCK_QUEUE_INSUFFICIENT';
      END IF;
      v_idx := CASE WHEN v_method = 'FIFO' THEN 0 ELSE v_len - 1 END;
      v_batch_qty := COALESCE((v_new_queue -> v_idx ->> 'qty')::numeric, 0);
      v_batch_rate := COALESCE((v_new_queue -> v_idx ->> 'rate')::numeric, 0);
      IF v_batch_qty <= 0 THEN
        v_new_queue := v_new_queue - v_idx;
        CONTINUE;
      END IF;
      v_take := LEAST(v_remaining, v_batch_qty);
      v_cogs := v_cogs + (v_take * v_batch_rate);
      v_remaining := v_remaining - v_take;
      IF v_take = v_batch_qty THEN
        v_new_queue := v_new_queue - v_idx;
      ELSE
        v_new_queue := jsonb_set(
          v_new_queue,
          ARRAY[v_idx::text, 'qty'],
          to_jsonb(v_batch_qty - v_take),
          false
        );
      END IF;
    END LOOP;
    v_new_value := GREATEST(v_prev_value - v_cogs, 0);
    IF v_new_qty = 0 THEN
      v_new_rate := 0;
      v_new_queue := '[]'::jsonb;
    ELSE
      v_len := jsonb_array_length(v_new_queue);
      v_idx := CASE WHEN v_method = 'FIFO' THEN 0 ELSE v_len - 1 END;
      v_new_rate := COALESCE((v_new_queue -> v_idx ->> 'rate')::numeric, 0);
    END IF;
  ELSE
    v_batch_rate := CASE WHEN v_prev_qty > 0 THEN v_prev_value / v_prev_qty ELSE 0 END;
    v_cogs := p_qty * v_batch_rate;
    v_new_value := GREATEST(v_prev_value - v_cogs, 0);
    v_new_rate := CASE WHEN v_new_qty > 0 THEN v_new_value / v_new_qty ELSE 0 END;
    v_new_queue := CASE WHEN v_new_qty > 0
      THEN jsonb_build_array(jsonb_build_object('qty', v_new_qty, 'rate', v_new_rate))
      ELSE '[]'::jsonb END;
  END IF;

  INSERT INTO public.stock_ledger_entries (
    voucher_type, voucher_id, voucher_number, product_id, warehouse_id,
    posting_date, actual_qty, qty_after_transaction, outgoing_rate,
    valuation_rate, stock_value, stock_value_difference, stock_queue,
    is_cancelled, docstatus, org_id, created_by
  ) VALUES (
    p_voucher_type, p_voucher_id, p_voucher_number, p_product, p_warehouse,
    COALESCE(p_posting_date, CURRENT_DATE), -p_qty, v_new_qty,
    CASE WHEN p_qty > 0 THEN v_cogs / p_qty ELSE 0 END,
    v_new_rate, v_new_value, -v_cogs, v_new_queue,
    false, 1, p_org, auth.uid()
  );

  UPDATE public.bins
  SET actual_qty = v_new_qty,
      valuation_rate = v_new_rate,
      stock_value = v_new_value,
      stock_queue = v_new_queue,
      updated_at = now()
  WHERE org_id = p_org AND product_id = p_product AND warehouse_id = p_warehouse;

  SELECT COALESCE(SUM(actual_qty), 0), COALESCE(SUM(stock_value), 0)
  INTO v_prod_qty, v_prod_value
  FROM public.bins
  WHERE org_id = p_org AND product_id = p_product;
  v_prod_rate := CASE WHEN v_prod_qty > 0 THEN v_prod_value / v_prod_qty ELSE 0 END;

  UPDATE public.products
  SET stock_quantity = v_prod_qty,
      stock_value = v_prod_value,
      cost_price = CASE WHEN v_prod_qty > 0 THEN v_prod_rate ELSE cost_price END,
      updated_at = now()
  WHERE id = p_product AND org_id = p_org;

  RETURN jsonb_build_object(
    'applied', true,
    'new_qty', v_new_qty,
    'new_rate', round(v_new_rate, 6),
    'new_value', round(v_new_value, 6),
    'cogs', round(v_cogs, 6),
    'method', v_method
  );
END;
$$;


--
-- Name: wardah_apply_stock_outgoing(uuid, uuid, uuid, numeric, text, uuid, text, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_apply_stock_outgoing(p_org uuid, p_product uuid, p_warehouse uuid, p_qty numeric, p_voucher_type text, p_voucher_id uuid, p_voucher_number text, p_posting_date date, p_source_line_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_method text;
  v_prev_qty numeric;
  v_prev_value numeric;
  v_prev_queue jsonb;
  v_new_qty numeric;
  v_new_value numeric;
  v_new_rate numeric;
  v_new_queue jsonb;
  v_remaining numeric;
  v_take numeric;
  v_batch_qty numeric;
  v_batch_rate numeric;
  v_cogs numeric := 0;
  v_idx integer;
  v_len integer;
  v_prod_qty numeric;
  v_prod_value numeric;
  v_prod_rate numeric;
  v_total_on_hand numeric;
  v_other_mo_reserved numeric;
BEGIN
  PERFORM public.wardah_assert_org_member(p_org);

  IF p_product IS NULL OR p_warehouse IS NULL OR p_qty IS NULL OR p_qty <= 0 THEN
    RAISE EXCEPTION 'INVALID_STOCK_OUT_PARAMETERS';
  END IF;

  IF lower(btrim(COALESCE(p_voucher_type, ''))) = 'stock adjustment' THEN
    IF p_source_line_id IS NULL THEN
      RAISE EXCEPTION 'STOCK_SOURCE_LINE_REQUIRED';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.stock_adjustment_items sai
      JOIN public.stock_adjustments sa ON sa.id = sai.adjustment_id
      WHERE sai.id = p_source_line_id
        AND sai.adjustment_id = p_voucher_id
        AND sai.organization_id = p_org
        AND sai.product_id = p_product
        AND COALESCE(sai.warehouse_id, sa.warehouse_id) = p_warehouse
        AND COALESCE(sa.org_id, sa.organization_id) = p_org
    ) THEN
      RAISE EXCEPTION 'STOCK_SOURCE_LINE_MISMATCH';
    END IF;
  END IF;

  SELECT COALESCE(valuation_method::text, 'Weighted Average')
  INTO v_method
  FROM public.products
  WHERE id = p_product AND org_id = p_org;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PRODUCT_NOT_FOUND_OR_WRONG_ORG';
  END IF;

  PERFORM 1
  FROM public.bins
  WHERE org_id = p_org AND product_id = p_product
  ORDER BY warehouse_id, id
  FOR UPDATE;

  SELECT COALESCE(SUM(actual_qty), 0)
  INTO v_total_on_hand
  FROM public.bins
  WHERE org_id = p_org AND product_id = p_product;

  SELECT COALESCE(SUM(GREATEST(
    quantity_reserved
      - COALESCE(quantity_consumed, 0)
      - COALESCE(quantity_released, 0),
    0
  )), 0)
  INTO v_other_mo_reserved
  FROM public.material_reservations
  WHERE org_id = p_org
    AND product_id = p_product
    AND status = 'reserved'
    AND NOT (
      lower(COALESCE(p_voucher_type, '')) = 'material consumption'
      AND p_voucher_id IS NOT NULL
      AND mo_id = p_voucher_id
    );

  IF v_total_on_hand - p_qty < v_other_mo_reserved THEN
    RAISE EXCEPTION
      'INSUFFICIENT_UNRESERVED_STOCK: on_hand=%, protected_mo=%, requested=%',
      v_total_on_hand,
      v_other_mo_reserved,
      p_qty;
  END IF;

  SELECT COALESCE(actual_qty, 0),
         COALESCE(stock_value, 0),
         COALESCE(stock_queue, '[]'::jsonb)
  INTO v_prev_qty, v_prev_value, v_prev_queue
  FROM public.bins
  WHERE org_id = p_org
    AND product_id = p_product
    AND warehouse_id = p_warehouse
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BIN_NOT_FOUND';
  END IF;
  IF v_prev_qty < p_qty THEN
    RAISE EXCEPTION 'INSUFFICIENT_STOCK: available=%, required=%', v_prev_qty, p_qty;
  END IF;

  v_new_qty := v_prev_qty - p_qty;
  v_new_queue := v_prev_queue;

  IF v_method IN ('FIFO', 'LIFO') AND jsonb_array_length(v_new_queue) > 0 THEN
    v_remaining := p_qty;
    WHILE v_remaining > 0 LOOP
      v_len := jsonb_array_length(v_new_queue);
      IF v_len = 0 THEN
        RAISE EXCEPTION 'STOCK_QUEUE_INSUFFICIENT';
      END IF;
      v_idx := CASE WHEN v_method = 'FIFO' THEN 0 ELSE v_len - 1 END;
      v_batch_qty := COALESCE((v_new_queue -> v_idx ->> 'qty')::numeric, 0);
      v_batch_rate := COALESCE((v_new_queue -> v_idx ->> 'rate')::numeric, 0);
      IF v_batch_qty <= 0 THEN
        v_new_queue := v_new_queue - v_idx;
        CONTINUE;
      END IF;
      v_take := LEAST(v_remaining, v_batch_qty);
      v_cogs := v_cogs + (v_take * v_batch_rate);
      v_remaining := v_remaining - v_take;
      IF v_take = v_batch_qty THEN
        v_new_queue := v_new_queue - v_idx;
      ELSE
        v_new_queue := jsonb_set(
          v_new_queue,
          ARRAY[v_idx::text, 'qty'],
          to_jsonb(v_batch_qty - v_take),
          false
        );
      END IF;
    END LOOP;
    v_new_value := GREATEST(v_prev_value - v_cogs, 0);
    IF v_new_qty = 0 THEN
      v_new_rate := 0;
      v_new_queue := '[]'::jsonb;
    ELSE
      v_len := jsonb_array_length(v_new_queue);
      v_idx := CASE WHEN v_method = 'FIFO' THEN 0 ELSE v_len - 1 END;
      v_new_rate := COALESCE((v_new_queue -> v_idx ->> 'rate')::numeric, 0);
    END IF;
  ELSE
    v_batch_rate := CASE WHEN v_prev_qty > 0 THEN v_prev_value / v_prev_qty ELSE 0 END;
    v_cogs := p_qty * v_batch_rate;
    v_new_value := GREATEST(v_prev_value - v_cogs, 0);
    v_new_rate := CASE WHEN v_new_qty > 0 THEN v_new_value / v_new_qty ELSE 0 END;
    v_new_queue := CASE
      WHEN v_new_qty > 0
        THEN jsonb_build_array(jsonb_build_object('qty', v_new_qty, 'rate', v_new_rate))
      ELSE '[]'::jsonb
    END;
  END IF;

  INSERT INTO public.stock_ledger_entries (
    voucher_type,
    voucher_id,
    voucher_number,
    product_id,
    warehouse_id,
    posting_date,
    actual_qty,
    qty_after_transaction,
    outgoing_rate,
    valuation_rate,
    stock_value,
    stock_value_difference,
    stock_queue,
    is_cancelled,
    docstatus,
    org_id,
    created_by,
    source_line_id
  ) VALUES (
    p_voucher_type,
    p_voucher_id,
    p_voucher_number,
    p_product,
    p_warehouse,
    COALESCE(p_posting_date, CURRENT_DATE),
    -p_qty,
    v_new_qty,
    CASE WHEN p_qty > 0 THEN v_cogs / p_qty ELSE 0 END,
    v_new_rate,
    v_new_value,
    -v_cogs,
    v_new_queue,
    false,
    1,
    p_org,
    auth.uid(),
    p_source_line_id
  );

  UPDATE public.bins
  SET actual_qty = v_new_qty,
      valuation_rate = v_new_rate,
      stock_value = v_new_value,
      stock_queue = v_new_queue,
      updated_at = now()
  WHERE org_id = p_org
    AND product_id = p_product
    AND warehouse_id = p_warehouse;

  SELECT COALESCE(SUM(actual_qty), 0),
         COALESCE(SUM(stock_value), 0)
  INTO v_prod_qty, v_prod_value
  FROM public.bins
  WHERE org_id = p_org AND product_id = p_product;
  v_prod_rate := CASE WHEN v_prod_qty > 0 THEN v_prod_value / v_prod_qty ELSE 0 END;

  UPDATE public.products
  SET stock_quantity = v_prod_qty,
      stock_value = v_prod_value,
      cost_price = CASE WHEN v_prod_qty > 0 THEN v_prod_rate ELSE cost_price END,
      updated_at = now()
  WHERE id = p_product AND org_id = p_org;

  RETURN jsonb_build_object(
    'applied', true,
    'new_qty', v_new_qty,
    'new_rate', round(v_new_rate, 6),
    'new_value', round(v_new_value, 6),
    'cogs', round(v_cogs, 6),
    'method', v_method,
    'source_line_id', p_source_line_id
  );
END;
$$;


--
-- Name: wardah_assert_org_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_assert_org_admin(p_org uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    PERFORM public.wardah_assert_org_member(p_org);
    IF NOT (COALESCE(public.is_super_admin(), FALSE)
            OR public.wardah_is_org_admin(p_org)) THEN
        RAISE EXCEPTION 'NOT_ORG_ADMIN';
    END IF;
END;
$$;


--
-- Name: wardah_assert_org_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_assert_org_member(p_org uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;
  IF p_org IS NULL THEN
    RAISE EXCEPTION 'ORG_UNRESOLVED';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations
    WHERE user_id = auth.uid()
      AND org_id = p_org
      AND is_active IS TRUE
  ) THEN
    RAISE EXCEPTION 'NOT_ORG_MEMBER';
  END IF;
END;
$$;


--
-- Name: wardah_create_posted_voucher_gl(uuid, text, uuid, text, date, text, uuid, uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_create_posted_voucher_gl(p_org uuid, p_reference_type text, p_reference_id uuid, p_reference_number text, p_entry_date date, p_description text, p_debit_account_id uuid, p_credit_account_id uuid, p_amount numeric, p_actor uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_entry_id uuid;
  v_entry_number text;
  v_journal_id uuid;
  v_existing_status text;
  v_idempotency_key text := p_reference_type || ':' || p_reference_id::text;
BEGIN
  IF p_org IS NULL OR p_reference_id IS NULL OR p_actor IS NULL THEN
    RAISE EXCEPTION 'VOUCHER_GL_SCOPE_REQUIRED: org, reference and actor are required';
  END IF;
  IF p_reference_type NOT IN ('CUSTOMER_RECEIPT', 'SUPPLIER_PAYMENT') THEN
    RAISE EXCEPTION 'VOUCHER_GL_REFERENCE_TYPE_INVALID';
  END IF;
  IF p_amount IS NULL OR round(p_amount, 2) <= 0 THEN
    RAISE EXCEPTION 'VOUCHER_AMOUNT_INVALID: amount must be positive';
  END IF;
  IF p_debit_account_id = p_credit_account_id THEN
    RAISE EXCEPTION 'VOUCHER_GL_SAME_ACCOUNT_FORBIDDEN';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.gl_accounts a
    WHERE a.id = p_debit_account_id AND a.org_id = p_org
      AND coalesce(a.is_active, true) AND coalesce(a.allow_posting, true)
  ) OR NOT EXISTS (
    SELECT 1 FROM public.gl_accounts a
    WHERE a.id = p_credit_account_id AND a.org_id = p_org
      AND coalesce(a.is_active, true) AND coalesce(a.allow_posting, true)
  ) THEN
    RAISE EXCEPTION 'VOUCHER_GL_ACCOUNT_INVALID: legal posting accounts must belong to the voucher organization';
  END IF;

  PERFORM public.assert_period_open(p_org, coalesce(p_entry_date, current_date));

  SELECT e.id, e.status
  INTO v_entry_id, v_existing_status
  FROM public.gl_entries e
  WHERE e.org_id = p_org AND e.idempotency_key = v_idempotency_key
  FOR UPDATE;

  IF v_entry_id IS NOT NULL AND v_existing_status = 'posted' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.gl_entries e
      WHERE e.id = v_entry_id
        AND e.org_id = p_org
        AND e.reference_type = p_reference_type
        AND e.reference_id = p_reference_id
        AND e.reference_number IS NOT DISTINCT FROM p_reference_number
        AND e.entry_date = coalesce(p_entry_date, current_date)
        AND round(e.total_debit, 2) = round(p_amount, 2)
        AND round(e.total_credit, 2) = round(p_amount, 2)
        AND (
          SELECT count(*)
          FROM public.gl_entry_lines l
          WHERE l.entry_id = e.id AND l.org_id = p_org
            AND (
              (l.account_id = p_debit_account_id AND round(l.debit,2) = round(p_amount,2) AND l.credit = 0)
              OR
              (l.account_id = p_credit_account_id AND l.debit = 0 AND round(l.credit,2) = round(p_amount,2))
            )
        ) = 2
    ) THEN
      RAISE EXCEPTION 'VOUCHER_GL_IDEMPOTENCY_CONFLICT: existing posted entry does not match voucher contract';
    END IF;
    RETURN v_entry_id;
  END IF;

  IF v_entry_id IS NOT NULL AND v_existing_status <> 'draft' THEN
    RAISE EXCEPTION 'VOUCHER_GL_STATE_CONFLICT: existing entry status=%', v_existing_status;
  END IF;

  IF v_entry_id IS NULL THEN
    SELECT j.id INTO v_journal_id
    FROM public.journals j
    WHERE j.org_id = p_org AND coalesce(j.is_active, true)
    ORDER BY CASE WHEN j.journal_type IN ('cash','bank') THEN 0 ELSE 1 END,
             j.created_at NULLS LAST, j.id
    LIMIT 1;
    IF v_journal_id IS NULL THEN
      RAISE EXCEPTION 'VOUCHER_JOURNAL_REQUIRED: an active journal is required';
    END IF;

    v_entry_number := 'PV-' || to_char(coalesce(p_entry_date, current_date), 'YYYYMMDD') || '-' ||
                      substr(replace(gen_random_uuid()::text, '-', ''), 1, 12);

    INSERT INTO public.gl_entries (
      org_id, journal_id, entry_number, entry_date, entry_type,
      reference_type, reference_id, reference_number,
      description, description_ar, status, total_debit, total_credit,
      idempotency_key, created_by
    ) VALUES (
      p_org, v_journal_id, v_entry_number, coalesce(p_entry_date, current_date), 'manual',
      p_reference_type, p_reference_id, p_reference_number,
      p_description, p_description, 'draft', round(p_amount,2), round(p_amount,2),
      v_idempotency_key, p_actor
    ) RETURNING id INTO v_entry_id;
  ELSE
    DELETE FROM public.gl_entry_lines
    WHERE entry_id = v_entry_id AND org_id = p_org;

    UPDATE public.gl_entries
    SET entry_date = coalesce(p_entry_date, current_date),
        reference_type = p_reference_type,
        reference_id = p_reference_id,
        reference_number = p_reference_number,
        description = p_description,
        description_ar = p_description,
        total_debit = round(p_amount,2),
        total_credit = round(p_amount,2),
        posted_at = NULL,
        posted_by = NULL,
        updated_at = now()
    WHERE id = v_entry_id AND org_id = p_org AND status = 'draft';
    IF NOT FOUND THEN RAISE EXCEPTION 'VOUCHER_GL_DRAFT_CHANGED'; END IF;
  END IF;

  INSERT INTO public.gl_entry_lines (
    org_id, tenant_id, entry_id, line_number, account_id,
    debit, credit, currency_code, description, description_ar
  ) VALUES
    (p_org, p_org, v_entry_id, 1, p_debit_account_id,
     round(p_amount,2), 0, 'SAR', p_description, p_description),
    (p_org, p_org, v_entry_id, 2, p_credit_account_id,
     0, round(p_amount,2), 'SAR', p_description, p_description);

  UPDATE public.gl_entries
  SET status = 'posted', posted_at = now(), posted_by = p_actor, updated_at = now()
  WHERE id = v_entry_id AND org_id = p_org AND status = 'draft';
  IF NOT FOUND THEN RAISE EXCEPTION 'VOUCHER_GL_POST_STATE_CHANGED'; END IF;

  RETURN v_entry_id;
END
$$;


--
-- Name: wardah_guard_allocation_immutability(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_guard_allocation_immutability() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RAISE EXCEPTION
    'AP_ALLOCATION_IMMUTABLE: دفتر التخصيصات append-only — العكس يكون بصف جديد يشير إلى أصله، لا بتعديل أو حذف (العملية: %)',
    TG_OP;
END $$;


--
-- Name: wardah_guard_mapped_product_uom_stock_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_guard_mapped_product_uom_stock_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row jsonb := to_jsonb(NEW);
  v_org uuid;
  v_product uuid;
  v_warehouse uuid;
  v_adjustment uuid;
  v_enabled boolean := false;
BEGIN
  v_org := COALESCE(
    NULLIF(v_row ->> 'org_id', '')::uuid,
    NULLIF(v_row ->> 'organization_id', '')::uuid
  );
  v_product := NULLIF(v_row ->> 'product_id', '')::uuid;
  v_warehouse := NULLIF(v_row ->> 'warehouse_id', '')::uuid;
  v_adjustment := NULLIF(v_row ->> 'adjustment_id', '')::uuid;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'ORG_CONTEXT_REQUIRED: table=%', TG_TABLE_NAME;
  END IF;

  IF TG_TABLE_NAME = 'stock_adjustment_items' THEN
    IF v_adjustment IS NULL OR NOT EXISTS (
      SELECT 1
      FROM public.stock_adjustments sa
      WHERE sa.id = v_adjustment
        AND COALESCE(sa.org_id, sa.organization_id) = v_org
        AND sa.organization_id = v_org
    ) THEN
      RAISE EXCEPTION
        'ADJUSTMENT_ORG_MISMATCH: adjustment=%, org=%',
        v_adjustment, v_org;
    END IF;
  END IF;

  IF v_warehouse IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.warehouses w
    WHERE w.id = v_warehouse
      AND w.org_id = v_org
  ) THEN
    RAISE EXCEPTION
      'WAREHOUSE_NOT_FOUND_OR_WRONG_ORG: table=%, warehouse=%, org=%',
      TG_TABLE_NAME, v_warehouse, v_org;
  END IF;

  SELECT CASE
    WHEN jsonb_typeof(os.value -> 'enabled') = 'boolean'
      THEN (os.value ->> 'enabled')::boolean
    WHEN lower(COALESCE(os.value ->> 'enabled', '')) IN ('true', 'false')
      THEN (os.value ->> 'enabled')::boolean
    ELSE false
  END
  INTO v_enabled
  FROM public.org_settings os
  WHERE os.org_id = v_org
    AND os.key = 'uom_engine_enabled'
  LIMIT 1;

  IF NOT COALESCE(v_enabled, false) THEN
    RETURN NEW;
  END IF;

  PERFORM public.wardah_assert_org_member(v_org);

  IF v_product IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.products p
    JOIN public.uoms u
      ON u.id = p.base_uom_id
    WHERE p.id = v_product
      AND p.org_id = v_org
      AND p.uom_migration_status = 'MAPPED'
      AND u.is_active
      AND NOT u.is_product_specific
      AND (u.org_id IS NULL OR u.org_id = v_org)
  ) THEN
    RAISE EXCEPTION
      'PRODUCT_UOM_NOT_MAPPED: table=%, product=%, org=%',
      TG_TABLE_NAME, v_product, v_org;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: wardah_guard_products_base_uom_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_guard_products_base_uom_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_is_product_specific boolean;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.base_uom_id IS NULL THEN
      IF NEW.uom_migration_status = 'MAPPED' THEN
        RAISE EXCEPTION 'PRODUCT_BASE_UOM_REQUIRED: product=%', NEW.id;
      END IF;
      RETURN NEW;
    END IF;

    IF auth.uid() IS NOT NULL THEN
      PERFORM public.wardah_assert_org_admin(NEW.org_id);
    END IF;
  ELSE
    IF NEW.base_uom_id IS NOT DISTINCT FROM OLD.base_uom_id THEN
      RETURN NEW;
    END IF;

    PERFORM public.wardah_assert_org_admin(NEW.org_id);

    IF OLD.base_uom_id IS NOT NULL THEN
      RAISE EXCEPTION
        'PRODUCT_BASE_UOM_CHANGE_REQUIRES_ATOMIC_REMAP: product=%, current=%, requested=%',
        NEW.id, OLD.base_uom_id, NEW.base_uom_id;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.stock_ledger_entries sle
      WHERE sle.product_id = NEW.id
        AND sle.org_id = NEW.org_id
    ) THEN
      RAISE EXCEPTION 'PRODUCT_BASE_UOM_LOCKED_HAS_MOVEMENTS: product=%', NEW.id;
    END IF;
  END IF;

  IF NEW.base_uom_id IS NULL THEN
    RAISE EXCEPTION 'PRODUCT_BASE_UOM_REQUIRED: product=%', NEW.id;
  END IF;

  SELECT u.is_product_specific
  INTO v_is_product_specific
  FROM public.uoms u
  WHERE u.id = NEW.base_uom_id
    AND u.is_active
    AND (u.org_id IS NULL OR u.org_id = NEW.org_id);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PRODUCT_BASE_UOM_INVALID: product=%, uom=%', NEW.id, NEW.base_uom_id;
  END IF;
  IF v_is_product_specific THEN
    RAISE EXCEPTION 'PRODUCT_BASE_UOM_CANNOT_BE_PRODUCT_SPECIFIC: product=%', NEW.id;
  END IF;

  NEW.uom_migration_status := 'MAPPED';
  NEW.updated_at := v_now;

  UPDATE public.uom_backfill_issues
  SET status = 'RESOLVED',
      resolved_uom_id = NEW.base_uom_id,
      resolved_by = auth.uid(),
      resolved_at = v_now,
      details = COALESCE(details, '{}'::jsonb)
        || jsonb_build_object(
          'resolution',
          CASE WHEN TG_OP = 'INSERT'
            THEN 'validated_on_product_insert'
            ELSE 'auto_on_base_uom_assign'
          END
        )
  WHERE org_id = NEW.org_id
    AND source_table = 'products'
    AND source_id = NEW.id
    AND status = 'OPEN';

  RETURN NEW;
END;
$$;


--
-- Name: wardah_has_exact_permission(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_has_exact_permission(p_user_id uuid, p_org_id uuid, p_permission_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    EXISTS (
      SELECT 1
      FROM public.super_admins sa
      WHERE sa.user_id = p_user_id
        AND sa.is_active = true
    )
    OR (
      NOT COALESCE(public.wardah_is_sensitive_permission(p_permission_key), false)
      AND EXISTS (
        SELECT 1
        FROM public.user_organizations uo
        WHERE uo.user_id = p_user_id
          AND uo.org_id = p_org_id
          AND uo.is_active = true
          AND uo.is_org_admin = true
      )
    )
    OR EXISTS (
      SELECT 1
      FROM public.user_roles ur
      JOIN public.user_organizations uo
        ON uo.user_id = ur.user_id
       AND uo.org_id = ur.org_id
       AND uo.is_active IS TRUE
      JOIN public.roles r
        ON r.id = ur.role_id
       AND r.org_id = p_org_id
       AND COALESCE(r.is_active, true)
      JOIN public.role_permissions rp ON rp.role_id = ur.role_id
      JOIN public.permissions p ON p.id = rp.permission_id
      WHERE ur.user_id = p_user_id
        AND ur.org_id = p_org_id
        AND p.permission_key = p_permission_key
        AND (ur.expires_at IS NULL OR ur.expires_at > now())
    );
$$;


--
-- Name: wardah_is_org_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_is_org_admin(p_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_organizations
    WHERE user_id = auth.uid()
      AND org_id = p_org
      AND is_active IS TRUE
      AND (COALESCE(is_org_admin, FALSE) OR role IN ('admin', 'owner'))
  );
$$;


--
-- Name: wardah_is_org_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_is_org_member(p_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT auth.uid() IS NOT NULL
       AND p_org IS NOT NULL
       AND EXISTS (
            SELECT 1 FROM public.user_organizations
            WHERE user_id = auth.uid() AND org_id = p_org AND COALESCE(is_active, TRUE)
       );
$$;


--
-- Name: wardah_is_sensitive_permission(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_is_sensitive_permission(p_permission_key text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT p_permission_key IN (
    'accounting.vouchers.unpost',
    'accounting.vouchers.cancel',
    'accounting.journals.reverse'
  );
$$;


--
-- Name: wardah_next_voucher_number(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_next_voucher_number(p_org uuid, p_kind text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_prefix text;
  v_period text := to_char(current_date, 'YYYYMM');
  v_stem text;
  v_seq integer;
BEGIN
  IF p_org IS NULL THEN
    RAISE EXCEPTION 'VOUCHER_NUMBER_SCOPE_REQUIRED';
  END IF;

  IF p_kind = 'CUSTOMER_RECEIPT' THEN
    v_prefix := 'CR-';
  ELSIF p_kind = 'SUPPLIER_PAYMENT' THEN
    v_prefix := 'SP-';
  ELSE
    RAISE EXCEPTION 'VOUCHER_NUMBER_KIND_INVALID: %', p_kind;
  END IF;

  v_stem := v_prefix || v_period || '-';
  PERFORM pg_advisory_xact_lock(hashtext(p_org::text || ':' || p_kind || ':' || v_period));

  IF p_kind = 'CUSTOMER_RECEIPT' THEN
    SELECT coalesce(max(substr(c.collection_number, length(v_stem) + 1)::integer), 0)
    INTO v_seq
    FROM public.customer_collections c
    WHERE c.org_id = p_org
      AND c.collection_number ~ ('^' || v_stem || '[0-9]+$');
  ELSE
    SELECT coalesce(max(substr(p.payment_number, length(v_stem) + 1)::integer), 0)
    INTO v_seq
    FROM public.supplier_payments p
    WHERE p.org_id = p_org
      AND p.payment_number ~ ('^' || v_stem || '[0-9]+$');
  END IF;

  RETURN v_stem || lpad((v_seq + 1)::text, 5, '0');
END
$_$;


--
-- Name: wardah_org_id(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_org_id(p_explicit uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_org uuid;
BEGIN
    IF p_explicit IS NOT NULL THEN
        IF public.wardah_is_org_member(p_explicit) THEN RETURN p_explicit; END IF;
        RETURN NULL;
    END IF;
    BEGIN v_org := public.get_current_tenant_id();
    EXCEPTION WHEN OTHERS THEN v_org := NULL; END;
    RETURN v_org;
END;
$$;


--
-- Name: wardah_periods_org_col(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_periods_org_col() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
    SELECT CASE
        WHEN EXISTS (
            SELECT 1 FROM information_schema.columns
            WHERE table_schema = 'public' AND table_name = 'accounting_periods'
              AND column_name = 'org_id'
        ) THEN 'org_id'
        WHEN EXISTS (
            SELECT 1 FROM information_schema.columns
            WHERE table_schema = 'public' AND table_name = 'accounting_periods'
              AND column_name = 'tenant_id'
        ) THEN 'tenant_id'
        ELSE NULL
    END;
$$;


--
-- Name: wardah_protect_invoice_payment_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_protect_invoice_payment_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_payment_change boolean;
BEGIN
  IF TG_TABLE_NAME = 'sales_invoices' THEN
    v_payment_change := NEW.paid_amount IS DISTINCT FROM OLD.paid_amount
      OR NEW.payment_status IS DISTINCT FROM OLD.payment_status;
  ELSE
    v_payment_change := NEW.paid_amount IS DISTINCT FROM OLD.paid_amount
      OR (
        NEW.status IS DISTINCT FROM OLD.status
        AND (
          OLD.status IN ('partially_paid', 'paid')
          OR NEW.status IN ('partially_paid', 'paid')
        )
      );
  END IF;

  IF v_payment_change
     AND NOT public.wardah_voucher_write_is_trusted('wardah.voucher_invoice_payment_write') THEN
    RAISE EXCEPTION 'VOUCHER_DERIVED_PAYMENT_FIELDS_WRITE_FORBIDDEN: table=%', TG_TABLE_NAME;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: wardah_protect_voucher_allocation_lines(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_protect_voucher_allocation_lines() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.wardah_voucher_write_is_trusted('wardah.voucher_lines_write') THEN
    RAISE EXCEPTION 'VOUCHER_ALLOCATION_DIRECT_MUTATION_FORBIDDEN: operation=% table=%',
      TG_OP, TG_TABLE_NAME;
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;


--
-- Name: wardah_protect_voucher_headers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_protect_voucher_headers() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.wardah_voucher_write_is_trusted('wardah.voucher_header_write') THEN
    RAISE EXCEPTION 'VOUCHER_HEADER_WRITE_FORBIDDEN: operation=% table=%', TG_OP, TG_TABLE_NAME;
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;


--
-- Name: wardah_receipt_line_uninvoiced_base(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_receipt_line_uninvoiced_base(p_goods_receipt_line_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org             uuid;
  v_accepted_base   numeric(18,6);
  v_allocated_base  numeric(18,6);
BEGIN
  SELECT gr.org_id,
         CASE WHEN grl.quality_status = 'accepted'
              THEN COALESCE(grl.received_quantity,0)
              ELSE 0 END
    INTO v_org, v_accepted_base
  FROM public.goods_receipt_lines grl
  JOIN public.goods_receipts gr ON gr.id = grl.goods_receipt_id
  WHERE grl.id = p_goods_receipt_line_id;

  IF v_org IS NULL THEN
    RAISE EXCEPTION
      'AP_GRN_LINE_NOT_FOUND: سطر استلام غير موجود (%)',
      p_goods_receipt_line_id;
  END IF;

  PERFORM public.wardah_assert_org_member(v_org);

  SELECT COALESCE(SUM(
           CASE WHEN a.reversal_of_allocation_id IS NULL
                THEN a.quantity_base
                ELSE -a.quantity_base
           END),0)
    INTO v_allocated_base
  FROM public.supplier_invoice_receipt_allocations a
  WHERE a.org_id = v_org
    AND a.goods_receipt_line_id = p_goods_receipt_line_id;

  RETURN v_accepted_base - v_allocated_base;
END $$;


--
-- Name: wardah_require_positive_bom_quantity(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_require_positive_bom_quantity(p_bom_id uuid, p_quantity numeric) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    RAISE EXCEPTION 'BOM_CHILD_QUANTITY_INVALID: bom_id=%, quantity=%', p_bom_id, p_quantity;
  END IF;
  RETURN p_quantity;
END;
$$;


--
-- Name: wardah_resolve_product_id(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_resolve_product_id(p_org uuid, p_item_or_product uuid, p_at timestamp with time zone DEFAULT now()) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_product uuid;
BEGIN
  IF p_org IS NULL OR p_item_or_product IS NULL THEN RAISE EXCEPTION 'ITEM_PRODUCT_CONTEXT_REQUIRED'; END IF;

  SELECT m.product_id INTO v_product
  FROM public.item_product_map m
  WHERE m.org_id=p_org AND m.item_id=p_item_or_product AND m.is_active
    AND m.valid_from<=COALESCE(p_at,now()) AND (m.valid_to IS NULL OR m.valid_to>COALESCE(p_at,now()))
  ORDER BY m.valid_from DESC LIMIT 1;
  IF FOUND THEN RETURN v_product; END IF;

  -- Compatibility is accepted only when the supplied UUID is a real product in the same org.
  SELECT p.id INTO v_product FROM public.products p
  WHERE p.id=p_item_or_product AND p.org_id=p_org;
  IF FOUND THEN RETURN v_product; END IF;

  RAISE EXCEPTION 'ITEM_PRODUCT_MAP_MISSING: org=%, item=%',p_org,p_item_or_product;
END;
$$;


--
-- Name: wardah_settlement_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_settlement_snapshot(p_settlement_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT jsonb_build_object(
        'employee_id',       s.employee_id,
        'settlement_type',   s.settlement_type,
        'termination_type',  s.termination_type,
        'payable_amount',    ROUND(COALESCE(s.payable_amount, 0), 2),
        'calculated_amount', ROUND(COALESCE(s.calculated_amount, 0), 2),
        'service_start',     s.service_start,
        'service_end',       s.service_end,
        'notes',             s.notes,
        'lines', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                       'component_code', l.component_code,
                       'amount', ROUND(l.amount, 2),
                       'is_deduction', l.is_deduction)
                   ORDER BY l.component_code, l.amount)
            FROM hr_settlement_lines l
            WHERE l.settlement_id = s.id), '[]'::jsonb))
    FROM hr_settlements s
    WHERE s.id = p_settlement_id;
$$;


--
-- Name: wardah_sync_gl_line_legal_to_legacy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_sync_gl_line_legal_to_legacy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_code text;
  v_name text;
  v_name_en text;
  v_name_ar text;
  v_legacy_max constant numeric := 9999999999.99;
BEGIN
  IF NEW.org_id IS NULL OR NEW.entry_id IS NULL THEN
    RAISE EXCEPTION 'GL_LEGAL_SCOPE_REQUIRED: org_id and entry_id are required';
  END IF;
  IF NEW.tenant_id IS NOT NULL AND NEW.tenant_id <> NEW.org_id THEN
    RAISE EXCEPTION 'GL_CROSS_ORG_TENANT_ALIAS: tenant_id must equal org_id';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.gl_entries e
    WHERE e.id = NEW.entry_id AND e.org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'GL_CROSS_ORG_ENTRY: entry_id does not belong to org_id';
  END IF;
  NEW.debit := coalesce(NEW.debit, 0);
  NEW.credit := coalesce(NEW.credit, 0);
  IF NEW.debit < 0 OR NEW.credit < 0 THEN
    RAISE EXCEPTION 'GL_NEGATIVE_LEGAL_AMOUNT: debit/credit cannot be negative';
  END IF;
  IF NEW.debit > 0 AND NEW.credit > 0 THEN
    RAISE EXCEPTION 'GL_DOUBLE_SIDED_LEGAL_AMOUNT: debit and credit cannot both be positive';
  END IF;
  IF NEW.debit = 0 AND NEW.credit = 0 THEN
    RAISE EXCEPTION 'GL_ZERO_LEGAL_LINE: a legal GL line must carry value';
  END IF;
  IF NEW.account_id IS NULL THEN
    RAISE EXCEPTION 'GL_LEGAL_ACCOUNT_REQUIRED: new writes require account_id';
  END IF;
  SELECT a.code, a.name, a.name_en, a.name_ar
  INTO v_code, v_name, v_name_en, v_name_ar
  FROM public.gl_accounts a
  WHERE a.id = NEW.account_id AND a.org_id = NEW.org_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'GL_ACCOUNT_NOT_FOUND_OR_CROSS_ORG: account_id is not a gl_account in org_id';
  END IF;
  IF NEW.account_code IS NOT NULL AND NEW.account_code <> v_code THEN
    RAISE EXCEPTION 'GL_ACCOUNT_CODE_CONFLICT: supplied account_code does not match account_id';
  END IF;
  IF coalesce(NEW.debit_amount,0) <> 0 OR coalesce(NEW.credit_amount,0) <> 0 THEN
    IF round(coalesce(NEW.debit_amount,0),2) IS DISTINCT FROM round(NEW.debit,2)
       OR round(coalesce(NEW.credit_amount,0),2) IS DISTINCT FROM round(NEW.credit,2) THEN
      RAISE EXCEPTION 'GL_LEGACY_AMOUNT_WRITE_REJECTED: debit/credit are the only legal input amounts';
    END IF;
  END IF;
  IF NEW.debit > v_legacy_max OR NEW.credit > v_legacy_max THEN
    RAISE EXCEPTION 'GL_LEGACY_COMPAT_RANGE_EXCEEDED: temporary numeric(12,2) legacy mirror cannot represent legal amount';
  END IF;
  NEW.account_code := v_code;
  NEW.account_name := coalesce(v_name_en, v_name);
  NEW.account_name_ar := coalesce(v_name_ar, v_name);
  NEW.debit_amount := NEW.debit;
  NEW.credit_amount := NEW.credit;
  NEW.tenant_id := coalesce(NEW.tenant_id, NEW.org_id);
  RETURN NEW;
END
$$;


