CREATE FUNCTION public.wardah_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    NEW.updated_at := NOW();
    RETURN NEW;
END;
$$;


--
-- Name: wardah_uom_cost_to_base(uuid, uuid, numeric, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_uom_cost_to_base(p_org uuid, p_product uuid, p_unit_cost_entered numeric, p_uom uuid, p_at timestamp with time zone DEFAULT now()) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_factor numeric;
BEGIN
  IF p_unit_cost_entered IS NULL OR p_unit_cost_entered<0 THEN RAISE EXCEPTION 'UOM_UNIT_COST_MUST_BE_NONNEGATIVE'; END IF;
  v_factor:=public.wardah_uom_factor(p_org,p_product,p_uom,p_at);
  RETURN round(p_unit_cost_entered/v_factor,6);
END;
$$;


--
-- Name: wardah_uom_factor(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_uom_factor(p_org uuid, p_product uuid, p_uom uuid, p_at timestamp with time zone DEFAULT now()) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_product_org uuid; v_base_uom uuid; v_base_category uuid;
  v_base_factor numeric; v_base_product_specific boolean;
  v_target_category uuid; v_target_factor numeric; v_target_product_specific boolean;
  v_product_factor numeric; v_allow_cross boolean;
BEGIN
  IF p_org IS NULL OR p_product IS NULL THEN RAISE EXCEPTION 'UOM_INVALID_PRODUCT_CONTEXT'; END IF;
  SELECT p.org_id,p.base_uom_id INTO v_product_org,v_base_uom
  FROM public.products p WHERE p.id=p_product;
  IF NOT FOUND OR v_product_org IS DISTINCT FROM p_org THEN RAISE EXCEPTION 'UOM_PRODUCT_NOT_FOUND_OR_WRONG_ORG'; END IF;
  IF v_base_uom IS NULL THEN RAISE EXCEPTION 'PRODUCT_BASE_UOM_REQUIRED: product=%',p_product; END IF;
  IF p_uom IS NULL OR p_uom=v_base_uom THEN RETURN 1; END IF;

  SELECT u.category_id,u.factor_to_category_base,u.is_product_specific
  INTO v_base_category,v_base_factor,v_base_product_specific
  FROM public.uoms u
  WHERE u.id=v_base_uom AND u.is_active AND (u.org_id IS NULL OR u.org_id=p_org);
  IF NOT FOUND THEN RAISE EXCEPTION 'PRODUCT_BASE_UOM_INVALID_OR_WRONG_ORG: product=%',p_product; END IF;
  IF v_base_product_specific THEN RAISE EXCEPTION 'PRODUCT_BASE_UOM_CANNOT_BE_PRODUCT_SPECIFIC'; END IF;

  SELECT u.category_id,u.factor_to_category_base,u.is_product_specific
  INTO v_target_category,v_target_factor,v_target_product_specific
  FROM public.uoms u
  WHERE u.id=p_uom AND u.is_active AND (u.org_id IS NULL OR u.org_id=p_org);
  IF NOT FOUND THEN RAISE EXCEPTION 'UOM_NOT_FOUND_IN_ORG_OR_INACTIVE: uom=%',p_uom; END IF;

  SELECT c.factor_to_base,c.allow_cross_dimension
  INTO v_product_factor,v_allow_cross
  FROM public.product_uom_conversions c
  WHERE c.org_id=p_org AND c.product_id=p_product AND c.uom_id=p_uom AND c.is_active
    AND c.valid_from<=COALESCE(p_at,now())
    AND (c.valid_to IS NULL OR c.valid_to>COALESCE(p_at,now()))
  ORDER BY c.valid_from DESC,c.created_at DESC LIMIT 1;
  IF FOUND THEN
    IF v_product_factor<=0 THEN RAISE EXCEPTION 'UOM_FACTOR_MUST_BE_POSITIVE'; END IF;
    IF v_target_category<>v_base_category AND NOT v_allow_cross THEN RAISE EXCEPTION 'UOM_CROSS_DIMENSION_NOT_ALLOWED'; END IF;
    RETURN v_product_factor;
  END IF;

  IF v_target_category<>v_base_category THEN RAISE EXCEPTION 'UOM_CATEGORY_MISMATCH'; END IF;
  IF v_target_product_specific THEN RAISE EXCEPTION 'PRODUCT_UOM_CONVERSION_MISSING: product=%, uom=%',p_product,p_uom; END IF;
  IF v_target_factor IS NULL OR v_base_factor IS NULL OR v_target_factor<=0 OR v_base_factor<=0 THEN RAISE EXCEPTION 'STANDARD_UOM_FACTOR_INVALID'; END IF;
  RETURN v_target_factor/v_base_factor;
END;
$$;


--
-- Name: wardah_uom_to_base(uuid, uuid, numeric, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_uom_to_base(p_org uuid, p_product uuid, p_quantity numeric, p_uom uuid, p_at timestamp with time zone DEFAULT now()) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_factor numeric;
BEGIN
  IF p_quantity IS NULL OR p_quantity<0 THEN RAISE EXCEPTION 'UOM_QUANTITY_MUST_BE_NONNEGATIVE'; END IF;
  v_factor:=public.wardah_uom_factor(p_org,p_product,p_uom,p_at);
  RETURN round(p_quantity*v_factor,6);
END;
$$;


--
-- Name: wardah_validate_voucher_payment_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_validate_voucher_payment_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_subtype text;
  v_expected text[];
BEGIN
  IF NEW.org_id IS NULL OR NEW.payment_account_id IS NULL THEN
    RAISE EXCEPTION 'VOUCHER_PAYMENT_ACCOUNT_REQUIRED';
  END IF;

  SELECT a.subtype
  INTO v_subtype
  FROM public.gl_accounts a
  WHERE a.id = NEW.payment_account_id
    AND a.org_id = NEW.org_id
    AND coalesce(a.is_active, true)
    AND coalesce(a.allow_posting, true);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'VOUCHER_PAYMENT_ACCOUNT_INVALID_OR_CROSS_ORG';
  END IF;

  IF TG_TABLE_NAME = 'customer_collections' THEN
    v_expected := CASE
      WHEN NEW.payment_method IN ('cash', 'check') THEN ARRAY['CASH']::text[]
      WHEN NEW.payment_method = 'other' THEN ARRAY['CASH', 'BANK']::text[]
      ELSE ARRAY['BANK']::text[]
    END;
  ELSE
    v_expected := CASE
      WHEN NEW.payment_method = 'cash' THEN ARRAY['CASH']::text[]
      WHEN NEW.payment_method = 'other' THEN ARRAY['CASH', 'BANK']::text[]
      ELSE ARRAY['BANK']::text[]
    END;
  END IF;

  IF NOT (v_subtype = ANY(v_expected)) THEN
    RAISE EXCEPTION 'VOUCHER_PAYMENT_ACCOUNT_METHOD_MISMATCH: method=% account_subtype=% expected=%',
      NEW.payment_method, v_subtype, array_to_string(v_expected, ',');
  END IF;

  RETURN NEW;
END
$$;


--
-- Name: wardah_voucher_write_is_trusted(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wardah_voucher_write_is_trusted(p_capability text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT current_user = pg_get_userbyid(
       (SELECT p.proowner
        FROM pg_proc p
        WHERE p.oid = 'public.wardah_voucher_write_is_trusted(text)'::regprocedure)
     )
     AND (
       coalesce(current_setting(p_capability, true), '') = 'on'
       OR session_user = current_user
     );
$$;


