--
-- Name: bom_cost_analysis; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bom_cost_analysis (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    bom_id uuid NOT NULL,
    analysis_date date DEFAULT CURRENT_DATE NOT NULL,
    quantity numeric(18,6) DEFAULT 1 NOT NULL,
    standard_material_cost numeric(18,4) DEFAULT 0,
    standard_labor_cost numeric(18,4) DEFAULT 0,
    standard_overhead_cost numeric(18,4) DEFAULT 0,
    standard_total_cost numeric(18,4) DEFAULT 0,
    standard_unit_cost numeric(18,6) DEFAULT 0,
    actual_material_cost numeric(18,4) DEFAULT 0,
    actual_labor_cost numeric(18,4) DEFAULT 0,
    actual_overhead_cost numeric(18,4) DEFAULT 0,
    actual_total_cost numeric(18,4) DEFAULT 0,
    actual_unit_cost numeric(18,6) DEFAULT 0,
    material_variance numeric(18,4) GENERATED ALWAYS AS ((actual_material_cost - standard_material_cost)) STORED,
    labor_variance numeric(18,4) GENERATED ALWAYS AS ((actual_labor_cost - standard_labor_cost)) STORED,
    overhead_variance numeric(18,4) GENERATED ALWAYS AS ((actual_overhead_cost - standard_overhead_cost)) STORED,
    total_variance numeric(18,4) GENERATED ALWAYS AS ((actual_total_cost - standard_total_cost)) STORED,
    material_variance_pct numeric(5,2) GENERATED ALWAYS AS (
CASE
    WHEN (standard_material_cost > (0)::numeric) THEN (((actual_material_cost - standard_material_cost) / standard_material_cost) * (100)::numeric)
    ELSE (0)::numeric
END) STORED,
    labor_variance_pct numeric(5,2) GENERATED ALWAYS AS (
CASE
    WHEN (standard_labor_cost > (0)::numeric) THEN (((actual_labor_cost - standard_labor_cost) / standard_labor_cost) * (100)::numeric)
    ELSE (0)::numeric
END) STORED,
    status character varying(20) DEFAULT 'DRAFT'::character varying,
    notes text,
    org_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now(),
    updated_by uuid,
    CONSTRAINT bom_cost_analysis_status_check CHECK (((status)::text = ANY (ARRAY[('DRAFT'::character varying)::text, ('APPROVED'::character varying)::text, ('ARCHIVED'::character varying)::text])))
);


