    total_cost_per_unit numeric(18,4) GENERATED ALWAYS AS ((((setup_time_minutes / 60.0) * COALESCE(labor_rate, (0)::numeric)) + ((run_time_minutes / 60.0) * COALESCE(labor_rate, (0)::numeric)))) STORED,
    tooling_required text,
