    CONSTRAINT bom_operations_machine_rate_check CHECK ((machine_rate >= (0)::numeric)),
    CONSTRAINT bom_operations_move_time_minutes_check CHECK ((move_time_minutes >= (0)::numeric)),
    CONSTRAINT bom_operations_overhead_rate_check CHECK ((overhead_rate >= (0)::numeric)),
    CONSTRAINT bom_operations_queue_time_minutes_check CHECK ((queue_time_minutes >= (0)::numeric)),
    CONSTRAINT bom_operations_run_time_minutes_check CHECK ((run_time_minutes >= (0)::numeric)),
    CONSTRAINT bom_operations_setup_time_minutes_check CHECK ((setup_time_minutes >= (0)::numeric))
);


