--
-- Name: stage_costs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.stage_costs (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    org_id uuid NOT NULL,
    manufacturing_order_id uuid NOT NULL,
    stage_number integer NOT NULL,
    work_center_id uuid,
    input_qty numeric(18,6) DEFAULT 0,
    good_qty numeric(18,6) DEFAULT 0,
    scrap_qty numeric(18,6) DEFAULT 0,
    rework_qty numeric(18,6) DEFAULT 0,
    transferred_in numeric(18,6) DEFAULT 0,
    dm_cost numeric(18,6) DEFAULT 0,
    dl_cost numeric(18,6) DEFAULT 0,
    moh_cost numeric(18,6) DEFAULT 0,
    regrind_proc_cost numeric(18,6) DEFAULT 0,
    waste_credit numeric(18,6) DEFAULT 0,
    total_cost numeric(18,6) DEFAULT 0,
    unit_cost numeric(18,6) DEFAULT 0,
    mode text DEFAULT 'precosted'::text,
    is_final boolean DEFAULT false,
    notes text,
    batch_id text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    created_by uuid,
    updated_by uuid,
    wip_end_qty numeric(18,6) DEFAULT 0,
    wip_end_dm_completion_pct numeric(5,2) DEFAULT 0,
    wip_end_cc_completion_pct numeric(5,2) DEFAULT 0,
    wip_beginning_qty numeric(18,6) DEFAULT 0,
    wip_beginning_dm_completion_pct numeric(5,2) DEFAULT 0,
    wip_beginning_cc_completion_pct numeric(5,2) DEFAULT 0,
    normal_scrap_qty numeric(18,6) DEFAULT 0,
    abnormal_scrap_qty numeric(18,6) DEFAULT 0,
    normal_scrap_cost numeric(18,6) DEFAULT 0,
    abnormal_scrap_cost numeric(18,6) DEFAULT 0,
    regrind_cost numeric(18,6) DEFAULT 0,
    waste_credit_amount numeric(18,6) DEFAULT 0,
    wip_beginning_cost numeric(18,6) DEFAULT 0,
    current_period_cost numeric(18,6) DEFAULT 0,
    CONSTRAINT stage_costs_abnormal_scrap_cost_check CHECK ((abnormal_scrap_cost >= (0)::numeric)),
    CONSTRAINT stage_costs_abnormal_scrap_qty_check CHECK ((abnormal_scrap_qty >= (0)::numeric)),
    CONSTRAINT stage_costs_current_period_cost_check CHECK ((current_period_cost >= (0)::numeric)),
    CONSTRAINT stage_costs_good_qty_check CHECK ((good_qty >= (0)::numeric)),
    CONSTRAINT stage_costs_input_qty_check CHECK ((input_qty >= (0)::numeric)),
    CONSTRAINT stage_costs_mode_check CHECK ((mode = ANY (ARRAY['precosted'::text, 'actual'::text, 'completed'::text]))),
    CONSTRAINT stage_costs_normal_scrap_cost_check CHECK ((normal_scrap_cost >= (0)::numeric)),
    CONSTRAINT stage_costs_normal_scrap_qty_check CHECK ((normal_scrap_qty >= (0)::numeric)),
    CONSTRAINT stage_costs_regrind_cost_check CHECK ((regrind_cost >= (0)::numeric)),
    CONSTRAINT stage_costs_rework_qty_check CHECK ((rework_qty >= (0)::numeric)),
    CONSTRAINT stage_costs_scrap_qty_check CHECK ((scrap_qty >= (0)::numeric)),
    CONSTRAINT stage_costs_stage_number_check CHECK ((stage_number > 0)),
    CONSTRAINT stage_costs_waste_credit_amount_check CHECK ((waste_credit_amount >= (0)::numeric)),
    CONSTRAINT stage_costs_wip_beginning_cc_completion_pct_check CHECK (((wip_beginning_cc_completion_pct >= (0)::numeric) AND (wip_beginning_cc_completion_pct <= (100)::numeric))),
    CONSTRAINT stage_costs_wip_beginning_cost_check CHECK ((wip_beginning_cost >= (0)::numeric)),
    CONSTRAINT stage_costs_wip_beginning_dm_completion_pct_check CHECK (((wip_beginning_dm_completion_pct >= (0)::numeric) AND (wip_beginning_dm_completion_pct <= (100)::numeric))),
    CONSTRAINT stage_costs_wip_beginning_qty_check CHECK ((wip_beginning_qty >= (0)::numeric)),
    CONSTRAINT stage_costs_wip_end_cc_completion_pct_check CHECK (((wip_end_cc_completion_pct >= (0)::numeric) AND (wip_end_cc_completion_pct <= (100)::numeric))),
    CONSTRAINT stage_costs_wip_end_dm_completion_pct_check CHECK (((wip_end_dm_completion_pct >= (0)::numeric) AND (wip_end_dm_completion_pct <= (100)::numeric))),
    CONSTRAINT stage_costs_wip_end_qty_check CHECK ((wip_end_qty >= (0)::numeric))
);


--
-- Name: stage_wip_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.stage_wip_log (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    org_id uuid NOT NULL,
    mo_id uuid NOT NULL,
    stage_id uuid NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    units_beginning_wip numeric(18,6) DEFAULT 0,
    units_started numeric(18,6) DEFAULT 0,
    units_completed numeric(18,6) DEFAULT 0,
    units_ending_wip numeric(18,6) DEFAULT 0,
    units_transferred_out numeric(18,6) DEFAULT 0,
    units_transferred_in numeric(18,6) DEFAULT 0,
    material_completion_pct numeric(5,2) DEFAULT 100,
    conversion_completion_pct numeric(5,2) DEFAULT 100,
    cost_beginning_wip numeric(18,6) DEFAULT 0,
    cost_material numeric(18,6) DEFAULT 0,
    cost_labor numeric(18,6) DEFAULT 0,
    cost_overhead numeric(18,6) DEFAULT 0,
    cost_transferred_in numeric(18,6) DEFAULT 0,
    cost_total numeric(18,6) GENERATED ALWAYS AS (((((cost_beginning_wip + cost_material) + cost_labor) + cost_overhead) + cost_transferred_in)) STORED,
    equivalent_units_material numeric(18,6) DEFAULT 0,
    equivalent_units_conversion numeric(18,6) DEFAULT 0,
    cost_per_eu_material numeric(18,6) DEFAULT 0,
    cost_per_eu_conversion numeric(18,6) DEFAULT 0,
    cost_completed_transferred numeric(18,6) DEFAULT 0,
    cost_ending_wip numeric(18,6) DEFAULT 0,
    is_closed boolean DEFAULT false,
    closed_at timestamp with time zone,
    closed_by uuid,
    notes text,
    batch_number character varying(100),
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    created_by uuid,
    updated_by uuid,
    cost_beginning_wip_material numeric(18,6),
    cost_beginning_wip_conversion numeric(18,6),
    cost_beginning_wip_transferred_in numeric(18,6),
    equivalent_units_transferred_in numeric(18,6) DEFAULT 0,
    cost_per_eu_transferred_in numeric(18,6) DEFAULT 0,
    eu_calculation_version smallint DEFAULT 1,
    eu_calculation_note text,
    CONSTRAINT stage_wip_log_check CHECK ((period_start <= period_end)),
    CONSTRAINT stage_wip_log_check1 CHECK (((units_beginning_wip + units_started) = ((units_completed + units_ending_wip) + units_transferred_out))),
    CONSTRAINT stage_wip_log_conversion_completion_pct_check CHECK (((conversion_completion_pct >= (0)::numeric) AND (conversion_completion_pct <= (100)::numeric))),
    CONSTRAINT stage_wip_log_cost_completed_transferred_check CHECK ((cost_completed_transferred >= (0)::numeric)),
    CONSTRAINT stage_wip_log_cost_ending_wip_check CHECK ((cost_ending_wip >= (0)::numeric)),
    CONSTRAINT stage_wip_log_cost_labor_check CHECK ((cost_labor >= (0)::numeric)),
    CONSTRAINT stage_wip_log_cost_material_check CHECK ((cost_material >= (0)::numeric)),
    CONSTRAINT stage_wip_log_cost_overhead_check CHECK ((cost_overhead >= (0)::numeric)),
    CONSTRAINT stage_wip_log_cost_per_eu_conversion_check CHECK ((cost_per_eu_conversion >= (0)::numeric)),
    CONSTRAINT stage_wip_log_cost_per_eu_material_check CHECK ((cost_per_eu_material >= (0)::numeric)),
    CONSTRAINT stage_wip_log_cost_transferred_in_check CHECK ((cost_transferred_in >= (0)::numeric)),
    CONSTRAINT stage_wip_log_equivalent_units_conversion_check CHECK ((equivalent_units_conversion >= (0)::numeric)),
    CONSTRAINT stage_wip_log_equivalent_units_material_check CHECK ((equivalent_units_material >= (0)::numeric)),
    CONSTRAINT stage_wip_log_material_completion_pct_check CHECK (((material_completion_pct >= (0)::numeric) AND (material_completion_pct <= (100)::numeric))),
    CONSTRAINT stage_wip_log_units_beginning_wip_check CHECK ((units_beginning_wip >= (0)::numeric)),
    CONSTRAINT stage_wip_log_units_completed_check CHECK ((units_completed >= (0)::numeric)),
    CONSTRAINT stage_wip_log_units_ending_wip_check CHECK ((units_ending_wip >= (0)::numeric)),
    CONSTRAINT stage_wip_log_units_started_check CHECK ((units_started >= (0)::numeric)),
    CONSTRAINT stage_wip_log_units_transferred_in_check CHECK ((units_transferred_in >= (0)::numeric)),
    CONSTRAINT stage_wip_log_units_transferred_out_check CHECK ((units_transferred_out >= (0)::numeric))
);


--
-- Name: standard_costs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.standard_costs (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
