    material_cost_per_unit numeric(18,6) DEFAULT 0,
    labor_cost_per_unit numeric(18,6) DEFAULT 0,
    overhead_cost_per_unit numeric(18,6) DEFAULT 0,
    total_cost_per_unit numeric(18,6) GENERATED ALWAYS AS (((material_cost_per_unit + labor_cost_per_unit) + overhead_cost_per_unit)) STORED,
    standard_material_qty numeric(18,6) DEFAULT 0,
    standard_labor_hours numeric(8,2) DEFAULT 0,
    effective_from date NOT NULL,
    effective_to date,
    is_active boolean DEFAULT true,
    approved_by uuid,
    approved_at timestamp with time zone,
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    created_by uuid,
    updated_by uuid,
    CONSTRAINT standard_costs_check CHECK (((effective_to IS NULL) OR (effective_to >= effective_from))),
    CONSTRAINT standard_costs_labor_cost_per_unit_check CHECK ((labor_cost_per_unit >= (0)::numeric)),
    CONSTRAINT standard_costs_material_cost_per_unit_check CHECK ((material_cost_per_unit >= (0)::numeric)),
    CONSTRAINT standard_costs_overhead_cost_per_unit_check CHECK ((overhead_cost_per_unit >= (0)::numeric)),
    CONSTRAINT standard_costs_standard_labor_hours_check CHECK ((standard_labor_hours >= (0)::numeric)),
    CONSTRAINT standard_costs_standard_material_qty_check CHECK ((standard_material_qty >= (0)::numeric))
);


