--
-- Name: supplier_invoice_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_invoice_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    supplier_invoice_id uuid NOT NULL,
    goods_receipt_line_id uuid,
    line_number integer DEFAULT 1 NOT NULL,
    product_id uuid NOT NULL,
    description text,
    quantity numeric(18,6) NOT NULL,
    unit_cost numeric(12,4) NOT NULL,
    discount_percentage numeric(5,2) DEFAULT 0,
    tax_percentage numeric(5,2) DEFAULT 15,
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    line_total numeric(18,2) GENERATED ALWAYS AS ((((quantity * unit_cost) * ((1)::numeric - (discount_percentage / (100)::numeric))) * ((1)::numeric + (tax_percentage / (100)::numeric)))) STORED,
    purchase_order_line_id uuid,
    uom_id uuid,
    qty_entered numeric(18,6),
    conversion_factor_snapshot numeric(30,12),
    unit_cost_entered numeric(18,6),
    po_unit_price_snapshot numeric(18,6),
    quantity_variance numeric(18,6),
    price_variance numeric(18,6),
    match_status text,
    CONSTRAINT supplier_invoice_lines_discount_percentage_check CHECK (((discount_percentage >= (0)::numeric) AND (discount_percentage <= (100)::numeric))),
    CONSTRAINT supplier_invoice_lines_match_status_check CHECK (((match_status IS NULL) OR (match_status = 'matched'::text))),
    CONSTRAINT supplier_invoice_lines_quantity_check CHECK ((quantity > (0)::numeric)),
    CONSTRAINT supplier_invoice_lines_tax_percentage_check CHECK ((tax_percentage >= (0)::numeric)),
    CONSTRAINT supplier_invoice_lines_unit_cost_check CHECK ((unit_cost >= (0)::numeric))
);


