    total_amount numeric(12,2) NOT NULL,
    paid_amount numeric(12,2) DEFAULT 0,
    balance numeric(12,2) GENERATED ALWAYS AS ((total_amount - paid_amount)) STORED,
    status character varying(20) DEFAULT 'draft'::character varying,
    notes text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    idempotency_key text,
    request_hash text,
    match_status text,
    journal_entry_id uuid,
    matched_at timestamp with time zone,
    matched_by uuid,
    CONSTRAINT supplier_invoices_discount_amount_check CHECK ((discount_amount >= (0)::numeric)),
    CONSTRAINT supplier_invoices_match_status_check CHECK (((match_status IS NULL) OR (match_status = 'matched'::text))),
    CONSTRAINT supplier_invoices_paid_amount_check CHECK ((paid_amount >= (0)::numeric)),
    CONSTRAINT supplier_invoices_status_check CHECK (((status)::text = ANY (ARRAY[('draft'::character varying)::text, ('submitted'::character varying)::text, ('approved'::character varying)::text, ('paid'::character varying)::text, ('partially_paid'::character varying)::text, ('overdue'::character varying)::text]))),
    CONSTRAINT supplier_invoices_subtotal_check CHECK ((subtotal >= (0)::numeric)),
    CONSTRAINT supplier_invoices_tax_amount_check CHECK ((tax_amount >= (0)::numeric)),
    CONSTRAINT supplier_invoices_total_amount_check CHECK ((total_amount >= (0)::numeric))
);


