    CONSTRAINT supplier_payments_payment_method_check CHECK (((payment_method)::text = ANY (ARRAY[('cash'::character varying)::text, ('bank_transfer'::character varying)::text, ('check'::character varying)::text, ('credit_card'::character varying)::text, ('debit_card'::character varying)::text, ('online_payment'::character varying)::text, ('mobile_payment'::character varying)::text, ('other'::character varying)::text]))),
    CONSTRAINT supplier_payments_status_check CHECK (((status)::text = ANY (ARRAY[('draft'::character varying)::text, ('posted'::character varying)::text, ('cancelled'::character varying)::text])))
);


