    CONSTRAINT uoms_factor_check CHECK (((is_product_specific AND (factor_to_category_base IS NULL)) OR ((NOT is_product_specific) AND (factor_to_category_base > (0)::numeric)))),
    CONSTRAINT uoms_rounding_mode_check CHECK ((rounding_mode = ANY (ARRAY['HALF_UP'::text, 'HALF_EVEN'::text, 'DOWN'::text, 'UP'::text])))
);


