--
-- Name: employees Managers can insert employees; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Managers can insert employees" ON public.employees FOR INSERT TO authenticated WITH CHECK ((EXISTS ( SELECT 1
   FROM public.user_organizations uo
  WHERE ((uo.user_id = ( SELECT auth.uid() AS uid)) AND (uo.org_id = employees.org_id) AND (uo.is_active IS TRUE) AND ((uo.role)::text = ANY ((ARRAY['admin'::character varying, 'manager'::character varying])::text[]))))));


--
-- Name: employees Managers can update employees; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Managers can update employees" ON public.employees FOR UPDATE TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.user_organizations uo
  WHERE ((uo.user_id = ( SELECT auth.uid() AS uid)) AND (uo.org_id = employees.org_id) AND (uo.is_active IS TRUE) AND ((uo.role)::text = ANY ((ARRAY['admin'::character varying, 'manager'::character varying])::text[])))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.user_organizations uo
  WHERE ((uo.user_id = ( SELECT auth.uid() AS uid)) AND (uo.org_id = employees.org_id) AND (uo.is_active IS TRUE) AND ((uo.role)::text = ANY ((ARRAY['admin'::character varying, 'manager'::character varying])::text[]))))));


--
-- Name: employees Users can view org employees; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Users can view org employees" ON public.employees FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.user_organizations uo
  WHERE ((uo.user_id = ( SELECT auth.uid() AS uid)) AND (uo.org_id = employees.org_id) AND (uo.is_active IS TRUE)))));


--
-- Name: security_audit_reports Users can view their org audit reports; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Users can view their org audit reports" ON public.security_audit_reports FOR SELECT USING (((EXISTS ( SELECT 1
   FROM public.super_admins
  WHERE ((super_admins.user_id = ( SELECT auth.uid() AS uid)) AND (super_admins.is_active = true)))) OR (org_id IN ( SELECT user_organizations.org_id
   FROM public.user_organizations
  WHERE ((user_organizations.user_id = ( SELECT auth.uid() AS uid)) AND (user_organizations.is_active = true)))) OR ((org_id IS NULL) AND (EXISTS ( SELECT 1
   FROM public.user_organizations
  WHERE ((user_organizations.user_id = ( SELECT auth.uid() AS uid)) AND (user_organizations.is_org_admin = true) AND (user_organizations.is_active = true)))))));


