--
-- Name: hr_alerts hr_alerts_del_m; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY hr_alerts_del_m ON public.hr_alerts FOR DELETE TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.user_organizations uo
  WHERE ((uo.user_id = ( SELECT auth.uid() AS uid)) AND (uo.org_id = hr_alerts.org_id) AND (uo.is_active IS TRUE) AND ((uo.role)::text = ANY ((ARRAY['admin'::character varying, 'manager'::character varying])::text[]))))));


