--
-- Name: item_product_map item_product_map_admin; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY item_product_map_admin ON public.item_product_map TO authenticated USING (public.wardah_is_org_admin(org_id)) WITH CHECK ((public.wardah_is_org_admin(org_id) AND (EXISTS ( SELECT 1
   FROM public.items i
  WHERE ((i.id = item_product_map.item_id) AND (i.org_id = i.org_id)))) AND (EXISTS ( SELECT 1
   FROM public.products p
  WHERE ((p.id = item_product_map.product_id) AND (p.org_id = p.org_id))))));


